(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("lucretius-nature-b",[{"sp":"HDR","t":"Liber I"},{"sp":"N","t":"Aeneadum genetrix, hominum divomque voluptas,","st":"1.1"},{"sp":"N","t":"alma Venus, caeli subter labentia signa"},{"sp":"N","t":"quae mare navigerum, quae terras frugiferentis"},{"sp":"N","t":"concelebras, per te quoniam genus omne animantum"},{"sp":"N","t":"concipitur visitque exortum lumina solis:","st":"1.5"},{"sp":"N","t":"te, dea, te fugiunt venti, te nubila caeli"},{"sp":"N","t":"adventumque tuum, tibi suavis daedala tellus"},{"sp":"N","t":"summittit flores, tibi rident aequora ponti"},{"sp":"N","t":"placatumque nitet diffuso lumine caelum."},{"sp":"N","t":"nam simul ac species patefactast verna diei","st":"1.10"},{"sp":"N","t":"et reserata viget genitabilis aura favoni,"},{"sp":"N","t":"aeriae primum volucris te, diva, tuumque"},{"sp":"N","t":"significant initum perculsae corda tua vi."},{"sp":"N","t":"inde ferae pecudes persultant pabula laeta","st":"1.15"},{"sp":"N","t":"et rapidos tranant amnis: ita capta lepore"},{"sp":"N","t":"te sequitur cupide quo quamque inducere pergis."},{"sp":"N","t":"denique per maria ac montis fluviosque rapacis"},{"sp":"N","t":"frondiferasque domos avium camposque virentis"},{"sp":"N","t":"omnibus incutiens blandum per pectora amorem"},{"sp":"N","t":"efficis ut cupide generatim saecla propagent.","st":"1.20"},{"sp":"N","t":"quae quoniam rerum naturam sola gubernas"},{"sp":"N","t":"nec sine te quicquam dias in luminis oras"},{"sp":"N","t":"exoritur neque fit laetum neque amabile quicquam,"},{"sp":"N","t":"te sociam studeo scribendis versibus esse,"},{"sp":"N","t":"quos ego de rerum natura pangere conor","st":"1.25"},{"sp":"N","t":"Memmiadae nostro, quem tu, dea, tempore in omni"},{"sp":"N","t":"omnibus ornatum voluisti excellere rebus."},{"sp":"N","t":"quo magis aeternum da dictis, diva, leporem."},{"sp":"N","t":"effice ut interea fera moenera militiai"},{"sp":"N","t":"per maria ac terras omnis sopita quiescant;","st":"1.30"},{"sp":"N","t":"nam tu sola potes tranquilla pace iuvare"},{"sp":"N","t":"mortalis, quoniam belli fera moenera Mavors"},{"sp":"N","t":"armipotens regit, in gremium qui saepe tuum se"},{"sp":"N","t":"reiicit aeterno devictus vulnere amoris,"},{"sp":"N","t":"atque ita suspiciens tereti cervice reposta","st":"1.35"},{"sp":"N","t":"pascit amore avidos inhians in te, dea, visus"},{"sp":"N","t":"eque tuo pendet resupini spiritus ore."},{"sp":"N","t":"hunc tu, diva, tuo recubantem corpore sancto"},{"sp":"N","t":"circum fusa super, suavis ex ore loquellas"},{"sp":"N","t":"funde petens placidam Romanis, incluta, pacem;","st":"1.40"},{"sp":"N","t":"nam neque nos agere hoc patriai tempore iniquo"},{"sp":"N","t":"possumus aequo animo nec Memmi clara propago"},{"sp":"N","t":"talibus in rebus communi desse saluti."},{"sp":"N","t":"omnis enim per se divum natura necessest"},{"sp":"N","t":"immortali aevo summa cum pace fruatur","st":"1.45"},{"sp":"N","t":"semota ab nostris rebus seiunctaque longe;"},{"sp":"N","t":"nam privata dolore omni, privata periclis,"},{"sp":"N","t":"ipsa suis pollens opibus, nihil indiga nostri,"},{"sp":"N","t":"nec bene promeritis capitur nec tangitur ira."},{"sp":"N","t":"Quod super est, vacuas auris animumque sagacem","st":"1.50"},{"sp":"N","t":"semotum a curis adhibe veram ad rationem,"},{"sp":"N","t":"ne mea dona tibi studio disposta fideli,"},{"sp":"N","t":"intellecta prius quam sint, contempta relinquas."},{"sp":"N","t":"nam tibi de summa caeli ratione deumque"},{"sp":"N","t":"disserere incipiam et rerum primordia pandam,","st":"1.55"},{"sp":"N","t":"unde omnis natura creet res, auctet alatque,"},{"sp":"N","t":"quove eadem rursum natura perempta resolvat,"},{"sp":"N","t":"quae nos materiem et genitalia corpora rebus"},{"sp":"N","t":"reddunda in ratione vocare et semina rerum"},{"sp":"N","t":"appellare suemus et haec eadem usurpare","st":"1.60"},{"sp":"N","t":"corpora prima, quod ex illis sunt omnia primis."},{"sp":"N","t":"Humana ante oculos foede cum vita iaceret"},{"sp":"N","t":"in terris oppressa gravi sub religione,"},{"sp":"N","t":"quae caput a caeli regionibus ostendebat"},{"sp":"N","t":"horribili super aspectu mortalibus instans,","st":"1.65"},{"sp":"N","t":"primum Graius homo mortalis tollere contra"},{"sp":"N","t":"est oculos ausus primusque obsistere contra;"},{"sp":"N","t":"quem neque fama deum nec fulmina nec minitanti"},{"sp":"N","t":"murmure compressit caelum, sed eo magis acrem"},{"sp":"N","t":"inritat animi virtutem, effringere ut arta","st":"1.70"},{"sp":"N","t":"naturae primus portarum claustra cupiret."},{"sp":"N","t":"ergo vivida vis animi pervicit et extra"},{"sp":"N","t":"processit longe flammantia moenia mundi"},{"sp":"N","t":"atque omne immensum peragravit mente animoque,"},{"sp":"N","t":"unde refert nobis victor quid possit oriri,","st":"1.75"},{"sp":"N","t":"quid nequeat, finita potestas denique cuique"},{"sp":"N","t":"qua nam sit ratione atque alte terminus haerens."},{"sp":"N","t":"quare religio pedibus subiecta vicissim"},{"sp":"N","t":"opteritur, nos exaequat victoria caelo."},{"sp":"N","t":"Illud in his rebus vereor, ne forte rearis","st":"1.80"},{"sp":"N","t":"impia te rationis inire elementa viamque"},{"sp":"N","t":"indugredi sceleris. quod contra saepius illa"},{"sp":"N","t":"religio peperit scelerosa atque impia facta."},{"sp":"N","t":"Aulide quo pacto Triviai virginis aram"},{"sp":"N","t":"Iphianassai turparunt sanguine foede","st":"1.85"},{"sp":"N","t":"ductores Danaum delecti, prima virorum."},{"sp":"N","t":"cui simul infula virgineos circum data comptus"},{"sp":"N","t":"ex utraque pari malarum parte profusast,"},{"sp":"N","t":"et maestum simul ante aras adstare parentem"},{"sp":"N","t":"sensit et hunc propter ferrum celare ministros","st":"1.90"},{"sp":"N","t":"aspectuque suo lacrimas effundere civis,"},{"sp":"N","t":"muta metu terram genibus summissa petebat."},{"sp":"N","t":"nec miserae prodesse in tali tempore quibat,"},{"sp":"N","t":"quod patrio princeps donarat nomine regem;"},{"sp":"N","t":"nam sublata virum manibus tremibundaque ad aras","st":"1.95"},{"sp":"N","t":"deductast, non ut sollemni more sacrorum"},{"sp":"N","t":"perfecto posset claro comitari Hymenaeo,"},{"sp":"N","t":"sed casta inceste nubendi tempore in ipso"},{"sp":"N","t":"hostia concideret mactatu maesta parentis,"},{"sp":"N","t":"exitus ut classi felix faustusque daretur.","st":"1.100"},{"sp":"N","t":"tantum religio potuit suadere malorum."},{"sp":"N","t":"Tutemet a nobis iam quovis tempore vatum"},{"sp":"N","t":"terriloquis victus dictis desciscere quaeres."},{"sp":"N","t":"quippe etenim quam multa tibi iam fingere possunt"},{"sp":"N","t":"somnia, quae vitae rationes vertere possint","st":"1.105"},{"sp":"N","t":"fortunasque tuas omnis turbare timore!"},{"sp":"N","t":"et merito; nam si certam finem esse viderent"},{"sp":"N","t":"aerumnarum homines, aliqua ratione valerent"},{"sp":"N","t":"religionibus atque minis obsistere vatum."},{"sp":"N","t":"nunc ratio nulla est restandi, nulla facultas,","st":"1.110"},{"sp":"N","t":"aeternas quoniam poenas in morte timendum."},{"sp":"N","t":"ignoratur enim quae sit natura animai,"},{"sp":"N","t":"nata sit an contra nascentibus insinuetur"},{"sp":"N","t":"et simul intereat nobiscum morte dirempta"},{"sp":"N","t":"an tenebras Orci visat vastasque lacunas","st":"1.115"},{"sp":"N","t":"an pecudes alias divinitus insinuet se,"},{"sp":"N","t":"Ennius ut noster cecinit, qui primus amoeno"},{"sp":"N","t":"detulit ex Helicone perenni fronde coronam,"},{"sp":"N","t":"per gentis Italas hominum quae clara clueret;"},{"sp":"N","t":"etsi praeterea tamen esse Acherusia templa","st":"1.120"},{"sp":"N","t":"Ennius aeternis exponit versibus edens,"},{"sp":"N","t":"quo neque permaneant animae neque corpora nostra,"},{"sp":"N","t":"sed quaedam simulacra modis pallentia miris;"},{"sp":"N","t":"unde sibi exortam semper florentis Homeri"},{"sp":"N","t":"commemorat speciem lacrimas effundere salsas","st":"1.125"},{"sp":"N","t":"coepisse et rerum naturam expandere dictis."},{"sp":"N","t":"qua propter bene cum superis de rebus habenda"},{"sp":"N","t":"nobis est ratio, solis lunaeque meatus"},{"sp":"N","t":"qua fiant ratione, et qua vi quaeque gerantur"},{"sp":"N","t":"in terris, tunc cum primis ratione sagaci","st":"1.130"},{"sp":"N","t":"unde anima atque animi constet natura videndum,"},{"sp":"N","t":"et quae res nobis vigilantibus obvia mentes"},{"sp":"N","t":"terrificet morbo adfectis somnoque sepultis,"},{"sp":"N","t":"cernere uti videamur eos audireque coram,"},{"sp":"N","t":"morte obita quorum tellus amplectitur ossa.","st":"1.135"},{"sp":"N","t":"Nec me animi fallit Graiorum obscura reperta"},{"sp":"N","t":"difficile inlustrare Latinis versibus esse,"},{"sp":"N","t":"multa novis verbis praesertim cum sit agendum"},{"sp":"N","t":"propter egestatem linguae et rerum novitatem;"},{"sp":"N","t":"sed tua me virtus tamen et sperata voluptas","st":"1.140"},{"sp":"N","t":"suavis amicitiae quemvis efferre laborem"},{"sp":"N","t":"suadet et inducit noctes vigilare serenas"},{"sp":"N","t":"quaerentem dictis quibus et quo carmine demum"},{"sp":"N","t":"clara tuae possim praepandere lumina menti,"},{"sp":"N","t":"res quibus occultas penitus convisere possis.","st":"1.145"},{"sp":"N","t":"hunc igitur terrorem animi tenebrasque necessest"},{"sp":"N","t":"non radii solis neque lucida tela diei"},{"sp":"N","t":"discutiant, sed naturae species ratioque."},{"sp":"N","t":"Principium cuius hinc nobis exordia sumet,"},{"sp":"N","t":"nullam rem e nihilo gigni divinitus umquam.","st":"1.150"},{"sp":"N","t":"quippe ita formido mortalis continet omnis,"},{"sp":"N","t":"quod multa in terris fieri caeloque tuentur,"},{"sp":"N","t":"quorum operum causas nulla ratione videre"},{"sp":"N","t":"possunt ac fieri divino numine rentur."},{"sp":"N","t":"quas ob res ubi viderimus nil posse creari"},{"sp":"N","t":"de nihilo, tum quod sequimur iam rectius inde"},{"sp":"N","t":"perspiciemus, et unde queat res quaeque creari"},{"sp":"N","t":"et quo quaeque modo fiant opera sine divom.","st":"1.155"},{"sp":"N","t":"Nam si de nihilo fierent, ex omnibus rebus"},{"sp":"N","t":"omne genus nasci posset, nil semine egeret.","st":"1.160"},{"sp":"N","t":"e mare primum homines, e terra posset oriri"},{"sp":"N","t":"squamigerum genus et volucres erumpere caelo;"},{"sp":"N","t":"armenta atque aliae pecudes, genus omne ferarum,"},{"sp":"N","t":"incerto partu culta ac deserta tenerent."},{"sp":"N","t":"nec fructus idem arboribus constare solerent,","st":"1.165"},{"sp":"N","t":"sed mutarentur, ferre omnes omnia possent."},{"sp":"N","t":"quippe ubi non essent genitalia corpora cuique,"},{"sp":"N","t":"qui posset mater rebus consistere certa?"},{"sp":"N","t":"at nunc seminibus quia certis quaeque creantur,"},{"sp":"N","t":"inde enascitur atque oras in luminis exit,","st":"1.170"},{"sp":"N","t":"materies ubi inest cuiusque et corpora prima;"},{"sp":"N","t":"atque hac re nequeunt ex omnibus omnia gigni,"},{"sp":"N","t":"quod certis in rebus inest secreta facultas."},{"sp":"N","t":"Praeterea cur vere rosam, frumenta calore,"},{"sp":"N","t":"vites autumno fundi suadente videmus,","st":"1.175"},{"sp":"N","t":"si non, certa suo quia tempore semina rerum"},{"sp":"N","t":"cum confluxerunt, patefit quod cumque creatur,"},{"sp":"N","t":"dum tempestates adsunt et vivida tellus"},{"sp":"N","t":"tuto res teneras effert in luminis oras?"},{"sp":"N","t":"quod si de nihilo fierent, subito exorerentur","st":"1.180"},{"sp":"N","t":"incerto spatio atque alienis partibus anni,"},{"sp":"N","t":"quippe ubi nulla forent primordia, quae genitali"},{"sp":"N","t":"concilio possent arceri tempore iniquo."},{"sp":"N","t":"Nec porro augendis rebus spatio foret usus"},{"sp":"N","t":"seminis ad coitum, si e nilo crescere possent;","st":"1.185"},{"sp":"N","t":"nam fierent iuvenes subito ex infantibus parvis"},{"sp":"N","t":"e terraque exorta repente arbusta salirent."},{"sp":"N","t":"quorum nil fieri manifestum est, omnia quando"},{"sp":"N","t":"paulatim crescunt, ut par est semine certo,"},{"sp":"N","t":"crescentesque genus servant; ut noscere possis","st":"1.190"},{"sp":"N","t":"quicque sua de materia grandescere alique."},{"sp":"N","t":"Huc accedit uti sine certis imbribus anni"},{"sp":"N","t":"laetificos nequeat fetus submittere tellus"},{"sp":"N","t":"nec porro secreta cibo natura animantum"},{"sp":"N","t":"propagare genus possit vitamque tueri;","st":"1.195"},{"sp":"N","t":"ut potius multis communia corpora rebus"},{"sp":"N","t":"multa putes esse, ut verbis elementa videmus,"},{"sp":"N","t":"quam sine principiis ullam rem existere posse."},{"sp":"N","t":"Denique cur homines tantos natura parare"},{"sp":"N","t":"non potuit, pedibus qui pontum per vada possent","st":"1.200"},{"sp":"N","t":"transire et magnos manibus divellere montis"},{"sp":"N","t":"multaque vivendo vitalia vincere saecla,"},{"sp":"N","t":"si non, materies quia rebus reddita certast"},{"sp":"N","t":"gignundis, e qua constat quid possit oriri?"},{"sp":"N","t":"nil igitur fieri de nilo posse fatendumst,","st":"1.205"},{"sp":"N","t":"semine quando opus est rebus, quo quaeque creatae"},{"sp":"N","t":"aeris in teneras possint proferrier auras."},{"sp":"N","t":"Postremo quoniam incultis praestare videmus"},{"sp":"N","t":"culta loca et manibus melioris reddere fetus,"},{"sp":"N","t":"esse videlicet in terris primordia rerum","st":"1.210"},{"sp":"N","t":"quae nos fecundas vertentes vomere glebas"},{"sp":"N","t":"terraique solum subigentes cimus ad ortus;"},{"sp":"N","t":"quod si nulla forent, nostro sine quaeque labore"},{"sp":"N","t":"sponte sua multo fieri meliora videres."},{"sp":"N","t":"Huc accedit uti quicque in sua corpora rursum","st":"1.215"},{"sp":"N","t":"dissoluat natura neque ad nihilum interemat res."},{"sp":"N","t":"nam siquid mortale e cunctis partibus esset,"},{"sp":"N","t":"ex oculis res quaeque repente erepta periret;"},{"sp":"N","t":"nulla vi foret usus enim, quae partibus eius"},{"sp":"N","t":"discidium parere et nexus exsolvere posset.","st":"1.220"},{"sp":"N","t":"quod nunc, aeterno quia constant semine quaeque,"},{"sp":"N","t":"donec vis obiit, quae res diverberet ictu"},{"sp":"N","t":"aut intus penetret per inania dissoluatque,"},{"sp":"N","t":"nullius exitium patitur natura videri."},{"sp":"N","t":"Praeterea quae cumque vetustate amovet aetas,","st":"1.225"},{"sp":"N","t":"si penitus peremit consumens materiem omnem,"},{"sp":"N","t":"unde animale genus generatim in lumina vitae"},{"sp":"N","t":"redducit Venus, aut redductum daedala tellus"},{"sp":"N","t":"unde alit atque auget generatim pabula praebens?"},{"sp":"N","t":"unde mare ingenuei fontes externaque longe","st":"1.230"},{"sp":"N","t":"flumina suppeditant? unde aether sidera pascit?"},{"sp":"N","t":"omnia enim debet, mortali corpore quae sunt,"},{"sp":"N","t":"infinita aetas consumpse ante acta diesque."},{"sp":"N","t":"quod si in eo spatio atque ante acta aetate fuere"},{"sp":"N","t":"e quibus haec rerum consistit summa refecta,","st":"1.235"},{"sp":"N","t":"inmortali sunt natura praedita certe."},{"sp":"N","t":"haud igitur possunt ad nilum quaeque reverti."},{"sp":"N","t":"Denique res omnis eadem vis causaque volgo"},{"sp":"N","t":"conficeret, nisi materies aeterna teneret,"},{"sp":"N","t":"inter se nexus minus aut magis indupedita;","st":"1.240"},{"sp":"N","t":"tactus enim leti satis esset causa profecto,"},{"sp":"N","t":"quippe ubi nulla forent aeterno corpore, quorum"},{"sp":"N","t":"contextum vis deberet dissolvere quaeque."},{"sp":"N","t":"at nunc, inter se quia nexus principiorum"},{"sp":"N","t":"dissimiles constant aeternaque materies est,","st":"1.245"},{"sp":"N","t":"incolumi remanent res corpore, dum satis acris"},{"sp":"N","t":"vis obeat pro textura cuiusque reperta."},{"sp":"N","t":"haud igitur redit ad nihilum res ulla, sed omnes"},{"sp":"N","t":"discidio redeunt in corpora materiai."},{"sp":"N","t":"postremo pereunt imbres, ubi eos pater aether","st":"1.250"},{"sp":"N","t":"in gremium matris terrai praecipitavit;"},{"sp":"N","t":"at nitidae surgunt fruges ramique virescunt"},{"sp":"N","t":"arboribus, crescunt ipsae fetuque gravantur."},{"sp":"N","t":"hinc alitur porro nostrum genus atque ferarum,"},{"sp":"N","t":"hinc laetas urbes pueris florere videmus","st":"1.255"},{"sp":"N","t":"frondiferasque novis avibus canere undique silvas,"},{"sp":"N","t":"hinc fessae pecudes pinguis per pabula laeta"},{"sp":"N","t":"corpora deponunt et candens lacteus umor"},{"sp":"N","t":"uberibus manat distentis, hinc nova proles"},{"sp":"N","t":"artubus infirmis teneras lasciva per herbas","st":"1.260"},{"sp":"N","t":"ludit lacte mero mentes perculsa novellas."},{"sp":"N","t":"haud igitur penitus pereunt quaecumque videntur,"},{"sp":"N","t":"quando alit ex alio reficit natura nec ullam"},{"sp":"N","t":"rem gigni patitur nisi morte adiuta aliena."},{"sp":"N","t":"Nunc age, res quoniam docui non posse creari","st":"1.265"},{"sp":"N","t":"de nihilo neque item genitas ad nil revocari,"},{"sp":"N","t":"ne qua forte tamen coeptes diffidere dictis,"},{"sp":"N","t":"quod nequeunt oculis rerum primordia cerni,"},{"sp":"N","t":"accipe praeterea quae corpora tute necessest"},{"sp":"N","t":"confiteare esse in rebus nec posse videri.","st":"1.270"},{"sp":"N","t":"Principio venti vis verberat incita corpus"},{"sp":"N","t":"ingentisque ruit navis et nubila differt,"},{"sp":"N","t":"inter dum rapido percurrens turbine campos"},{"sp":"N","t":"arboribus magnis sternit montisque supremos"},{"sp":"N","t":"silvifragis vexat flabris: ita perfurit acri","st":"1.275"},{"sp":"N","t":"cum fremitu saevitque minaci murmure pontus."},{"sp":"N","t":"sunt igitur venti ni mirum corpora caeca,"},{"sp":"N","t":"quae mare, quae terras, quae denique nubila caeli"},{"sp":"N","t":"verrunt ac subito vexantia turbine raptant,"},{"sp":"N","t":"nec ratione fluunt alia stragemque propagant","st":"1.280"},{"sp":"N","t":"et cum mollis aquae fertur natura repente"},{"sp":"N","t":"flumine abundanti, quam largis imbribus auget"},{"sp":"N","t":"montibus ex altis magnus decursus aquai"},{"sp":"N","t":"fragmina coniciens silvarum arbustaque tota,"},{"sp":"N","t":"nec validi possunt pontes venientis aquai","st":"1.285"},{"sp":"N","t":"vim subitam tolerare: ita magno turbidus imbri"},{"sp":"N","t":"molibus incurrit validis cum viribus amnis,"},{"sp":"N","t":"dat sonitu magno stragem volvitque sub undis"},{"sp":"N","t":"grandia saxa, ruit qua quidquid fluctibus obstat."},{"sp":"N","t":"sic igitur debent venti quoque flamina ferri,","st":"1.290"},{"sp":"N","t":"quae vel uti validum cum flumen procubuere"},{"sp":"N","t":"quam libet in partem, trudunt res ante ruuntque"},{"sp":"N","t":"impetibus crebris, inter dum vertice torto"},{"sp":"N","t":"corripiunt rapidique rotanti turbine portant."},{"sp":"N","t":"quare etiam atque etiam sunt venti corpora caeca,","st":"1.295"},{"sp":"N","t":"quandoquidem factis et moribus aemula magnis"},{"sp":"N","t":"amnibus inveniuntur, aperto corpore qui sunt."},{"sp":"N","t":"Tum porro varios rerum sentimus odores"},{"sp":"N","t":"nec tamen ad naris venientis cernimus umquam"},{"sp":"N","t":"nec calidos aestus tuimur nec frigora quimus","st":"1.300"},{"sp":"N","t":"usurpare oculis nec voces cernere suemus;"},{"sp":"N","t":"quae tamen omnia corporea constare necessest"},{"sp":"N","t":"natura, quoniam sensus inpellere possunt;"},{"sp":"N","t":"tangere enim et tangi, nisi corpus, nulla potest res."},{"sp":"N","t":"Denique fluctifrago suspensae in litore vestis","st":"1.305"},{"sp":"N","t":"uvescunt, eaedem dispansae in sole serescunt."},{"sp":"N","t":"at neque quo pacto persederit umor aquai"},{"sp":"N","t":"visumst nec rursum quo pacto fugerit aestu."},{"sp":"N","t":"in parvas igitur partis dispergitur umor,"},{"sp":"N","t":"quas oculi nulla possunt ratione videre.","st":"1.310"},{"sp":"N","t":"quin etiam multis solis redeuntibus annis"},{"sp":"N","t":"anulus in digito subter tenuatur habendo,"},{"sp":"N","t":"stilicidi casus lapidem cavat, uncus aratri"},{"sp":"N","t":"ferreus occulte decrescit vomer in arvis,"},{"sp":"N","t":"strataque iam volgi pedibus detrita viarum","st":"1.315"},{"sp":"N","t":"saxea conspicimus; tum portas propter aena"},{"sp":"N","t":"signa manus dextras ostendunt adtenuari"},{"sp":"N","t":"saepe salutantum tactu praeterque meantum."},{"sp":"N","t":"haec igitur minui, cum sint detrita, videmus."},{"sp":"N","t":"sed quae corpora decedant in tempore quoque,","st":"1.320"},{"sp":"N","t":"invida praeclusit speciem natura videndi."},{"sp":"N","t":"Postremo quae cumque dies naturaque rebus"},{"sp":"N","t":"paulatim tribuit moderatim crescere cogens,"},{"sp":"N","t":"nulla potest oculorum acies contenta tueri,"},{"sp":"N","t":"nec porro quae cumque aevo macieque senescunt,","st":"1.325"},{"sp":"N","t":"nec, mare quae impendent, vesco sale saxa peresa"},{"sp":"N","t":"quid quoque amittant in tempore cernere possis."},{"sp":"N","t":"corporibus caecis igitur natura gerit res."},{"sp":"N","t":"Nec tamen undique corporea stipata tenentur"},{"sp":"N","t":"omnia natura; namque est in rebus inane.","st":"1.330"},{"sp":"N","t":"quod tibi cognosse in multis erit utile rebus"},{"sp":"N","t":"nec sinet errantem dubitare et quaerere semper"},{"sp":"N","t":"de summa rerum et nostris diffidere dictis."},{"sp":"N","t":"qua propter locus est intactus inane vacansque."},{"sp":"N","t":"quod si non esset, nulla ratione moveri","st":"1.335"},{"sp":"N","t":"res possent; namque officium quod corporis exstat,"},{"sp":"N","t":"officere atque obstare, id in omni tempore adesset"},{"sp":"N","t":"omnibus; haud igitur quicquam procedere posset,"},{"sp":"N","t":"principium quoniam cedendi nulla daret res."},{"sp":"N","t":"at nunc per maria ac terras sublimaque caeli","st":"1.340"},{"sp":"N","t":"multa modis multis varia ratione moveri"},{"sp":"N","t":"cernimus ante oculos, quae, si non esset inane,"},{"sp":"N","t":"non tam sollicito motu privata carerent"},{"sp":"N","t":"quam genita omnino nulla ratione fuissent,"},{"sp":"N","t":"undique materies quoniam stipata quiesset.","st":"1.345"},{"sp":"N","t":"Praeterea quamvis solidae res esse putentur,"},{"sp":"N","t":"hinc tamen esse licet raro cum corpore cernas."},{"sp":"N","t":"in saxis ac speluncis permanat aquarum"},{"sp":"N","t":"liquidus umor et uberibus flent omnia guttis."},{"sp":"N","t":"dissipat in corpus sese cibus omne animantum;","st":"1.350"},{"sp":"N","t":"crescunt arbusta et fetus in tempore fundunt,"},{"sp":"N","t":"quod cibus in totas usque ab radicibus imis"},{"sp":"N","t":"per truncos ac per ramos diffunditur omnis."},{"sp":"N","t":"inter saepta meant voces et clausa domorum"},{"sp":"N","t":"transvolitant, rigidum permanat frigus ad ossa.","st":"1.355"},{"sp":"N","t":"quod nisi inania sint, qua possent corpora quaeque"},{"sp":"N","t":"transire, haud ulla fieri ratione videres."},{"sp":"N","t":"Denique cur alias aliis praestare videmus"},{"sp":"N","t":"pondere res rebus nihilo maiore figura?"},{"sp":"N","t":"nam si tantundemst in lanae glomere quantum","st":"1.360"},{"sp":"N","t":"corporis in plumbo est, tantundem pendere par est,"},{"sp":"N","t":"corporis officiumst quoniam premere omnia deorsum,"},{"sp":"N","t":"contra autem natura manet sine pondere inanis."},{"sp":"N","t":"ergo quod magnumst aeque leviusque videtur,"},{"sp":"N","t":"ni mirum plus esse sibi declarat inanis;","st":"1.365"},{"sp":"N","t":"at contra gravius plus in se corporis esse"},{"sp":"N","t":"dedicat et multo vacui minus intus habere."},{"sp":"N","t":"est igitur ni mirum id quod ratione sagaci"},{"sp":"N","t":"quaerimus, admixtum rebus, quod inane vocamus."},{"sp":"N","t":"Illud in his rebus ne te deducere vero","st":"1.370"},{"sp":"N","t":"possit, quod quidam fingunt, praecurrere cogor."},{"sp":"N","t":"cedere squamigeris latices nitentibus aiunt"},{"sp":"N","t":"et liquidas aperire vias, quia post loca pisces"},{"sp":"N","t":"linquant, quo possint cedentes confluere undae;"},{"sp":"N","t":"sic alias quoque res inter se posse moveri","st":"1.375"},{"sp":"N","t":"et mutare locum, quamvis sint omnia plena."},{"sp":"N","t":"scilicet id falsa totum ratione receptumst."},{"sp":"N","t":"nam quo squamigeri poterunt procedere tandem,"},{"sp":"N","t":"ni spatium dederint latices? concedere porro"},{"sp":"N","t":"quo poterunt undae, cum pisces ire nequibunt?","st":"1.380"},{"sp":"N","t":"aut igitur motu privandumst corpora quaeque"},{"sp":"N","t":"aut esse admixtum dicundumst rebus inane,"},{"sp":"N","t":"unde initum primum capiat res quaeque movendi."},{"sp":"N","t":"Postremo duo de concursu corpora lata"},{"sp":"N","t":"si cita dissiliant, nempe aer omne necessest,","st":"1.385"},{"sp":"N","t":"inter corpora quod fiat, possidat inane."},{"sp":"N","t":"is porro quamvis circum celerantibus auris"},{"sp":"N","t":"confluat, haud poterit tamen uno tempore totum"},{"sp":"N","t":"compleri spatium; nam primum quemque necessest"},{"sp":"N","t":"occupet ille locum, deinde omnia possideantur.","st":"1.390"},{"sp":"N","t":"quod si forte aliquis, cum corpora dissiluere,"},{"sp":"N","t":"tum putat id fieri quia se condenseat aer,"},{"sp":"N","t":"errat; nam vacuum tum fit quod non fuit ante"},{"sp":"N","t":"et repletur item vacuum quod constitit ante,"},{"sp":"N","t":"nec tali ratione potest denserier aer","st":"1.395"},{"sp":"N","t":"nec, si iam posset, sine inani posset, opinor,"},{"sp":"N","t":"ipse in se trahere et partis conducere in unum."},{"sp":"N","t":"Qua propter, quamvis causando multa moreris,"},{"sp":"N","t":"esse in rebus inane tamen fateare necessest."},{"sp":"N","t":"multaque praeterea tibi possum commemorando","st":"1.400"},{"sp":"N","t":"argumenta fidem dictis conradere nostris."},{"sp":"N","t":"verum animo satis haec vestigia parva sagaci"},{"sp":"N","t":"sunt, per quae possis cognoscere cetera tute."},{"sp":"N","t":"namque canes ut montivagae persaepe ferai"},{"sp":"N","t":"naribus inveniunt intectas fronde quietes,","st":"1.405"},{"sp":"N","t":"cum semel institerunt vestigia certa viai,"},{"sp":"N","t":"sic alid ex alio per te tute ipse videre"},{"sp":"N","t":"talibus in rebus poteris caecasque latebras"},{"sp":"N","t":"insinuare omnis et verum protrahere inde."},{"sp":"N","t":"quod si pigraris paulumve recesseris ab re,","st":"1.410"},{"sp":"N","t":"hoc tibi de plano possum promittere, Memmi:"},{"sp":"N","t":"usque adeo largos haustus e fontibus magnis"},{"sp":"N","t":"lingua meo suavis diti de pectore fundet,"},{"sp":"N","t":"ut verear ne tarda prius per membra senectus"},{"sp":"N","t":"serpat et in nobis vitai claustra resolvat,","st":"1.415"},{"sp":"N","t":"quam tibi de quavis una re versibus omnis"},{"sp":"N","t":"argumentorum sit copia missa per auris."},{"sp":"N","t":"Sed nunc ut repetam coeptum pertexere dictis,"},{"sp":"N","t":"omnis ut est igitur per se natura duabus"},{"sp":"N","t":"constitit in rebus; nam corpora sunt et inane,","st":"1.420"},{"sp":"N","t":"haec in quo sita sunt et qua diversa moventur."},{"sp":"N","t":"corpus enim per se communis dedicat esse"},{"sp":"N","t":"sensus; cui nisi prima fides fundata valebit,"},{"sp":"N","t":"haut erit occultis de rebus quo referentes"},{"sp":"N","t":"confirmare animi quicquam ratione queamus.","st":"1.425"},{"sp":"N","t":"tum porro locus ac spatium, quod inane vocamus,"},{"sp":"N","t":"si nullum foret, haut usquam sita corpora possent"},{"sp":"N","t":"esse neque omnino quoquam diversa meare;"},{"sp":"N","t":"id quod iam supera tibi paulo ostendimus ante."},{"sp":"N","t":"praeterea nihil est quod possis dicere ab omni","st":"1.430"},{"sp":"N","t":"corpore seiunctum secretumque esse ab inani,"},{"sp":"N","t":"quod quasi tertia sit numero natura reperta."},{"sp":"N","t":"nam quod cumque erit, esse aliquid debebit id ipsum"},{"sp":"N","t":"augmine vel grandi vel parvo denique, dum sit;"},{"sp":"N","t":"cui si tactus erit quamvis levis exiguusque,","st":"1.435"},{"sp":"N","t":"corporis augebit numerum summamque sequetur;"},{"sp":"N","t":"sin intactile erit, nulla de parte quod ullam"},{"sp":"N","t":"rem prohibere queat per se transire meantem,"},{"sp":"N","t":"scilicet hoc id erit, vacuum quod inane vocamus."},{"sp":"N","t":"Praeterea per se quod cumque erit, aut faciet quid","st":"1.440"},{"sp":"N","t":"aut aliis fungi debebit agentibus ipsum"},{"sp":"N","t":"aut erit ut possint in eo res esse gerique."},{"sp":"N","t":"at facere et fungi sine corpore nulla potest res"},{"sp":"N","t":"nec praebere locum porro nisi inane vacansque."},{"sp":"N","t":"ergo praeter inane et corpora tertia per se","st":"1.445"},{"sp":"N","t":"nulla potest rerum in numero natura relinqui,"},{"sp":"N","t":"nec quae sub sensus cadat ullo tempore nostros"},{"sp":"N","t":"nec ratione animi quam quisquam possit apisci."},{"sp":"N","t":"Nam quae cumque cluent, aut his coniuncta duabus"},{"sp":"N","t":"rebus ea invenies aut horum eventa videbis.","st":"1.450"},{"sp":"N","t":"coniunctum est id quod nusquam sine permitiali"},{"sp":"N","t":"discidio potis est seiungi seque gregari,"},{"sp":"N","t":"pondus uti saxis, calor ignis, liquor aquai,"},{"sp":"N","t":"tactus corporibus cunctis, intactus inani."},{"sp":"N","t":"servitium contra paupertas divitiaeque,","st":"1.455"},{"sp":"N","t":"libertas bellum concordia cetera quorum"},{"sp":"N","t":"adventu manet incolumis natura abituque,"},{"sp":"N","t":"haec soliti sumus, ut par est, eventa vocare."},{"sp":"N","t":"tempus item per se non est, sed rebus ab ipsis"},{"sp":"N","t":"consequitur sensus, transactum quid sit in aevo,","st":"1.460"},{"sp":"N","t":"tum quae res instet, quid porro deinde sequatur;"},{"sp":"N","t":"nec per se quemquam tempus sentire fatendumst"},{"sp":"N","t":"semotum ab rerum motu placidaque quiete."},{"sp":"N","t":"denique Tyndaridem raptam belloque subactas"},{"sp":"N","t":"Troiiugenas gentis cum dicunt esse, videndumst","st":"1.465"},{"sp":"N","t":"ne forte haec per se cogant nos esse fateri,"},{"sp":"N","t":"quando ea saecla hominum, quorum haec eventa fuerunt,"},{"sp":"N","t":"inrevocabilis abstulerit iam praeterita aetas;"},{"sp":"N","t":"namque aliud terris, aliud regionibus ipsis"},{"sp":"N","t":"eventum dici poterit quod cumque erit actum.","st":"1.470"},{"sp":"N","t":"denique materies si rerum nulla fuisset"},{"sp":"N","t":"nec locus ac spatium, res in quo quaeque geruntur,"},{"sp":"N","t":"numquam Tyndaridis forma conflatus amore"},{"sp":"N","t":"ignis Alexandri Phrygio sub pectore gliscens"},{"sp":"N","t":"clara accendisset saevi certamina belli","st":"1.475"},{"sp":"N","t":"nec clam durateus Troiianis Pergama partu"},{"sp":"N","t":"inflammasset equos nocturno Graiiugenarum;"},{"sp":"N","t":"perspicere ut possis res gestas funditus omnis"},{"sp":"N","t":"non ita uti corpus per se constare neque esse"},{"sp":"N","t":"nec ratione cluere eadem qua constet inane,","st":"1.480"},{"sp":"N","t":"sed magis ut merito possis eventa vocare"},{"sp":"N","t":"corporis atque loci, res in quo quaeque gerantur."},{"sp":"N","t":"Corpora sunt porro partim primordia rerum,"},{"sp":"N","t":"partim concilio quae constant principiorum."},{"sp":"N","t":"sed quae sunt rerum primordia, nulla potest vis","st":"1.485"},{"sp":"N","t":"stinguere; nam solido vincunt ea corpore demum."},{"sp":"N","t":"etsi difficile esse videtur credere quicquam"},{"sp":"N","t":"in rebus solido reperiri corpore posse."},{"sp":"N","t":"transit enim fulmen caeli per saepta domorum"},{"sp":"N","t":"clamor ut ac voces, ferrum candescit in igni","st":"1.490"},{"sp":"N","t":"dissiliuntque fero ferventi saxa vapore;"},{"sp":"N","t":"cum labefactatus rigor auri solvitur aestu,"},{"sp":"N","t":"tum glacies aeris flamma devicta liquescit;"},{"sp":"N","t":"permanat calor argentum penetraleque frigus,"},{"sp":"N","t":"quando utrumque manu retinentes pocula rite","st":"1.495"},{"sp":"N","t":"sensimus infuso lympharum rore superne."},{"sp":"N","t":"usque adeo in rebus solidi nihil esse videtur."},{"sp":"N","t":"sed quia vera tamen ratio naturaque rerum"},{"sp":"N","t":"cogit, ades, paucis dum versibus expediamus"},{"sp":"N","t":"esse ea quae solido atque aeterno corpore constent,","st":"1.500"},{"sp":"N","t":"semina quae rerum primordiaque esse docemus,"},{"sp":"N","t":"unde omnis rerum nunc constet summa creata."},{"sp":"N","t":"Principio quoniam duplex natura duarum"},{"sp":"N","t":"dissimilis rerum longe constare repertast,"},{"sp":"N","t":"corporis atque loci, res in quo quaeque geruntur,","st":"1.505"},{"sp":"N","t":"esse utramque sibi per se puramque necessest."},{"sp":"N","t":"nam qua cumque vacat spatium, quod inane vocamus,"},{"sp":"N","t":"corpus ea non est; qua porro cumque tenet se"},{"sp":"N","t":"corpus, ea vacuum nequaquam constat inane."},{"sp":"N","t":"sunt igitur solida ac sine inani corpora prima.","st":"1.510"},{"sp":"N","t":"Praeterea quoniam genitis in rebus inanest,"},{"sp":"N","t":"materiem circum solidam constare necessest;"},{"sp":"N","t":"nec res ulla potest vera ratione probari"},{"sp":"N","t":"corpore inane suo celare atque intus habere,"},{"sp":"N","t":"si non, quod cohibet, solidum constare relinquas.","st":"1.515"},{"sp":"N","t":"id porro nihil esse potest nisi materiai"},{"sp":"N","t":"concilium, quod inane queat rerum cohibere."},{"sp":"N","t":"materies igitur, solido quae corpore constat,"},{"sp":"N","t":"esse aeterna potest, cum cetera dissoluantur."},{"sp":"N","t":"Tum porro si nil esset quod inane vocaret,","st":"1.520"},{"sp":"N","t":"omne foret solidum; nisi contra corpora certa"},{"sp":"N","t":"essent quae loca complerent quae cumque tenerent"},{"sp":"N","t":"omne quod est spatium, vacuum constaret inane."},{"sp":"N","t":"alternis igitur ni mirum corpus inani"},{"sp":"N","t":"distinctum, quoniam nec plenum naviter extat","st":"1.525"},{"sp":"N","t":"nec porro vacuum; sunt ergo corpora certa,"},{"sp":"N","t":"quae spatium pleno possint distinguere inane."},{"sp":"N","t":"haec neque dissolui plagis extrinsecus icta"},{"sp":"N","t":"possunt nec porro penitus penetrata retexi"},{"sp":"N","t":"nec ratione queunt alia temptata labare;","st":"1.530"},{"sp":"N","t":"id quod iam supra tibi paulo ostendimus ante."},{"sp":"N","t":"nam neque conlidi sine inani posse videtur"},{"sp":"N","t":"quicquam nec frangi nec findi in bina secando"},{"sp":"N","t":"nec capere umorem neque item manabile frigus"},{"sp":"N","t":"nec penetralem ignem, quibus omnia conficiuntur.","st":"1.535"},{"sp":"N","t":"et quo quaeque magis cohibet res intus inane,"},{"sp":"N","t":"tam magis his rebus penitus temptata labascit."},{"sp":"N","t":"ergo si solida ac sine inani corpora prima"},{"sp":"N","t":"sunt ita uti docui, sint haec aeterna necessest."},{"sp":"N","t":"Praeterea nisi materies aeterna fuisset,","st":"1.540"},{"sp":"N","t":"antehac ad nihilum penitus res quaeque redissent"},{"sp":"N","t":"de nihiloque renata forent quae cumque videmus."},{"sp":"N","t":"at quoniam supra docui nil posse creari"},{"sp":"N","t":"de nihilo neque quod genitumst ad nil revocari,"},{"sp":"N","t":"esse inmortali primordia corpore debent,","st":"1.545"},{"sp":"N","t":"dissolui quo quaeque supremo tempore possint,"},{"sp":"N","t":"materies ut subpeditet rebus reparandis."},{"sp":"N","t":"sunt igitur solida primordia simplicitate"},{"sp":"N","t":"nec ratione queunt alia servata per aevom"},{"sp":"N","t":"ex infinito iam tempore res reparare.","st":"1.550"},{"sp":"N","t":"denique si nullam finem natura parasset"},{"sp":"N","t":"frangendis rebus, iam corpora materiai"},{"sp":"N","t":"usque redacta forent aevo frangente priore,"},{"sp":"N","t":"ut nihil ex illis a certo tempore posset"},{"sp":"N","t":"conceptum summum aetatis pervadere finem.","st":"1.555"},{"sp":"N","t":"nam quidvis citius dissolvi posse videmus"},{"sp":"N","t":"quam rursus refici; qua propter longa diei"},{"sp":"N","t":"infinita aetas ante acti temporis omnis"},{"sp":"N","t":"quod fregisset adhuc disturbans dissoluensque,"},{"sp":"N","t":"numquam relicuo reparari tempore posset.","st":"1.560"},{"sp":"N","t":"at nunc ni mirum frangendi reddita finis"},{"sp":"N","t":"certa manet, quoniam refici rem quamque videmus"},{"sp":"N","t":"et finita simul generatim tempora rebus"},{"sp":"N","t":"stare, quibus possint aevi contingere florem."},{"sp":"N","t":"Huc accedit uti, solidissima materiai","st":"1.565"},{"sp":"N","t":"corpora cum constant, possint tamen omnia reddi,"},{"sp":"N","t":"mollia quae fiunt, aer aqua terra vapores,"},{"sp":"N","t":"quo pacto fiant et qua vi quaeque gerantur,"},{"sp":"N","t":"admixtum quoniam semel est in rebus inane."},{"sp":"N","t":"at contra si mollia sint primordia rerum,","st":"1.570"},{"sp":"N","t":"unde queant validi silices ferrumque creari,"},{"sp":"N","t":"non poterit ratio reddi; nam funditus omnis"},{"sp":"N","t":"principio fundamenti natura carebit."},{"sp":"N","t":"sunt igitur solida pollentia simplicitate,"},{"sp":"N","t":"quorum condenso magis omnia conciliatu","st":"1.575"},{"sp":"N","t":"artari possunt validasque ostendere viris."},{"sp":"N","t":"porro si nullast frangendis reddita finis"},{"sp":"N","t":"corporibus, tamen ex aeterno tempore quaeque"},{"sp":"N","t":"nunc etiam superare necessest corpora rebus,"},{"sp":"N","t":"quae non dum clueant ullo temptata periclo.","st":"1.580"},{"sp":"N","t":"at quoniam fragili natura praedita constant,"},{"sp":"N","t":"discrepat aeternum tempus potuisse manere"},{"sp":"N","t":"innumerabilibus plagis vexata per aevom."},{"sp":"N","t":"Denique iam quoniam generatim reddita finis"},{"sp":"N","t":"crescendi rebus constat vitamque tenendi,","st":"1.585"},{"sp":"N","t":"et quid quaeque queant per foedera naturai,"},{"sp":"N","t":"quid porro nequeant, sancitum quando quidem extat,"},{"sp":"N","t":"nec commutatur quicquam, quin omnia constant"},{"sp":"N","t":"usque adeo, variae volucres ut in ordine cunctae"},{"sp":"N","t":"ostendant maculas generalis corpore inesse,","st":"1.590"},{"sp":"N","t":"inmutabilis materiae quoque corpus habere"},{"sp":"N","t":"debent ni mirum; nam si primordia rerum"},{"sp":"N","t":"commutari aliqua possent ratione revicta,"},{"sp":"N","t":"incertum quoque iam constet quid possit oriri,"},{"sp":"N","t":"quid nequeat, finita potestas denique cuique","st":"1.595"},{"sp":"N","t":"qua nam sit ratione atque alte terminus haerens,"},{"sp":"N","t":"nec totiens possent generatim saecla referre"},{"sp":"N","t":"naturam mores victum motusque parentum."},{"sp":"N","t":"Tum porro quoniam est extremum quodque cacumen"},{"sp":"N","t":"corporis illius, quod nostri cernere sensus","st":"1.600"},{"sp":"N","t":"iam nequeunt, id ni mirum sine partibus extat"},{"sp":"N","t":"et minima constat natura nec fuit umquam"},{"sp":"N","t":"per se secretum neque post hac esse valebit,"},{"sp":"N","t":"alterius quoniamst ipsum pars primaque et una,"},{"sp":"N","t":"inde aliae atque aliae similes ex ordine partes","st":"1.605"},{"sp":"N","t":"agmine condenso naturam corporis explent;"},{"sp":"N","t":"quae quoniam per se nequeunt constare, necessest"},{"sp":"N","t":"haerere unde queant nulla ratione revelli."},{"sp":"N","t":"sunt igitur solida primordia simplicitate,"},{"sp":"N","t":"quae minimis stipata cohaerent partibus arte.","st":"1.610"},{"sp":"N","t":"non ex illorum conventu conciliata,"},{"sp":"N","t":"sed magis aeterna pollentia simplicitate,"},{"sp":"N","t":"unde neque avelli quicquam neque deminui iam"},{"sp":"N","t":"concedit natura reservans semina rebus."},{"sp":"N","t":"Praeterea nisi erit minimum, parvissima quaeque","st":"1.615"},{"sp":"N","t":"corpora constabunt ex partibus infinitis,"},{"sp":"N","t":"quippe ubi dimidiae partis pars semper habebit"},{"sp":"N","t":"dimidiam partem nec res praefiniet ulla."},{"sp":"N","t":"ergo rerum inter summam minimamque quod escit,"},{"sp":"N","t":"nil erit ut distet; nam quamvis funditus omnis","st":"1.620"},{"sp":"N","t":"summa sit infinita, tamen, parvissima quae sunt,"},{"sp":"N","t":"ex infinitis constabunt partibus aeque."},{"sp":"N","t":"quod quoniam ratio reclamat vera negatque"},{"sp":"N","t":"credere posse animum, victus fateare necessest"},{"sp":"N","t":"esse ea quae nullis iam praedita partibus extent","st":"1.625"},{"sp":"N","t":"et minima constent natura. quae quoniam sunt,"},{"sp":"N","t":"illa quoque esse tibi solida atque aeterna fatendum."},{"sp":"N","t":"Denique si minimas in partis cuncta resolvi"},{"sp":"N","t":"cogere consuesset rerum natura creatrix,"},{"sp":"N","t":"iam nihil ex illis eadem reparare valeret","st":"1.630"},{"sp":"N","t":"propterea quia, quae nullis sunt partibus aucta,"},{"sp":"N","t":"non possunt ea quae debet genitalis habere"},{"sp":"N","t":"materies, varios conexus pondera plagas"},{"sp":"N","t":"concursus motus, per quas res quaeque geruntur."},{"sp":"N","t":"Quapropter qui materiem rerum esse putarunt","st":"1.635"},{"sp":"N","t":"ignem atque ex igni summam consistere solo,"},{"sp":"N","t":"magno opere a vera lapsi ratione videntur."},{"sp":"N","t":"Heraclitus init quorum dux proelia primus,"},{"sp":"N","t":"clarus ob obscuram linguam magis inter inanis"},{"sp":"N","t":"quamde gravis inter Graios, qui vera requirunt;","st":"1.640"},{"sp":"N","t":"omnia enim stolidi magis admirantur amantque,"},{"sp":"N","t":"inversis quae sub verbis latitantia cernunt,"},{"sp":"N","t":"veraque constituunt quae belle tangere possunt"},{"sp":"N","t":"auris et lepido quae sunt fucata sonore."},{"sp":"N","t":"Nam cur tam variae res possent esse, requiro,","st":"1.645"},{"sp":"N","t":"ex uno si sunt igni puroque creatae?"},{"sp":"N","t":"nil prodesset enim calidum denserier ignem"},{"sp":"N","t":"nec rare fieri, si partes ignis eandem"},{"sp":"N","t":"naturam quam totus habet super ignis haberent."},{"sp":"N","t":"acrior ardor enim conductis partibus esset,","st":"1.650"},{"sp":"N","t":"languidior porro disiectis disque supatis."},{"sp":"N","t":"amplius hoc fieri nihil est quod posse rearis"},{"sp":"N","t":"talibus in causis, ne dum variantia rerum"},{"sp":"N","t":"tanta queat densis rarisque ex ignibus esse."},{"sp":"N","t":"Id quoque: si faciant admixtum rebus inane,","st":"1.655"},{"sp":"N","t":"denseri poterunt ignes rarique relinqui;"},{"sp":"N","t":"sed quia multa sibi cernunt contraria quae sint"},{"sp":"N","t":"et fugitant in rebus inane relinquere purum,"},{"sp":"N","t":"ardua dum metuunt, amittunt vera viai"},{"sp":"N","t":"nec rursum cernunt exempto rebus inane","st":"1.660"},{"sp":"N","t":"omnia denseri fierique ex omnibus unum"},{"sp":"N","t":"corpus, nil ab se quod possit mittere raptim,"},{"sp":"N","t":"aestifer ignis uti lumen iacit atque vaporem,"},{"sp":"N","t":"ut videas non e stipatis partibus esse."},{"sp":"N","t":"Quod si forte alia credunt ratione potesse","st":"1.665"},{"sp":"N","t":"ignis in coetu stingui mutareque corpus,"},{"sp":"N","t":"scilicet ex nulla facere id si parte reparcent,"},{"sp":"N","t":"occidet ad nihilum ni mirum funditus ardor"},{"sp":"N","t":"omnis et e nihilo fient quae cumque creantur;"},{"sp":"N","t":"nam quod cumque suis mutatum finibus exit,","st":"1.670"},{"sp":"N","t":"continuo hoc mors est illius quod fuit ante."},{"sp":"N","t":"proinde aliquid superare necesse est incolume ollis,"},{"sp":"N","t":"ne tibi res redeant ad nilum funditus omnes"},{"sp":"N","t":"de nihiloque renata vigescat copia rerum."},{"sp":"N","t":"Nunc igitur quoniam certissima corpora quaedam","st":"1.675"},{"sp":"N","t":"sunt, quae conservant naturam semper eandem,"},{"sp":"N","t":"quorum abitu aut aditu mutatoque ordine mutant"},{"sp":"N","t":"naturam res et convertunt corpora sese,"},{"sp":"N","t":"scire licet non esse haec ignea corpora rerum."},{"sp":"N","t":"nil referret enim quaedam decedere, abire","st":"1.680"},{"sp":"N","t":"atque alia adtribui mutarique ordine quaedam,"},{"sp":"N","t":"si tamen ardoris naturam cuncta tenerent;"},{"sp":"N","t":"ignis enim foret omnimodis quod cumque crearet."},{"sp":"N","t":"verum, ut opinor, itast: sunt quaedam corpora, quorum"},{"sp":"N","t":"concursus motus ordo positura figurae","st":"1.685"},{"sp":"N","t":"efficiunt ignis mutatoque ordine mutant"},{"sp":"N","t":"naturam neque sunt igni simulata neque ulli"},{"sp":"N","t":"praeterea rei quae corpora mittere possit"},{"sp":"N","t":"sensibus et nostros adiectu tangere tactus."},{"sp":"N","t":"dicere porro ignem res omnis esse neque ullam","st":"1.690"},{"sp":"N","t":"rem veram in numero rerum constare nisi ignem,"},{"sp":"N","t":"quod facit hic idem, perdelirum esse videtur."},{"sp":"N","t":"nam contra sensus ab sensibus ipse repugnat"},{"sp":"N","t":"et labefactat eos, unde omnia credita pendent,"},{"sp":"N","t":"unde hic cognitus est ipsi quem nominat ignem;","st":"1.695"},{"sp":"N","t":"credit enim sensus ignem cognoscere vere,"},{"sp":"N","t":"cetera non credit, quae nilo clara minus sunt."},{"sp":"N","t":"quod mihi cum vanum tum delirum esse videtur;"},{"sp":"N","t":"quo referemus enim? quid nobis certius ipsis"},{"sp":"N","t":"sensibus esse potest, qui vera ac falsa notemus?","st":"1.700"},{"sp":"N","t":"Praeterea quare quisquam magis omnia tollat"},{"sp":"N","t":"et velit ardoris naturam linquere solam,"},{"sp":"N","t":"quam neget esse ignis, aliam tamen esse relinquat?"},{"sp":"N","t":"aequa videtur enim dementia dicere utrumque."},{"sp":"N","t":"Quapropter qui materiem rerum esse putarunt","st":"1.705"},{"sp":"N","t":"ignem atque ex igni summam consistere posse,"},{"sp":"N","t":"et qui principium gignundis aera rebus"},{"sp":"N","t":"constituere aut umorem qui cumque putarunt"},{"sp":"N","t":"fingere res ipsum per se terramve creare"},{"sp":"N","t":"omnia et in rerum naturas vertier omnis,","st":"1.710"},{"sp":"N","t":"magno opere a vero longe derrasse videntur."},{"sp":"N","t":"adde etiam qui conduplicant primordia rerum"},{"sp":"N","t":"aera iungentes igni terramque liquori,"},{"sp":"N","t":"et qui quattuor ex rebus posse omnia rentur"},{"sp":"N","t":"ex igni terra atque anima procrescere et imbri.","st":"1.715"},{"sp":"N","t":"quorum Acragantinus cum primis Empedocles est,"},{"sp":"N","t":"insula quem triquetris terrarum gessit in oris,"},{"sp":"N","t":"quam fluitans circum magnis anfractibus aequor"},{"sp":"N","t":"Ionium glaucis aspargit virus ab undis"},{"sp":"N","t":"angustoque fretu rapidum mare dividit undis","st":"1.720"},{"sp":"N","t":"Aeoliae terrarum oras a finibus eius."},{"sp":"N","t":"hic est vasta Charybdis et hic Aetnaea minantur"},{"sp":"N","t":"murmura flammarum rursum se colligere iras,"},{"sp":"N","t":"faucibus eruptos iterum vis ut vomat ignis"},{"sp":"N","t":"ad caelumque ferat flammai fulgura rursum.","st":"1.725"},{"sp":"N","t":"quae cum magna modis multis miranda videtur"},{"sp":"N","t":"gentibus humanis regio visendaque fertur"},{"sp":"N","t":"rebus opima bonis, multa munita virum vi,"},{"sp":"N","t":"nil tamen hoc habuisse viro praeclarius in se"},{"sp":"N","t":"nec sanctum magis et mirum carumque videtur.","st":"1.730"},{"sp":"N","t":"carmina quin etiam divini pectoris eius"},{"sp":"N","t":"vociferantur et exponunt praeclara reperta,"},{"sp":"N","t":"ut vix humana videatur stirpe creatus."},{"sp":"N","t":"Hic tamen et supra quos diximus inferiores"},{"sp":"N","t":"partibus egregie multis multoque minores,","st":"1.735"},{"sp":"N","t":"quamquam multa bene ac divinitus invenientes"},{"sp":"N","t":"ex adyto tam quam cordis responsa dedere"},{"sp":"N","t":"sanctius et multo certa ratione magis quam"},{"sp":"N","t":"Pythia quae tripodi a Phoebi lauroque profatur,"},{"sp":"N","t":"principiis tamen in rerum fecere ruinas","st":"1.740"},{"sp":"N","t":"et graviter magni magno cecidere ibi casu."},{"sp":"N","t":"Primum quod motus exempto rebus inani"},{"sp":"N","t":"constituunt et res mollis rarasque relinquunt"},{"sp":"N","t":"aera solem ignem terras animalia frugis"},{"sp":"N","t":"nec tamen admiscent in eorum corpus inane;","st":"1.745"},{"sp":"N","t":"deinde quod omnino finem non esse secandis"},{"sp":"N","t":"corporibus facient neque pausam stare fragori"},{"sp":"N","t":"nec prorsum in rebus minimum consistere quicquam,"},{"sp":"N","t":"cum videamus id extremum cuiusque cacumen"},{"sp":"N","t":"esse quod ad sensus nostros minimum esse videtur,","st":"1.750"},{"sp":"N","t":"conicere ut possis ex hoc, quae cernere non quis"},{"sp":"N","t":"extremum quod habent, minimum consistere rerum."},{"sp":"N","t":"Huc accedit item, quoniam primordia rerum"},{"sp":"N","t":"mollia constituunt, quae nos nativa videmus"},{"sp":"N","t":"esse et mortali cum corpore, funditus ut qui","st":"1.755"},{"sp":"N","t":"debeat ad nihilum iam rerum summa reverti"},{"sp":"N","t":"de nihiloque renata vigescere copia rerum;"},{"sp":"N","t":"quorum utrumque quid a vero iam distet habebis."},{"sp":"N","t":"Deinde inimica modis multis sunt atque veneno"},{"sp":"N","t":"ipsa sibi inter se; quare aut congressa peribunt","st":"1.760"},{"sp":"N","t":"aut ita diffugient, ut tempestate coacta"},{"sp":"N","t":"fulmina diffugere atque imbris ventosque videmus."},{"sp":"N","t":"Denique quattuor ex rebus si cuncta creantur"},{"sp":"N","t":"atque in eas rursum res omnia dissoluuntur,"},{"sp":"N","t":"qui magis illa queunt rerum primordia dici","st":"1.765"},{"sp":"N","t":"quam contra res illorum retroque putari?"},{"sp":"N","t":"alternis gignuntur enim mutantque colorem"},{"sp":"N","t":"et totam inter se naturam tempore ab omni."},{"sp":"N","t":"fulmina diffugere atque imbris ventosque videmus."},{"sp":"N","t":"sin ita forte putas ignis terraeque coire","st":"1.770"},{"sp":"N","t":"corpus et aerias auras roremque liquoris,"},{"sp":"N","t":"nil in concilio naturam ut mutet eorum,"},{"sp":"N","t":"nulla tibi ex illis poterit res esse creata,"},{"sp":"N","t":"non animans, non exanimo cum corpore, ut arbos;"},{"sp":"N","t":"quippe suam quicque in coetu variantis acervi","st":"1.775"},{"sp":"N","t":"naturam ostendet mixtusque videbitur aer"},{"sp":"N","t":"cum terra simul et quodam cum rore manere."},{"sp":"N","t":"at primordia gignundis in rebus oportet"},{"sp":"N","t":"naturam clandestinam caecamque adhibere,"},{"sp":"N","t":"emineat ne quid, quod contra pugnet et obstet","st":"1.780"},{"sp":"N","t":"quo minus esse queat proprie quodcumque creatur."},{"sp":"N","t":"Quin etiam repetunt a caelo atque ignibus eius"},{"sp":"N","t":"et primum faciunt ignem se vertere in auras"},{"sp":"N","t":"aeris, hinc imbrem gigni terramque creari"},{"sp":"N","t":"ex imbri retroque a terra cuncta reverti,","st":"1.785"},{"sp":"N","t":"umorem primum, post aera, deinde calorem,"},{"sp":"N","t":"nec cessare haec inter se mutare, meare"},{"sp":"N","t":"a caelo ad terram, de terra ad sidera mundi."},{"sp":"N","t":"quod facere haud ullo debent primordia pacto."},{"sp":"N","t":"immutabile enim quiddam superare necessest,","st":"1.790"},{"sp":"N","t":"ne res ad nihilum redigantur funditus omnes;"},{"sp":"N","t":"nam quod cumque suis mutatum finibus exit,"},{"sp":"N","t":"continuo hoc mors est illius quod fuit ante."},{"sp":"N","t":"quapropter quoniam quae paulo diximus ante"},{"sp":"N","t":"in commutatum veniunt, constare necessest","st":"1.795"},{"sp":"N","t":"ex aliis ea, quae nequeant convertier usquam,"},{"sp":"N","t":"ne tibi res redeant ad nilum funditus omnis;"},{"sp":"N","t":"quin potius tali natura praedita quaedam"},{"sp":"N","t":"corpora constituas, ignem si forte crearint,"},{"sp":"N","t":"posse eadem demptis paucis paucisque tributis,","st":"1.800"},{"sp":"N","t":"ordine mutato et motu, facere aeris auras,"},{"sp":"N","t":"sic alias aliis rebus mutarier omnis?"},{"sp":"N","t":"'At manifesta palam res indicat' inquis 'in auras"},{"sp":"N","t":"aeris e terra res omnis crescere alique;"},{"sp":"N","t":"et nisi tempestas indulget tempore fausto","st":"1.805"},{"sp":"N","t":"imbribus, ut tabe nimborum arbusta vacillent,"},{"sp":"N","t":"solque sua pro parte fovet tribuitque calorem,"},{"sp":"N","t":"crescere non possint fruges arbusta animantis.'"},{"sp":"N","t":"scilicet et nisi nos cibus aridus et tener umor"},{"sp":"N","t":"adiuvet, amisso iam corpore vita quoque omnis","st":"1.810"},{"sp":"N","t":"omnibus e nervis atque ossibus exsoluatur;"},{"sp":"N","t":"adiutamur enim dubio procul atque alimur nos"},{"sp":"N","t":"certis ab rebus, certis aliae atque aliae res."},{"sp":"N","t":"ni mirum quia multa modis communia multis"},{"sp":"N","t":"multarum rerum in rebus primordia mixta","st":"1.815"},{"sp":"N","t":"sunt, ideo variis variae res rebus aluntur."},{"sp":"N","t":"atque eadem magni refert primordia saepe"},{"sp":"N","t":"cum quibus et quali positura contineantur"},{"sp":"N","t":"et quos inter se dent motus accipiantque;"},{"sp":"N","t":"namque eadem caelum mare terras flumina solem","st":"1.820"},{"sp":"N","t":"constituunt, eadem fruges arbusta animantis,"},{"sp":"N","t":"verum aliis alioque modo commixta moventur."},{"sp":"N","t":"quin etiam passim nostris in versibus ipsis"},{"sp":"N","t":"multa elementa vides multis communia verbis,"},{"sp":"N","t":"cum tamen inter se versus ac verba necessest","st":"1.825"},{"sp":"N","t":"confiteare et re et sonitu distare sonanti."},{"sp":"N","t":"tantum elementa queunt permutato ordine solo;"},{"sp":"N","t":"at rerum quae sunt primordia, plura adhibere"},{"sp":"N","t":"possunt unde queant variae res quaeque creari."},{"sp":"N","t":"Nunc et Anaxagorae scrutemur homoeomerian","st":"1.830"},{"sp":"N","t":"quam Grai memorant nec nostra dicere lingua"},{"sp":"N","t":"concedit nobis patrii sermonis egestas,"},{"sp":"N","t":"sed tamen ipsam rem facilest exponere verbis."},{"sp":"N","t":"principio, rerum quam dicit homoeomerian,"},{"sp":"N","t":"ossa videlicet e pauxillis atque minutis","st":"1.835"},{"sp":"N","t":"ossibus hic et de pauxillis atque minutis"},{"sp":"N","t":"visceribus viscus gigni sanguenque creari"},{"sp":"N","t":"sanguinis inter se multis coeuntibus guttis"},{"sp":"N","t":"ex aurique putat micis consistere posse"},{"sp":"N","t":"aurum et de terris terram concrescere parvis,","st":"1.840"},{"sp":"N","t":"ignibus ex ignis, umorem umoribus esse,"},{"sp":"N","t":"cetera consimili fingit ratione putatque."},{"sp":"N","t":"nec tamen esse ulla de parte in rebus inane"},{"sp":"N","t":"concedit neque corporibus finem esse secandis."},{"sp":"N","t":"quare in utraque mihi pariter ratione videtur","st":"1.845"},{"sp":"N","t":"errare atque illi, supra quos diximus ante."},{"sp":"N","t":"Adde quod inbecilla nimis primordia fingit;"},{"sp":"N","t":"si primordia sunt, simili quae praedita constant"},{"sp":"N","t":"natura atque ipsae res sunt aequeque laborant"},{"sp":"N","t":"et pereunt, neque ab exitio res ulla refrenat.","st":"1.850"},{"sp":"N","t":"nam quid in oppressu valido durabit eorum,"},{"sp":"N","t":"ut mortem effugiat, leti sub dentibus ipsis?"},{"sp":"N","t":"ignis an umor an aura? quid horum? sanguen an ossa?"},{"sp":"N","t":"nil ut opinor, ubi ex aequo res funditus omnis"},{"sp":"N","t":"tam mortalis erit quam quae manifesta videmus","st":"1.855"},{"sp":"N","t":"ex oculis nostris aliqua vi victa perire."},{"sp":"N","t":"at neque reccidere ad nihilum res posse neque autem"},{"sp":"N","t":"crescere de nihilo testor res ante probatas."},{"sp":"N","t":"Praeterea quoniam cibus auget corpus alitque,"},{"sp":"N","t":"scire licet nobis venas et sanguen et ossa","st":"1.860"},{"sp":"N","t":"* * *"},{"sp":"N","t":"sive cibos omnis commixto corpore dicent"},{"sp":"N","t":"esse et habere in se nervorum corpora parva"},{"sp":"N","t":"ossaque et omnino venas partisque cruoris,"},{"sp":"N","t":"fiet uti cibus omnis et aridus et liquor ipse"},{"sp":"N","t":"ex alienigenis rebus constare putetur,","st":"1.865"},{"sp":"N","t":"ossibus et nervis sanieque et sanguine mixto."},{"sp":"N","t":"Praeterea quae cumque e terra corpora crescunt,"},{"sp":"N","t":"si sunt in terris, terram constare necessest"},{"sp":"N","t":"ex alienigenis, quae terris exoriuntur."},{"sp":"N","t":"transfer item, totidem verbis utare licebit:","st":"1.870"},{"sp":"N","t":"in lignis si flamma latet fumusque cinisque,"},{"sp":"N","t":"ex alienigenis consistant ligna necessest,"},{"sp":"N","t":"praeterea tellus quae corpora cumque alit auget"},{"sp":"N","t":"ex alienigenis, quae lignis exoriuntur."},{"sp":"N","t":"Linquitur hic quaedam latitandi copia tenvis,","st":"1.875"},{"sp":"N","t":"id quod Anaxagoras sibi sumit, ut omnibus omnis"},{"sp":"N","t":"res putet inmixtas rebus latitare, sed illud"},{"sp":"N","t":"apparere unum, cuius sint plurima mixta"},{"sp":"N","t":"et magis in promptu primaque in fronte locata."},{"sp":"N","t":"quod tamen a vera longe ratione repulsumst;","st":"1.880"},{"sp":"N","t":"conveniebat enim fruges quoque saepe, minaci"},{"sp":"N","t":"robore cum in saxi franguntur, mittere signum"},{"sp":"N","t":"sanguinis aut aliquid, nostro quae corpore aluntur."},{"sp":"N","t":"cum lapidi in lapidem terimus, manare cruorem"},{"sp":"N","t":"consimili ratione herbis quoque saepe decebat,","st":"1.885"},{"sp":"N","t":"et latices dulcis guttas similique sapore"},{"sp":"N","t":"mittere, lanigerae quali sunt ubere lactis,"},{"sp":"N","t":"scilicet et glebis terrarum saepe friatis"},{"sp":"N","t":"herbarum genera et fruges frondesque videri"},{"sp":"N","t":"dispertita inter terram latitare minute,","st":"1.890"},{"sp":"N","t":"postremo in lignis cinerem fumumque videri,"},{"sp":"N","t":"cum praefracta forent, ignisque latere minutos."},{"sp":"N","t":"quorum nil fieri quoniam manifesta docet res,"},{"sp":"N","t":"scire licet non esse in rebus res ita mixtas,"},{"sp":"N","t":"verum semina multimodis inmixta latere","st":"1.895"},{"sp":"N","t":"multarum rerum in rebus communia debent."},{"sp":"N","t":"'At saepe in magnis fit montibus' inquis 'ut altis"},{"sp":"N","t":"arboribus vicina cacumina summa terantur"},{"sp":"N","t":"inter se validis facere id cogentibus austris,"},{"sp":"N","t":"donec flammai fulserunt flore coorto.'","st":"1.900"},{"sp":"N","t":"scilicet et non est lignis tamen insitus ignis,"},{"sp":"N","t":"verum semina sunt ardoris multa, terendo"},{"sp":"N","t":"quae cum confluxere, creant incendia silvis."},{"sp":"N","t":"quod si facta foret silvis abscondita flamma,"},{"sp":"N","t":"non possent ullum tempus celarier ignes,","st":"1.905"},{"sp":"N","t":"conficerent volgo silvas, arbusta cremarent."},{"sp":"N","t":"iamne vides igitur, paulo quod diximus ante,"},{"sp":"N","t":"permagni referre eadem primordia saepe"},{"sp":"N","t":"cum quibus et quali positura contineantur"},{"sp":"N","t":"et quos inter se dent motus accipiantque,","st":"1.910"},{"sp":"N","t":"atque eadem paulo inter se mutata creare"},{"sp":"N","t":"ignes et lignum? quo pacto verba quoque ipsa"},{"sp":"N","t":"inter se paulo mutatis sunt elementis,"},{"sp":"N","t":"cum ligna atque ignes distincta voce notemus."},{"sp":"N","t":"Denique iam quae cumque in rebus cernis apertis","st":"1.915"},{"sp":"N","t":"si fieri non posse putas, quin materiai"},{"sp":"N","t":"corpora consimili natura praedita fingas,"},{"sp":"N","t":"hac ratione tibi pereunt primordia rerum:"},{"sp":"N","t":"fiet uti risu tremulo concussa cachinnent"},{"sp":"N","t":"et lacrimis salsis umectent ora genasque.","st":"1.920"},{"sp":"N","t":"Nunc age, quod super est, cognosce et clarius audi."},{"sp":"N","t":"nec me animi fallit quam sint obscura; sed acri"},{"sp":"N","t":"percussit thyrso laudis spes magna meum cor"},{"sp":"N","t":"et simul incussit suavem mi in pectus amorem"},{"sp":"N","t":"Musarum, quo nunc instinctus mente vigenti","st":"1.925"},{"sp":"N","t":"avia Pieridum peragro loca nullius ante"},{"sp":"N","t":"trita solo. iuvat integros accedere fontis"},{"sp":"N","t":"atque haurire iuvatque novos decerpere flores"},{"sp":"N","t":"insignemque meo capiti petere inde coronam,"},{"sp":"N","t":"unde prius nulli velarint tempora Musae;","st":"1.930"},{"sp":"N","t":"primum quod magnis doceo de rebus et artis"},{"sp":"N","t":"religionum animum nodis exsolvere pergo,"},{"sp":"N","t":"deinde quod obscura de re tam lucida pango"},{"sp":"N","t":"carmina musaeo contingens cuncta lepore."},{"sp":"N","t":"id quoque enim non ab nulla ratione videtur;","st":"1.935"},{"sp":"N","t":"sed vel uti pueris absinthia taetra medentes"},{"sp":"N","t":"cum dare conantur, prius oras pocula circum"},{"sp":"N","t":"contingunt mellis dulci flavoque liquore,"},{"sp":"N","t":"ut puerorum aetas inprovida ludificetur"},{"sp":"N","t":"labrorum tenus, interea perpotet amarum","st":"1.940"},{"sp":"N","t":"absinthi laticem deceptaque non capiatur,"},{"sp":"N","t":"sed potius tali facto recreata valescat,"},{"sp":"N","t":"sic ego nunc, quoniam haec ratio plerumque videtur"},{"sp":"N","t":"tristior esse quibus non est tractata, retroque"},{"sp":"N","t":"volgus abhorret ab hac, volui tibi suaviloquenti","st":"1.945"},{"sp":"N","t":"carmine Pierio rationem exponere nostram"},{"sp":"N","t":"et quasi musaeo dulci contingere melle,"},{"sp":"N","t":"si tibi forte animum tali ratione tenere"},{"sp":"N","t":"versibus in nostris possem, dum perspicis omnem"},{"sp":"N","t":"naturam rerum, qua constet compta figura.","st":"1.950"},{"sp":"N","t":"Sed quoniam docui solidissima materiai"},{"sp":"N","t":"corpora perpetuo volitare invicta per aevom,"},{"sp":"N","t":"nunc age, summai quaedam sit finis eorum"},{"sp":"N","t":"necne sit, evolvamus; item quod inane repertumst"},{"sp":"N","t":"seu locus ac spatium, res in quo quaeque gerantur,","st":"1.955"},{"sp":"N","t":"pervideamus utrum finitum funditus omne"},{"sp":"N","t":"constet an immensum pateat vasteque profundum."},{"sp":"N","t":"Omne quod est igitur nulla regione viarum"},{"sp":"N","t":"finitumst; namque extremum debebat habere."},{"sp":"N","t":"extremum porro nullius posse videtur","st":"1.960"},{"sp":"N","t":"esse, nisi ultra sit quod finiat, ut videatur"},{"sp":"N","t":"quo non longius haec sensus natura sequatur."},{"sp":"N","t":"nunc extra summam quoniam nihil esse fatendum,"},{"sp":"N","t":"non habet extremum, caret ergo fine modoque."},{"sp":"N","t":"nec refert quibus adsistas regionibus eius;","st":"1.965"},{"sp":"N","t":"usque adeo, quem quisque locum possedit, in omnis"},{"sp":"N","t":"tantundem partis infinitum omne relinquit."},{"sp":"N","t":"Praeterea si iam finitum constituatur"},{"sp":"N","t":"omne quod est spatium, si quis procurrat ad oras"},{"sp":"N","t":"ultimus extremas iaciatque volatile telum,","st":"1.970"},{"sp":"N","t":"id validis utrum contortum viribus ire"},{"sp":"N","t":"quo fuerit missum mavis longeque volare,"},{"sp":"N","t":"an prohibere aliquid censes obstareque posse?"},{"sp":"N","t":"alterutrum fatearis enim sumasque necessest."},{"sp":"N","t":"quorum utrumque tibi effugium praecludit et omne","st":"1.975"},{"sp":"N","t":"cogit ut exempta concedas fine patere."},{"sp":"N","t":"nam sive est aliquid quod probeat efficiatque"},{"sp":"N","t":"quo minus quo missum est veniat finique locet se,"},{"sp":"N","t":"sive foras fertur, non est a fine profectum."},{"sp":"N","t":"hoc pacto sequar atque, oras ubi cumque locaris","st":"1.980"},{"sp":"N","t":"extremas, quaeram: quid telo denique fiet?"},{"sp":"N","t":"fiet uti nusquam possit consistere finis"},{"sp":"N","t":"effugiumque fugae prolatet copia semper."},{"sp":"N","t":"Praeterea spatium summai totius omne"},{"sp":"N","t":"undique si inclusum certis consisteret oris","st":"1.985"},{"sp":"N","t":"finitumque foret, iam copia materiai"},{"sp":"N","t":"undique ponderibus solidis confluxet ad imum"},{"sp":"N","t":"nec res ulla geri sub caeli tegmine posset"},{"sp":"N","t":"nec foret omnino caelum neque lumina solis,"},{"sp":"N","t":"quippe ubi materies omnis cumulata iaceret","st":"1.990"},{"sp":"N","t":"ex infinito iam tempore subsidendo."},{"sp":"N","t":"at nunc ni mirum requies data principiorum"},{"sp":"N","t":"corporibus nullast, quia nil est funditus imum,"},{"sp":"N","t":"quo quasi confluere et sedes ubi ponere possint."},{"sp":"N","t":"semper in adsiduo motu res quaeque geruntur","st":"1.995"},{"sp":"N","t":"partibus in cunctis, infernaque suppeditantur"},{"sp":"N","t":"ex infinito cita corpora materiai."},{"sp":"N","t":"Postremo ante oculos res rem finire videtur;"},{"sp":"N","t":"aer dissaepit collis atque aera montes,"},{"sp":"N","t":"terra mare et contra mare terras terminat omnis;","st":"1.1000"},{"sp":"N","t":"omne quidem vero nihil est quod finiat extra."},{"sp":"N","t":"est igitur natura loci spatiumque profundi,"},{"sp":"N","t":"quod neque clara suo percurrere fulmina cursu"},{"sp":"N","t":"perpetuo possint aevi labentia tractu"},{"sp":"N","t":"nec prorsum facere ut restet minus ire meando;","st":"1.1005"},{"sp":"N","t":"usque adeo passim patet ingens copia rebus"},{"sp":"N","t":"finibus exemptis in cunctas undique partis."},{"sp":"N","t":"Ipsa modum porro sibi rerum summa parare"},{"sp":"N","t":"ne possit, natura tenet, quae corpus inane"},{"sp":"N","t":"et quod inane autem est finiri corpore cogit,","st":"1.1010"},{"sp":"N","t":"ut sic alternis infinita omnia reddat,"},{"sp":"N","t":"aut etiam alterutrum, nisi terminet alterum eorum,"},{"sp":"N","t":"simplice natura pateat tamen inmoderatum,"},{"sp":"N","t":"nec mare nec tellus neque caeli lucida templa"},{"sp":"N","t":"nec mortale genus nec divum corpora sancta","st":"1.1015"},{"sp":"N","t":"exiguum possent horai sistere tempus;"},{"sp":"N","t":"nam dispulsa suo de coetu materiai"},{"sp":"N","t":"copia ferretur magnum per inane soluta,"},{"sp":"N","t":"sive adeo potius numquam concreta creasset"},{"sp":"N","t":"ullam rem, quoniam cogi disiecta nequisset.","st":"1.1020"},{"sp":"N","t":"nam certe neque consilio primordia rerum"},{"sp":"N","t":"ordine se suo quaeque sagaci mente locarunt"},{"sp":"N","t":"nec quos quaeque darent motus pepigere profecto"},{"sp":"N","t":"sed quia multa modis multis mutata per omne"},{"sp":"N","t":"ex infinito vexantur percita plagis,","st":"1.1025"},{"sp":"N","t":"omne genus motus et coetus experiundo"},{"sp":"N","t":"tandem deveniunt in talis disposituras,"},{"sp":"N","t":"qualibus haec rerum consistit summa creata,"},{"sp":"N","t":"et multos etiam magnos servata per annos"},{"sp":"N","t":"ut semel in motus coniectast convenientis,","st":"1.1030"},{"sp":"N","t":"efficit ut largis avidum mare fluminis undis"},{"sp":"N","t":"integrent amnes et solis terra vapore"},{"sp":"N","t":"fota novet fetus summissaque gens animantum"},{"sp":"N","t":"floreat et vivant labentis aetheris ignes."},{"sp":"N","t":"quod nullo facerent pacto, nisi materiai","st":"1.1035"},{"sp":"N","t":"ex infinito suboriri copia posset,"},{"sp":"N","t":"unde amissa solent reparare in tempore quaeque."},{"sp":"N","t":"nam vel uti privata cibo natura animantum"},{"sp":"N","t":"diffluit amittens corpus, sic omnia debent"},{"sp":"N","t":"dissolui simul ac defecit suppeditare","st":"1.1040"},{"sp":"N","t":"materies aliqua ratione aversa viai."},{"sp":"N","t":"nec plagae possunt extrinsecus undique summam"},{"sp":"N","t":"conservare omnem, quae cumque est conciliata."},{"sp":"N","t":"cudere enim crebro possunt partemque morari,"},{"sp":"N","t":"dum veniant aliae ac suppleri summa queatur;","st":"1.1045"},{"sp":"N","t":"inter dum resilire tamen coguntur et una"},{"sp":"N","t":"principiis rerum spatium tempusque fugai"},{"sp":"N","t":"largiri, ut possint a coetu libera ferri."},{"sp":"N","t":"quare etiam atque etiam suboriri multa necessest,"},{"sp":"N","t":"et tamen ut plagae quoque possint suppetere ipsae,","st":"1.1050"},{"sp":"N","t":"infinita opus est vis undique materiai."},{"sp":"N","t":"Illud in his rebus longe fuge credere, Memmi,"},{"sp":"N","t":"in medium summae quod dicunt omnia niti"},{"sp":"N","t":"atque ideo mundi naturam stare sine ullis"},{"sp":"N","t":"ictibus externis neque quoquam posse resolvi","st":"1.1055"},{"sp":"N","t":"summa atque ima, quod in medium sint omnia nixa,"},{"sp":"N","t":"ipsum si quicquam posse in se sistere credis,"},{"sp":"N","t":"et quae pondera sunt sub terris omnia sursum"},{"sp":"N","t":"nitier in terraque retro requiescere posta,"},{"sp":"N","t":"ut per aquas quae nunc rerum simulacra videmus;","st":"1.1060"},{"sp":"N","t":"et simili ratione animalia suppa vagari"},{"sp":"N","t":"contendunt neque posse e terris in loca caeli"},{"sp":"N","t":"reccidere inferiora magis quam corpora nostra"},{"sp":"N","t":"sponte sua possint in caeli templa volare;"},{"sp":"N","t":"illi cum videant solem, nos sidera noctis","st":"1.1065"},{"sp":"N","t":"cernere et alternis nobiscum tempora caeli"},{"sp":"N","t":"dividere et noctes parilis agitare diebus."},{"sp":"N","t":"sed vanus stolidis haec * * *"},{"sp":"N","t":"amplexi quod habent perv * * *"},{"sp":"N","t":"nam medium nihil esse potest * * *","st":"1.1070"},{"sp":"N","t":"infinita; neque omnino, si iam medium sit,"},{"sp":"N","t":"possit ibi quicquam consistere * * *"},{"sp":"N","t":"quam quavis alia longe ratione * * *"},{"sp":"N","t":"omnis enim locus ac spatium, quod inane vocamus,"},{"sp":"N","t":"per medium, per non medium, concedere debet","st":"1.1075"},{"sp":"N","t":"aeque ponderibus, motus qua cumque feruntur."},{"sp":"N","t":"nec quisquam locus est, quo corpora cum venerunt,"},{"sp":"N","t":"ponderis amissa vi possint stare in inani;"},{"sp":"N","t":"nec quod inane autem est ulli subsistere debet,"},{"sp":"N","t":"quin, sua quod natura petit, concedere pergat.","st":"1.1080"},{"sp":"N","t":"haud igitur possunt tali ratione teneri"},{"sp":"N","t":"res in concilium medii cuppedine victae."},{"sp":"N","t":"Praeterea quoniam non omnia corpora fingunt"},{"sp":"N","t":"in medium niti, sed terrarum atque liquoris"},{"sp":"N","t":"umorem ponti magnasque e montibus undas,"},{"sp":"N","t":"et quasi terreno quae corpore contineantur,","st":"1.1085"},{"sp":"N","t":"at contra tenuis exponunt aeris auras"},{"sp":"N","t":"et calidos simul a medio differrier ignis,"},{"sp":"N","t":"atque ideo totum circum tremere aethera signis"},{"sp":"N","t":"et solis flammam per caeli caerula pasci,","st":"1.1090"},{"sp":"N","t":"quod calor a medio fugiens se ibi conligat omnis,"},{"sp":"N","t":"nec prorsum arboribus summos frondescere ramos"},{"sp":"N","t":"posse, nisi a terris paulatim cuique cibatum"},{"sp":"N","t":"ne volucri ritu flammarum moenia mundi"},{"sp":"N","t":"diffugiant subito magnum per inane soluta"},{"sp":"N","t":"et ne cetera consimili ratione sequantur"},{"sp":"N","t":"neve ruant caeli tonitralia templa superne","st":"1.1105"},{"sp":"N","t":"terraque se pedibus raptim subducat et omnis"},{"sp":"N","t":"inter permixtas rerum caelique ruinas"},{"sp":"N","t":"corpora solventes abeat per inane profundum,"},{"sp":"N","t":"temporis ut puncto nihil extet reliquiarum"},{"sp":"N","t":"desertum praeter spatium et primordia caeca.","st":"1.1110"},{"sp":"N","t":"nam qua cumque prius de parti corpora desse"},{"sp":"N","t":"constitues, haec rebus erit pars ianua leti,"},{"sp":"N","t":"hac se turba foras dabit omnis materiai."},{"sp":"N","t":"Haec sic pernosces parva perductus opella;"},{"sp":"N","t":"namque alid ex alio clarescet nec tibi caeca","st":"1.1115"},{"sp":"N","t":"nox iter eripiet, quin ultima naturai"},{"sp":"N","t":"pervideas: ita res accendent lumina rebus."},{"sp":"HDR","t":"Liber II"},{"sp":"N","t":"Suave, mari magno turbantibus aequora ventis","st":"2.1"},{"sp":"N","t":"e terra magnum alterius spectare laborem;"},{"sp":"N","t":"non quia vexari quemquamst iucunda voluptas,"},{"sp":"N","t":"sed quibus ipse malis careas quia cernere suavest."},{"sp":"N","t":"suave etiam belli certamina magna tueri"},{"sp":"N","t":"per campos instructa tua sine parte pericli;","st":"2.5"},{"sp":"N","t":"sed nihil dulcius est, bene quam munita tenere"},{"sp":"N","t":"edita doctrina sapientum templa serena,"},{"sp":"N","t":"despicere unde queas alios passimque videre"},{"sp":"N","t":"errare atque viam palantis quaerere vitae,","st":"2.10"},{"sp":"N","t":"certare ingenio, contendere nobilitate,"},{"sp":"N","t":"noctes atque dies niti praestante labore"},{"sp":"N","t":"ad summas emergere opes rerumque potiri."},{"sp":"N","t":"o miseras hominum mentes, o pectora caeca!"},{"sp":"N","t":"qualibus in tenebris vitae quantisque periclis","st":"2.15"},{"sp":"N","t":"degitur hoc aevi quod cumquest! nonne videre"},{"sp":"N","t":"nihil aliud sibi naturam latrare, nisi ut qui"},{"sp":"N","t":"corpore seiunctus dolor absit, mente fruatur"},{"sp":"N","t":"iucundo sensu cura semota metuque?"},{"sp":"N","t":"ergo corpoream ad naturam pauca videmus","st":"2.20"},{"sp":"N","t":"esse opus omnino: quae demant cumque dolorem,"},{"sp":"N","t":"delicias quoque uti multas substernere possint"},{"sp":"N","t":"gratius inter dum, neque natura ipsa requirit,"},{"sp":"N","t":"si non aurea sunt iuvenum simulacra per aedes"},{"sp":"N","t":"lampadas igniferas manibus retinentia dextris,","st":"2.25"},{"sp":"N","t":"lumina nocturnis epulis ut suppeditentur,"},{"sp":"N","t":"nec domus argento fulget auroque renidet"},{"sp":"N","t":"nec citharae reboant laqueata aurataque templa,"},{"sp":"N","t":"cum tamen inter se prostrati in gramine molli"},{"sp":"N","t":"propter aquae rivum sub ramis arboris altae","st":"2.30"},{"sp":"N","t":"non magnis opibus iucunde corpora curant,"},{"sp":"N","t":"praesertim cum tempestas adridet et anni"},{"sp":"N","t":"tempora conspergunt viridantis floribus herbas."},{"sp":"N","t":"nec calidae citius decedunt corpore febres,"},{"sp":"N","t":"textilibus si in picturis ostroque rubenti","st":"2.35"},{"sp":"N","t":"iacteris, quam si in plebeia veste cubandum est."},{"sp":"N","t":"quapropter quoniam nihil nostro in corpore gazae"},{"sp":"N","t":"proficiunt neque nobilitas nec gloria regni,"},{"sp":"N","t":"quod super est, animo quoque nil prodesse putandum;"},{"sp":"N","t":"si non forte tuas legiones per loca campi","st":"2.40"},{"sp":"N","t":"fervere cum videas belli simulacra cientis,"},{"sp":"N","t":"subsidiis magnis et opum vi constabilitas,"},{"sp":"N","t":"ornatas armis stlattas pariterque animatas,"},{"sp":"N","t":"his tibi tum rebus timefactae religiones"},{"sp":"N","t":"effugiunt animo pavidae mortisque timores","st":"2.45"},{"sp":"N","t":"tum vacuum pectus lincunt curaque solutum."},{"sp":"N","t":"quod si ridicula haec ludibriaque esse videmus,"},{"sp":"N","t":"re veraque metus hominum curaeque sequaces"},{"sp":"N","t":"nec metuunt sonitus armorum nec fera tela"},{"sp":"N","t":"audacterque inter reges rerumque potentis","st":"2.50"},{"sp":"N","t":"versantur neque fulgorem reverentur ab auro"},{"sp":"N","t":"nec clarum vestis splendorem purpureai,"},{"sp":"N","t":"quid dubitas quin omnis sit haec rationis potestas,"},{"sp":"N","t":"omnis cum in tenebris praesertim vita laboret?"},{"sp":"N","t":"nam vel uti pueri trepidant atque omnia caecis","st":"2.55"},{"sp":"N","t":"in tenebris metuunt, sic nos in luce timemus"},{"sp":"N","t":"inter dum, nihilo quae sunt metuenda magis quam"},{"sp":"N","t":"quae pueri in tenebris pavitant finguntque futura."},{"sp":"N","t":"hunc igitur terrorem animi tenebrasque necessest"},{"sp":"N","t":"non radii solis neque lucida tela diei","st":"2.60"},{"sp":"N","t":"discutiant, sed naturae species ratioque."},{"sp":"N","t":"Nunc age, quo motu genitalia materiai"},{"sp":"N","t":"corpora res varias gignant genitasque resolvant"},{"sp":"N","t":"et qua vi facere id cogantur quaeque sit ollis"},{"sp":"N","t":"reddita mobilitas magnum per inane meandi,","st":"2.65"},{"sp":"N","t":"expediam: tu te dictis praebere memento."},{"sp":"N","t":"nam certe non inter se stipata cohaeret"},{"sp":"N","t":"materies, quoniam minui rem quamque videmus"},{"sp":"N","t":"et quasi longinquo fluere omnia cernimus aevo"},{"sp":"N","t":"ex oculisque vetustatem subducere nostris,","st":"2.70"},{"sp":"N","t":"cum tamen incolumis videatur summa manere"},{"sp":"N","t":"propterea quia, quae decedunt corpora cuique,"},{"sp":"N","t":"unde abeunt minuunt, quo venere augmine donant."},{"sp":"N","t":"illa senescere, at haec contra florescere cogunt,"},{"sp":"N","t":"nec remorantur ibi. sic rerum summa novatur","st":"2.75"},{"sp":"N","t":"semper, et inter se mortales mutua vivunt."},{"sp":"N","t":"augescunt aliae gentes, aliae minuuntur,"},{"sp":"N","t":"inque brevi spatio mutantur saecla animantum"},{"sp":"N","t":"et quasi cursores vitai lampada tradunt."},{"sp":"N","t":"Si cessare putas rerum primordia posse","st":"2.80"},{"sp":"N","t":"cessandoque novos rerum progignere motus,"},{"sp":"N","t":"avius a vera longe ratione vagaris."},{"sp":"N","t":"nam quoniam per inane vagantur, cuncta necessest"},{"sp":"N","t":"aut gravitate sua ferri primordia rerum"},{"sp":"N","t":"aut ictu forte alterius. nam cum cita saepe","st":"2.85"},{"sp":"N","t":"obvia conflixere, fit ut diversa repente"},{"sp":"N","t":"dissiliant; neque enim mirum, durissima quae sint"},{"sp":"N","t":"ponderibus solidis neque quicquam a tergibus obstet."},{"sp":"N","t":"et quo iactari magis omnia materiai"},{"sp":"N","t":"corpora pervideas, reminiscere totius imum","st":"2.90"},{"sp":"N","t":"nil esse in summa, neque habere ubi corpora prima"},{"sp":"N","t":"consistant, quoniam spatium sine fine modoquest"},{"sp":"N","t":"inmensumque patere in cunctas undique partis"},{"sp":"N","t":"pluribus ostendi et certa ratione probatumst."},{"sp":"N","t":"quod quoniam constat, ni mirum nulla quies est","st":"2.95"},{"sp":"N","t":"reddita corporibus primis per inane profundum,"},{"sp":"N","t":"sed magis adsiduo varioque exercita motu"},{"sp":"N","t":"partim intervallis magnis confulta resultant,"},{"sp":"N","t":"pars etiam brevibus spatiis vexantur ab ictu."},{"sp":"N","t":"et quae cumque magis condenso conciliatu","st":"2.100"},{"sp":"N","t":"exiguis intervallis convecta resultant,"},{"sp":"N","t":"indupedita suis perplexis ipsa figuris,"},{"sp":"N","t":"haec validas saxi radices et fera ferri"},{"sp":"N","t":"corpora constituunt et cetera de genere horum."},{"sp":"N","t":"paucula quae porro magnum per inane vagantur,","st":"2.105"},{"sp":"N","t":"cetera dissiliunt longe longeque recursant"},{"sp":"N","t":"in magnis intervallis; haec aera rarum"},{"sp":"N","t":"sufficiunt nobis et splendida lumina solis."},{"sp":"N","t":"multaque praeterea magnum per inane vagantur,"},{"sp":"N","t":"conciliis rerum quae sunt reiecta nec usquam","st":"2.110"},{"sp":"N","t":"consociare etiam motus potuere recepta."},{"sp":"N","t":"Cuius, uti memoro, rei simulacrum et imago"},{"sp":"N","t":"ante oculos semper nobis versatur et instat."},{"sp":"N","t":"contemplator enim, cum solis lumina cumque"},{"sp":"N","t":"inserti fundunt radii per opaca domorum:","st":"2.115"},{"sp":"N","t":"multa minuta modis multis per inane videbis"},{"sp":"N","t":"corpora misceri radiorum lumine in ipso"},{"sp":"N","t":"et vel ut aeterno certamine proelia pugnas"},{"sp":"N","t":"edere turmatim certantia nec dare pausam,"},{"sp":"N","t":"conciliis et discidiis exercita crebris;","st":"2.120"},{"sp":"N","t":"conicere ut possis ex hoc, primordia rerum"},{"sp":"N","t":"quale sit in magno iactari semper inani."},{"sp":"N","t":"dum taxat, rerum magnarum parva potest res"},{"sp":"N","t":"exemplare dare et vestigia notitiai."},{"sp":"N","t":"Hoc etiam magis haec animum te advertere par est","st":"2.125"},{"sp":"N","t":"corpora quae in solis radiis turbare videntur,"},{"sp":"N","t":"quod tales turbae motus quoque materiai"},{"sp":"N","t":"significant clandestinos caecosque subesse."},{"sp":"N","t":"multa videbis enim plagis ibi percita caecis"},{"sp":"N","t":"commutare viam retroque repulsa reverti","st":"2.130"},{"sp":"N","t":"nunc huc nunc illuc in cunctas undique partis."},{"sp":"N","t":"scilicet hic a principiis est omnibus error."},{"sp":"N","t":"prima moventur enim per se primordia rerum,"},{"sp":"N","t":"inde ea quae parvo sunt corpora conciliatu"},{"sp":"N","t":"et quasi proxima sunt ad viris principiorum,","st":"2.135"},{"sp":"N","t":"ictibus illorum caecis inpulsa cientur,"},{"sp":"N","t":"ipsaque proporro paulo maiora lacessunt."},{"sp":"N","t":"sic a principiis ascendit motus et exit"},{"sp":"N","t":"paulatim nostros ad sensus, ut moveantur"},{"sp":"N","t":"illa quoque, in solis quae lumine cernere quimus","st":"2.140"},{"sp":"N","t":"nec quibus id faciant plagis apparet aperte."},{"sp":"N","t":"Nunc quae mobilitas sit reddita materiai"},{"sp":"N","t":"corporibus, paucis licet hinc cognoscere, Memmi."},{"sp":"N","t":"primum aurora novo cum spargit lumine terras"},{"sp":"N","t":"et variae volucres nemora avia pervolitantes","st":"2.145"},{"sp":"N","t":"aera per tenerum liquidis loca vocibus opplent,"},{"sp":"N","t":"quam subito soleat sol ortus tempore tali"},{"sp":"N","t":"convestire sua perfundens omnia luce,"},{"sp":"N","t":"omnibus in promptu manifestumque esse videmus."},{"sp":"N","t":"at vapor is, quem sol mittit, lumenque serenum","st":"2.150"},{"sp":"N","t":"non per inane meat vacuum; quo tardius ire"},{"sp":"N","t":"cogitur, aerias quasi dum diverberat undas;"},{"sp":"N","t":"nec singillatim corpuscula quaeque vaporis"},{"sp":"N","t":"sed complexa meant inter se conque globata;"},{"sp":"N","t":"qua propter simul inter se retrahuntur et extra","st":"2.155"},{"sp":"N","t":"officiuntur, uti cogantur tardius ire."},{"sp":"N","t":"at quae sunt solida primordia simplicitate,"},{"sp":"N","t":"cum per inane meant vacuum nec res remoratur"},{"sp":"N","t":"ulla foris atque ipsa suis e partibus unum,"},{"sp":"N","t":"unum, in quem coepere, locum conixa feruntur,","st":"2.160"},{"sp":"N","t":"debent ni mirum praecellere mobilitate"},{"sp":"N","t":"et multo citius ferri quam lumina solis"},{"sp":"N","t":"multiplexque loci spatium transcurrere eodem"},{"sp":"N","t":"tempore quo solis pervolgant fulgura caelum."},{"sp":"N","t":"* * *"},{"sp":"N","t":"nec persectari primordia singula quaeque,","st":"2.165"},{"sp":"N","t":"ut videant qua quicque geratur cum ratione."},{"sp":"N","t":"At quidam contra haec, ignari materiai,"},{"sp":"N","t":"naturam non posse deum sine numine reddunt"},{"sp":"N","t":"tanto opere humanis rationibus atmoderate"},{"sp":"N","t":"tempora mutare annorum frugesque creare","st":"2.170"},{"sp":"N","t":"et iam cetera, mortalis quae suadet adire"},{"sp":"N","t":"ipsaque deducit dux vitae dia voluptas"},{"sp":"N","t":"et res per Veneris blanditur saecla propagent,"},{"sp":"N","t":"ne genus occidat humanum. quorum omnia causa"},{"sp":"N","t":"constituisse deos cum fingunt, omnibus rebus","st":"2.175"},{"sp":"N","t":"magno opere a vera lapsi ratione videntur."},{"sp":"N","t":"nam quamvis rerum ignorem primordia quae sint,"},{"sp":"N","t":"hoc tamen ex ipsis caeli rationibus ausim"},{"sp":"N","t":"confirmare aliisque ex rebus reddere multis,"},{"sp":"N","t":"nequaquam nobis divinitus esse creatam","st":"2.180"},{"sp":"N","t":"naturam mundi: tanta stat praedita culpa."},{"sp":"N","t":"quae tibi posterius, Memmi, faciemus aperta;"},{"sp":"N","t":"nunc id quod super est de motibus expediemus."},{"sp":"N","t":"Nunc locus est, ut opinor, in his illud quoque rebus"},{"sp":"N","t":"confirmare tibi, nullam rem posse sua vi","st":"2.185"},{"sp":"N","t":"corpoream sursum ferri sursumque meare."},{"sp":"N","t":"ne tibi dent in eo flammarum corpora frudem;"},{"sp":"N","t":"sursus enim versus gignuntur et augmina sumunt"},{"sp":"N","t":"et sursum nitidae fruges arbustaque crescunt,"},{"sp":"N","t":"pondera, quantum in se est, cum deorsum cuncta ferantur.","st":"2.190"},{"sp":"N","t":"nec cum subsiliunt ignes ad tecta domorum"},{"sp":"N","t":"et celeri flamma degustant tigna trabesque,"},{"sp":"N","t":"sponte sua facere id sine vi subiecta putandum est."},{"sp":"N","t":"quod genus e nostro com missus corpore sanguis"},{"sp":"N","t":"emicat exultans alte spargitque cruorem.","st":"2.195"},{"sp":"N","t":"nonne vides etiam quanta vi tigna trabesque"},{"sp":"N","t":"respuat umor aquae? nam quo magis ursimus altum"},{"sp":"N","t":"derecta et magna vi multi pressimus aegre,"},{"sp":"N","t":"tam cupide sursum removet magis atque remittit,"},{"sp":"N","t":"plus ut parte foras emergant exiliantque.","st":"2.200"},{"sp":"N","t":"nec tamen haec, quantum est in se, dubitamus, opinor,"},{"sp":"N","t":"quin vacuum per inane deorsum cuncta ferantur."},{"sp":"N","t":"sic igitur debent flammae quoque posse per auras"},{"sp":"N","t":"aeris expressae sursum succedere, quamquam"},{"sp":"N","t":"pondera, quantum in se est, deorsum deducere pugnent.","st":"2.205"},{"sp":"N","t":"nocturnasque faces caeli sublime volantis"},{"sp":"N","t":"nonne vides longos flammarum ducere tractus"},{"sp":"N","t":"in quas cumque dedit partis natura meatum?"},{"sp":"N","t":"non cadere in terras stellas et sidera cernis?"},{"sp":"N","t":"sol etiam caeli de vertice dissipat omnis","st":"2.210"},{"sp":"N","t":"ardorem in partis et lumine conserit arva;"},{"sp":"N","t":"in terras igitur quoque solis vergitur ardor."},{"sp":"N","t":"transversosque volare per imbris fulmina cernis,"},{"sp":"N","t":"nunc hinc nunc illinc abrupti nubibus ignes"},{"sp":"N","t":"concursant; cadit in terras vis flammea volgo.","st":"2.215"},{"sp":"N","t":"Illud in his quoque te rebus cognoscere avemus,"},{"sp":"N","t":"corpora cum deorsum rectum per inane feruntur"},{"sp":"N","t":"ponderibus propriis, incerto tempore ferme"},{"sp":"N","t":"incertisque locis spatio depellere paulum,"},{"sp":"N","t":"tantum quod momen mutatum dicere possis.","st":"2.220"},{"sp":"N","t":"quod nisi declinare solerent, omnia deorsum"},{"sp":"N","t":"imbris uti guttae caderent per inane profundum"},{"sp":"N","t":"nec foret offensus natus nec plaga creata"},{"sp":"N","t":"principiis; ita nihil umquam natura creasset."},{"sp":"N","t":"Quod si forte aliquis credit graviora potesse","st":"2.225"},{"sp":"N","t":"corpora, quo citius rectum per inane feruntur,"},{"sp":"N","t":"incidere ex supero levioribus atque ita plagas"},{"sp":"N","t":"gignere, quae possint genitalis reddere motus,"},{"sp":"N","t":"avius a vera longe ratione recedit."},{"sp":"N","t":"nam per aquas quae cumque cadunt atque aera rarum,","st":"2.230"},{"sp":"N","t":"haec pro ponderibus casus celerare necessest"},{"sp":"N","t":"propterea quia corpus aquae naturaque tenvis"},{"sp":"N","t":"aeris haud possunt aeque rem quamque morari,"},{"sp":"N","t":"sed citius cedunt gravioribus exsuperata;"},{"sp":"N","t":"at contra nulli de nulla parte neque ullo","st":"2.235"},{"sp":"N","t":"tempore inane potest vacuum subsistere rei,"},{"sp":"N","t":"quin, sua quod natura petit, concedere pergat;"},{"sp":"N","t":"omnia qua propter debent per inane quietum"},{"sp":"N","t":"aeque ponderibus non aequis concita ferri."},{"sp":"N","t":"haud igitur poterunt levioribus incidere umquam","st":"2.240"},{"sp":"N","t":"ex supero graviora neque ictus gignere per se,"},{"sp":"N","t":"qui varient motus, per quos natura gerat res."},{"sp":"N","t":"quare etiam atque etiam paulum inclinare necessest"},{"sp":"N","t":"corpora; nec plus quam minimum, ne fingere motus"},{"sp":"N","t":"obliquos videamur et id res vera refutet.","st":"2.245"},{"sp":"N","t":"namque hoc in promptu manifestumque esse videmus,"},{"sp":"N","t":"pondera, quantum in se est, non posse obliqua meare,"},{"sp":"N","t":"ex supero cum praecipitant, quod cernere possis;"},{"sp":"N","t":"sed nihil omnino recta regione viai"},{"sp":"N","t":"declinare quis est qui possit cernere sese?","st":"2.250"},{"sp":"N","t":"Denique si semper motu conectitur omnis"},{"sp":"N","t":"et vetere exoritur motus novus ordine certo"},{"sp":"N","t":"nec declinando faciunt primordia motus"},{"sp":"N","t":"principium quoddam, quod fati foedera rumpat,"},{"sp":"N","t":"ex infinito ne causam causa sequatur,","st":"2.255"},{"sp":"N","t":"libera per terras unde haec animantibus exstat,"},{"sp":"N","t":"unde est haec, inquam, fatis avolsa voluntas,"},{"sp":"N","t":"per quam progredimur quo ducit quemque voluptas,"},{"sp":"N","t":"declinamus item motus nec tempore certo"},{"sp":"N","t":"nec regione loci certa, sed ubi ipsa tulit mens?","st":"2.260"},{"sp":"N","t":"nam dubio procul his rebus sua cuique voluntas"},{"sp":"N","t":"principium dat et hinc motus per membra rigantur."},{"sp":"N","t":"nonne vides etiam patefactis tempore puncto"},{"sp":"N","t":"carceribus non posse tamen prorumpere equorum"},{"sp":"N","t":"vim cupidam tam de subito quam mens avet ipsa?","st":"2.265"},{"sp":"N","t":"omnis enim totum per corpus materiai"},{"sp":"N","t":"copia conciri debet, concita per artus"},{"sp":"N","t":"omnis ut studium mentis conixa sequatur;"},{"sp":"N","t":"ut videas initum motus a corde creari"},{"sp":"N","t":"ex animique voluntate id procedere primum,","st":"2.270"},{"sp":"N","t":"inde dari porro per totum corpus et artus."},{"sp":"N","t":"nec similest ut cum inpulsi procedimus ictu"},{"sp":"N","t":"viribus alterius magnis magnoque coactu;"},{"sp":"N","t":"nam tum materiem totius corporis omnem"},{"sp":"N","t":"perspicuumst nobis invitis ire rapique,","st":"2.275"},{"sp":"N","t":"donec eam refrenavit per membra voluntas."},{"sp":"N","t":"iamne vides igitur, quamquam vis extera multos"},{"sp":"N","t":"pellat et invitos cogat procedere saepe"},{"sp":"N","t":"praecipitesque rapi, tamen esse in pectore nostro"},{"sp":"N","t":"quiddam quod contra pugnare obstareque possit?","st":"2.280"},{"sp":"N","t":"cuius ad arbitrium quoque copia materiai"},{"sp":"N","t":"cogitur inter dum flecti per membra per artus"},{"sp":"N","t":"et proiecta refrenatur retroque residit."},{"sp":"N","t":"quare in seminibus quoque idem fateare necessest,"},{"sp":"N","t":"esse aliam praeter plagas et pondera causam","st":"2.285"},{"sp":"N","t":"motibus, unde haec est nobis innata potestas,"},{"sp":"N","t":"de nihilo quoniam fieri nihil posse videmus."},{"sp":"N","t":"pondus enim prohibet ne plagis omnia fiant"},{"sp":"N","t":"externa quasi vi; sed ne res ipsa necessum"},{"sp":"N","t":"intestinum habeat cunctis in rebus agendis","st":"2.290"},{"sp":"N","t":"et devicta quasi cogatur ferre patique,"},{"sp":"N","t":"id facit exiguum clinamen principiorum"},{"sp":"N","t":"nec regione loci certa nec tempore certo."},{"sp":"N","t":"Nec stipata magis fuit umquam materiai"},{"sp":"N","t":"copia nec porro maioribus intervallis;","st":"2.295"},{"sp":"N","t":"nam neque adaugescit quicquam neque deperit inde."},{"sp":"N","t":"qua propter quo nunc in motu principiorum"},{"sp":"N","t":"corpora sunt, in eodem ante acta aetate fuere"},{"sp":"N","t":"et post haec semper simili ratione ferentur,"},{"sp":"N","t":"et quae consuerint gigni gignentur eadem","st":"2.300"},{"sp":"N","t":"condicione et erunt et crescent vique valebunt,"},{"sp":"N","t":"quantum cuique datum est per foedera naturai."},{"sp":"N","t":"nec rerum summam commutare ulla potest vis;"},{"sp":"N","t":"nam neque quo possit genus ullum materiai"},{"sp":"N","t":"effugere ex omni quicquam est extra, neque in omne","st":"2.305"},{"sp":"N","t":"unde coorta queat nova vis inrumpere et omnem"},{"sp":"N","t":"naturam rerum mutare et vertere motus."},{"sp":"N","t":"Illud in his rebus non est mirabile, quare,"},{"sp":"N","t":"omnia cum rerum primordia sint in motu,"},{"sp":"N","t":"summa tamen summa videatur stare quiete,","st":"2.310"},{"sp":"N","t":"praeter quam siquid proprio dat corpore motus."},{"sp":"N","t":"omnis enim longe nostris ab sensibus infra"},{"sp":"N","t":"primorum natura iacet; qua propter, ubi ipsa"},{"sp":"N","t":"cernere iam nequeas, motus quoque surpere debent;"},{"sp":"N","t":"praesertim cum, quae possimus cernere, celent","st":"2.315"},{"sp":"N","t":"saepe tamen motus spatio diducta locorum."},{"sp":"N","t":"nam saepe in colli tondentes pabula laeta"},{"sp":"N","t":"lanigerae reptant pecudes, quo quamque vocantes"},{"sp":"N","t":"invitant herbae gemmantes rore recenti,"},{"sp":"N","t":"et satiati agni ludunt blandeque coruscant;","st":"2.320"},{"sp":"N","t":"omnia quae nobis longe confusa videntur"},{"sp":"N","t":"et velut in viridi candor consistere colli."},{"sp":"N","t":"praeterea magnae legiones cum loca cursu"},{"sp":"N","t":"camporum complent belli simulacra cientes,"},{"sp":"N","t":"fulgor ubi ad caelum se tollit totaque circum","st":"2.325"},{"sp":"N","t":"aere renidescit tellus supterque virum vi"},{"sp":"N","t":"excitur pedibus sonitus clamoreque montes"},{"sp":"N","t":"icti reiectant voces ad sidera mundi"},{"sp":"N","t":"et circum volitant equites mediosque repente"},{"sp":"N","t":"tramittunt valido quatientes impete campos;","st":"2.330"},{"sp":"N","t":"et tamen est quidam locus altis montibus, unde"},{"sp":"N","t":"stare videntur et in campis consistere fulgor."},{"sp":"N","t":"Nunc age, iam deinceps cunctarum exordia rerum"},{"sp":"N","t":"qualia sint et quam longe distantia formis,"},{"sp":"N","t":"percipe, multigenis quam sint variata figuris;","st":"2.335"},{"sp":"N","t":"non quo multa parum simili sint praedita forma,"},{"sp":"N","t":"sed quia non volgo paria omnibus omnia constant."},{"sp":"N","t":"nec mirum; nam cum sit eorum copia tanta,"},{"sp":"N","t":"ut neque finis, uti docui, neque summa sit ulla,"},{"sp":"N","t":"debent ni mirum non omnibus omnia prorsum","st":"2.340"},{"sp":"N","t":"esse pari filo similique adfecta figura."},{"sp":"N","t":"Praeterea genus humanum mutaeque natantes"},{"sp":"N","t":"squamigerum pecudes et laeta armenta feraeque"},{"sp":"N","t":"et variae volucres, laetantia quae loca aquarum"},{"sp":"N","t":"concelebrant circum ripas fontisque lacusque,","st":"2.345"},{"sp":"N","t":"et quae pervolgant nemora avia pervolitantes,"},{"sp":"N","t":"quorum unum quidvis generatim sumere perge;"},{"sp":"N","t":"invenies tamen inter se differre figuris."},{"sp":"N","t":"nec ratione alia proles cognoscere matrem"},{"sp":"N","t":"nec mater posset prolem; quod posse videmus","st":"2.350"},{"sp":"N","t":"nec minus atque homines inter se nota cluere."},{"sp":"N","t":"nam saepe ante deum vitulus delubra decora"},{"sp":"N","t":"turicremas propter mactatus concidit aras"},{"sp":"N","t":"sanguinis expirans calidum de pectore flumen;"},{"sp":"N","t":"at mater viridis saltus orbata peragrans","st":"2.355"},{"sp":"N","t":"novit humi pedibus vestigia pressa bisulcis,"},{"sp":"N","t":"omnia convisens oculis loca, si queat usquam"},{"sp":"N","t":"conspicere amissum fetum, completque querellis"},{"sp":"N","t":"frondiferum nemus adsistens et crebra revisit"},{"sp":"N","t":"ad stabulum desiderio perfixa iuvenci,","st":"2.360"},{"sp":"N","t":"nec tenerae salices atque herbae rore vigentes"},{"sp":"N","t":"fluminaque ulla queunt summis labentia ripis"},{"sp":"N","t":"oblectare animum subitamque avertere curam,"},{"sp":"N","t":"nec vitulorum aliae species per pabula laeta"},{"sp":"N","t":"derivare queunt animum curaque levare;","st":"2.365"},{"sp":"N","t":"usque adeo quiddam proprium notumque requirit."},{"sp":"N","t":"praeterea teneri tremulis cum vocibus haedi"},{"sp":"N","t":"cornigeras norunt matres agnique petulci"},{"sp":"N","t":"balantum pecudes; ita, quod natura resposcit,"},{"sp":"N","t":"ad sua quisque fere decurrunt ubera lactis.","st":"2.370"},{"sp":"N","t":"Postremo quodvis frumentum non tamen omne"},{"sp":"N","t":"quidque suo genere inter se simile esse videbis,"},{"sp":"N","t":"quin intercurrat quaedam distantia formis."},{"sp":"N","t":"concharumque genus parili ratione videmus"},{"sp":"N","t":"pingere telluris gremium, qua mollibus undis","st":"2.375"},{"sp":"N","t":"litoris incurvi bibulam pavit aequor harenam."},{"sp":"N","t":"quare etiam atque etiam simili ratione necessest,"},{"sp":"N","t":"natura quoniam constant neque facta manu sunt"},{"sp":"N","t":"unius ad certam formam primordia rerum,"},{"sp":"N","t":"dissimili inter se quaedam volitare figura.","st":"2.380"},{"sp":"N","t":"Perfacile est animi ratione exsolvere nobis"},{"sp":"N","t":"quare fulmineus multo penetralior ignis"},{"sp":"N","t":"quam noster fluat e taedis terrestribus ortus;"},{"sp":"N","t":"dicere enim possis caelestem fulminis ignem"},{"sp":"N","t":"subtilem magis e parvis constare figuris","st":"2.385"},{"sp":"N","t":"atque ideo transire foramina quae nequit ignis"},{"sp":"N","t":"noster hic e lignis ortus taedaque creatus."},{"sp":"N","t":"praeterea lumen per cornum transit, at imber"},{"sp":"N","t":"respuitur. quare, nisi luminis illa minora"},{"sp":"N","t":"corpora sunt quam de quibus est liquor almus aquarum?","st":"2.390"},{"sp":"N","t":"et quamvis subito per colum vina videmus"},{"sp":"N","t":"perfluere, at contra tardum cunctatur olivom,"},{"sp":"N","t":"aut quia ni mirum maioribus est elementis"},{"sp":"N","t":"aut magis hamatis inter se perque plicatis,"},{"sp":"N","t":"atque ideo fit uti non tam diducta repente","st":"2.395"},{"sp":"N","t":"inter se possint primordia singula quaeque"},{"sp":"N","t":"singula per cuiusque foramina permanare."},{"sp":"N","t":"Huc accedit uti mellis lactisque liquores"},{"sp":"N","t":"iucundo sensu linguae tractentur in ore;"},{"sp":"N","t":"at contra taetra absinthi natura ferique","st":"2.400"},{"sp":"N","t":"centauri foedo pertorquent ora sapore;"},{"sp":"N","t":"ut facile agnoscas e levibus atque rutundis"},{"sp":"N","t":"esse ea quae sensus iucunde tangere possunt,"},{"sp":"N","t":"at contra quae amara atque aspera cumque videntur,"},{"sp":"N","t":"haec magis hamatis inter se nexa teneri","st":"2.405"},{"sp":"N","t":"proptereaque solere vias rescindere nostris"},{"sp":"N","t":"sensibus introituque suo perrumpere corpus."},{"sp":"N","t":"omnia postremo bona sensibus et mala tactu"},{"sp":"N","t":"dissimili inter se pugnant perfecta figura;"},{"sp":"N","t":"ne tu forte putes serrae stridentis acerbum","st":"2.410"},{"sp":"N","t":"horrorem constare elementis levibus aeque"},{"sp":"N","t":"ac musaea mele, per chordas organici quae"},{"sp":"N","t":"mobilibus digitis expergefacta figurant;"},{"sp":"N","t":"neu simili penetrare putes primordia forma"},{"sp":"N","t":"in nares hominum, cum taetra cadavera torrent,","st":"2.415"},{"sp":"N","t":"et cum scena croco Cilici perfusa recens est"},{"sp":"N","t":"araque Panchaeos exhalat propter odores;"},{"sp":"N","t":"neve bonos rerum simili constare colores"},{"sp":"N","t":"semine constituas, oculos qui pascere possunt,"},{"sp":"N","t":"et qui conpungunt aciem lacrimareque cogunt","st":"2.420"},{"sp":"N","t":"aut foeda specie foedi turpesque videntur."},{"sp":"N","t":"omnis enim, sensus quae mulcet cumque, tibi res"},{"sp":"N","t":"haut sine principiali aliquo levore creatast;"},{"sp":"N","t":"at contra quae cumque molesta atque aspera constat,"},{"sp":"N","t":"non aliquo sine materiae squalore repertast.","st":"2.425"},{"sp":"N","t":"Sunt etiam quae iam nec levia iure putantur"},{"sp":"N","t":"esse neque omnino flexis mucronibus unca,"},{"sp":"N","t":"sed magis angellis paulum prostantibus, ut quae"},{"sp":"N","t":"titillare magis sensus quam laedere possint,"},{"sp":"N","t":"fecula iam quo de genere est inulaeque sapores.","st":"2.430"},{"sp":"N","t":"Denique iam calidos ignis gelidamque pruinam"},{"sp":"N","t":"dissimili dentata modo conpungere sensus"},{"sp":"N","t":"corporis, indicio nobis est tactus uterque."},{"sp":"N","t":"tactus enim, tactus, pro divum numina sancta,"},{"sp":"N","t":"corporis est sensus, vel cum res extera sese","st":"2.435"},{"sp":"N","t":"insinuat, vel cum laedit quae in corpore natast"},{"sp":"N","t":"aut iuvat egrediens genitalis per Veneris res,"},{"sp":"N","t":"aut ex offensu cum turbant corpore in ipso,"},{"sp":"N","t":"semina confundunt inter se concita sensum;"},{"sp":"N","t":"ut si forte manu quamvis iam corporis ipse","st":"2.440"},{"sp":"N","t":"tute tibi partem ferias atque experiare."},{"sp":"N","t":"qua propter longe formas distare necessest"},{"sp":"N","t":"principiis, varios quae possint edere sensus."},{"sp":"N","t":"Denique quae nobis durata ac spissa videntur,"},{"sp":"N","t":"haec magis hamatis inter sese esse necessest","st":"2.445"},{"sp":"N","t":"et quasi ramosis alte compacta teneri."},{"sp":"N","t":"in quo iam genere in primis adamantina saxa"},{"sp":"N","t":"prima acie constant ictus contemnere sueta"},{"sp":"N","t":"et validi silices ac duri robora ferri"},{"sp":"N","t":"aeraque quae claustris restantia vociferantur.","st":"2.450"},{"sp":"N","t":"illa quidem debent e levibus atque rutundis"},{"sp":"N","t":"esse magis, fluvido quae corpore liquida constant."},{"sp":"N","t":"namque papaveris haustus itemst facilis quod aquarum;"},{"sp":"N","t":"nec retinentur enim inter se glomeramina quaeque"},{"sp":"N","t":"et perculsus item proclive volubilis exstat.","st":"2.455"},{"sp":"N","t":"omnia postremo quae puncto tempore cernis"},{"sp":"N","t":"diffugere ut fumum nebulas flammasque, necessest,"},{"sp":"N","t":"si minus omnia sunt e levibus atque rotundis,"},{"sp":"N","t":"at non esse tamen perplexis indupedita,"},{"sp":"N","t":"pungere uti possint corpus penetrareque saxa,","st":"2.460"},{"sp":"N","t":"nec tamen haerere inter se; quod cumque videmus"},{"sp":"N","t":"sensibus dentatum, facile ut cognoscere possis"},{"sp":"N","t":"non e perplexis, sed acutis esse elementis."},{"sp":"N","t":"sed quod amara vides eadem quae fluvida constant,"},{"sp":"N","t":"sudor uti maris est, minime mirabile debet","st":"2.465"},{"sp":"N","t":"* * *"},{"sp":"N","t":"nam quod fluvidus est, e levibus atque rotundis"},{"sp":"N","t":"est, sed levibus sunt hamata admixta doloris"},{"sp":"N","t":"corpora. nec tamen haec retineri hamata necessust:"},{"sp":"N","t":"scilicet esse globosa tamen, cum squalida constent,"},{"sp":"N","t":"provolvi simul ut possint et laedere sensus.","st":"2.470"},{"sp":"N","t":"et quo mixta putes magis aspera levibus esse"},{"sp":"N","t":"principiis, unde est Neptuni corpus acerbum,"},{"sp":"N","t":"est ratio secernendi seorsumque videndi,"},{"sp":"N","t":"umor dulcis ubi per terras crebrius idem"},{"sp":"N","t":"percolatur, ut in foveam fluat ac mansuescat;","st":"2.475"},{"sp":"N","t":"linquit enim supera taetri primordia viri,"},{"sp":"N","t":"aspera quo magis in terris haerescere possint."},{"sp":"N","t":"Quod quoniam docui, pergam conectere rem quae"},{"sp":"N","t":"ex hoc apta fidem ducat, primordia rerum"},{"sp":"N","t":"finita variare figurarum ratione.","st":"2.480"},{"sp":"N","t":"quod si non ita sit, rursum iam semina quaedam"},{"sp":"N","t":"esse infinito debebunt corporis auctu."},{"sp":"N","t":"namque in eadem una cuiusvis iam brevitate"},{"sp":"N","t":"corporis inter se multum variare figurae"},{"sp":"N","t":"non possunt. fac enim minimis e partibus esse","st":"2.485"},{"sp":"N","t":"corpora prima tribus, vel paulo pluribus auge;"},{"sp":"N","t":"nempe ubi eas partis unius corporis omnis,"},{"sp":"N","t":"summa atque ima locans, transmutans dextera laevis,"},{"sp":"N","t":"omnimodis expertus eris, quam quisque det ordo"},{"sp":"N","t":"formai speciem totius corporis eius,","st":"2.490"},{"sp":"N","t":"quod super est, si forte voles variare figuras,"},{"sp":"N","t":"addendum partis alias erit. inde sequetur,"},{"sp":"N","t":"adsimili ratione alias ut postulet ordo,"},{"sp":"N","t":"si tu forte voles etiam variare figuras."},{"sp":"N","t":"ergo formarum novitatem corporis augmen","st":"2.495"},{"sp":"N","t":"subsequitur. quare non est ut credere possis"},{"sp":"N","t":"esse infinitis distantia semina formis,"},{"sp":"N","t":"ne quaedam cogas inmani maximitate"},{"sp":"N","t":"esse, supra quod iam docui non posse probari."},{"sp":"N","t":"iam tibi barbaricae vestes Meliboeaque fulgens","st":"2.500"},{"sp":"N","t":"purpura Thessalico concharum tacta colore,"},{"sp":"N","t":"aurea pavonum ridenti imbuta lepore"},{"sp":"N","t":"saecla novo rerum superata colore iacerent"},{"sp":"N","t":"et contemptus odor smyrnae mellisque sapores,"},{"sp":"N","t":"et cycnea mele Phoebeaque daedala chordis","st":"2.505"},{"sp":"N","t":"carmina consimili ratione oppressa silerent;"},{"sp":"N","t":"namque aliis aliud praestantius exoreretur."},{"sp":"N","t":"cedere item retro possent in deteriores"},{"sp":"N","t":"omnia sic partis, ut diximus in melioris;"},{"sp":"N","t":"namque aliis aliud retro quoque taetrius esset","st":"2.510"},{"sp":"N","t":"naribus auribus atque oculis orisque sapori."},{"sp":"N","t":"quae quoniam non sunt, sed rebus reddita certa"},{"sp":"N","t":"finis utrimque tenet summam, fateare necessest"},{"sp":"N","t":"materiem quoque finitis differe figuris."},{"sp":"N","t":"denique ab ignibus ad gelidas hiemum usque pruinas","st":"2.515"},{"sp":"N","t":"finitumst retroque pari ratione remensumst."},{"sp":"N","t":"omnis enim calor ac frigus mediique tepores"},{"sp":"N","t":"interutrasque iacent explentes ordine summam."},{"sp":"N","t":"ergo finita distant ratione creata,"},{"sp":"N","t":"ancipiti quoniam mucroni utrimque notantur,","st":"2.520"},{"sp":"N","t":"hinc flammis illinc rigidis infesta pruinis."},{"sp":"N","t":"Quod quoniam docui, pergam conectere rem quae"},{"sp":"N","t":"ex hoc apta fidem ducat, primordia rerum,"},{"sp":"N","t":"inter se simili quae sunt perfecta figura,"},{"sp":"N","t":"infinita cluere. etenim distantia cum sit","st":"2.525"},{"sp":"N","t":"formarum finita, necesse est quae similes sint"},{"sp":"N","t":"esse infinitas aut summam materiai"},{"sp":"N","t":"finitam constare, id quod non esse probavi."},{"sp":"N","t":"* * *"},{"sp":"N","t":"versibus ostendam corpuscula materiai"},{"sp":"N","t":"ex infinito summam rerum usque tenere","st":"2.530"},{"sp":"N","t":"undique protelo plagarum continuato."},{"sp":"N","t":"nam quod rara vides magis esse animalia quaedam"},{"sp":"N","t":"fecundamque magis naturam cernis in illis,"},{"sp":"N","t":"at regione locoque alio terrisque remotis"},{"sp":"N","t":"multa licet genere esse in eo numerumque repleri;","st":"2.535"},{"sp":"N","t":"sicut quadripedum cum primis esse videmus"},{"sp":"N","t":"in genere anguimanus elephantos, India quorum"},{"sp":"N","t":"milibus e multis vallo munitur eburno,"},{"sp":"N","t":"ut penitus nequeat penetrari: tanta ferarum"},{"sp":"N","t":"vis est, quarum nos perpauca exempla videmus.","st":"2.540"},{"sp":"N","t":"sed tamen id quoque uti concedam, quam lubet esto"},{"sp":"N","t":"unica res quaedem nativo corpore sola,"},{"sp":"N","t":"cui similis toto terrarum non sit, in orbi;"},{"sp":"N","t":"infinita tamen nisi erit vis materiai,"},{"sp":"N","t":"unde ea progigni possit concepta, creari","st":"2.545"},{"sp":"N","t":"non poterit neque, quod super est, procrescere alique."},{"sp":"N","t":"quippe etenim sumant alii finita per omne"},{"sp":"N","t":"corpora iactari unius genitalia rei,"},{"sp":"N","t":"unde ubi qua vi et quo pacto congressa coibunt"},{"sp":"N","t":"materiae tanto in pelago turbaque aliena?","st":"2.550"},{"sp":"N","t":"non, ut opinor, habent rationem conciliandi:"},{"sp":"N","t":"sed quasi naufragiis magnis multisque coortis"},{"sp":"N","t":"disiactare solet magnum mare transtra cavernas"},{"sp":"N","t":"antemnas prorem malos tonsasque natantis,"},{"sp":"N","t":"per terrarum omnis oras fluitantia aplustra","st":"2.555"},{"sp":"N","t":"ut videantur et indicium mortalibus edant,"},{"sp":"N","t":"infidi maris insidias virisque dolumque"},{"sp":"N","t":"ut vitare velint, neve ullo tempore credant,"},{"sp":"N","t":"subdola cum ridet placidi pellacia ponti,"},{"sp":"N","t":"sic tibi si finita semel primordia quaedam","st":"2.560"},{"sp":"N","t":"constitues, aevom debebunt sparsa per omnem"},{"sp":"N","t":"disiectare aestus diversi materiai,"},{"sp":"N","t":"numquam in concilium ut possint compulsa coire"},{"sp":"N","t":"nec remorari in concilio nec crescere adaucta;"},{"sp":"N","t":"quorum utrumque palam fieri manifesta docet res,","st":"2.565"},{"sp":"N","t":"et res progigni et genitas procrescere posse."},{"sp":"N","t":"esse igitur genere in quovis primordia rerum"},{"sp":"N","t":"infinita palam est, unde omnia suppeditantur."},{"sp":"N","t":"Nec superare queunt motus itaque exitiales"},{"sp":"N","t":"perpetuo neque in aeternum sepelire salutem,","st":"2.570"},{"sp":"N","t":"nec porro rerum genitales auctificique"},{"sp":"N","t":"motus perpetuo possunt servare creata."},{"sp":"N","t":"sic aequo geritur certamine principiorum"},{"sp":"N","t":"ex infinito contractum tempore bellum."},{"sp":"N","t":"nunc hic nunc illic superant vitalia rerum","st":"2.575"},{"sp":"N","t":"et superantur item. miscetur funere vagor,"},{"sp":"N","t":"quem pueri tollunt visentis luminis oras;"},{"sp":"N","t":"nec nox ulla diem neque noctem aurora secutast,"},{"sp":"N","t":"quae non audierit mixtos vagitibus aegris"},{"sp":"N","t":"ploratus, mortis comites et funeris atri.","st":"2.580"},{"sp":"N","t":"Illud in his obsignatum quoque rebus habere"},{"sp":"N","t":"convenit et memori mandatum mente tenere,"},{"sp":"N","t":"nil esse, in promptu quorum natura videtur,"},{"sp":"N","t":"quod genere ex uno consistat principiorum,"},{"sp":"N","t":"nec quicquam quod non permixto semine constet.","st":"2.585"},{"sp":"N","t":"et quod cumque magis vis multas possidet in se"},{"sp":"N","t":"atque potestates, ita plurima principiorum"},{"sp":"N","t":"in sese genera ac varias docet esse figuras."},{"sp":"N","t":"Principio tellus habet in se corpora prima,"},{"sp":"N","t":"unde mare inmensum volventes frigora fontes","st":"2.590"},{"sp":"N","t":"adsidue renovent, habet ignes unde oriantur;"},{"sp":"N","t":"nam multis succensa locis ardent sola terrae,"},{"sp":"N","t":"ex imis vero furit ignibus impetus Aetnae."},{"sp":"N","t":"tum porro nitidas fruges arbustaque laeta"},{"sp":"N","t":"gentibus humanis habet unde extollere possit,","st":"2.595"},{"sp":"N","t":"unde etiam fluvios frondes et pabula laeta"},{"sp":"N","t":"montivago generi possit praebere ferarum."},{"sp":"N","t":"quare magna deum mater materque ferarum"},{"sp":"N","t":"et nostri genetrix haec dicta est corporis una."},{"sp":"N","t":"Hanc veteres Graium docti cecinere poetae","st":"2.600"},{"sp":"N","t":"sedibus in curru biiugos agitare leones,"},{"sp":"N","t":"aeris in spatio magnam pendere docentes"},{"sp":"N","t":"tellurem neque posse in terra sistere terram."},{"sp":"N","t":"adiunxere feras, quia quamvis effera proles"},{"sp":"N","t":"officiis debet molliri victa parentum.","st":"2.605"},{"sp":"N","t":"muralique caput summum cinxere corona,"},{"sp":"N","t":"eximiis munita locis quia sustinet urbes."},{"sp":"N","t":"quo nunc insigni per magnas praedita terras"},{"sp":"N","t":"horrifice fertur divinae matris imago."},{"sp":"N","t":"hanc variae gentes antiquo more sacrorum","st":"2.610"},{"sp":"N","t":"Idaeam vocitant matrem Phrygiasque catervas"},{"sp":"N","t":"dant comites, quia primum ex illis finibus edunt"},{"sp":"N","t":"per terrarum orbes fruges coepisse creari."},{"sp":"N","t":"Gallos attribuunt, quia, numen qui violarint"},{"sp":"N","t":"Matris et ingrati genitoribus inventi sint,","st":"2.615"},{"sp":"N","t":"significare volunt indignos esse putandos,"},{"sp":"N","t":"vivam progeniem qui in oras luminis edant."},{"sp":"N","t":"tympana tenta tonant palmis et cymbala circum"},{"sp":"N","t":"concava, raucisonoque minantur cornua cantu,"},{"sp":"N","t":"et Phrygio stimulat numero cava tibia mentis,","st":"2.620"},{"sp":"N","t":"telaque praeportant, violenti signa furoris,"},{"sp":"N","t":"ingratos animos atque impia pectora volgi"},{"sp":"N","t":"conterrere metu quae possint numine divae."},{"sp":"N","t":"ergo cum primum magnas invecta per urbis"},{"sp":"N","t":"munificat tacita mortalis muta salute,","st":"2.625"},{"sp":"N","t":"aere atque argento sternunt iter omne viarum"},{"sp":"N","t":"largifica stipe ditantes ninguntque rosarum"},{"sp":"N","t":"floribus umbrantes matrem comitumque catervam."},{"sp":"N","t":"hic armata manus, Curetas nomine Grai"},{"sp":"N","t":"quos memorant, Phrygias inter si forte catervas","st":"2.630"},{"sp":"N","t":"ludunt in numerumque exultant sanguine laeti"},{"sp":"N","t":"terrificas capitum quatientes numine cristas,"},{"sp":"N","t":"Dictaeos referunt Curetas, qui Iovis illum"},{"sp":"N","t":"vagitum in Creta quondam occultasse feruntur,"},{"sp":"N","t":"cum pueri circum puerum pernice chorea","st":"2.635"},{"sp":"N","t":"armat et in numerum pernice chorea"},{"sp":"N","t":"armati in numerum pulsarent aeribus aera,"},{"sp":"N","t":"ne Saturnus eum malis mandaret adeptus"},{"sp":"N","t":"aeternumque daret matri sub pectore volnus."},{"sp":"N","t":"propterea magnam armati matrem comitantur,","st":"2.640"},{"sp":"N","t":"aut quia significant divam praedicere ut armis"},{"sp":"N","t":"ac virtute velint patriam defendere terram"},{"sp":"N","t":"praesidioque parent decorique parentibus esse."},{"sp":"N","t":"quae bene et eximie quamvis disposta ferantur,"},{"sp":"N","t":"longe sunt tamen a vera ratione repulsa.","st":"2.645"},{"sp":"N","t":"omnis enim per se divom natura necessest"},{"sp":"N","t":"inmortali aevo summa cum pace fruatur"},{"sp":"N","t":"semota ab nostris rebus seiunctaque longe;"},{"sp":"N","t":"nam privata dolore omni, privata periclis,"},{"sp":"N","t":"ipsa suis pollens opibus, nihil indiga nostri,","st":"2.650"},{"sp":"N","t":"nec bene promeritis capitur neque tangitur ira."},{"sp":"N","t":"terra quidem vero caret omni tempore sensu,"},{"sp":"N","t":"et quia multarum potitur primordia rerum,"},{"sp":"N","t":"multa modis multis effert in lumina solis."},{"sp":"N","t":"hic siquis mare Neptunum Cereremque vocare","st":"2.655"},{"sp":"N","t":"constituet fruges et Bacchi nomine abuti"},{"sp":"N","t":"mavolt quam laticis proprium proferre vocamen,"},{"sp":"N","t":"concedamus ut hic terrarum dictitet orbem"},{"sp":"N","t":"esse deum matrem, dum vera re tamen ipse"},{"sp":"N","t":"religione animum turpi contingere parcat.","st":"2.680"},{"sp":"N","t":"Saepe itaque ex uno tondentes gramina campo","st":"2.660"},{"sp":"N","t":"lanigerae pecudes et equorum duellica proles"},{"sp":"N","t":"buceriaeque greges eodem sub tegmine caeli"},{"sp":"N","t":"ex unoque sitim sedantes flumine aquai"},{"sp":"N","t":"dissimili vivont specie retinentque parentum"},{"sp":"N","t":"naturam et mores generatim quaeque imitantur.","st":"2.665"},{"sp":"N","t":"tanta est in quovis genere herbae materiai"},{"sp":"N","t":"dissimilis ratio, tanta est in flumine quoque."},{"sp":"N","t":"Hinc porro quamvis animantem ex omnibus unam"},{"sp":"N","t":"ossa cruor venae calor umor viscera nervi"},{"sp":"N","t":"constituunt, quae sunt porro distantia longe,","st":"2.670"},{"sp":"N","t":"dissimili perfecta figura principiorum."},{"sp":"N","t":"Tum porro quae cumque igni flammata cremantur."},{"sp":"N","t":"si nil praeterea, tamen haec in corpore tradunt,"},{"sp":"N","t":"unde ignem iacere et lumen submittere possint"},{"sp":"N","t":"scintillasque agere ac late differre favillam.","st":"2.675"},{"sp":"N","t":"cetera consimili mentis ratione peragrans"},{"sp":"N","t":"invenies igitur multarum semina rerum"},{"sp":"N","t":"corpore celare et varias cohibere figuras."},{"sp":"N","t":"Denique multa vides, quibus et color et sapor una"},{"sp":"N","t":"reddita sunt cum odore in primis pleraque poma."},{"sp":"N","t":"haec igitur variis debent constare figuris;"},{"sp":"N","t":"nidor enim penetrat qua fucus non it in artus,"},{"sp":"N","t":"fucus item sorsum, sorsum sapor insinuatur"},{"sp":"N","t":"sensibus; ut noscas primis differre figuris.","st":"2.685"},{"sp":"N","t":"dissimiles igitur formae glomeramen in unum"},{"sp":"N","t":"conveniunt et res permixto semine constant."},{"sp":"N","t":"Quin etiam passim nostris in versibus ipsis"},{"sp":"N","t":"multa elementa vides multis communia verbis,"},{"sp":"N","t":"cum tamen inter se versus ac verba necesse est","st":"2.690"},{"sp":"N","t":"confiteare alia ex aliis constare elementis;"},{"sp":"N","t":"non quo multa parum communis littera currat"},{"sp":"N","t":"aut nulla inter se duo sint ex omnibus isdem,"},{"sp":"N","t":"sed quia non volgo paria omnibus omnia constant."},{"sp":"N","t":"sic aliis in rebus item communia multa","st":"2.695"},{"sp":"N","t":"multarum rerum cum sint, primordia rerum"},{"sp":"N","t":"dissimili tamen inter se consistere summa"},{"sp":"N","t":"possunt; ut merito ex aliis constare feratur"},{"sp":"N","t":"humanum genus et fruges arbustaque laeta."},{"sp":"N","t":"Nec tamen omnimodis conecti posse putandum est","st":"2.700"},{"sp":"N","t":"omnia; nam volgo fieri portenta videres,"},{"sp":"N","t":"semiferas hominum species existere et altos"},{"sp":"N","t":"inter dum ramos egigni corpore vivo"},{"sp":"N","t":"multaque conecti terrestria membra marinis,"},{"sp":"N","t":"tum flammam taetro spirantis ore Chimaeras","st":"2.705"},{"sp":"N","t":"pascere naturam per terras omniparentis."},{"sp":"N","t":"quorum nil fieri manifestum est, omnia quando"},{"sp":"N","t":"seminibus certis certa genetrice creata"},{"sp":"N","t":"conservare genus crescentia posse videmus."},{"sp":"N","t":"scilicet id certa fieri ratione necessust.","st":"2.710"},{"sp":"N","t":"nam sua cuique cibis ex omnibus intus in artus"},{"sp":"N","t":"corpora discedunt conexaque convenientis"},{"sp":"N","t":"efficiunt motus; at contra aliena videmus"},{"sp":"N","t":"reicere in terras naturam, multaque caecis"},{"sp":"N","t":"corporibus fugiunt e corpore percita plagis,","st":"2.715"},{"sp":"N","t":"quae neque conecti quoquam potuere neque intus"},{"sp":"N","t":"vitalis motus consentire atque imitari."},{"sp":"N","t":"sed ne forte putes animalia sola teneri"},{"sp":"N","t":"legibus his, quaedam ratio res terminat omnis"},{"sp":"N","t":"nam vel uti tota natura dissimiles sunt","st":"2.720"},{"sp":"N","t":"inter se genitae res quaeque, ita quamque necessest"},{"sp":"N","t":"dissimili constare figura principiorum;"},{"sp":"N","t":"non quo multa parum simili sint praedita forma,"},{"sp":"N","t":"sed quia non volgo paria omnibus omnia constant."},{"sp":"N","t":"semina cum porro distent, differre necessust","st":"2.725"},{"sp":"N","t":"intervalla vias conexus pondera plagas"},{"sp":"N","t":"concursus motus; quae non animalia solum"},{"sp":"N","t":"corpora seiungunt, sed terras ac mare totum"},{"sp":"N","t":"secernunt caelumque a terris omne retentant."},{"sp":"N","t":"Nunc age dicta meo dulci quaesita labore","st":"2.730"},{"sp":"N","t":"percipe, ne forte haec albis ex alba rearis"},{"sp":"N","t":"principiis esse, ante oculos quae candida cernis,"},{"sp":"N","t":"aut ea quae nigrant nigro de semine nata;"},{"sp":"N","t":"nive alium quemvis quae sunt inbuta colorem,"},{"sp":"N","t":"propterea gerere hunc credas, quod materiai","st":"2.735"},{"sp":"N","t":"corpora consimili sint eius tincta colore;"},{"sp":"N","t":"nullus enim color est omnino materiai"},{"sp":"N","t":"corporibus, neque par rebus neque denique dispar."},{"sp":"N","t":"in quae corpora si nullus tibi forte videtur"},{"sp":"N","t":"posse animi iniectus fieri, procul avius erras.","st":"2.740"},{"sp":"N","t":"nam cum caecigeni, solis qui lumina numquam"},{"sp":"N","t":"dispexere, tamen cognoscant corpora tactu"},{"sp":"N","t":"ex ineunte aevo nullo coniuncta colore,"},{"sp":"N","t":"scire licet nostrae quoque menti corpora posse"},{"sp":"N","t":"vorti in notitiam nullo circum lita fuco.","st":"2.745"},{"sp":"N","t":"denique nos ipsi caecis quaecumque tenebris"},{"sp":"N","t":"tangimus, haud ullo sentimus tincta colore."},{"sp":"N","t":"Quod quoniam vinco fieri, nunc esse docebo."},{"sp":"N","t":"omnis enim color omnino mutatur in omnis;"},{"sp":"N","t":"quod facere haud ullo debent primordia pacto;","st":"2.750"},{"sp":"N","t":"immutabile enim quiddam superare necessest,"},{"sp":"N","t":"ne res ad nihilum redigantur funditus omnes;"},{"sp":"N","t":"nam quod cumque suis mutatum finibus exit,"},{"sp":"N","t":"continuo hoc mors est illius quod fuit ante."},{"sp":"N","t":"proinde colore cave contingas semina rerum,","st":"2.755"},{"sp":"N","t":"ne tibi res redeant ad nihilum funditus omnes."},{"sp":"N","t":"Praeterea si nulla coloris principiis est"},{"sp":"N","t":"reddita natura et variis sunt praedita formis,"},{"sp":"N","t":"e quibus omnigenus gignunt variantque colores,"},{"sp":"N","t":"propterea magni quod refert, semina quaeque","st":"2.760"},{"sp":"N","t":"cum quibus et quali positura contineantur"},{"sp":"N","t":"et quos inter se dent motus accipiantque,"},{"sp":"N","t":"perfacile extemplo rationem reddere possis,"},{"sp":"N","t":"cur ea quae nigro fuerint paulo ante colore,"},{"sp":"N","t":"marmoreo fieri possint candore repente,","st":"2.765"},{"sp":"N","t":"ut mare, cum magni commorunt aequora venti,"},{"sp":"N","t":"vertitur in canos candenti marmore fluctus;"},{"sp":"N","t":"dicere enim possis, nigrum quod saepe videmus,"},{"sp":"N","t":"materies ubi permixta est illius et ordo"},{"sp":"N","t":"principiis mutatus et addita demptaque quaedam,","st":"2.770"},{"sp":"N","t":"continuo id fieri ut candens videatur et album."},{"sp":"N","t":"quod si caeruleis constarent aequora ponti"},{"sp":"N","t":"seminibus, nullo possent albescere pacto;"},{"sp":"N","t":"nam quo cumque modo perturbes caerula quae sint,"},{"sp":"N","t":"numquam in marmoreum possunt migrare colorem.","st":"2.775"},{"sp":"N","t":"sin alio atque alio sunt semina tincta colore,"},{"sp":"N","t":"quae maris efficiunt unum purumque nitorem,"},{"sp":"N","t":"ut saepe ex aliis formis variisque figuris"},{"sp":"N","t":"efficitur quiddam quadratum unaque figura,"},{"sp":"N","t":"conveniebat, ut in quadrato cernimus esse","st":"2.780"},{"sp":"N","t":"dissimiles formas, ita cernere in aequore ponti"},{"sp":"N","t":"aut alio in quovis uno puroque nitore"},{"sp":"N","t":"dissimiles longe inter se variosque colores."},{"sp":"N","t":"praeterea nihil officiunt obstantque figurae"},{"sp":"N","t":"dissimiles, quo quadratum minus omne sit extra;","st":"2.785"},{"sp":"N","t":"at varii rerum inpediunt prohibentque colores,"},{"sp":"N","t":"quo minus esse uno possit res tota nitore."},{"sp":"N","t":"Tum porro quae ducit et inlicit ut tribuamus"},{"sp":"N","t":"principiis rerum non numquam causa colores,"},{"sp":"N","t":"occidit, ex albis quoniam non alba creantur,","st":"2.790"},{"sp":"N","t":"nec quae nigra cluent de nigris, sed variis ex."},{"sp":"N","t":"quippe etenim multo proclivius exorientur"},{"sp":"N","t":"candida de nullo quam nigro nata colore"},{"sp":"N","t":"aut alio quovis, qui contra pugnet et obstet."},{"sp":"N","t":"Praeterea quoniam nequeunt sine luce colores","st":"2.795"},{"sp":"N","t":"esse neque in lucem existunt primordia rerum,"},{"sp":"N","t":"scire licet quam sint nullo velata colore;"},{"sp":"N","t":"qualis enim caecis poterit color esse tenebris?"},{"sp":"N","t":"lumine quin ipso mutatur propterea quod"},{"sp":"N","t":"recta aut obliqua percussus luce refulget;","st":"2.800"},{"sp":"N","t":"pluma columbarum quo pacto in sole videtur,"},{"sp":"N","t":"quae sita cervices circum collumque coronat;"},{"sp":"N","t":"namque alias fit uti claro sit rubra pyropo,"},{"sp":"N","t":"inter dum quodam sensu fit uti videatur"},{"sp":"N","t":"inter caeruleum viridis miscere zmaragdos.","st":"2.805"},{"sp":"N","t":"caudaque pavonis, larga cum luce repleta est,"},{"sp":"N","t":"consimili mutat ratione obversa colores;"},{"sp":"N","t":"qui quoniam quodam gignuntur luminis ictu,"},{"sp":"N","t":"scire licet, sine eo fieri non posse putandum est."},{"sp":"N","t":"Et quoniam plagae quoddam genus excipit in se","st":"2.810"},{"sp":"N","t":"pupula, cum sentire colorem dicitur album,"},{"sp":"N","t":"atque aliud porro, nigrum cum et cetera sentit,"},{"sp":"N","t":"nec refert ea quae tangas quo forte colore"},{"sp":"N","t":"praedita sint, verum quali magis apta figura,"},{"sp":"N","t":"scire licet nihil principiis opus esse colore,","st":"2.815"},{"sp":"N","t":"sed variis formis variantes edere tactus."},{"sp":"N","t":"Praeterea quoniam non certis certa figuris"},{"sp":"N","t":"est natura coloris et omnia principiorum"},{"sp":"N","t":"formamenta queunt in quovis esse nitore,"},{"sp":"N","t":"cur ea quae constant ex illis non pariter sunt","st":"2.820"},{"sp":"N","t":"omnigenus perfusa coloribus in genere omni?"},{"sp":"N","t":"conveniebat enim corvos quoque saepe volantis"},{"sp":"N","t":"ex albis album pinnis iactare colorem"},{"sp":"N","t":"et nigros fieri nigro de semine cycnos"},{"sp":"N","t":"aut alio quovis uno varioque colore.","st":"2.825"},{"sp":"N","t":"Quin etiam quanto in partes res quaeque minutas"},{"sp":"N","t":"distrahitur magis, hoc magis est ut cernere possis"},{"sp":"N","t":"evanescere paulatim stinguique colorem;"},{"sp":"N","t":"ut fit ubi in parvas partis discerpitur austrum:"},{"sp":"N","t":"purpura poeniceusque color clarissimus multo,","st":"2.830"},{"sp":"N","t":"filatim cum distractum est, disperditur omnis;"},{"sp":"N","t":"noscere ut hinc possis prius omnem efflare colorem"},{"sp":"N","t":"particulas, quam discedant ad semina rerum."},{"sp":"N","t":"Postremo quoniam non omnia corpora vocem"},{"sp":"N","t":"mittere concedis neque odorem, propterea fit","st":"2.835"},{"sp":"N","t":"ut non omnibus adtribuas sonitus et odores:"},{"sp":"N","t":"sic oculis quoniam non omnia cernere quimus,"},{"sp":"N","t":"scire licet quaedam tam constare orba colore"},{"sp":"N","t":"quam sine odore ullo quaedam sonituque remota,"},{"sp":"N","t":"nec minus haec animum cognoscere posse sagacem","st":"2.840"},{"sp":"N","t":"quam quae sunt aliis rebus privata notare."},{"sp":"N","t":"Sed ne forte putes solo spoliata colore"},{"sp":"N","t":"corpora prima manere, etiam secreta teporis"},{"sp":"N","t":"sunt ac frigoris omnino calidique vaporis,"},{"sp":"N","t":"et sonitu sterila et suco ieiuna feruntur,","st":"2.845"},{"sp":"N","t":"nec iaciunt ullum proprium de corpore odorem."},{"sp":"N","t":"sicut amaracini blandum stactaeque liquorem"},{"sp":"N","t":"et nardi florem, nectar qui naribus halat,"},{"sp":"N","t":"cum facere instituas, cum primis quaerere par est,"},{"sp":"N","t":"quod licet ac possis reperire, inolentis olivi","st":"2.850"},{"sp":"N","t":"naturam, nullam quae mittat naribus auram,"},{"sp":"N","t":"quam minime ut possit mixtos in corpore odores"},{"sp":"N","t":"concoctosque suo contractans perdere viro,"},{"sp":"N","t":"propter eandem rem debent primordia rerum"},{"sp":"N","t":"non adhibere suum gignundis rebus odorem","st":"2.855"},{"sp":"N","t":"nec sonitum, quoniam nihil ab se mittere possunt,"},{"sp":"N","t":"nec simili ratione saporem denique quemquam"},{"sp":"N","t":"nec frigus neque item calidum tepidumque vaporem,"},{"sp":"N","t":"cetera, quae cum ita sunt tamen ut mortalia constent,"},{"sp":"N","t":"molli lenta, fragosa putri, cava corpore raro,","st":"2.860"},{"sp":"N","t":"omnia sint a principiis seiuncta necessest,"},{"sp":"N","t":"inmortalia si volumus subiungere rebus"},{"sp":"N","t":"fundamenta, quibus nitatur summa salutis;"},{"sp":"N","t":"ne tibi res redeant ad nihilum funditus omnes."},{"sp":"N","t":"Nunc ea quae sentire videmus cumque necessest","st":"2.865"},{"sp":"N","t":"ex insensilibus tamen omnia confiteare"},{"sp":"N","t":"principiis constare. neque id manufesta refutant"},{"sp":"N","t":"nec contra pugnant, in promptu cognita quae sunt,"},{"sp":"N","t":"sed magis ipsa manu ducunt et credere cogunt"},{"sp":"N","t":"ex insensilibus, quod dico, animalia gigni.","st":"2.870"},{"sp":"N","t":"quippe videre licet vivos existere vermes"},{"sp":"N","t":"stercore de taetro, putorem cum sibi nacta est"},{"sp":"N","t":"intempestivis ex imbribus umida tellus."},{"sp":"N","t":"Praeterea cunctas itidem res vertere sese."},{"sp":"N","t":"vertunt se fluvii in frondes et pabula laeta","st":"2.875"},{"sp":"N","t":"in pecudes, vertunt pecudes in corpora nostra"},{"sp":"N","t":"naturam, et nostro de corpore saepe ferarum"},{"sp":"N","t":"augescunt vires et corpora pennipotentum."},{"sp":"N","t":"ergo omnes natura cibos in corpora viva"},{"sp":"N","t":"vertit et hinc sensus animantum procreat omnes,","st":"2.880"},{"sp":"N","t":"non alia longe ratione atque arida ligna"},{"sp":"N","t":"explicat in flammas et in ignis omnia versat."},{"sp":"N","t":"iamne vides igitur magni primordia rerum"},{"sp":"N","t":"referre in quali sint ordine quaeque locata"},{"sp":"N","t":"et commixta quibus dent motus accipiantque?","st":"2.885"},{"sp":"N","t":"Tum porro, quid id est, animum quod percutit, ipsum,"},{"sp":"N","t":"quod movet et varios sensus expromere cogit,"},{"sp":"N","t":"ex insensilibus ne credas sensile gigni?"},{"sp":"N","t":"ni mirum lapides et ligna et terra quod una"},{"sp":"N","t":"mixta tamen nequeunt vitalem reddere sensum.","st":"2.890"},{"sp":"N","t":"illud in his igitur rebus meminisse decebit,"},{"sp":"N","t":"non ex omnibus omnino, quaecumque creant res"},{"sp":"N","t":"sensilia, extemplo me gigni dicere sensus,"},{"sp":"N","t":"sed magni referre ea primum quantula constent,"},{"sp":"N","t":"sensile quae faciunt, et qua sint praedita forma,","st":"2.895"},{"sp":"N","t":"motibus ordinibus posituris denique quae sint."},{"sp":"N","t":"quarum nil rerum in lignis glaebisque videmus;"},{"sp":"N","t":"et tamen haec, cum sunt quasi putrefacta per imbres,"},{"sp":"N","t":"vermiculos pariunt, quia corpora materiai"},{"sp":"N","t":"antiquis ex ordinibus permota nova re","st":"2.900"},{"sp":"N","t":"conciliantur ita ut debent animalia gigni."},{"sp":"N","t":"Deinde ex sensilibus qui sensile posse creari"},{"sp":"N","t":"constituunt, porro ex aliis sentire sueti"},{"sp":"N","t":"* * *"},{"sp":"N","t":"mollia cum faciunt; nam sensus iungitur omnis"},{"sp":"N","t":"visceribus nervis venis, quae cumque videmus","st":"2.905"},{"sp":"N","t":"mollia mortali consistere corpore creta."},{"sp":"N","t":"sed tamen esto iam posse haec aeterna manere;"},{"sp":"N","t":"nempe tamen debent aut sensum partis habere"},{"sp":"N","t":"aut similis totis animalibus esse putari."},{"sp":"N","t":"at nequeant per se partes sentire necesse est:","st":"2.910"},{"sp":"N","t":"namque animus sensus membrorum respuit omnis,"},{"sp":"N","t":"nec manus a nobis potis est secreta neque ulla"},{"sp":"N","t":"corporis omnino sensum pars sola tenere."},{"sp":"N","t":"linquitur ut totis animantibus adsimulentur,"},{"sp":"N","t":"vitali ut possint consentire undique sensu.","st":"2.915"},{"sp":"N","t":"qui poterunt igitur rerum primordia dici"},{"sp":"N","t":"et leti vitare vias, animalia cum sint,"},{"sp":"N","t":"atque animalia sint mortalibus una eademque?"},{"sp":"N","t":"quod tamen ut possint, at coetu concilioque"},{"sp":"N","t":"nil facient praeter volgum turbamque animantum,","st":"2.920"},{"sp":"N","t":"scilicet ut nequeant homines armenta feraeque"},{"sp":"N","t":"inter sese ullam rem gignere conveniundo."},{"sp":"N","t":"sic itidem quae sentimus sentire necessest."},{"sp":"N","t":"quod si forte suum dimittunt corpore sensum"},{"sp":"N","t":"atque alium capiunt, quid opus fuit adtribui id quod","st":"2.925"},{"sp":"N","t":"detrahitur? tum praeterea, quod fudimus ante,"},{"sp":"N","t":"quatinus in pullos animalis vertier ova"},{"sp":"N","t":"cernimus alituum vermisque effervere terra,"},{"sp":"N","t":"intempestivos quam putor cepit ob imbris,"},{"sp":"N","t":"scire licet gigni posse ex non sensibus sensus.","st":"2.930"},{"sp":"N","t":"Quod si forte aliquis dicet, dum taxat oriri"},{"sp":"N","t":"posse ex non sensu sensus mutabilitate,"},{"sp":"N","t":"aut aliquo tamquam partu quod proditur extra,"},{"sp":"N","t":"huic satis illud erit planum facere atque probare,"},{"sp":"N","t":"non fieri partum nisi concilio ante coacto,","st":"2.935"},{"sp":"N","t":"nec quicquam commutari sine conciliatu."},{"sp":"N","t":"Principio nequeunt ullius corporis esse"},{"sp":"N","t":"sensus ante ipsam genitam naturam animantis,"},{"sp":"N","t":"ni mirum quia materies disiecta tenetur"},{"sp":"N","t":"aere fluminibus terris terraque creatis,","st":"2.940"},{"sp":"N","t":"nec congressa modo vitalis convenientes"},{"sp":"N","t":"contulit inter se motus, quibus omnituentes"},{"sp":"N","t":"accensi sensus animantem quamque tuentur."},{"sp":"N","t":"Praeterea quamvis animantem grandior ictus,"},{"sp":"N","t":"quam patitur natura, repente adfligit et omnis","st":"2.945"},{"sp":"N","t":"corporis atque animi pergit confundere sensus."},{"sp":"N","t":"dissoluuntur enim positurae principiorum"},{"sp":"N","t":"et penitus motus vitales inpediuntur,"},{"sp":"N","t":"donec materies omnis concussa per artus"},{"sp":"N","t":"vitalis animae nodos a corpore solvit","st":"2.950"},{"sp":"N","t":"dispersamque foras per caulas eiecit omnis;"},{"sp":"N","t":"nam quid praeterea facere ictum posse reamur"},{"sp":"N","t":"oblatum, nisi discutere ac dissolvere quaeque?"},{"sp":"N","t":"fit quoque uti soleant minus oblato acriter ictu"},{"sp":"N","t":"reliqui motus vitalis vincere saepe,","st":"2.955"},{"sp":"N","t":"vincere et ingentis plagae sedare tumultus"},{"sp":"N","t":"inque suos quicquid rursus revocare meatus"},{"sp":"N","t":"et quasi iam leti dominantem in corpore motum"},{"sp":"N","t":"discutere ac paene amissos accendere sensus;"},{"sp":"N","t":"nam qua re potius leti iam limine ab ipso","st":"2.960"},{"sp":"N","t":"ad vitam possint conlecta mente reverti,"},{"sp":"N","t":"quam quo decursum prope iam siet ire et abire?"},{"sp":"N","t":"Praeterea, quoniam dolor est, ubi materiai"},{"sp":"N","t":"corpora vi quadam per viscera viva per artus"},{"sp":"N","t":"sollicitata suis trepidant in sedibus intus,","st":"2.965"},{"sp":"N","t":"inque locum quando remigrant, fit blanda voluptas,"},{"sp":"N","t":"scire licet nullo primordia posse dolore"},{"sp":"N","t":"temptari nullamque voluptatem capere ex se;"},{"sp":"N","t":"quandoquidem non sunt ex ullis principiorum"},{"sp":"N","t":"corporibus, quorum motus novitate laborent","st":"2.970"},{"sp":"N","t":"aut aliquem fructum capiant dulcedinis almae."},{"sp":"N","t":"haut igitur debent esse ullo praedita sensu."},{"sp":"N","t":"Denique uti possint sentire animalia quaeque,"},{"sp":"N","t":"principiis si iam est sensus tribuendus eorum,"},{"sp":"N","t":"quid, genus humanum propritim de quibus auctumst?","st":"2.975"},{"sp":"N","t":"scilicet et risu tremulo concussa cachinnant"},{"sp":"N","t":"et lacrimis spargunt rorantibus ora genasque"},{"sp":"N","t":"multaque de rerum mixtura dicere callent"},{"sp":"N","t":"et sibi proporro quae sint primordia quaerunt;"},{"sp":"N","t":"quando quidem totis mortalibus adsimulata","st":"2.980"},{"sp":"N","t":"ipsa quoque ex aliis debent constare elementis,"},{"sp":"N","t":"inde alia ex aliis, nusquam consistere ut ausis;"},{"sp":"N","t":"quippe sequar, quod cumque loqui ridereque dices"},{"sp":"N","t":"et sapere, ex aliis eadem haec facientibus ut sit."},{"sp":"N","t":"quod si delira haec furiosaque cernimus esse","st":"2.985"},{"sp":"N","t":"et ridere potest non ex ridentibus auctus,"},{"sp":"N","t":"et sapere et doctis rationem reddere dictis"},{"sp":"N","t":"non ex seminibus sapientibus atque disertis,"},{"sp":"N","t":"qui minus esse queant ea quae sentire videmus"},{"sp":"N","t":"seminibus permixta carentibus undique sensu?","st":"2.990"},{"sp":"N","t":"Denique caelesti sumus omnes semine oriundi;"},{"sp":"N","t":"omnibus ille idem pater est, unde alma liquentis"},{"sp":"N","t":"umoris guttas mater cum terra recepit,"},{"sp":"N","t":"feta parit nitidas fruges arbustaque laeta"},{"sp":"N","t":"et genus humanum, parit omnia saecla ferarum,","st":"2.995"},{"sp":"N","t":"pabula cum praebet, quibus omnes corpora pascunt"},{"sp":"N","t":"et dulcem ducunt vitam prolemque propagant;"},{"sp":"N","t":"qua propter merito maternum nomen adepta est."},{"sp":"N","t":"cedit item retro, de terra quod fuit ante,"},{"sp":"N","t":"in terras, et quod missumst ex aetheris oris,","st":"2.1000"},{"sp":"N","t":"id rursum caeli rellatum templa receptant."},{"sp":"N","t":"nec sic interemit mors res ut materiai"},{"sp":"N","t":"corpora conficiat, sed coetum dissupat ollis;"},{"sp":"N","t":"inde aliis aliud coniungit et efficit, omnis"},{"sp":"N","t":"res ut convertant formas mutentque colores","st":"2.1005"},{"sp":"N","t":"et capiant sensus et puncto tempore reddant;"},{"sp":"N","t":"ut noscas referre earum primordia rerum"},{"sp":"N","t":"cum quibus et quali positura contineantur"},{"sp":"N","t":"et quos inter se dent motus accipiantque,"},{"sp":"N","t":"neve putes aeterna penes residere potesse","st":"2.1010"},{"sp":"N","t":"corpora prima quod in summis fluitare videmus"},{"sp":"N","t":"rebus et interdum nasci subitoque perire."},{"sp":"N","t":"quin etiam refert nostris in versibus ipsis"},{"sp":"N","t":"cum quibus et quali sint ordine quaeque locata;"},{"sp":"N","t":"namque eadem caelum mare terras flumina solem","st":"2.1015"},{"sp":"N","t":"significant, eadem fruges arbusta animantis;"},{"sp":"N","t":"si non omnia sunt, at multo maxima pars est"},{"sp":"N","t":"consimilis; verum positura discrepitant res."},{"sp":"N","t":"sic ipsis in rebus item iam materiai"},{"sp":"N","t":"intervalla vias conexus pondera plagas","st":"2.1020"},{"sp":"N","t":"concursus motus ordo positura figurae"},{"sp":"N","t":"cum permutantur, mutari res quoque debent."},{"sp":"N","t":"Nunc animum nobis adhibe veram ad rationem."},{"sp":"N","t":"nam tibi vehementer nova res molitur ad auris"},{"sp":"N","t":"accedere et nova se species ostendere rerum.","st":"2.1025"},{"sp":"N","t":"sed neque tam facilis res ulla est, quin ea primum"},{"sp":"N","t":"difficilis magis ad credendum constet, itemque"},{"sp":"N","t":"nil adeo magnum neque tam mirabile quicquam,"},{"sp":"N","t":"quod non paulatim minuant mirarier omnes,"},{"sp":"N","t":"principio caeli clarum purumque colorem","st":"2.1030"},{"sp":"N","t":"quaeque in se cohibet, palantia sidera passim,"},{"sp":"N","t":"lunamque et solis praeclara luce nitorem;"},{"sp":"N","t":"omnia quae nunc si primum mortalibus essent"},{"sp":"N","t":"ex improviso si sint obiecta repente,"},{"sp":"N","t":"quid magis his rebus poterat mirabile dici,","st":"2.1035"},{"sp":"N","t":"aut minus ante quod auderent fore credere gentes?"},{"sp":"N","t":"nil, ut opinor; ita haec species miranda fuisset."},{"sp":"N","t":"quam tibi iam nemo fessus satiate videndi,"},{"sp":"N","t":"suspicere in caeli dignatur lucida templa."},{"sp":"N","t":"desine qua propter novitate exterritus ipsa","st":"2.1040"},{"sp":"N","t":"expuere ex animo rationem, sed magis acri"},{"sp":"N","t":"iudicio perpende, et si tibi vera videntur,"},{"sp":"N","t":"dede manus, aut, si falsum est, accingere contra."},{"sp":"N","t":"quaerit enim rationem animus, cum summa loci sit"},{"sp":"N","t":"infinita foris haec extra moenia mundi,","st":"2.1045"},{"sp":"N","t":"quid sit ibi porro, quo prospicere usque velit mens"},{"sp":"N","t":"atque animi iactus liber quo pervolet ipse."},{"sp":"N","t":"Principio nobis in cunctas undique partis"},{"sp":"N","t":"et latere ex utroque supra supterque per omne"},{"sp":"N","t":"nulla est finis; uti docui, res ipsaque per se","st":"2.1050"},{"sp":"N","t":"vociferatur, et elucet natura profundi."},{"sp":"N","t":"nullo iam pacto veri simile esse putandumst,"},{"sp":"N","t":"undique cum vorsum spatium vacet infinitum"},{"sp":"N","t":"seminaque innumero numero summaque profunda"},{"sp":"N","t":"multimodis volitent aeterno percita motu,","st":"2.1055"},{"sp":"N","t":"hunc unum terrarum orbem caelumque creatum,"},{"sp":"N","t":"nil agere illa foris tot corpora materiai;"},{"sp":"N","t":"cum praesertim hic sit natura factus et ipsa"},{"sp":"N","t":"sponte sua forte offensando semina rerum"},{"sp":"N","t":"multimodis temere in cassum frustraque coacta","st":"2.1060"},{"sp":"N","t":"tandem coluerunt ea quae coniecta repente"},{"sp":"N","t":"magnarum rerum fierent exordia semper,"},{"sp":"N","t":"terrai maris et caeli generisque animantum."},{"sp":"N","t":"quare etiam atque etiam talis fateare necesse est"},{"sp":"N","t":"esse alios alibi congressus materiai,","st":"2.1065"},{"sp":"N","t":"qualis hic est, avido complexu quem tenet aether."},{"sp":"N","t":"Praeterea cum materies est multa parata,"},{"sp":"N","t":"cum locus est praesto nec res nec causa moratur"},{"sp":"N","t":"ulla, geri debent ni mirum et confieri res."},{"sp":"N","t":"nunc et seminibus si tanta est copia, quantam","st":"2.1070"},{"sp":"N","t":"enumerare aetas animantum non queat omnis,"},{"sp":"N","t":"quis eadem natura manet, quae semina rerum"},{"sp":"N","t":"conicere in loca quaeque queat simili ratione"},{"sp":"N","t":"atque huc sunt coniecta, necesse est confiteare"},{"sp":"N","t":"esse alios aliis terrarum in partibus orbis","st":"2.1075"},{"sp":"N","t":"et varias hominum gentis et saecla ferarum."},{"sp":"N","t":"Huc accedit ut in summa res nulla sit una,"},{"sp":"N","t":"unica quae gignatur et unica solaque crescat,"},{"sp":"N","t":"quin aliquoius siet saecli permultaque eodem"},{"sp":"N","t":"sint genere. in primis animalibus indice mente","st":"2.1080"},{"sp":"N","t":"invenies sic montivagum genus esse ferarum,"},{"sp":"N","t":"sic hominum geminam prolem, sic denique mutas"},{"sp":"N","t":"squamigerum pecudes et corpora cuncta volantum."},{"sp":"N","t":"qua propter caelum simili ratione fatendumst"},{"sp":"N","t":"terramque et solem, lunam mare cetera quae sunt,","st":"2.1085"},{"sp":"N","t":"non esse unica, sed numero magis innumerali;"},{"sp":"N","t":"quando quidem vitae depactus terminus alte"},{"sp":"N","t":"tam manet haec et tam nativo corpore constant"},{"sp":"N","t":"quam genus omne, quod his generatimst rebus abundans."},{"sp":"N","t":"Quae bene cognita si teneas, natura videtur","st":"2.1090"},{"sp":"N","t":"libera continuo, dominis privata superbis,"},{"sp":"N","t":"ipsa sua per se sponte omnia dis agere expers."},{"sp":"N","t":"nam pro sancta deum tranquilla pectora pace"},{"sp":"N","t":"quae placidum degunt aevom vitamque serenam,"},{"sp":"N","t":"quis regere immensi summam, quis habere profundi","st":"2.1095"},{"sp":"N","t":"indu manu validas potis est moderanter habenas,"},{"sp":"N","t":"quis pariter caelos omnis convertere et omnis"},{"sp":"N","t":"ignibus aetheriis terras suffire feracis,"},{"sp":"N","t":"omnibus inve locis esse omni tempore praesto,"},{"sp":"N","t":"nubibus ut tenebras faciat caelique serena","st":"2.1100"},{"sp":"N","t":"concutiat sonitu, tum fulmina mittat et aedis"},{"sp":"N","t":"saepe suas disturbet et in deserta recedens"},{"sp":"N","t":"saeviat exercens telum, quod saepe nocentes"},{"sp":"N","t":"praeterit exanimatque indignos inque merentes?"},{"sp":"N","t":"Multaque post mundi tempus genitale diemque","st":"2.1105"},{"sp":"N","t":"primigenum maris et terrae solisque coortum"},{"sp":"N","t":"addita corpora sunt extrinsecus, addita circum"},{"sp":"N","t":"semina, quae magnum iaculando contulit omne,"},{"sp":"N","t":"unde mare et terrae possent augescere et unde"},{"sp":"N","t":"appareret spatium caeli domus altaque tecta","st":"2.1110"},{"sp":"N","t":"tolleret a terris procul et consurgeret aer."},{"sp":"N","t":"nam sua cuique, locis ex omnibus, omnia plagis"},{"sp":"N","t":"corpora distribuuntur et ad sua saecla recedunt,"},{"sp":"N","t":"umor ad umorem, terreno corpore terra"},{"sp":"N","t":"crescit et ignem ignes procudunt aetheraque aether,","st":"2.1115"},{"sp":"N","t":"donique ad extremum crescendi perfica finem"},{"sp":"N","t":"omnia perduxit rerum natura creatrix;"},{"sp":"N","t":"ut fit ubi nihilo iam plus est quod datur intra"},{"sp":"N","t":"vitalis venas quam quod fluit atque recedit."},{"sp":"N","t":"omnibus hic aetas debet consistere rebus,","st":"2.1120"},{"sp":"N","t":"hic natura suis refrenat viribus auctum."},{"sp":"N","t":"nam quae cumque vides hilaro grandescere adauctu"},{"sp":"N","t":"paulatimque gradus aetatis scandere adultae,"},{"sp":"N","t":"plura sibi adsumunt quam de se corpora mittunt,"},{"sp":"N","t":"dum facile in venas cibus omnis inditur et dum","st":"2.1125"},{"sp":"N","t":"non ita sunt late dispessa, ut multa remittant"},{"sp":"N","t":"et plus dispendi faciant quam vescitur aetas."},{"sp":"N","t":"nam certe fluere atque recedere corpora rebus"},{"sp":"N","t":"multa manus dandum est; sed plura accedere debent,"},{"sp":"N","t":"donec alescendi summum tetigere cacumen.","st":"2.1130"},{"sp":"N","t":"inde minutatim vires et robur adultum"},{"sp":"N","t":"frangit et in partem peiorem liquitur aetas."},{"sp":"N","t":"quippe etenim quanto est res amplior, augmine adempto,"},{"sp":"N","t":"et quo latior est, in cunctas undique partis"},{"sp":"N","t":"plura modo dispargit et a se corpora mittit,","st":"2.1135"},{"sp":"N","t":"nec facile in venas cibus omnis diditur ei"},{"sp":"N","t":"nec satis est, pro quam largos exaestuat aestus,"},{"sp":"N","t":"unde queat tantum suboriri ac subpeditare."},{"sp":"N","t":"iure igitur pereunt, cum rarefacta fluendo"},{"sp":"N","t":"sunt et cum externis succumbunt omnia plagis,","st":"2.1140"},{"sp":"N","t":"quando quidem grandi cibus aevo denique defit,"},{"sp":"N","t":"nec tuditantia rem cessant extrinsecus ullam"},{"sp":"N","t":"corpora conficere et plagis infesta domare."},{"sp":"N","t":"Sic igitur magni quoque circum moenia mundi"},{"sp":"N","t":"expugnata dabunt labem putrisque ruinas;","st":"2.1145"},{"sp":"N","t":"omnia debet enim cibus integrare novando"},{"sp":"N","t":"et fulcire cibus, cibus omnia sustentare,"},{"sp":"N","t":"ne quiquam, quoniam nec venae perpetiuntur"},{"sp":"N","t":"quod satis est, neque quantum opus est natura ministrat."},{"sp":"N","t":"Iamque adeo fracta est aetas effetaque tellus","st":"2.1150"},{"sp":"N","t":"vix animalia parva creat, quae cuncta creavit"},{"sp":"N","t":"saecla deditque ferarum ingentia corpora partu."},{"sp":"N","t":"haud, ut opinor, enim mortalia saecla superne"},{"sp":"N","t":"aurea de caelo demisit funis in arva"},{"sp":"N","t":"nec mare nec fluctus plangentis saxa crearunt,","st":"2.1155"},{"sp":"N","t":"sed genuit tellus eadem quae nunc alit ex se."},{"sp":"N","t":"praeterea nitidas fruges vinetaque laeta"},{"sp":"N","t":"sponte sua primum mortalibus ipsa creavit,"},{"sp":"N","t":"ipsa dedit dulcis fetus et pabula laeta;"},{"sp":"N","t":"quae nunc vix nostro grandescunt aucta labore,","st":"2.1160"},{"sp":"N","t":"conterimusque boves et viris agricolarum,"},{"sp":"N","t":"conficimus ferrum vix arvis suppeditati:"},{"sp":"N","t":"usque adeo parcunt fetus augentque laborem."},{"sp":"N","t":"iamque caput quassans grandis suspirat arator"},{"sp":"N","t":"crebrius, in cassum magnos cecidisse labores,","st":"2.1165"},{"sp":"N","t":"et cum tempora temporibus praesentia confert"},{"sp":"N","t":"praeteritis, laudat fortunas saepe parentis."},{"sp":"N","t":"tristis item vetulae vitis sator atque vietae"},{"sp":"N","t":"temporis incusat momen saeclumque fatigat,"},{"sp":"N","t":"et crepat, antiquum genus ut pietate repletum","st":"2.1170"},{"sp":"N","t":"perfacile angustis tolerarit finibus aevom,"},{"sp":"N","t":"cum minor esset agri multo modus ante viritim;"},{"sp":"N","t":"nec tenet omnia paulatim tabescere et ire"},{"sp":"N","t":"ad capulum spatio aetatis defessa vetusto."},{"sp":"HDR","t":"Liber III"},{"sp":"N","t":"E tenebris tantis tam clarum extollere lumen","st":"3.1"},{"sp":"N","t":"qui primus potuisti inlustrans commoda vitae,"},{"sp":"N","t":"te sequor, o Graiae gentis decus, inque tuis nunc"},{"sp":"N","t":"ficta pedum pono pressis vestigia signis,"},{"sp":"N","t":"non ita certandi cupidus quam propter amorem","st":"3.5"},{"sp":"N","t":"quod te imitari aveo; quid enim contendat hirundo"},{"sp":"N","t":"cycnis, aut quid nam tremulis facere artubus haedi"},{"sp":"N","t":"consimile in cursu possint et fortis equi vis?"},{"sp":"N","t":"tu, pater, es rerum inventor, tu patria nobis"},{"sp":"N","t":"suppeditas praecepta, tuisque ex, inclute, chartis,","st":"3.10"},{"sp":"N","t":"floriferis ut apes in saltibus omnia libant,"},{"sp":"N","t":"omnia nos itidem depascimur aurea dicta,"},{"sp":"N","t":"aurea, perpetua semper dignissima vita."},{"sp":"N","t":"nam simul ac ratio tua coepit vociferari"},{"sp":"N","t":"naturam rerum divina mente coorta","st":"3.15"},{"sp":"N","t":"diffugiunt animi terrores, moenia mundi"},{"sp":"N","t":"discedunt. totum video per inane geri res."},{"sp":"N","t":"apparet divum numen sedesque quietae,"},{"sp":"N","t":"quas neque concutiunt venti nec nubila nimbis"},{"sp":"N","t":"aspergunt neque nix acri concreta pruina","st":"3.20"},{"sp":"N","t":"cana cadens violat semperque innubilus aether"},{"sp":"N","t":"integit et large diffuso lumine ridet:"},{"sp":"N","t":"omnia suppeditat porro natura neque ulla"},{"sp":"N","t":"res animi pacem delibat tempore in ullo."},{"sp":"N","t":"at contra nusquam apparent Acherusia templa,","st":"3.25"},{"sp":"N","t":"nec tellus obstat quin omnia dispiciantur,"},{"sp":"N","t":"sub pedibus quae cumque infra per inane geruntur."},{"sp":"N","t":"his ibi me rebus quaedam divina voluptas"},{"sp":"N","t":"percipit atque horror, quod sic natura tua vi"},{"sp":"N","t":"tam manifesta patens ex omni parte retecta est.","st":"3.30"},{"sp":"N","t":"Et quoniam docui, cunctarum exordia rerum"},{"sp":"N","t":"qualia sint et quam variis distantia formis"},{"sp":"N","t":"sponte sua volitent aeterno percita motu,"},{"sp":"N","t":"quove modo possint res ex his quaeque creari,"},{"sp":"N","t":"hasce secundum res animi natura videtur","st":"3.35"},{"sp":"N","t":"atque animae claranda meis iam versibus esse"},{"sp":"N","t":"et metus ille foras praeceps Acheruntis agendus,"},{"sp":"N","t":"funditus humanam qui vitam turbat ab imo"},{"sp":"N","t":"omnia suffundens mortis nigrore neque ullam"},{"sp":"N","t":"esse voluptatem liquidam puramque relinquit.","st":"3.40"},{"sp":"N","t":"nam quod saepe homines morbos magis esse timendos"},{"sp":"N","t":"infamemque ferunt vitam quam Tartara leti"},{"sp":"N","t":"et se scire animi naturam sanguinis esse,"},{"sp":"N","t":"aut etiam venti, si fert ita forte voluntas,"},{"sp":"N","t":"nec prosum quicquam nostrae rationis egere,","st":"3.45"},{"sp":"N","t":"hinc licet advertas animum magis omnia laudis"},{"sp":"N","t":"iactari causa quam quod res ipsa probetur."},{"sp":"N","t":"extorres idem patria longeque fugati"},{"sp":"N","t":"conspectu ex hominum, foedati crimine turpi,"},{"sp":"N","t":"omnibus aerumnis adfecti denique vivunt,","st":"3.50"},{"sp":"N","t":"et quo cumque tamen miseri venere parentant"},{"sp":"N","t":"et nigras mactant pecudes et manibus divis"},{"sp":"N","t":"inferias mittunt multoque in rebus acerbis"},{"sp":"N","t":"acrius advertunt animos ad religionem."},{"sp":"N","t":"quo magis in dubiis hominem spectare periclis","st":"3.55"},{"sp":"N","t":"convenit adversisque in rebus noscere qui sit;"},{"sp":"N","t":"nam verae voces tum demum pectore ab imo"},{"sp":"N","t":"eliciuntur et eripitur persona amanare."},{"sp":"N","t":"denique avarities et honorum caeca cupido,"},{"sp":"N","t":"quae miseros homines cogunt transcendere fines","st":"3.60"},{"sp":"N","t":"iuris et inter dum socios scelerum atque ministros"},{"sp":"N","t":"noctes atque dies niti praestante labore"},{"sp":"N","t":"ad summas emergere opes, haec vulnera vitae"},{"sp":"N","t":"non minimam partem mortis formidine aluntur."},{"sp":"N","t":"turpis enim ferme contemptus et acris egestas","st":"3.65"},{"sp":"N","t":"semota ab dulci vita stabilique videtur"},{"sp":"N","t":"et quasi iam leti portas cunctarier ante;"},{"sp":"N","t":"unde homines dum se falso terrore coacti"},{"sp":"N","t":"effugisse volunt longe longeque remosse,"},{"sp":"N","t":"sanguine civili rem conflant divitiasque","st":"3.70"},{"sp":"N","t":"conduplicant avidi, caedem caede accumulantes,"},{"sp":"N","t":"crudeles gaudent in tristi funere fratris"},{"sp":"N","t":"et consanguineum mensas odere timentque."},{"sp":"N","t":"consimili ratione ab eodem saepe timore"},{"sp":"N","t":"macerat invidia ante oculos illum esse potentem,","st":"3.75"},{"sp":"N","t":"illum aspectari, claro qui incedit honore,"},{"sp":"N","t":"ipsi se in tenebris volvi caenoque queruntur."},{"sp":"N","t":"intereunt partim statuarum et nominis ergo."},{"sp":"N","t":"et saepe usque adeo, mortis formidine, vitae"},{"sp":"N","t":"percipit humanos odium lucisque videndae,","st":"3.80"},{"sp":"N","t":"ut sibi consciscant maerenti pectore letum"},{"sp":"N","t":"obliti fontem curarum hunc esse timorem:"},{"sp":"N","t":"hunc vexare pudorem, hunc vincula amicitiai"},{"sp":"N","t":"rumpere et in summa pietate evertere suadet:"},{"sp":"N","t":"nam iam saepe homines patriam carosque parentis","st":"3.85"},{"sp":"N","t":"prodiderunt vitare Acherusia templa petentes."},{"sp":"N","t":"nam vel uti pueri trepidant atque omnia caecis"},{"sp":"N","t":"in tenebris metuunt, sic nos in luce timemus"},{"sp":"N","t":"inter dum, nihilo quae sunt metuenda magis quam"},{"sp":"N","t":"quae pueri in tenebris pavitant finguntque futura.","st":"3.90"},{"sp":"N","t":"hunc igitur terrorem animi tenebrasque necessest"},{"sp":"N","t":"non radii solis neque lucida tela diei"},{"sp":"N","t":"discutiant, sed naturae species ratioque."},{"sp":"N","t":"Primum animum dico, mentem quem saepe vocamus,"},{"sp":"N","t":"in quo consilium vitae regimenque locatum est,","st":"3.95"},{"sp":"N","t":"esse hominis partem nihilo minus ac manus et pes"},{"sp":"N","t":"atque oculei partes animantis totius extant."},{"sp":"N","t":"sensum animi certa non esse in parte locatum,"},{"sp":"N","t":"verum habitum quendam vitalem corporis esse,"},{"sp":"N","t":"harmoniam Grai quam dicunt, quod faciat nos","st":"3.100"},{"sp":"N","t":"vivere cum sensu, nulla cum in parte siet mens;"},{"sp":"N","t":"ut bona saepe valetudo cum dicitur esse"},{"sp":"N","t":"corporis, et non est tamen haec pars ulla valentis,"},{"sp":"N","t":"sic animi sensum non certa parte reponunt;"},{"sp":"N","t":"magno opere in quo mi diversi errare videntur.","st":"3.105"},{"sp":"N","t":"Saepe itaque, in promptu corpus quod cernitur, aegret,"},{"sp":"N","t":"cum tamen ex alia laetamur parte latenti;"},{"sp":"N","t":"et retro fit ubi contra sit saepe vicissim,"},{"sp":"N","t":"cum miser ex animo laetatur corpore toto;"},{"sp":"N","t":"non alio pacto quam si, pes cum dolet aegri,","st":"3.110"},{"sp":"N","t":"in nullo caput interea sit forte dolore."},{"sp":"N","t":"Praeterea molli cum somno dedita membra"},{"sp":"N","t":"effusumque iacet sine sensu corpus honustum,"},{"sp":"N","t":"est aliud tamen in nobis quod tempore in illo"},{"sp":"N","t":"multimodis agitatur et omnis accipit in se","st":"3.115"},{"sp":"N","t":"laetitiae motus et curas cordis inanis."},{"sp":"N","t":"Nunc animam quoque ut in membris cognoscere possis"},{"sp":"N","t":"esse neque harmonia corpus sentire solere,"},{"sp":"N","t":"principio fit uti detracto corpore multo"},{"sp":"N","t":"saepe tamen nobis in membris vita moretur.","st":"3.120"},{"sp":"N","t":"Atque eadem rursum, cum corpora pauca caloris"},{"sp":"N","t":"diffugere forasque per os est editus aer,"},{"sp":"N","t":"deserit extemplo venas atque ossa relinquit;"},{"sp":"N","t":"noscere ut hinc possis non aequas omnia partis"},{"sp":"N","t":"corpora habere neque ex aequo fulcire salutem,","st":"3.125"},{"sp":"N","t":"sed magis haec, venti quae sunt calidique vaporis"},{"sp":"N","t":"semina, curare in membris ut vita moretur."},{"sp":"N","t":"est igitur calor ac ventus vitalis in ipso"},{"sp":"N","t":"corpore, qui nobis moribundos deserit artus."},{"sp":"N","t":"quapropter quoniam est animi natura reperta","st":"3.130"},{"sp":"N","t":"atque animae quasi pars hominis, redde harmoniai"},{"sp":"N","t":"nomen, ad organicos alto delatum Heliconi,"},{"sp":"N","t":"sive aliunde ipsi porro traxere et in illam"},{"sp":"N","t":"transtulerunt, proprio quae tum res nomine egebat."},{"sp":"N","t":"quidquid id est, habeant: tu cetera percipe dicta.","st":"3.135"},{"sp":"N","t":"Nunc animum atque animam dico coniuncta teneri"},{"sp":"N","t":"inter se atque unam naturam conficere ex se,"},{"sp":"N","t":"sed caput esse quasi et dominari in corpore toto"},{"sp":"N","t":"consilium, quod nos animum mentemque vocamus."},{"sp":"N","t":"idque situm media regione in pectoris haeret.","st":"3.140"},{"sp":"N","t":"hic exultat enim pavor ac metus, haec loca circum"},{"sp":"N","t":"laetitiae mulcent: hic ergo mens animusquest."},{"sp":"N","t":"cetera pars animae per totum dissita corpus"},{"sp":"N","t":"paret et ad numen mentis momenque movetur."},{"sp":"N","t":"idque sibi solum per se sapit et sibi gaudet,","st":"3.145"},{"sp":"N","t":"cum neque res animam neque corpus commovet una."},{"sp":"N","t":"et quasi, cum caput aut oculus temptante dolore"},{"sp":"N","t":"laeditur in nobis, non omni concruciamur"},{"sp":"N","t":"corpore, sic animus nonnumquam laeditur ipse"},{"sp":"N","t":"laetitiaque viget, cum cetera pars animai","st":"3.150"},{"sp":"N","t":"per membra atque artus nulla novitate cietur;"},{"sp":"N","t":"verum ubi vementi magis est commota metu mens,"},{"sp":"N","t":"consentire animam totam per membra videmus"},{"sp":"N","t":"sudoresque ita palloremque existere toto"},{"sp":"N","t":"corpore et infringi linguam vocemque aboriri,","st":"3.155"},{"sp":"N","t":"caligare oculos, sonere auris, succidere artus,"},{"sp":"N","t":"denique concidere ex animi terrore videmus"},{"sp":"N","t":"saepe homines; facile ut quivis hinc noscere possit"},{"sp":"N","t":"esse animam cum animo coniunctam, quae cum animi vi"},{"sp":"N","t":"percussa est, exim corpus propellit et icit.","st":"3.160"},{"sp":"N","t":"Haec eadem ratio naturam animi atque animai"},{"sp":"N","t":"corpoream docet esse; ubi enim propellere membra,"},{"sp":"N","t":"corripere ex somno corpus mutareque vultum"},{"sp":"N","t":"atque hominem totum regere ac versare videtur,"},{"sp":"N","t":"quorum nil fieri sine tactu posse videmus","st":"3.165"},{"sp":"N","t":"nec tactum porro sine corpore, nonne fatendumst"},{"sp":"N","t":"corporea natura animum constare animamque?"},{"sp":"N","t":"praeterea pariter fungi cum corpore et una"},{"sp":"N","t":"consentire animum nobis in corpore cernis."},{"sp":"N","t":"si minus offendit vitam vis horrida teli","st":"3.170"},{"sp":"N","t":"ossibus ac nervis disclusis intus adacta,"},{"sp":"N","t":"at tamen insequitur languor terraeque petitus"},{"sp":"N","t":"suavis et in terra mentis qui gignitur aestus"},{"sp":"N","t":"inter dumque quasi exsurgendi incerta voluntas."},{"sp":"N","t":"ergo corpoream naturam animi esse necessest,","st":"3.175"},{"sp":"N","t":"corporeis quoniam telis ictuque laborat."},{"sp":"N","t":"Is tibi nunc animus quali sit corpore et unde"},{"sp":"N","t":"constiterit pergam rationem reddere dictis."},{"sp":"N","t":"principio esse aio persuptilem atque minutis"},{"sp":"N","t":"perquam corporibus factum constare. id ita esse","st":"3.180"},{"sp":"N","t":"hinc licet advertas animum, ut pernoscere possis."},{"sp":"N","t":"Nil adeo fieri celeri ratione videtur,"},{"sp":"N","t":"quam si mens fieri proponit et inchoat ipsa;"},{"sp":"N","t":"ocius ergo animus quam res se perciet ulla,"},{"sp":"N","t":"ante oculos quorum in promptu natura videtur.","st":"3.185"},{"sp":"N","t":"at quod mobile tanto operest, constare rutundis"},{"sp":"N","t":"perquam seminibus debet perquamque minutis,"},{"sp":"N","t":"momine uti parvo possint inpulsa moveri."},{"sp":"N","t":"namque movetur aqua et tantillo momine flutat,"},{"sp":"N","t":"quippe volubilibus parvisque creata figuris.","st":"3.190"},{"sp":"N","t":"at contra mellis constantior est natura"},{"sp":"N","t":"et pigri latices magis et cunctantior actus:"},{"sp":"N","t":"haeret enim inter se magis omnis materiai"},{"sp":"N","t":"copia, ni mirum quia non tam levibus extat"},{"sp":"N","t":"corporibus neque tam suptilibus atque rutundis.","st":"3.195"},{"sp":"N","t":"namque papaveris aura potest suspensa levisque"},{"sp":"N","t":"cogere ut ab summo tibi diffluat altus acervus,"},{"sp":"N","t":"at contra lapidum coniectum spicarumque"},{"sp":"N","t":"noenu potest. igitur parvissima corpora pro quam"},{"sp":"N","t":"et levissima sunt, ita mobilitate fruuntur;","st":"3.200"},{"sp":"N","t":"at contra quae cumque magis cum pondere magno"},{"sp":"N","t":"asperaque inveniuntur, eo stabilita magis sunt."},{"sp":"N","t":"nunc igitur quoniamst animi natura reperta"},{"sp":"N","t":"mobilis egregie, perquam constare necessest"},{"sp":"N","t":"corporibus parvis et levibus atque rutundis.","st":"3.205"},{"sp":"N","t":"quae tibi cognita res in multis, o bone, rebus"},{"sp":"N","t":"utilis invenietur et opportuna cluebit."},{"sp":"N","t":"Haec quoque res etiam naturam dedicat eius,"},{"sp":"N","t":"quam tenui constet textura quamque loco se"},{"sp":"N","t":"contineat parvo, si possit conglomerari,","st":"3.210"},{"sp":"N","t":"quod simul atque hominem leti secura quies est"},{"sp":"N","t":"indepta atque animi natura animaeque recessit,"},{"sp":"N","t":"nil ibi libatum de toto corpore cernas"},{"sp":"N","t":"ad speciem, nihil ad pondus: mors omnia praestat,"},{"sp":"N","t":"vitalem praeter sensum calidumque vaporem.","st":"3.215"},{"sp":"N","t":"ergo animam totam perparvis esse necessest"},{"sp":"N","t":"seminibus nexam per venas viscera nervos,"},{"sp":"N","t":"qua tenus, omnis ubi e toto iam corpore cessit,"},{"sp":"N","t":"extima membrorum circumcaesura tamen se"},{"sp":"N","t":"incolumem praestat nec defit ponderis hilum.","st":"3.220"},{"sp":"N","t":"quod genus est, Bacchi cum flos evanuit aut cum"},{"sp":"N","t":"spiritus unguenti suavis diffugit in auras"},{"sp":"N","t":"aut aliquo cum iam sucus de corpore cessit;"},{"sp":"N","t":"nil oculis tamen esse minor res ipsa videtur"},{"sp":"N","t":"propterea neque detractum de pondere quicquam,","st":"3.225"},{"sp":"N","t":"ni mirum quia multa minutaque semina sucos"},{"sp":"N","t":"efficiunt et odorem in toto corpore rerum."},{"sp":"N","t":"quare etiam atque etiam mentis naturam animaeque"},{"sp":"N","t":"scire licet perquam pauxillis esse creatam"},{"sp":"N","t":"seminibus, quoniam fugiens nil ponderis aufert.","st":"3.230"},{"sp":"N","t":"Nec tamen haec simplex nobis natura putanda est."},{"sp":"N","t":"tenvis enim quaedam moribundos deserit aura"},{"sp":"N","t":"mixta vapore, vapor porro trahit aera secum;"},{"sp":"N","t":"nec calor est quisquam, cui non sit mixtus et aer;"},{"sp":"N","t":"rara quod eius enim constat natura, necessest","st":"3.235"},{"sp":"N","t":"aeris inter eum primordia multa moveri."},{"sp":"N","t":"iam triplex animi est igitur natura reperta;"},{"sp":"N","t":"nec tamen haec sat sunt ad sensum cuncta creandum,"},{"sp":"N","t":"nil horum quoniam recipit mens posse creare"},{"sp":"N","t":"sensiferos motus, quae denique mente volutat.","st":"3.240"},{"sp":"N","t":"quarta quoque his igitur quaedam natura necessest"},{"sp":"N","t":"adtribuatur; east omnino nominis expers;"},{"sp":"N","t":"qua neque mobilius quicquam neque tenvius extat"},{"sp":"N","t":"nec magis e parvis et levibus ex elementis;"},{"sp":"N","t":"sensiferos motus quae didit prima per artus.","st":"3.245"},{"sp":"N","t":"prima cietur enim, parvis perfecta figuris,"},{"sp":"N","t":"inde calor motus et venti caeca potestas"},{"sp":"N","t":"accipit, inde aer, inde omnia mobilitantur:"},{"sp":"N","t":"concutitur sanguis, tum viscera persentiscunt"},{"sp":"N","t":"omnia, postremis datur ossibus atque medullis","st":"3.250"},{"sp":"N","t":"sive voluptas est sive est contrarius ardor."},{"sp":"N","t":"nec temere huc dolor usque potest penetrare neque acre"},{"sp":"N","t":"permanare malum, quin omnia perturbentur"},{"sp":"N","t":"usque adeo ut vitae desit locus atque animai"},{"sp":"N","t":"diffugiant partes per caulas corporis omnis.","st":"3.255"},{"sp":"N","t":"sed plerumque fit in summo quasi corpore finis"},{"sp":"N","t":"motibus: hanc ob rem vitam retinere valemus."},{"sp":"N","t":"Nunc ea quo pacto inter sese mixta quibusque"},{"sp":"N","t":"compta modis vigeant rationem reddere aventem"},{"sp":"N","t":"abstrahit invitum patrii sermonis egestas;","st":"3.260"},{"sp":"N","t":"sed tamen, ut potero summatim attingere, tangam."},{"sp":"N","t":"inter enim cursant primordia principiorum"},{"sp":"N","t":"motibus inter se, nihil ut secernier unum"},{"sp":"N","t":"possit nec spatio fieri divisa potestas,"},{"sp":"N","t":"sed quasi multae vis unius corporis extant.","st":"3.265"},{"sp":"N","t":"quod genus in quovis animantum viscere volgo"},{"sp":"N","t":"est odor et quidam color et sapor, et tamen ex his"},{"sp":"N","t":"omnibus est unum perfectum corporis augmen,"},{"sp":"N","t":"sic calor atque aer et venti caeca potestas"},{"sp":"N","t":"mixta creant unam naturam et mobilis illa","st":"3.270"},{"sp":"N","t":"vis, initum motus ab se quae dividit ollis,"},{"sp":"N","t":"sensifer unde oritur primum per viscera motus."},{"sp":"N","t":"nam penitus prorsum latet haec natura subestque"},{"sp":"N","t":"nec magis hac infra quicquam est in corpore nostro"},{"sp":"N","t":"atque anima est animae proporro totius ipsa.","st":"3.275"},{"sp":"N","t":"quod genus in nostris membris et corpore toto"},{"sp":"N","t":"mixta latens animi vis est animaeque potestas,"},{"sp":"N","t":"corporibus quia de parvis paucisque creatast,"},{"sp":"N","t":"sic tibi nominis haec expers vis, facta minutis"},{"sp":"N","t":"corporibus, latet atque animae quasi totius ipsa","st":"3.280"},{"sp":"N","t":"proporrost anima et dominatur corpore toto."},{"sp":"N","t":"consimili ratione necessest ventus et aer"},{"sp":"N","t":"et calor inter se vigeant commixta per artus"},{"sp":"N","t":"atque aliis aliud subsit magis emineatque,"},{"sp":"N","t":"ut quiddam fieri videatur ab omnibus unum,","st":"3.285"},{"sp":"N","t":"ni calor ac ventus seorsum seorsumque potestas"},{"sp":"N","t":"aeris interemant sensum diductaque solvant."},{"sp":"N","t":"est etiam calor ille animo, quem sumit, in ira"},{"sp":"N","t":"cum fervescit et ex oculis micat acrius ardor;"},{"sp":"N","t":"est et frigida multa, comes formidinis, aura,","st":"3.290"},{"sp":"N","t":"quae ciet horrorem membris et concitat artus;"},{"sp":"N","t":"est etiam quoque pacati status aeris ille,"},{"sp":"N","t":"pectore tranquillo fit qui voltuque sereno."},{"sp":"N","t":"sed calidi plus est illis quibus acria corda"},{"sp":"N","t":"iracundaque mens facile effervescit in ira,","st":"3.295"},{"sp":"N","t":"quo genere in primis vis est violenta leonum,"},{"sp":"N","t":"pectora qui fremitu rumpunt plerumque gementes"},{"sp":"N","t":"nec capere irarum fluctus in pectore possunt."},{"sp":"N","t":"at ventosa magis cervorum frigida mens est"},{"sp":"N","t":"et gelidas citius per viscera concitat auras,","st":"3.300"},{"sp":"N","t":"quae tremulum faciunt membris existere motum."},{"sp":"N","t":"at natura boum placido magis aere vivit"},{"sp":"N","t":"nec nimis irai fax umquam subdita percit"},{"sp":"N","t":"fumida, suffundens caecae caliginis umbra,"},{"sp":"N","t":"nec gelidis torpet telis perfixa pavoris;","st":"3.305"},{"sp":"N","t":"interutrasque sitast cervos saevosque leones."},{"sp":"N","t":"sic hominum genus est: quamvis doctrina politos"},{"sp":"N","t":"constituat pariter quosdam, tamen illa relinquit"},{"sp":"N","t":"naturae cuiusque animi vestigia prima."},{"sp":"N","t":"nec radicitus evelli mala posse putandumst,","st":"3.310"},{"sp":"N","t":"quin proclivius hic iras decurrat ad acris,"},{"sp":"N","t":"ille metu citius paulo temptetur, at ille"},{"sp":"N","t":"tertius accipiat quaedam clementius aequo."},{"sp":"N","t":"inque aliis rebus multis differre necessest"},{"sp":"N","t":"naturas hominum varias moresque sequacis;","st":"3.315"},{"sp":"N","t":"quorum ego nunc nequeo caecas exponere causas"},{"sp":"N","t":"nec reperire figurarum tot nomina quot sunt"},{"sp":"N","t":"principiis, unde haec oritur variantia rerum."},{"sp":"N","t":"illud in his rebus video firmare potesse,"},{"sp":"N","t":"usque adeo naturarum vestigia linqui","st":"3.320"},{"sp":"N","t":"parvola, quae nequeat ratio depellere nobis,"},{"sp":"N","t":"ut nihil inpediat dignam dis degere vitam."},{"sp":"N","t":"Haec igitur natura tenetur corpore ab omni"},{"sp":"N","t":"ipsaque corporis est custos et causa salutis;"},{"sp":"N","t":"nam communibus inter se radicibus haerent","st":"3.325"},{"sp":"N","t":"nec sine pernicie divelli posse videntur."},{"sp":"N","t":"quod genus e thuris glaebis evellere odorem"},{"sp":"N","t":"haud facile est, quin intereat natura quoque eius,"},{"sp":"N","t":"sic animi atque animae naturam corpore toto"},{"sp":"N","t":"extrahere haut facile est, quin omnia dissoluantur.","st":"3.330"},{"sp":"N","t":"inplexis ita principiis ab origine prima"},{"sp":"N","t":"inter se fiunt consorti praedita vita,"},{"sp":"N","t":"nec sibi quaeque sine alterius vi posse videtur"},{"sp":"N","t":"corporis atque animi seorsum sentire potestas,"},{"sp":"N","t":"sed communibus inter eas conflatur utrimque","st":"3.335"},{"sp":"N","t":"motibus accensus nobis per viscera sensus."},{"sp":"N","t":"Praeterea corpus per se nec gignitur umquam"},{"sp":"N","t":"nec crescit neque post mortem durare videtur."},{"sp":"N","t":"non enim, ut umor aquae dimittit saepe vaporem,"},{"sp":"N","t":"qui datus est, neque ea causa convellitur ipse,","st":"3.340"},{"sp":"N","t":"sed manet incolumis, non, inquam, sic animai"},{"sp":"N","t":"discidium possunt artus perferre relicti,"},{"sp":"N","t":"sed penitus pereunt convulsi conque putrescunt."},{"sp":"N","t":"ex ineunte aevo sic corporis atque animai"},{"sp":"N","t":"mutua vitalis discunt contagia motus,","st":"3.345"},{"sp":"N","t":"maternis etiam membris alvoque reposta,"},{"sp":"N","t":"discidium ut nequeat fieri sine peste maloque;"},{"sp":"N","t":"ut videas, quoniam coniunctast causa salutis,"},{"sp":"N","t":"coniunctam quoque naturam consistere eorum."},{"sp":"N","t":"Quod super est, siquis corpus sentire refutat","st":"3.350"},{"sp":"N","t":"atque animam credit permixtam corpore toto"},{"sp":"N","t":"suscipere hunc motum quem sensum nominitamus,"},{"sp":"N","t":"vel manifestas res contra verasque repugnat."},{"sp":"N","t":"quid sit enim corpus sentire quis adferet umquam,"},{"sp":"N","t":"si non ipsa palam quod res dedit ac docuit nos?","st":"3.355"},{"sp":"N","t":"'at dimissa anima corpus caret undique sensu.'"},{"sp":"N","t":"perdit enim quod non proprium fuit eius in aevo"},{"sp":"N","t":"multaque praeterea perdit quom expellitur aevo."},{"sp":"N","t":"Dicere porro oculos nullam rem cernere posse,"},{"sp":"N","t":"sed per eos animum ut foribus spectare reclusis,","st":"3.360"},{"sp":"N","t":"difficilest, contra cum sensus ducat eorum;"},{"sp":"N","t":"sensus enim trahit atque acies detrudit ad ipsas,"},{"sp":"N","t":"fulgida praesertim cum cernere saepe nequimus,"},{"sp":"N","t":"lumina luminibus quia nobis praepediuntur."},{"sp":"N","t":"quod foribus non fit; neque enim, qua cernimus ipsi,","st":"3.365"},{"sp":"N","t":"ostia suscipiunt ullum reclusa laborem."},{"sp":"N","t":"praeterea si pro foribus sunt lumina nostra,"},{"sp":"N","t":"iam magis exemptis oculis debere videtur"},{"sp":"N","t":"cernere res animus sublatis postibus ipsis."},{"sp":"N","t":"Illud in his rebus nequaquam sumere possis,","st":"3.370"},{"sp":"N","t":"Democriti quod sancta viri sententia ponit,"},{"sp":"N","t":"corporis atque animi primordia singula primis"},{"sp":"N","t":"adposita alternis, variare ac nectere membra."},{"sp":"N","t":"nam cum multo sunt animae elementa minora"},{"sp":"N","t":"quam quibus e corpus nobis et viscera constant,","st":"3.375"},{"sp":"N","t":"tum numero quoque concedunt et rara per artus"},{"sp":"N","t":"dissita sunt, dum taxat ut hoc promittere possis,"},{"sp":"N","t":"quantula prima queant nobis iniecta ciere"},{"sp":"N","t":"corpora sensiferos motus in corpore, tanta"},{"sp":"N","t":"intervalla tenere exordia prima animai.","st":"3.380"},{"sp":"N","t":"nam neque pulveris inter dum sentimus adhaesum"},{"sp":"N","t":"corpore nec membris incussam sidere cretam,"},{"sp":"N","t":"nec nebulam noctu neque arani tenvia fila"},{"sp":"N","t":"obvia sentimus, quando obretimur euntes,"},{"sp":"N","t":"nec supera caput eiusdem cecidisse vietam","st":"3.385"},{"sp":"N","t":"vestem nec plumas avium papposque volantis,"},{"sp":"N","t":"qui nimia levitate cadunt plerumque gravatim,"},{"sp":"N","t":"nec repentis itum cuiusvis cumque animantis"},{"sp":"N","t":"sentimus nec priva pedum vestigia quaeque,"},{"sp":"N","t":"corpore quae in nostro culices et cetera ponunt.","st":"3.390"},{"sp":"N","t":"usque adeo prius est in nobis multa ciendum"},{"sp":"N","t":"quam primordia sentiscant concussa animai,"},{"sp":"N","t":"semina corporibus nostris inmixta per artus,"},{"sp":"N","t":"et quam in his intervallis tuditantia possint"},{"sp":"N","t":"concursare coire et dissultare vicissim.","st":"3.395"},{"sp":"N","t":"Et magis est animus vitai claustra coercens"},{"sp":"N","t":"et dominantior ad vitam quam vis animai."},{"sp":"N","t":"nam sine mente animoque nequit residere per artus"},{"sp":"N","t":"temporis exiguam partem pars ulla animai,"},{"sp":"N","t":"sed comes insequitur facile et discedit in auras","st":"3.400"},{"sp":"N","t":"et gelidos artus in leti frigore linquit."},{"sp":"N","t":"at manet in vita cui mens animusque remansit,"},{"sp":"N","t":"quamvis est circum caesis lacer undique membris;"},{"sp":"N","t":"truncus adempta anima circum membrisque remota"},{"sp":"N","t":"vivit et aetherias vitalis suscipit auras;","st":"3.405"},{"sp":"N","t":"si non omnimodis, at magna parte animai"},{"sp":"N","t":"privatus, tamen in vita cunctatur et haeret;"},{"sp":"N","t":"ut, lacerato oculo circum si pupula mansit"},{"sp":"N","t":"incolumis, stat cernundi vivata potestas,"},{"sp":"N","t":"dum modo ne totum corrumpas luminis orbem","st":"3.410"},{"sp":"N","t":"et circum caedas aciem solamque relinquas;"},{"sp":"N","t":"id quoque enim sine pernicie non fiet eorum."},{"sp":"N","t":"at si tantula pars oculi media illa peresa est,"},{"sp":"N","t":"occidit extemplo lumen tenebraeque secuntur,"},{"sp":"N","t":"incolumis quamvis alioqui splendidus orbis.","st":"3.415"},{"sp":"N","t":"hoc anima atque animus vincti sunt foedere semper."},{"sp":"N","t":"Nunc age, nativos animantibus et mortalis"},{"sp":"N","t":"esse animos animasque levis ut noscere possis,"},{"sp":"N","t":"conquisita diu dulcique reperta labore"},{"sp":"N","t":"digna tua pergam disponere carmina vita.","st":"3.420"},{"sp":"N","t":"tu fac utrumque uno subiungas nomine eorum"},{"sp":"N","t":"atque animam verbi causa cum dicere pergam,"},{"sp":"N","t":"mortalem esse docens, animum quoque dicere credas,"},{"sp":"N","t":"qua tenus est unum inter se coniunctaque res est."},{"sp":"N","t":"Principio quoniam tenuem constare minutis","st":"3.425"},{"sp":"N","t":"corporibus docui multoque minoribus esse"},{"sp":"N","t":"principiis factam quam liquidus umor aquai"},{"sp":"N","t":"aut nebula aut fumus —; nam longe mobilitate"},{"sp":"N","t":"praestat et a tenui causa magis icta movetur,"},{"sp":"N","t":"quippe ubi imaginibus fumi nebulaeque movetur;","st":"3.430"},{"sp":"N","t":"quod genus in somnis sopiti ubi cernimus alte"},{"sp":"N","t":"exhalare vaporem altaria ferreque fumum;"},{"sp":"N","t":"nam procul haec dubio nobis simulacra geruntur"},{"sp":"N","t":"nunc igitur quoniam quassatis undique vasis"},{"sp":"N","t":"diffluere umorem et laticem discedere cernis,","st":"3.435"},{"sp":"N","t":"et nebula ac fumus quoniam discedit in auras,"},{"sp":"N","t":"crede animam quoque diffundi multoque perire"},{"sp":"N","t":"ocius et citius dissolvi in corpora prima,"},{"sp":"N","t":"cum semel ex hominis membris ablata recessit;"},{"sp":"N","t":"quippe etenim corpus, quod vas quasi constitit eius,","st":"3.440"},{"sp":"N","t":"cum cohibere nequit conquassatum ex aliqua re"},{"sp":"N","t":"ac rarefactum detracto sanguine venis,"},{"sp":"N","t":"aere qui credas posse hanc cohiberier ullo,"},{"sp":"N","t":"corpore qui nostro rarus magis incohibens sit?"},{"sp":"N","t":"Praeterea gigni pariter cum corpore et una","st":"3.445"},{"sp":"N","t":"crescere sentimus pariterque senescere mentem."},{"sp":"N","t":"nam vel ut infirmo pueri teneroque vagantur"},{"sp":"N","t":"corpore, sic animi sequitur sententia tenvis."},{"sp":"N","t":"inde ubi robustis adolevit viribus aetas,"},{"sp":"N","t":"consilium quoque maius et auctior est animi vis.","st":"3.450"},{"sp":"N","t":"post ubi iam validis quassatum est viribus aevi"},{"sp":"N","t":"corpus et obtusis ceciderunt viribus artus,"},{"sp":"N","t":"claudicat ingenium, delirat lingua labat mens,"},{"sp":"N","t":"omnia deficiunt atque uno tempore desunt."},{"sp":"N","t":"ergo dissolui quoque convenit omnem animai","st":"3.455"},{"sp":"N","t":"naturam, ceu fumus, in altas aeris auras;"},{"sp":"N","t":"quando quidem gigni pariter pariterque videmus"},{"sp":"N","t":"crescere et, ut docui, simul aevo fessa fatisci."},{"sp":"N","t":"Huc accedit uti videamus, corpus ut ipsum"},{"sp":"N","t":"suscipere inmanis morbos durumque dolorem,","st":"3.460"},{"sp":"N","t":"sic animum curas acris luctumque metumque;"},{"sp":"N","t":"quare participem leti quoque convenit esse."},{"sp":"N","t":"quin etiam morbis in corporis avius errat"},{"sp":"N","t":"saepe animus; dementit enim deliraque fatur,"},{"sp":"N","t":"inter dumque gravi lethargo fertur in altum","st":"3.465"},{"sp":"N","t":"aeternumque soporem oculis nutuque cadenti;"},{"sp":"N","t":"unde neque exaudit voces nec noscere voltus"},{"sp":"N","t":"illorum potis est, ad vitam qui revocantes"},{"sp":"N","t":"circum stant lacrimis rorantes ora genasque."},{"sp":"N","t":"quare animum quoque dissolui fateare necessest,","st":"3.470"},{"sp":"N","t":"quandoquidem penetrant in eum contagia morbi;"},{"sp":"N","t":"nam dolor ac morbus leti fabricator uterquest,"},{"sp":"N","t":"multorum exitio perdocti quod sumus ante."},{"sp":"N","t":"et quoniam mentem sanari corpus ut aegrum"},{"sp":"N","t":"et pariter mentem sanari corpus inani","st":"3.475"},{"sp":"N","t":"denique cor, hominem cum vini vis penetravit"},{"sp":"N","t":"acris et in venas discessit diditus ardor,"},{"sp":"N","t":"consequitur gravitas membrorum, praepediuntur"},{"sp":"N","t":"crura vacillanti, tardescit lingua, madet mens,"},{"sp":"N","t":"nant oculi, clamor singultus iurgia gliscunt,","st":"3.480"},{"sp":"N","t":"et iam cetera de genere hoc quae cumque secuntur,"},{"sp":"N","t":"cur ea sunt, nisi quod vehemens violentia vini"},{"sp":"N","t":"conturbare animam consuevit corpore in ipso?"},{"sp":"N","t":"at quae cumque queunt conturbari inque pediri,"},{"sp":"N","t":"significant, paulo si durior insinuarit","st":"3.485"},{"sp":"N","t":"causa, fore ut pereant aevo privata futuro."},{"sp":"N","t":"Quin etiam subito vi morbi saepe coactus"},{"sp":"N","t":"ante oculos aliquis nostros, ut fulminis ictu,"},{"sp":"N","t":"concidit et spumas agit, ingemit et tremit artus,"},{"sp":"N","t":"desipit, extentat nervos, torquetur, anhelat","st":"3.490"},{"sp":"N","t":"inconstanter, et in iactando membra fatigat,"},{"sp":"N","t":"ni mirum quia vis morbi distracta per artus"},{"sp":"N","t":"turbat agens animam, spumans ut in aequore salso"},{"sp":"N","t":"ventorum validis fervescunt viribus undae."},{"sp":"N","t":"exprimitur porro gemitus, quia membra dolore","st":"3.495"},{"sp":"N","t":"adficiuntur et omnino quod semina vocis"},{"sp":"N","t":"eliciuntur et ore foras glomerata feruntur"},{"sp":"N","t":"qua quasi consuerunt et sunt munita viai."},{"sp":"N","t":"desipientia fit, quia vis animi atque animai"},{"sp":"N","t":"conturbatur et, ut docui, divisa seorsum","st":"3.500"},{"sp":"N","t":"disiectatur eodem illo distracta veneno."},{"sp":"N","t":"inde ubi iam morbi reflexit causa, reditque"},{"sp":"N","t":"in latebras acer corrupti corporis umor,"},{"sp":"N","t":"tum quasi vaccillans primum consurgit et omnis"},{"sp":"N","t":"paulatim redit in sensus animamque receptat.","st":"3.505"},{"sp":"N","t":"haec igitur tantis ubi morbis corpore in ipso"},{"sp":"N","t":"iactentur miserisque modis distracta laborent,"},{"sp":"N","t":"cur eadem credis sine corpore in aere aperto"},{"sp":"N","t":"cum validis ventis aetatem degere posse?"},{"sp":"N","t":"Et quoniam mentem sanari corpus ut aegrum","st":"3.510"},{"sp":"N","t":"cernimus et flecti medicina posse videmus,"},{"sp":"N","t":"id quoque praesagit mortalem vivere mentem."},{"sp":"N","t":"addere enim partis aut ordine traiecere aecumst"},{"sp":"N","t":"aut aliquid prosum de summa detrahere hilum,"},{"sp":"N","t":"commutare animum qui cumque adoritur et infit","st":"3.515"},{"sp":"N","t":"aut aliam quamvis naturam flectere quaerit."},{"sp":"N","t":"at neque transferri sibi partis nec tribui vult"},{"sp":"N","t":"inmortale quod est quicquam neque defluere hilum;"},{"sp":"N","t":"nam quod cumque suis mutatum finibus exit,"},{"sp":"N","t":"continuo hoc mors est illius quod fuit ante.","st":"3.520"},{"sp":"N","t":"ergo animus sive aegrescit, mortalia signa"},{"sp":"N","t":"mittit, uti docui, seu flectitur a medicina."},{"sp":"N","t":"usque adeo falsae rationi vera videtur"},{"sp":"N","t":"res occurrere et effugium praecludere eunti"},{"sp":"N","t":"ancipitique refutatu convincere falsum.","st":"3.525"},{"sp":"N","t":"Denique saepe hominem paulatim cernimus ire"},{"sp":"N","t":"et membratim vitalem deperdere sensum;"},{"sp":"N","t":"in pedibus primum digitos livescere et unguis,"},{"sp":"N","t":"inde pedes et crura mori, post inde per artus"},{"sp":"N","t":"ire alios tractim gelidi vestigia leti.","st":"3.530"},{"sp":"N","t":"scinditur atque animae haec quoniam natura nec uno"},{"sp":"N","t":"tempore sincera existit, mortalis habendast."},{"sp":"N","t":"quod si forte putas ipsam se posse per artus"},{"sp":"N","t":"introsum trahere et partis conducere in unum"},{"sp":"N","t":"atque ideo cunctis sensum diducere membris,","st":"3.535"},{"sp":"N","t":"at locus ille tamen, quo copia tanta animai"},{"sp":"N","t":"cogitur, in sensu debet maiore videri;"},{"sp":"N","t":"qui quoniam nusquamst, ni mirum, ut diximus ante,"},{"sp":"N","t":"dilaniata foras dispargitur, interit ergo."},{"sp":"N","t":"quin etiam si iam libeat concedere falsum","st":"3.540"},{"sp":"N","t":"et dare posse animam glomerari in corpore eorum,"},{"sp":"N","t":"lumina qui lincunt moribundi particulatim,"},{"sp":"N","t":"mortalem tamen esse animam fateare necesse"},{"sp":"N","t":"nec refert utrum pereat dispersa per auras"},{"sp":"N","t":"an contracta suis e partibus obbrutescat,","st":"3.545"},{"sp":"N","t":"quando hominem totum magis ac magis undique sensus"},{"sp":"N","t":"deficit et vitae minus et minus undique restat."},{"sp":"N","t":"Et quoniam mens est hominis pars una locoque"},{"sp":"N","t":"fixa manet certo, vel ut aures atque oculi sunt"},{"sp":"N","t":"atque alii sensus qui vitam cumque gubernant,","st":"3.550"},{"sp":"N","t":"et vel uti manus atque oculus naresve seorsum"},{"sp":"N","t":"secreta ab nobis nequeunt sentire neque esse,"},{"sp":"N","t":"sed tamen in parvo lincuntur tempore tali,"},{"sp":"N","t":"sic animus per se non quit sine corpore et ipso"},{"sp":"N","t":"esse homine, illius quasi quod vas esse videtur,","st":"3.555"},{"sp":"N","t":"sive aliud quid vis potius coniunctius ei"},{"sp":"N","t":"fingere, quandoquidem conexu corpus adhaeret."},{"sp":"N","t":"Denique corporis atque animi vivata potestas"},{"sp":"N","t":"inter se coniuncta valent vitaque fruuntur;"},{"sp":"N","t":"nec sine corpore enim vitalis edere motus","st":"3.560"},{"sp":"N","t":"sola potest animi per se natura nec autem"},{"sp":"N","t":"cassum anima corpus durare et sensibus uti."},{"sp":"N","t":"scilicet avolsus radicibus ut nequit ullam"},{"sp":"N","t":"dispicere ipse oculus rem seorsum corpore toto,"},{"sp":"N","t":"sic anima atque animus per se nil posse videtur.","st":"3.565"},{"sp":"N","t":"ni mirum quia per venas et viscera mixtim,"},{"sp":"N","t":"per nervos atque ossa tenentur corpore ab omni"},{"sp":"N","t":"nec magnis intervallis primordia possunt"},{"sp":"N","t":"libera dissultare, ideo conclusa moventur"},{"sp":"N","t":"sensiferos motus, quos extra corpus in auras","st":"3.570"},{"sp":"N","t":"aeris haut possunt post mortem eiecta moveri"},{"sp":"N","t":"propterea quia non simili ratione tenentur;"},{"sp":"N","t":"corpus enim atque animans erit aer, si cohibere"},{"sp":"N","t":"sese anima atque in eos poterit concludere motus,"},{"sp":"N","t":"quos ante in nervis et in ipso corpore agebat.","st":"3.575"},{"sp":"N","t":"quare etiam atque etiam resoluto corporis omni"},{"sp":"N","t":"tegmine et eiectis extra vitalibus auris"},{"sp":"N","t":"dissolui sensus animi fateare necessest"},{"sp":"N","t":"atque animam, quoniam coniunctast causa duobus."},{"sp":"N","t":"Denique cum corpus nequeat perferre animai","st":"3.580"},{"sp":"N","t":"discidium, quin in taetro tabescat odore,"},{"sp":"N","t":"quid dubitas quin ex imo penitusque coorta"},{"sp":"N","t":"emanarit uti fumus diffusa animae vis,"},{"sp":"N","t":"atque ideo tanta mutatum putre ruina"},{"sp":"N","t":"conciderit corpus, penitus quia mota loco sunt","st":"3.585"},{"sp":"N","t":"fundamenta foras manant animaeque per artus"},{"sp":"N","t":"perque viarum omnis flexus, in corpore qui sunt,"},{"sp":"N","t":"atque foramina? multimodis ut noscere possis"},{"sp":"N","t":"dispertitam animae naturam exisse per artus"},{"sp":"N","t":"et prius esse sibi distractam corpore in ipso,","st":"3.590"},{"sp":"N","t":"quam prolapsa foras enaret in aeris auras."},{"sp":"N","t":"Quin etiam finis dum vitae vertitur intra,"},{"sp":"N","t":"saepe aliqua tamen e causa labefacta videtur"},{"sp":"N","t":"ire anima ac toto solui de corpore tota"},{"sp":"N","t":"et quasi supremo languescere tempore voltus","st":"3.595"},{"sp":"N","t":"molliaque exsangui cadere omnia corpore membra."},{"sp":"N","t":"quod genus est, animo male factum cum perhibetur"},{"sp":"N","t":"aut animam liquisse; ubi iam trepidatur et omnes"},{"sp":"N","t":"extremum cupiunt vitae reprehendere vinclum;"},{"sp":"N","t":"conquassatur enim tum mens animaeque potestas","st":"3.600"},{"sp":"N","t":"omnis. et haec ipso cum corpore conlabefiunt,"},{"sp":"N","t":"ut gravior paulo possit dissolvere causa."},{"sp":"N","t":"Quid dubitas tandem quin extra prodita corpus"},{"sp":"N","t":"inbecilla foras in aperto, tegmine dempto,"},{"sp":"N","t":"non modo non omnem possit durare per aevom,","st":"3.605"},{"sp":"N","t":"sed minimum quodvis nequeat consistere tempus?"},{"sp":"N","t":"nec sibi enim quisquam moriens sentire videtur"},{"sp":"N","t":"ire foras animam incolumem de corpore toto,"},{"sp":"N","t":"nec prius ad iugulum et supera succedere fauces,"},{"sp":"N","t":"verum deficere in certa regione locatam;","st":"3.610"},{"sp":"N","t":"ut sensus alios in parti quemque sua scit"},{"sp":"N","t":"dissolui. quod si inmortalis nostra foret mens,"},{"sp":"N","t":"non tam se moriens dissolvi conquereretur,"},{"sp":"N","t":"sed magis ire foras vestemque relinquere, ut anguis."},{"sp":"N","t":"Denique cur animi numquam mens consiliumque","st":"3.615"},{"sp":"N","t":"gignitur in capite aut pedibus manibusve, sed unis"},{"sp":"N","t":"sedibus et certis regionibus omnibus haeret,"},{"sp":"N","t":"si non certa loca ad nascendum reddita cuique"},{"sp":"N","t":"sunt, et ubi quicquid possit durare creatum"},{"sp":"N","t":"atque ita multimodis partitis artubus esse,","st":"3.620"},{"sp":"N","t":"membrorum ut numquam existat praeposterus ordo?"},{"sp":"N","t":"usque adeo sequitur res rem, neque flamma creari"},{"sp":"N","t":"fluminibus solitast neque in igni gignier algor."},{"sp":"N","t":"Praeterea si inmortalis natura animaist"},{"sp":"N","t":"et sentire potest secreta a corpore nostro,","st":"3.625"},{"sp":"N","t":"quinque, ut opinor, eam faciundum est sensibus auctam."},{"sp":"N","t":"nec ratione alia nosmet proponere nobis"},{"sp":"N","t":"possumus infernas animas Acherunte vagare."},{"sp":"N","t":"pictores itaque et scriptorum saecla priora"},{"sp":"N","t":"sic animas intro duxerunt sensibus auctas.","st":"3.630"},{"sp":"N","t":"at neque sorsum oculi neque nares nec manus ipsa"},{"sp":"N","t":"esse potest animae neque sorsum lingua neque aures;"},{"sp":"N","t":"haud igitur per se possunt sentire neque esse."},{"sp":"N","t":"Et quoniam toto sentimus corpore inesse"},{"sp":"N","t":"vitalem sensum et totum esse animale videmus,","st":"3.635"},{"sp":"N","t":"si subito medium celeri praeciderit ictu"},{"sp":"N","t":"vis aliqua, ut sorsum partem secernat utramque,"},{"sp":"N","t":"dispertita procul dubio quoque vis animai"},{"sp":"N","t":"et discissa simul cum corpore dissicietur."},{"sp":"N","t":"at quod scinditur et partis discedit in ullas,","st":"3.640"},{"sp":"N","t":"scilicet aeternam sibi naturam abnuit esse."},{"sp":"N","t":"falciferos memorant currus abscidere membra"},{"sp":"N","t":"saepe ita de subito permixta caede calentis,"},{"sp":"N","t":"ut tremere in terra videatur ab artubus id quod"},{"sp":"N","t":"decidit abscisum, cum mens tamen atque hominis vis","st":"3.645"},{"sp":"N","t":"mobilitate mali non quit sentire dolorem;"},{"sp":"N","t":"et simul in pugnae studio quod dedita mens est,"},{"sp":"N","t":"corpore relicuo pugnam caedesque petessit,"},{"sp":"N","t":"nec tenet amissam laevam cum tegmine saepe"},{"sp":"N","t":"inter equos abstraxe rotas falcesque rapaces,","st":"3.650"},{"sp":"N","t":"nec cecidisse alius dextram, cum scandit et instat."},{"sp":"N","t":"inde alius conatur adempto surgere crure,"},{"sp":"N","t":"cum digitos agitat propter moribundus humi pes."},{"sp":"N","t":"et caput abscisum calido viventeque trunco"},{"sp":"N","t":"servat humi voltum vitalem oculosque patentis,","st":"3.655"},{"sp":"N","t":"donec reliquias animai reddidit omnes."},{"sp":"N","t":"quin etiam tibi si, lingua vibrante, minanti"},{"sp":"N","t":"serpentis cauda, procero corpore, utrumque"},{"sp":"N","t":"sit libitum in multas partis discidere ferro,"},{"sp":"N","t":"omnia iam sorsum cernes ancisa recenti","st":"3.660"},{"sp":"N","t":"volnere tortari et terram conspargere tabo,"},{"sp":"N","t":"ipsam seque retro partem petere ore priorem,"},{"sp":"N","t":"volneris ardenti ut morsu premat icta dolore."},{"sp":"N","t":"omnibus esse igitur totas dicemus in illis"},{"sp":"N","t":"particulis animas? at ea ratione sequetur","st":"3.665"},{"sp":"N","t":"unam animantem animas habuisse in corpore multas."},{"sp":"N","t":"ergo divisast ea quae fuit una simul cum"},{"sp":"N","t":"corpore; quapropter mortale utrumque putandumst,"},{"sp":"N","t":"in multas quoniam partis disciditur aeque."},{"sp":"N","t":"Praeterea si inmortalis natura animai","st":"3.670"},{"sp":"N","t":"constat et in corpus nascentibus insinuatur,"},{"sp":"N","t":"cur super ante actam aetatem meminisse nequimus"},{"sp":"N","t":"nec vestigia gestarum rerum ulla tenemus?"},{"sp":"N","t":"nam si tanto operest animi mutata potestas,"},{"sp":"N","t":"omnis ut actarum exciderit retinentia rerum,","st":"3.675"},{"sp":"N","t":"non, ut opinor, id ab leto iam longius errat;"},{"sp":"N","t":"qua propter fateare necessest quae fuit ante"},{"sp":"N","t":"interiisse, et quae nunc est nunc esse creatam."},{"sp":"N","t":"Praeterea si iam perfecto corpore nobis"},{"sp":"N","t":"inferri solitast animi vivata potestas","st":"3.680"},{"sp":"N","t":"tum cum gignimur et vitae cum limen inimus,"},{"sp":"N","t":"haud ita conveniebat uti cum corpore et una"},{"sp":"N","t":"cum membris videatur in ipso sanguine cresse,"},{"sp":"N","t":"sed vel ut in cavea per se sibi vivere solam"},{"sp":"N","t":"convenit, ut sensu corpus tamen affluat omne.","st":"3.685"},{"sp":"N","t":"quare etiam atque etiam neque originis esse putandumst"},{"sp":"N","t":"expertis animas nec leti lege solutas;"},{"sp":"N","t":"nam neque tanto opere adnecti potuisse putandumst"},{"sp":"N","t":"corporibus nostris extrinsecus insinuatas,"},{"sp":"N","t":"quod fieri totum contra manifesta docet res","st":"3.690"},{"sp":"N","t":"namque ita conexa est per venas viscera nervos"},{"sp":"N","t":"ossaque, uti dentes quoque sensu participentur;"},{"sp":"N","t":"morbus ut indicat et gelidai stringor aquai"},{"sp":"N","t":"et lapis oppressus subitis e frugibus asper"},{"sp":"N","t":"nec, tam contextae cum sint, exire videntur","st":"3.695"},{"sp":"N","t":"incolumes posse et salvas exsolvere sese"},{"sp":"N","t":"omnibus e nervis atque ossibus articulisque,"},{"sp":"N","t":"quod si forte putas extrinsecus insinuatam"},{"sp":"N","t":"permanare animam nobis per membra solere,"},{"sp":"N","t":"tanto quique magis cum corpore fusa peribit;","st":"3.700"},{"sp":"N","t":"quod permanat enim, dissolvitur, interit ergo;"},{"sp":"N","t":"dispertitur enim per caulas corporis omnis."},{"sp":"N","t":"ut cibus, in membra atque artus cum diditur omnis,"},{"sp":"N","t":"disperit atque aliam naturam sufficit ex se,"},{"sp":"N","t":"sic anima atque animus quamvis est integra recens in","st":"3.705"},{"sp":"N","t":"corpus eunt, tamen in manando dissoluuntur,"},{"sp":"N","t":"dum quasi per caulas omnis diduntur in artus"},{"sp":"N","t":"particulae quibus haec animi natura creatur,"},{"sp":"N","t":"quae nunc in nostro dominatur corpore nata"},{"sp":"N","t":"ex illa quae tunc periit partita per artus.","st":"3.710"},{"sp":"N","t":"quapropter neque natali privata videtur"},{"sp":"N","t":"esse die natura animae nec funeris expers."},{"sp":"N","t":"Semina praeterea linquontur necne animai"},{"sp":"N","t":"corpore in exanimo? quod si lincuntur et insunt,"},{"sp":"N","t":"haut erit ut merito inmortalis possit haberi,","st":"3.715"},{"sp":"N","t":"partibus amissis quoniam libata recessit."},{"sp":"N","t":"sin ita sinceris membris ablata profugit,"},{"sp":"N","t":"ut nullas partis in corpore liquerit ex se,"},{"sp":"N","t":"unde cadavera rancenti iam viscere vermes"},{"sp":"N","t":"expirant atque unde animantum copia tanta","st":"3.720"},{"sp":"N","t":"exos et exanguis tumidos perfluctuat artus?"},{"sp":"N","t":"quod si forte animas extrinsecus insinuari?"},{"sp":"N","t":"vermibus et privas in corpora posse venire"},{"sp":"N","t":"credis nec reputas cur milia multa animarum"},{"sp":"N","t":"conveniant unde una recesserit, hoc tamen est ut","st":"3.725"},{"sp":"N","t":"quaerendum videatur et in discrimen agendum,"},{"sp":"N","t":"utrum tandem animae venentur semina quaeque"},{"sp":"N","t":"vermiculorum ipsaeque sibi fabricentur ubi sint,"},{"sp":"N","t":"an quasi corporibus perfectis insinuentur."},{"sp":"N","t":"at neque cur faciant ipsae quareve laborent","st":"3.730"},{"sp":"N","t":"dicere suppeditat. neque enim, sine corpore cum sunt,"},{"sp":"N","t":"sollicitae volitant morbis alguque fameque;"},{"sp":"N","t":"corpus enim magis his vitiis adfine laborat,"},{"sp":"N","t":"et mala multa animus contage fungitur eius."},{"sp":"N","t":"sed tamen his esto quamvis facere utile corpus,","st":"3.735"},{"sp":"N","t":"cum subeant; at qua possint via nulla videtur."},{"sp":"N","t":"haut igitur faciunt animae sibi corpora et artus."},{"sp":"N","t":"nec tamen est ut qui cum perfectis insinuentur"},{"sp":"N","t":"corporibus; neque enim poterunt suptiliter esse"},{"sp":"N","t":"conexae neque consensu contagia fient.","st":"3.740"},{"sp":"N","t":"Denique cur acris violentia triste leonum"},{"sp":"N","t":"seminium sequitur, volpes dolus, et fuga cervos?"},{"sp":"N","t":"a patribus datur et a patrius pavor incitat artus,"},{"sp":"N","t":"et iam cetera de genere hoc cur omnia membris"},{"sp":"N","t":"ex ineunte aevo generascunt ingenioque,","st":"3.745"},{"sp":"N","t":"si non, certa suo quia semine seminioque"},{"sp":"N","t":"vis animi pariter crescit cum corpore quoque?"},{"sp":"N","t":"quod si inmortalis foret et mutare soleret"},{"sp":"N","t":"corpora, permixtis animantes moribus essent,"},{"sp":"N","t":"effugeret canis Hyrcano de semine saepe","st":"3.750"},{"sp":"N","t":"cornigeri incursum cervi tremeretque per auras"},{"sp":"N","t":"aeris accipiter fugiens veniente columba,"},{"sp":"N","t":"desiperent homines, saperent fera saecla ferarum."},{"sp":"N","t":"illud enim falsa fertur ratione, quod aiunt"},{"sp":"N","t":"inmortalem animam mutato corpore flecti;","st":"3.755"},{"sp":"N","t":"quod mutatur enim, dissolvitur, interit ergo;"},{"sp":"N","t":"traiciuntur enim partes atque ordine migrant;"},{"sp":"N","t":"quare dissolui quoque debent posse per artus,"},{"sp":"N","t":"denique ut intereant una cum corpore cunctae."},{"sp":"N","t":"sin animas hominum dicent in corpora semper","st":"3.760"},{"sp":"N","t":"ire humana, tamen quaeram cur e sapienti"},{"sp":"N","t":"stulta queat fieri, nec prudens sit puer ullus,"},{"sp":"N","t":"si non, certa suo quia semine seminioque"},{"sp":"N","t":"nec tam doctus equae pullus quam fortis equi vis."},{"sp":"N","t":"scilicet in tenero tenerascere corpore mentem","st":"3.765"},{"sp":"N","t":"confugient. quod si iam fit, fateare necessest"},{"sp":"N","t":"mortalem esse animam, quoniam mutata per artus"},{"sp":"N","t":"tanto opere amittit vitam sensumque priorem."},{"sp":"N","t":"quove modo poterit pariter cum corpore quoque"},{"sp":"N","t":"confirmata cupitum aetatis tangere florem","st":"3.770"},{"sp":"N","t":"vis animi, nisi erit consors in origine prima?"},{"sp":"N","t":"quidve foras sibi vult membris exire senectis?"},{"sp":"N","t":"an metuit conclusa manere in corpore putri"},{"sp":"N","t":"et domus aetatis spatio ne fessa vetusto"},{"sp":"N","t":"obruat? at non sunt immortali ulla pericla.","st":"3.775"},{"sp":"N","t":"Denique conubia ad Veneris partusque ferarum"},{"sp":"N","t":"esse animas praesto deridiculum esse videtur,"},{"sp":"N","t":"expectare immortalis mortalia membra"},{"sp":"N","t":"innumero numero certareque praeproperanter"},{"sp":"N","t":"inter se quae prima potissimaque insinuetur;","st":"3.780"},{"sp":"N","t":"si non forte ita sunt animarum foedera pacta,"},{"sp":"N","t":"ut quae prima volans advenerit insinuetur"},{"sp":"N","t":"prima neque inter se contendant viribus hilum."},{"sp":"N","t":"Denique in aethere non arbor, non aequore in alto"},{"sp":"N","t":"nubes esse queunt nec pisces vivere in arvis","st":"3.785"},{"sp":"N","t":"nec cruor in lignis neque saxis sucus inesse."},{"sp":"N","t":"certum ac dispositumst ubi quicquid crescat et insit."},{"sp":"N","t":"sic animi natura nequit sine corpore oriri"},{"sp":"N","t":"sola neque a nervis et sanguine longius esse."},{"sp":"N","t":"quod si posset enim, multo prius ipsa animi vis","st":"3.790"},{"sp":"N","t":"in capite aut umeris aut imis calcibus esse"},{"sp":"N","t":"posset et innasci quavis in parte soleret,"},{"sp":"N","t":"tandem in eodem homine atque in eodem vase manere."},{"sp":"N","t":"quod quoniam nostro quoque constat corpore certum"},{"sp":"N","t":"dispositumque videtur ubi esse et crescere possit","st":"3.795"},{"sp":"N","t":"sorsum anima atque animus, tanto magis infitiandum"},{"sp":"N","t":"totum posse extra corpus durare genique."},{"sp":"N","t":"quare, corpus ubi interiit, periisse necessest"},{"sp":"N","t":"confiteare animam distractam in corpore toto."},{"sp":"N","t":"quippe etenim mortale aeterno iungere et una","st":"3.800"},{"sp":"N","t":"consentire putare et fungi mutua posse"},{"sp":"N","t":"desiperest; quid enim diversius esse putandumst"},{"sp":"N","t":"aut magis inter se disiunctum discrepitansque,"},{"sp":"N","t":"quam mortale quod est inmortali atque perenni"},{"sp":"N","t":"iunctum in concilio saevas tolerare procellas?","st":"3.805"},{"sp":"N","t":"praeterea quaecumque manent aeterna necessest"},{"sp":"N","t":"aut quia sunt solido cum corpore respuere ictus"},{"sp":"N","t":"nec penetrare pati sibi quicquam quod queat artas"},{"sp":"N","t":"dissociare intus partis, ut materiai"},{"sp":"N","t":"corpora sunt, quorum naturam ostendimus ante,","st":"3.810"},{"sp":"N","t":"aut ideo durare aetatem posse per omnem,"},{"sp":"N","t":"plagarum quia sunt expertia sicut inanest,"},{"sp":"N","t":"quod manet intactum neque ab ictu fungitur hilum,"},{"sp":"N","t":"aut etiam quia nulla loci sit copia circum,"},{"sp":"N","t":"quo quasi res possint discedere dissoluique,","st":"3.815"},{"sp":"N","t":"sicut summarum summast aeterna, neque extra"},{"sp":"N","t":"quis locus est quo diffugiant neque corpora sunt quae"},{"sp":"N","t":"possint incidere et valida dissolvere plaga."},{"sp":"N","t":"Quod si forte ideo magis inmortalis habendast,"},{"sp":"N","t":"quod vitalibus ab rebus munita tenetur,","st":"3.820"},{"sp":"N","t":"aut quia non veniunt omnino aliena salutis,"},{"sp":"N","t":"aut quia quae veniunt aliqua ratione recedunt"},{"sp":"N","t":"pulsa prius quam quid noceant sentire queamus,"},{"sp":"N","t":"praeter enim quam quod morbis cum corporis aegret,"},{"sp":"N","t":"advenit id quod eam de rebus saepe futuris","st":"3.825"},{"sp":"N","t":"macerat inque metu male habet curisque fatigat,"},{"sp":"N","t":"praeteritisque male admissis peccata remordent."},{"sp":"N","t":"adde furorem animi proprium atque oblivia rerum,"},{"sp":"N","t":"adde quod in nigras lethargi mergitur undas."},{"sp":"N","t":"Nil igitur mors est ad nos neque pertinet hilum,","st":"3.830"},{"sp":"N","t":"quandoquidem natura animi mortalis habetur."},{"sp":"N","t":"et vel ut ante acto nihil tempore sensimus aegri,"},{"sp":"N","t":"ad confligendum venientibus undique Poenis,"},{"sp":"N","t":"omnia cum belli trepido concussa tumultu"},{"sp":"N","t":"horrida contremuere sub altis aetheris auris,","st":"3.835"},{"sp":"N","t":"in dubioque fuere utrorum ad regna cadendum"},{"sp":"N","t":"omnibus humanis esset terraque marique,"},{"sp":"N","t":"sic, ubi non erimus, cum corporis atque animai"},{"sp":"N","t":"discidium fuerit, quibus e sumus uniter apti,"},{"sp":"N","t":"scilicet haud nobis quicquam, qui non erimus tum,","st":"3.840"},{"sp":"N","t":"accidere omnino poterit sensumque movere,"},{"sp":"N","t":"non si terra mari miscebitur et mare caelo."},{"sp":"N","t":"et si iam nostro sentit de corpore postquam"},{"sp":"N","t":"distractast animi natura animaeque potestas,"},{"sp":"N","t":"nil tamen est ad nos, qui comptu coniugioque","st":"3.845"},{"sp":"N","t":"corporis atque animae consistimus uniter apti."},{"sp":"N","t":"nec, si materiem nostram collegerit aetas"},{"sp":"N","t":"post obitum rursumque redegerit ut sita nunc est,"},{"sp":"N","t":"atque iterum nobis fuerint data lumina vitae,"},{"sp":"N","t":"pertineat quicquam tamen ad nos id quoque factum,","st":"3.850"},{"sp":"N","t":"interrupta semel cum sit repetentia nostri."},{"sp":"N","t":"et nunc nil ad nos de nobis attinet, ante"},{"sp":"N","t":"qui fuimus, neque iam de illis nos adficit angor."},{"sp":"N","t":"nam cum respicias inmensi temporis omne"},{"sp":"N","t":"praeteritum spatium, tum motus materiai","st":"3.855"},{"sp":"N","t":"multimodi quam sint, facile hoc adcredere possis,"},{"sp":"N","t":"semina saepe in eodem, ut nunc sunt, ordine posta"},{"sp":"N","t":"haec eadem, quibus e nunc nos sumus, ante fuisse."},{"sp":"N","t":"nec memori tamen id quimus reprehendere mente;"},{"sp":"N","t":"inter enim iectast vitai pausa vageque","st":"3.860"},{"sp":"N","t":"deerrarunt passim motus ab sensibus omnes."},{"sp":"N","t":"debet enim, misere si forte aegreque futurumst;"},{"sp":"N","t":"ipse quoque esse in eo tum tempore, cui male possit"},{"sp":"N","t":"accidere. id quoniam mors eximit, esseque prohibet"},{"sp":"N","t":"illum cui possint incommoda conciliari,","st":"3.865"},{"sp":"N","t":"scire licet nobis nihil esse in morte timendum"},{"sp":"N","t":"nec miserum fieri qui non est posse, neque hilum"},{"sp":"N","t":"differre an nullo fuerit iam tempore natus,"},{"sp":"N","t":"mortalem vitam mors cum inmortalis ademit."},{"sp":"N","t":"Proinde ubi se videas hominem indignarier ipsum,","st":"3.870"},{"sp":"N","t":"post mortem fore ut aut putescat corpore posto"},{"sp":"N","t":"aut flammis interfiat malisve ferarum,"},{"sp":"N","t":"scire licet non sincerum sonere atque subesse"},{"sp":"N","t":"caecum aliquem cordi stimulum, quamvis neget ipse"},{"sp":"N","t":"credere se quemquam sibi sensum in morte futurum;","st":"3.875"},{"sp":"N","t":"non, ut opinor, enim dat quod promittit et unde"},{"sp":"N","t":"nec radicitus e vita se tollit et eicit,"},{"sp":"N","t":"sed facit esse sui quiddam super inscius ipse."},{"sp":"N","t":"vivus enim sibi cum proponit quisque futurum,"},{"sp":"N","t":"corpus uti volucres lacerent in morte feraeque,","st":"3.880"},{"sp":"N","t":"ipse sui miseret; neque enim se dividit illim"},{"sp":"N","t":"nec removet satis a proiecto corpore et illum"},{"sp":"N","t":"se fingit sensuque suo contaminat astans."},{"sp":"N","t":"hinc indignatur se mortalem esse creatum"},{"sp":"N","t":"nec videt in vera nullum fore morte alium se,","st":"3.885"},{"sp":"N","t":"qui possit vivus sibi se lugere peremptum"},{"sp":"N","t":"stansque iacentem se lacerari urive dolere."},{"sp":"N","t":"nam si in morte malumst malis morsuque ferarum"},{"sp":"N","t":"tractari, non invenio qui non sit acerbum"},{"sp":"N","t":"ignibus inpositum calidis torrescere flammis","st":"3.890"},{"sp":"N","t":"aut in melle situm suffocari atque rigere"},{"sp":"N","t":"frigore, cum summo gelidi cubat aequore saxi,"},{"sp":"N","t":"urgerive superne obrutum pondere terrae."},{"sp":"N","t":"'Iam iam non domus accipiet te laeta neque uxor"},{"sp":"N","t":"optima, nec dulces occurrent oscula nati","st":"3.895"},{"sp":"N","t":"praeripere et tacita pectus dulcedine tangent."},{"sp":"N","t":"non poteris factis florentibus esse tuisque"},{"sp":"N","t":"praesidium. misero misere' aiunt 'omnia ademit"},{"sp":"N","t":"una dies infesta tibi tot praemia vitae.'"},{"sp":"N","t":"illud in his rebus non addunt 'nec tibi earum","st":"3.900"},{"sp":"N","t":"iam desiderium rerum super insidet una.'"},{"sp":"N","t":"quod bene si videant animo dictisque sequantur,"},{"sp":"N","t":"dissoluant animi magno se angore metuque."},{"sp":"N","t":"'tu quidem ut es leto sopitus, sic eris aevi"},{"sp":"N","t":"quod super est cunctis privatus doloribus aegris;","st":"3.905"},{"sp":"N","t":"at nos horrifico cinefactum te prope busto"},{"sp":"N","t":"insatiabiliter deflevimus, aeternumque"},{"sp":"N","t":"nulla dies nobis maerorem e pectore demet.'"},{"sp":"N","t":"illud ab hoc igitur quaerendum est, quid sit amari"},{"sp":"N","t":"tanto opere, ad somnum si res redit atque quietem,","st":"3.910"},{"sp":"N","t":"cur quisquam aeterno possit tabescere luctu."},{"sp":"N","t":"Hoc etiam faciunt ubi discubuere tenentque"},{"sp":"N","t":"pocula saepe homines et inumbrant ora coronis,"},{"sp":"N","t":"ex animo ut dicant: 'brevis hic est fructus homullis;"},{"sp":"N","t":"iam fuerit neque post umquam revocare licebit.'","st":"3.915"},{"sp":"N","t":"tam quam in morte mali cum primis hoc sit eorum,"},{"sp":"N","t":"quod sitis exurat miseros atque arida torrat,"},{"sp":"N","t":"aut aliae cuius desiderium insideat rei."},{"sp":"N","t":"nec sibi enim quisquam tum se vitamque requiret,"},{"sp":"N","t":"cum pariter mens et corpus sopita quiescunt;","st":"3.920"},{"sp":"N","t":"nam licet aeternum per nos sic esse soporem,"},{"sp":"N","t":"nec desiderium nostri nos adficit ullum,"},{"sp":"N","t":"et tamen haud quaquam nostros tunc illa per artus"},{"sp":"N","t":"longe ab sensiferis primordia motibus errant,"},{"sp":"N","t":"cum correptus homo ex somno se colligit ipse.","st":"3.925"},{"sp":"N","t":"multo igitur mortem minus ad nos esse putandumst,"},{"sp":"N","t":"si minus esse potest quam quod nihil esse videmus;"},{"sp":"N","t":"maior enim turbae disiectus materiai"},{"sp":"N","t":"consequitur leto nec quisquam expergitus extat,"},{"sp":"N","t":"frigida quem semel est vitai pausa secuta.","st":"3.930"},{"sp":"N","t":"Denique si vocem rerum natura repente."},{"sp":"N","t":"mittat et hoc alicui nostrum sic increpet ipsa:"},{"sp":"N","t":"'quid tibi tanto operest, mortalis, quod nimis aegris"},{"sp":"N","t":"luctibus indulges? quid mortem congemis ac fles?"},{"sp":"N","t":"nam si grata fuit tibi vita ante acta priorque","st":"3.935"},{"sp":"N","t":"et non omnia pertusum congesta quasi in vas"},{"sp":"N","t":"commoda perfluxere atque ingrata interiere;"},{"sp":"N","t":"cur non ut plenus vitae conviva recedis"},{"sp":"N","t":"aequo animoque capis securam, stulte, quietem?"},{"sp":"N","t":"sin ea quae fructus cumque es periere profusa","st":"3.940"},{"sp":"N","t":"vitaque in offensost, cur amplius addere quaeris,"},{"sp":"N","t":"rursum quod pereat male et ingratum occidat omne,"},{"sp":"N","t":"non potius vitae finem facis atque laboris?"},{"sp":"N","t":"nam tibi praeterea quod machiner inveniamque,"},{"sp":"N","t":"quod placeat, nihil est; eadem sunt omnia semper.","st":"3.945"},{"sp":"N","t":"si tibi non annis corpus iam marcet et artus"},{"sp":"N","t":"confecti languent, eadem tamen omnia restant,"},{"sp":"N","t":"omnia si perges vivendo vincere saecla,"},{"sp":"N","t":"atque etiam potius, si numquam sis moriturus',"},{"sp":"N","t":"quid respondemus, nisi iustam intendere litem","st":"3.950"},{"sp":"N","t":"naturam et veram verbis exponere causam?"},{"sp":"N","t":"grandior hic vero si iam seniorque queratur"},{"sp":"N","t":"atque obitum lamentetur miser amplius aequo,"},{"sp":"N","t":"non merito inclamet magis et voce increpet acri:"},{"sp":"N","t":"'aufer abhinc lacrimas, baratre, et compesce querellas.","st":"3.955"},{"sp":"N","t":"omnia perfunctus vitai praemia marces;"},{"sp":"N","t":"sed quia semper aves quod abest, praesentia temnis,"},{"sp":"N","t":"inperfecta tibi elapsast ingrataque vita,"},{"sp":"N","t":"et nec opinanti mors ad caput adstitit ante"},{"sp":"N","t":"quam satur ac plenus possis discedere rerum.","st":"3.960"},{"sp":"N","t":"nunc aliena tua tamen aetate omnia mitte"},{"sp":"N","t":"aequo animoque, age dum, magnis concede necessis?'"},{"sp":"N","t":"iure, ut opinor, agat, iure increpet inciletque;"},{"sp":"N","t":"cedit enim rerum novitate extrusa vetustas"},{"sp":"N","t":"semper, et ex aliis aliud reparare necessest.","st":"3.965"},{"sp":"N","t":"Nec quisquam in barathrum nec Tartara deditur atra;"},{"sp":"N","t":"materies opus est, ut crescant postera saecla;"},{"sp":"N","t":"quae tamen omnia te vita perfuncta sequentur;"},{"sp":"N","t":"nec minus ergo ante haec quam tu cecidere cadentque."},{"sp":"N","t":"sic alid ex alio numquam desistet oriri","st":"3.970"},{"sp":"N","t":"vitaque mancipio nulli datur, omnibus usu."},{"sp":"N","t":"respice item quam nil ad nos ante acta vetustas"},{"sp":"N","t":"temporis aeterni fuerit, quam nascimur ante."},{"sp":"N","t":"hoc igitur speculum nobis natura futuri"},{"sp":"N","t":"temporis exponit post mortem denique nostram.","st":"3.975"},{"sp":"N","t":"numquid ibi horribile apparet, num triste videtur"},{"sp":"N","t":"quicquam, non omni somno securius exstat?"},{"sp":"N","t":"Atque ea ni mirum quae cumque Acherunte profundo"},{"sp":"N","t":"prodita sunt esse, in vita sunt omnia nobis."},{"sp":"N","t":"nec miser inpendens magnum timet aere saxum","st":"3.980"},{"sp":"N","t":"Tantalus, ut famast, cassa formidine torpens;"},{"sp":"N","t":"sed magis in vita divom metus urget inanis"},{"sp":"N","t":"mortalis casumque timent quem cuique ferat fors."},{"sp":"N","t":"nec Tityon volucres ineunt Acherunte iacentem"},{"sp":"N","t":"nec quod sub magno scrutentur pectore quicquam","st":"3.985"},{"sp":"N","t":"perpetuam aetatem possunt reperire profecto."},{"sp":"N","t":"quam libet immani proiectu corporis exstet,"},{"sp":"N","t":"qui non sola novem dispessis iugera membris"},{"sp":"N","t":"optineat, sed qui terrai totius orbem,"},{"sp":"N","t":"non tamen aeternum poterit perferre dolorem","st":"3.990"},{"sp":"N","t":"nec praebere cibum proprio de corpore semper."},{"sp":"N","t":"sed Tityos nobis hic est, in amore iacentem"},{"sp":"N","t":"quem volucres lacerant atque exest anxius angor"},{"sp":"N","t":"aut alia quavis scindunt cuppedine curae."},{"sp":"N","t":"Sisyphus in vita quoque nobis ante oculos est,","st":"3.995"},{"sp":"N","t":"qui petere a populo fasces saevasque secures"},{"sp":"N","t":"imbibit et semper victus tristisque recedit."},{"sp":"N","t":"nam petere imperium, quod inanest nec datur umquam,"},{"sp":"N","t":"atque in eo semper durum sufferre laborem,"},{"sp":"N","t":"hoc est adverso nixantem trudere monte","st":"3.1000"},{"sp":"N","t":"saxum, quod tamen e summo iam vertice rusum"},{"sp":"N","t":"volvitur et plani raptim petit aequora campi."},{"sp":"N","t":"deinde animi ingratam naturam pascere semper"},{"sp":"N","t":"atque explere bonis rebus satiareque numquam,"},{"sp":"N","t":"quod faciunt nobis annorum tempora, circum","st":"3.1005"},{"sp":"N","t":"cum redeunt fetusque ferunt variosque lepores,"},{"sp":"N","t":"nec tamen explemur vitai fructibus umquam,"},{"sp":"N","t":"hoc, ut opinor, id est, aevo florente puellas"},{"sp":"N","t":"quod memorant laticem pertusum congerere in vas,"},{"sp":"N","t":"quod tamen expleri nulla ratione potestur.","st":"3.1010"},{"sp":"N","t":"Cerberus et Furiae iam vero et lucis egestas,"},{"sp":"N","t":"Tartarus horriferos eructans faucibus aestus!"},{"sp":"N","t":"qui neque sunt usquam nec possunt esse profecto;"},{"sp":"N","t":"sed metus in vita poenarum pro male factis"},{"sp":"N","t":"est insignibus insignis scelerisque luela,","st":"3.1015"},{"sp":"N","t":"carcer et horribilis de saxo iactus deorsum,"},{"sp":"N","t":"verbera carnifices robur pix lammina taedae;"},{"sp":"N","t":"quae tamen etsi absunt, at mens sibi conscia factis"},{"sp":"N","t":"praemetuens adhibet stimulos torretque flagellis,"},{"sp":"N","t":"nec videt interea qui terminus esse malorum","st":"3.1020"},{"sp":"N","t":"possit nec quae sit poenarum denique finis,"},{"sp":"N","t":"atque eadem metuit magis haec ne in morte gravescant."},{"sp":"N","t":"hic Acherusia fit stultorum denique vita."},{"sp":"N","t":"Hoc etiam tibi tute interdum dicere possis."},{"sp":"N","t":"'lumina sis oculis etiam bonus Ancus reliquit,","st":"3.1025"},{"sp":"N","t":"qui melior multis quam tu fuit, improbe, rebus."},{"sp":"N","t":"inde alii multi reges rerumque potentes"},{"sp":"N","t":"occiderunt, magnis qui gentibus imperitarunt."},{"sp":"N","t":"ille quoque ipse, viam qui quondam per mare magnum"},{"sp":"N","t":"stravit iterque dedit legionibus ire per altum","st":"3.1030"},{"sp":"N","t":"ac pedibus salsas docuit super ire lucunas"},{"sp":"N","t":"et contempsit equis insultans murmura ponti,"},{"sp":"N","t":"lumine adempto animam moribundo corpore fudit."},{"sp":"N","t":"Scipiadas, belli fulmen, Carthaginis horror,"},{"sp":"N","t":"ossa dedit terrae proinde ac famul infimus esset.","st":"3.1035"},{"sp":"N","t":"adde repertores doctrinarum atque leporum,"},{"sp":"N","t":"adde Heliconiadum comites; quorum unus Homerus"},{"sp":"N","t":"sceptra potitus eadem aliis sopitus quietest."},{"sp":"N","t":"denique Democritum post quam matura vetustas"},{"sp":"N","t":"admonuit memores motus languescere mentis,","st":"3.1040"},{"sp":"N","t":"sponte sua leto caput obvius optulit ipse."},{"sp":"N","t":"ipse Epicurus obit decurso lumine vitae,"},{"sp":"N","t":"qui genus humanum ingenio superavit et omnis"},{"sp":"N","t":"restinxit stellas exortus ut aetherius sol."},{"sp":"N","t":"tu vero dubitabis et indignabere obire?","st":"3.1045"},{"sp":"N","t":"mortua cui vita est prope iam vivo atque videnti,"},{"sp":"N","t":"qui somno partem maiorem conteris aevi,"},{"sp":"N","t":"et viligans stertis nec somnia cernere cessas"},{"sp":"N","t":"sollicitamque geris cassa formidine mentem"},{"sp":"N","t":"nec reperire potes tibi quid sit saepe mali, cum","st":"3.1050"},{"sp":"N","t":"ebrius urgeris multis miser undique curis"},{"sp":"N","t":"atque animo incerto fluitans errore vagaris.'"},{"sp":"N","t":"Si possent homines, proinde ac sentire videntur"},{"sp":"N","t":"pondus inesse animo, quod se gravitate fatiget,"},{"sp":"N","t":"e quibus id fiat causis quoque noscere et unde","st":"3.1055"},{"sp":"N","t":"tanta mali tam quam moles in pectore constet,"},{"sp":"N","t":"haut ita vitam agerent, ut nunc plerumque videmus"},{"sp":"N","t":"quid sibi quisque velit nescire et quaerere semper,"},{"sp":"N","t":"commutare locum, quasi onus deponere possit."},{"sp":"N","t":"exit saepe foras magnis ex aedibus ille,","st":"3.1060"},{"sp":"N","t":"esse domi quem pertaesumst, subitoque revertit,"},{"sp":"N","t":"quippe foris nihilo melius qui sentiat esse."},{"sp":"N","t":"currit agens mannos ad villam praecipitanter"},{"sp":"N","t":"auxilium tectis quasi ferre ardentibus instans;"},{"sp":"N","t":"oscitat extemplo, tetigit cum limina villae,","st":"3.1065"},{"sp":"N","t":"aut abit in somnum gravis atque oblivia quaerit,"},{"sp":"N","t":"aut etiam properans urbem petit atque revisit."},{"sp":"N","t":"hoc se quisque modo fugit, at quem scilicet, ut fit,"},{"sp":"N","t":"effugere haut potis est: ingratius haeret et odit"},{"sp":"N","t":"propterea, morbi quia causam non tenet aeger;","st":"3.1070"},{"sp":"N","t":"quam bene si videat, iam rebus quisque relictis"},{"sp":"N","t":"naturam primum studeat cognoscere rerum,"},{"sp":"N","t":"temporis aeterni quoniam, non unius horae,"},{"sp":"N","t":"ambigitur status, in quo sit mortalibus omnis"},{"sp":"N","t":"aetas, post mortem quae restat cumque manendo.","st":"3.1075"},{"sp":"N","t":"Denique tanto opere in dubiis trepidare periclis"},{"sp":"N","t":"quae mala nos subigit vitai tanta cupido?"},{"sp":"N","t":"certe equidem finis vitae mortalibus adstat"},{"sp":"N","t":"nec devitari letum pote, quin obeamus."},{"sp":"N","t":"praeterea versamur ibidem atque insumus usque","st":"3.1080"},{"sp":"N","t":"nec nova vivendo procuditur ulla voluptas;"},{"sp":"N","t":"sed dum abest quod avemus, id exsuperare videtur"},{"sp":"N","t":"cetera; post aliud, cum contigit illud, avemus"},{"sp":"N","t":"et sitis aequa tenet vitai semper hiantis."},{"sp":"N","t":"posteraque in dubiost fortunam quam vehat aetas,","st":"3.1085"},{"sp":"N","t":"quidve ferat nobis casus quive exitus instet."},{"sp":"N","t":"nec prorsum vitam ducendo demimus hilum"},{"sp":"N","t":"tempore de mortis nec delibare valemus,"},{"sp":"N","t":"quo minus esse diu possimus forte perempti."},{"sp":"N","t":"proinde licet quod vis vivendo condere saecla,","st":"3.1090"},{"sp":"N","t":"mors aeterna tamen nihilo minus illa manebit,"},{"sp":"N","t":"nec minus ille diu iam non erit, ex hodierno"},{"sp":"N","t":"lumine qui finem vitai fecit, et ille,"},{"sp":"N","t":"mensibus atque annis qui multis occidit ante."},{"sp":"HDR","t":"Liber IV"},{"sp":"N","t":"Avia Pieridum peragro loca nullius ante","st":"4.1"},{"sp":"N","t":"trita solo. iuvat integros accedere fontis"},{"sp":"N","t":"atque haurire, iuvatque novos decerpere flores"},{"sp":"N","t":"insignemque meo capiti petere inde coronam,"},{"sp":"N","t":"unde prius nulli velarint tempora musae;","st":"4.5"},{"sp":"N","t":"primum quod magnis doceo de rebus et artis"},{"sp":"N","t":"religionum animum nodis exsolvere pergo,"},{"sp":"N","t":"deinde quod obscura de re tam lucida pango"},{"sp":"N","t":"carmina musaeo contingens cuncta lepore."},{"sp":"N","t":"id quoque enim non ab nulla ratione videtur;","st":"4.10"},{"sp":"N","t":"nam vel uti pueris absinthia taetra medentes"},{"sp":"N","t":"cum dare conantur, prius oras pocula circum"},{"sp":"N","t":"contingunt mellis dulci flavoque liquore,"},{"sp":"N","t":"ut puerorum aetas inprovida ludificetur"},{"sp":"N","t":"labrorum tenus, interea perpotet amarum","st":"4.15"},{"sp":"N","t":"absinthi laticem deceptaque non capiatur,"},{"sp":"N","t":"sed potius tali facto recreata valescat,"},{"sp":"N","t":"sic ego nunc, quoniam haec ratio plerumque videtur"},{"sp":"N","t":"tristior esse quibus non est tractata, retroque"},{"sp":"N","t":"volgus abhorret ab hac, volui tibi suaviloquenti","st":"4.20"},{"sp":"N","t":"carmine Pierio rationem exponere nostram"},{"sp":"N","t":"et quasi musaeo dulci contingere melle;"},{"sp":"N","t":"si tibi forte animum tali ratione tenere"},{"sp":"N","t":"versibus in nostris possem, dum percipis omnem"},{"sp":"N","t":"naturam rerum ac persentis utilitatem.","st":"4.25"},{"sp":"N","t":"Sed quoniam docui cunctarum exordia rerum"},{"sp":"N","t":"qualia sint et quam variis distantia formis"},{"sp":"N","t":"sponte sua volitent aeterno percita motu"},{"sp":"N","t":"quoque modo possit res ex his quaeque creari,"},{"sp":"N","t":"nunc agere incipiam tibi quod vehementer ad has res","st":"4.30"},{"sp":"N","t":"attinet esse ea quae rerum simulacra vocamus,"},{"sp":"N","t":"quae quasi membranae vel cortex nominitandast,"},{"sp":"N","t":"atque animi quoniam docui natura quid esset"},{"sp":"N","t":"et quibus e rebus cum corpore compta vigeret"},{"sp":"N","t":"quove modo distracta rediret in ordia prima,","st":"4.35"},{"sp":"N","t":"nunc agere incipiam tibi, quod vehementer ad has res"},{"sp":"N","t":"attinet esse ea quae rerum simulacra vocamus,"},{"sp":"N","t":"quod speciem ac formam similem gerit eius imago,"},{"sp":"N","t":"cuius cumque cluet de corpore fusa vagari;"},{"sp":"N","t":"quae quasi membranae summo de corpore rerum","st":"4.40"},{"sp":"N","t":"dereptae volitant ultroque citroque per auras,"},{"sp":"N","t":"atque eadem nobis vigilantibus obvia mentes"},{"sp":"N","t":"terrificant atque in somnis, cum saepe figuras"},{"sp":"N","t":"contuimur miras simulacraque luce carentum,"},{"sp":"N","t":"quae nos horrifice languentis saepe sopore","st":"4.45"},{"sp":"N","t":"excierunt ne forte animas Acherunte reamur"},{"sp":"N","t":"effugere aut umbras inter vivos volitare"},{"sp":"N","t":"neve aliquid nostri post mortem posse relinqui,"},{"sp":"N","t":"cum corpus simul atque animi natura perempta"},{"sp":"N","t":"in sua discessum dederint primordia quaeque.","st":"4.50"},{"sp":"N","t":"dico igitur rerum effigias tenuisque figuras"},{"sp":"N","t":"mittier ab rebus summo de cortice eorum;"},{"sp":"N","t":"id licet hinc quamvis hebeti cognoscere corde."},{"sp":"N","t":"Principio quoniam mittunt in rebus apertis"},{"sp":"N","t":"corpora res multae, partim diffusa solute,","st":"4.55"},{"sp":"N","t":"robora ceu fumum mittunt ignesque vaporem,"},{"sp":"N","t":"et partim contexta magis condensaque, ut olim"},{"sp":"N","t":"cum teretis ponunt tunicas aestate cicadae,"},{"sp":"N","t":"et vituli cum membranas de corpore summo"},{"sp":"N","t":"nascentes mittunt, et item cum lubrica serpens","st":"4.60"},{"sp":"N","t":"exuit in spinis vestem; nam saepe videmus"},{"sp":"N","t":"illorum spoliis vepres volitantibus auctas."},{"sp":"N","t":"quae quoniam fiunt, tenuis quoque debet imago"},{"sp":"N","t":"ab rebus mitti summo de corpore rerum."},{"sp":"N","t":"nam cur illa cadant magis ab rebusque recedant","st":"4.65"},{"sp":"N","t":"quam quae tenvia sunt, hiscendist nulla potestas;"},{"sp":"N","t":"praesertim cum sint in summis corpora rebus"},{"sp":"N","t":"multa minuta, iaci quae possint ordine eodem"},{"sp":"N","t":"quo fuerint et formai servare figuram,"},{"sp":"N","t":"et multo citius, quanto minus indupediri","st":"4.70"},{"sp":"N","t":"pauca queunt et quae sunt prima fronte locata."},{"sp":"N","t":"nam certe iacere ac largiri multa videmus,"},{"sp":"N","t":"non solum ex alto penitusque, ut diximus ante,"},{"sp":"N","t":"verum de summis ipsum quoque saepe colorem."},{"sp":"N","t":"et volgo faciunt id lutea russaque vela","st":"4.75"},{"sp":"N","t":"et ferrugina, cum magnis intenta theatris"},{"sp":"N","t":"per malos volgata trabesque trementia flutant;"},{"sp":"N","t":"namque ibi consessum caveai supter et omnem"},{"sp":"N","t":"scaenai speciem patrum matrumque deorsum"},{"sp":"N","t":"inficiunt coguntque suo fluitare colore.","st":"4.80"},{"sp":"N","t":"et quanto circum mage sunt inclusa theatri"},{"sp":"N","t":"moenia, tam magis haec intus perfusa lepore"},{"sp":"N","t":"omnia conrident correpta luce diei."},{"sp":"N","t":"ergo lintea de summo cum corpore fucum"},{"sp":"N","t":"mittunt, effigias quoque debent mittere tenvis","st":"4.85"},{"sp":"N","t":"res quaeque, ex summo quoniam iaculantur utraque."},{"sp":"N","t":"sunt igitur iam formarum vestigia certa,"},{"sp":"N","t":"quae volgo volitant subtili praedita filo"},{"sp":"N","t":"nec singillatim possunt secreta videri."},{"sp":"N","t":"Praeterea omnis odor fumus vapor atque aliae res","st":"4.90"},{"sp":"N","t":"consimiles ideo diffusae rebus abundant,"},{"sp":"N","t":"ex alto quia dum veniunt extrinsecus ortae"},{"sp":"N","t":"scinduntur per iter flexum, nec recta viarum"},{"sp":"N","t":"ostia sunt, qua contendant exire coortae."},{"sp":"N","t":"at contra tenuis summi membrana coloris","st":"4.95"},{"sp":"N","t":"cum iacitur, nihil est quod eam discerpere possit,"},{"sp":"N","t":"in promptu quoniam est in prima fronte locata."},{"sp":"N","t":"Postremo speculis in aqua splendoreque in omni"},{"sp":"N","t":"quae cumque apparent nobis simulacra, necessest,"},{"sp":"N","t":"quandoquidem simili specie sunt praedita rerum,","st":"4.100"},{"sp":"N","t":"exin imaginibus missis consistere eorum."},{"sp":"N","t":"nam cur illa cadant magis ab rebusque recedant"},{"sp":"N","t":"quam quae tenuia sunt, hiscendist nulla potestas."},{"sp":"N","t":"sunt igitur tenues formarum illis similesque"},{"sp":"N","t":"effigiae, singillatim quas cernere nemo","st":"4.105"},{"sp":"N","t":"cum possit, tamen adsiduo crebroque repulsu"},{"sp":"N","t":"reiectae reddunt speculorum ex aequore visum,"},{"sp":"N","t":"nec ratione alia servari posse videntur,"},{"sp":"N","t":"tanto opere ut similes reddantur cuique figurae."},{"sp":"N","t":"Nunc age, quam tenui natura constet imago","st":"4.110"},{"sp":"N","t":"percipe. et in primis, quoniam primordia tantum"},{"sp":"N","t":"sunt infra nostros sensus tantoque minora"},{"sp":"N","t":"quam quae primum oculi coeptant non posse tueri,"},{"sp":"N","t":"nunc tamen id quoque uti confirmem, exordia rerum"},{"sp":"N","t":"cunctarum quam sint subtilia percipe paucis.","st":"4.115"},{"sp":"N","t":"primum animalia sunt iam partim tantula, corum"},{"sp":"N","t":"tertia pars nulla possit ratione videri."},{"sp":"N","t":"horum intestinum quodvis quale esse putandumst!"},{"sp":"N","t":"quid cordis globus aut oculi? quid membra? quid artus?"},{"sp":"N","t":"quantula sunt! quid praeterea primordia quaeque,","st":"4.120"},{"sp":"N","t":"unde anima atque animi constet natura necessumst,"},{"sp":"N","t":"nonne vides quam sint subtilia quamque minuta?"},{"sp":"N","t":"praeterea quaecumque suo de corpore odorem"},{"sp":"N","t":"expirant acrem, panaces absinthia taetra"},{"sp":"N","t":"habrotonique graves et tristia centaurea,","st":"4.125"},{"sp":"N","t":"quorum unum quidvis leviter si forte duobus"},{"sp":"N","t":"quin potius noscas rerum simulacra vagari"},{"sp":"N","t":"multa modis multis, nulla vi cassaque sensu?"},{"sp":"N","t":"Sed ne forte putes ea demum sola vagari,"},{"sp":"N","t":"quae cumque ab rebus rerum simulacra recedunt,","st":"4.130"},{"sp":"N","t":"sunt etiam quae sponte sua gignuntur et ipsa"},{"sp":"N","t":"constituuntur in hoc caelo, qui dicitur aer,"},{"sp":"N","t":"quae multis formata modis sublime feruntur,"},{"sp":"N","t":"ut nubes facile inter dum concrescere in alto"},{"sp":"N","t":"cernimus et mundi speciem violare serenam","st":"4.135"},{"sp":"N","t":"aera mulcentes motu; nam saepe Gigantum"},{"sp":"N","t":"ora volare videntur et umbram ducere late,"},{"sp":"N","t":"inter dum magni montes avolsaque saxa"},{"sp":"N","t":"montibus ante ire et solem succedere praeter,"},{"sp":"N","t":"inde alios trahere atque inducere belua nimbos.","st":"4.140"},{"sp":"N","t":"nec speciem mutare suam liquentia cessant"},{"sp":"N","t":"et cuiusque modi formarum vertere in oras."},{"sp":"N","t":"Nunc ea quam facili et celeri ratione genantur"},{"sp":"N","t":"perpetuoque fluant ab rebus lapsaque cedant"},{"sp":"N","t":"semper enim summum quicquid de rebus abundat,","st":"4.145"},{"sp":"N","t":"quod iaculentur. et hoc alias cum pervenit in res,"},{"sp":"N","t":"transit, ut in primis vestem; sed ubi aspera saxa"},{"sp":"N","t":"aut in materiam ligni pervenit, ibi iam"},{"sp":"N","t":"scinditur, ut nullum simulacrum reddere possit."},{"sp":"N","t":"at cum splendida quae constant opposta fuerunt","st":"4.150"},{"sp":"N","t":"densaque, ut in primis speculum est, nihil accidit horum;"},{"sp":"N","t":"nam neque, uti vestem, possunt transire, neque autem"},{"sp":"N","t":"scindi; quam meminit levor praestare salutem."},{"sp":"N","t":"qua propter fit ut hinc nobis simulacra redundent."},{"sp":"N","t":"et quamvis subito quovis in tempore quamque","st":"4.155"},{"sp":"N","t":"rem contra speculum ponas, apparet imago;"},{"sp":"N","t":"perpetuo fluere ut noscas e corpore summo"},{"sp":"N","t":"texturas rerum tenuis tenuisque figuras."},{"sp":"N","t":"ergo multa brevi spatio simulacra genuntur,"},{"sp":"N","t":"ut merito celer his rebus dicatur origo.","st":"4.160"},{"sp":"N","t":"et quasi multa brevi spatio summittere debet"},{"sp":"N","t":"lumina sol, ut perpetuo sint omnia plena,"},{"sp":"N","t":"sic ab rebus item simili ratione necessest"},{"sp":"N","t":"temporis in puncto rerum simulacra ferantur"},{"sp":"N","t":"multa modis multis in cunctas undique partis;","st":"4.165"},{"sp":"N","t":"quandoquidem speculum quo cumque obvertimus oris,"},{"sp":"N","t":"res ibi respondent simili forma atque colore."},{"sp":"N","t":"Praeterea modo cum fuerit liquidissima caeli"},{"sp":"N","t":"tempestas, perquam subito fit turbida foede,"},{"sp":"N","t":"undique uti tenebras omnis Acherunta rearis","st":"4.170"},{"sp":"N","t":"liquisse et magnas caeli complesse cavernas."},{"sp":"N","t":"usque adeo taetra nimborum nocte coorta"},{"sp":"N","t":"inpendent atrae Formidinis ora superne;"},{"sp":"N","t":"quorum quantula pars sit imago dicere nemost"},{"sp":"N","t":"qui possit neque eam rationem reddere dictis.","st":"4.175"},{"sp":"N","t":"Nunc age, quam celeri motu simulacra ferantur,"},{"sp":"N","t":"et quae mobilitas ollis tranantibus auras"},{"sp":"N","t":"reddita sit, longo spatio ut brevis hora teratur,"},{"sp":"N","t":"in quem quaeque locum diverso numine tendunt,"},{"sp":"N","t":"suavidicis potius quam multis versibus edam;","st":"4.180"},{"sp":"N","t":"parvus ut est cycni melior canor, ille gruum quam"},{"sp":"N","t":"clamor in aetheriis dispersus nubibus austri."},{"sp":"N","t":"Principio persaepe levis res atque minutis"},{"sp":"N","t":"corporibus factas celeris licet esse videre."},{"sp":"N","t":"in quo iam genere est solis lux et vapor eius,","st":"4.185"},{"sp":"N","t":"propterea quia sunt e primis facta minutis,"},{"sp":"N","t":"quae quasi cuduntur perque aeris intervallum"},{"sp":"N","t":"non dubitant transire sequenti concita plaga;"},{"sp":"N","t":"suppeditatur enim confestim lumine lumen"},{"sp":"N","t":"et quasi protelo stimulatur fulgere fulgur.","st":"4.190"},{"sp":"N","t":"qua propter simulacra pari ratione necessest"},{"sp":"N","t":"inmemorabile per spatium transcurrere posse"},{"sp":"N","t":"temporis in puncto, primum quod parvola causa"},{"sp":"N","t":"est procul a tergo quae provehat atque propellat,"},{"sp":"N","t":"quod super est, ubi tam volucri levitate ferantur,","st":"4.195"},{"sp":"N","t":"deinde quod usque adeo textura praedita rara"},{"sp":"N","t":"mittuntur, facile ut quasvis penetrare queant res"},{"sp":"N","t":"et quasi permanare per aeris intervallum."},{"sp":"N","t":"Praeterea si quae penitus corpuscula rerum"},{"sp":"N","t":"ex altoque foras mittuntur, solis uti lux","st":"4.200"},{"sp":"N","t":"ac vapor, haec puncto cernuntur lapsa diei"},{"sp":"N","t":"per totum caeli spatium diffundere sese"},{"sp":"N","t":"perque volare mare ac terras caelumque rigare."},{"sp":"N","t":"quid quae sunt igitur iam prima fronte parata,"},{"sp":"N","t":"cum iaciuntur et emissum res nulla moratur?","st":"4.205"},{"sp":"N","t":"quone vides citius debere et longius ire"},{"sp":"N","t":"multiplexque loci spatium transcurrere eodem"},{"sp":"N","t":"tempore quo solis pervolgant lumina caelum?"},{"sp":"N","t":"Hoc etiam in primis specimen verum esse videtur,"},{"sp":"N","t":"quam celeri motu rerum simulacra ferantur,","st":"4.210"},{"sp":"N","t":"quod simul ac primum sub diu splendor aquai"},{"sp":"N","t":"ponitur, extemplo caelo stellante serena"},{"sp":"N","t":"sidera respondent in aqua radiantia mundi."},{"sp":"N","t":"iamne vides igitur quam puncto tempore imago"},{"sp":"N","t":"aetheris ex oris in terrarum accidat oras?","st":"4.215"},{"sp":"N","t":"quare etiam atque etiam mitti fateare necessest"},{"sp":"N","t":"corpora quae feriant oculos visumque lacessant."},{"sp":"N","t":"perpetuoque fluunt certis ab rebus odores,"},{"sp":"N","t":"frigus ut a fluviis, calor ab sole, aestus ab undis"},{"sp":"N","t":"aequoris, exesor moerorum litora circum,","st":"4.220"},{"sp":"N","t":"nec variae cessant voces volitare per auras."},{"sp":"N","t":"denique in os salsi venit umor saepe saporis,"},{"sp":"N","t":"cum mare versamur propter, dilutaque contra"},{"sp":"N","t":"cum tuimur misceri absinthia, tangit amaror."},{"sp":"N","t":"usque adeo omnibus ab rebus res quaeque fluenter","st":"4.225"},{"sp":"N","t":"fertur et in cunctas dimittitur undique partis"},{"sp":"N","t":"nec mora nec requies interdatur ulla fluendi,"},{"sp":"N","t":"perpetuo quoniam sentimus et omnia semper"},{"sp":"N","t":"cernere odorari licet et sentire sonare."},{"sp":"N","t":"Praeterea quoniam manibus tractata figura","st":"4.230"},{"sp":"N","t":"in tenebris quaedam cognoscitur esse eadem quae"},{"sp":"N","t":"cernitur in luce et claro candore, necessest"},{"sp":"N","t":"consimili causa tactum visumque moveri."},{"sp":"N","t":"nunc igitur si quadratum temptamus et id nos"},{"sp":"N","t":"commovet in tenebris, in luci quae poterit res","st":"4.235"},{"sp":"N","t":"accidere ad speciem quadrata, nisi eius imago?"},{"sp":"N","t":"esse in imaginibus qua propter causa videtur"},{"sp":"N","t":"cernundi neque posse sine his res ulla videri."},{"sp":"N","t":"Nunc ea quae dico rerum simulacra feruntur"},{"sp":"N","t":"undique et in cunctas iaciuntur didita partis;","st":"4.240"},{"sp":"N","t":"verum nos oculis quia solis cernere quimus,"},{"sp":"N","t":"propterea fit uti, speciem quo vertimus, omnes"},{"sp":"N","t":"res ibi eam contra feriant forma atque colore."},{"sp":"N","t":"et quantum quaeque ab nobis res absit, imago"},{"sp":"N","t":"efficit ut videamus et internoscere curat;","st":"4.245"},{"sp":"N","t":"nam cum mittitur, extemplo protrudit agitque"},{"sp":"N","t":"aera qui inter se cumque est oculosque locatus,"},{"sp":"N","t":"isque ita per nostras acies perlabitur omnis"},{"sp":"N","t":"et quasi perterget pupillas atque ita transit."},{"sp":"N","t":"propterea fit uti videamus quam procul absit","st":"4.250"},{"sp":"N","t":"res quaeque. et quanto plus aeris ante agitatur"},{"sp":"N","t":"et nostros oculos perterget longior aura,"},{"sp":"N","t":"tam procul esse magis res quaeque remota videtur."},{"sp":"N","t":"scilicet haec summe celeri ratione geruntur,"},{"sp":"N","t":"quale sit ut videamus, et una quam procul absit.","st":"4.255"},{"sp":"N","t":"Illud in his rebus minime mirabile habendumst,"},{"sp":"N","t":"cur, ea quae feriant oculos simulacra videri"},{"sp":"N","t":"singula cum nequeant, res ipsae perspiciantur."},{"sp":"N","t":"ventus enim quoque paulatim cum verberat et cum"},{"sp":"N","t":"acre fluit frigus, non privam quamque solemus","st":"4.260"},{"sp":"N","t":"particulam venti sentire et frigoris eius,"},{"sp":"N","t":"sed magis unorsum, fierique perinde videmus"},{"sp":"N","t":"corpore tum plagas in nostro tam quam aliquae res"},{"sp":"N","t":"verberet atque sui det sensum corporis extra."},{"sp":"N","t":"praeterea lapidem digito cum tundimus, ipsum","st":"4.265"},{"sp":"N","t":"tangimus extremum saxi summumque colorem"},{"sp":"N","t":"nec sentimus eum tactu, verum magis ipsam"},{"sp":"N","t":"duritiem penitus saxi sentimus in alto."},{"sp":"N","t":"Nunc age, cur ultra speculum videatur imago"},{"sp":"N","t":"percipe: nam certe penitus remmota videtur.","st":"4.270"},{"sp":"N","t":"quod genus illa foris quae vere transpiciuntur,"},{"sp":"N","t":"ianua cum per se transpectum praebet apertum,"},{"sp":"N","t":"multa facitque foris ex aedibus ut videantur;"},{"sp":"N","t":"is quoque enim duplici geminoque fit aere visus."},{"sp":"N","t":"primus enim citra postes tum cernitur aer,","st":"4.275"},{"sp":"N","t":"inde fores ipsae dextra laevaque secuntur,"},{"sp":"N","t":"post extraria lux oculos perterget et aer"},{"sp":"N","t":"alter, et illa foris quae vere transpiciuntur."},{"sp":"N","t":"sic ubi se primum speculi proiecit imago,"},{"sp":"N","t":"dum venit ad nostras acies, protrudit agitque","st":"4.280"},{"sp":"N","t":"aera qui inter se cumquest oculosque locatus,"},{"sp":"N","t":"et facit, ut prius hunc omnem sentire queamus"},{"sp":"N","t":"quam speculum; sed ubi in speculum quoque sensimus ipsum,"},{"sp":"N","t":"continuo a nobis in eum quae fertur imago"},{"sp":"N","t":"pervenit, et nostros oculos reiecta revisit","st":"4.285"},{"sp":"N","t":"atque alium prae se propellens aera volvit,"},{"sp":"N","t":"et facit ut prius hunc quam se videamus, eoque"},{"sp":"N","t":"distare ab speculo tantum semota videtur."},{"sp":"N","t":"quare etiam atque etiam minime mirarier est par"},{"sp":"N","t":"illis quae reddunt speculorum ex aequore visum,","st":"4.290"},{"sp":"N","t":"aeribus binis quoniam res confit utraque."},{"sp":"N","t":"Nunc ea quae nobis membrorum dextera pars est,"},{"sp":"N","t":"in speculis fit ut in laeva videatur eo quod"},{"sp":"N","t":"planitiem ad speculi veniens cum offendit imago,"},{"sp":"N","t":"non convertitur incolumis, sed recta retrorsum","st":"4.295"},{"sp":"N","t":"sic eliditur, ut siquis, prius arida quam sit"},{"sp":"N","t":"cretea persona, adlidat pilaeve trabive,"},{"sp":"N","t":"atque ea continuo rectam si fronte figuram"},{"sp":"N","t":"servet et elisam retro sese exprimat ipsa."},{"sp":"N","t":"fiet ut, ante oculus fuerit qui dexter, ut idem","st":"4.300"},{"sp":"N","t":"nunc sit laevus et e laevo sit mutua dexter."},{"sp":"N","t":"Fit quoque de speculo in speculum ut tradatur imago,"},{"sp":"N","t":"quinque etiam aut sex ut fieri simulacra suerint."},{"sp":"N","t":"nam quae cumque retro parte interiore latebunt,"},{"sp":"N","t":"inde tamen, quamvis torte penitusque remota,","st":"4.305"},{"sp":"N","t":"omnia per flexos aditus educta licebit"},{"sp":"N","t":"pluribus haec speculis videantur in aedibus esse."},{"sp":"N","t":"usque adeo speculo in speculum translucet imago,"},{"sp":"N","t":"et cum laeva data est, fit rusum ut dextera fiat,"},{"sp":"N","t":"inde retro rursum redit et convertit eodem.","st":"4.310"},{"sp":"N","t":"Quin etiam quae cumque latuscula sunt speculorum"},{"sp":"N","t":"adsimili lateris flexura praedita nostri,"},{"sp":"N","t":"dextera ea propter nobis simulacra remittunt,"},{"sp":"N","t":"aut quia de speculo in speculum transfertur imago,"},{"sp":"N","t":"inde ad nos elisa bis advolat, aut etiam quod","st":"4.315"},{"sp":"N","t":"circum agitur, cum venit, imago propterea quod"},{"sp":"N","t":"flexa figura docet speculi convertier ad nos."},{"sp":"N","t":"Indugredi porro pariter simulacra pedemque"},{"sp":"N","t":"ponere nobiscum credas gestumque imitari"},{"sp":"N","t":"propterea quia, de speculi qua parte recedas,","st":"4.320"},{"sp":"N","t":"continuo nequeunt illinc simulacra reverti;"},{"sp":"N","t":"omnia quandoquidem cogit natura referri"},{"sp":"N","t":"ac resilire ab rebus ad aequos reddita flexus."},{"sp":"N","t":"Splendida porro oculi fugitant vitantque tueri."},{"sp":"N","t":"sol etiam caecat, contra si tendere pergas,","st":"4.325"},{"sp":"N","t":"propterea quia vis magnast ipsius et alte"},{"sp":"N","t":"aera per purum simulacra feruntur"},{"sp":"N","t":"et feriunt oculos turbantia composituras."},{"sp":"N","t":"Praeterea splendor qui cumque est acer adurit"},{"sp":"N","t":"saepe oculos ideo quod semina possidet ignis","st":"4.330"},{"sp":"N","t":"multa, dolorem oculis quae gignunt insinuando."},{"sp":"N","t":"lurida praeterea fiunt quae cumque tuentur"},{"sp":"N","t":"arquati, quia luroris de corpore eorum"},{"sp":"N","t":"semina multa fluunt simulacris obvia rerum,"},{"sp":"N","t":"multaque sunt oculis in eorum denique mixta,","st":"4.335"},{"sp":"N","t":"quae contage sua palloribus omnia pingunt."},{"sp":"N","t":"E tenebris autem quae sunt in luce tuemur"},{"sp":"N","t":"propterea quia, cum propior caliginis aer"},{"sp":"N","t":"ater init oculos prior et possedit apertos,"},{"sp":"N","t":"insequitur candens confestim lucidus aer,","st":"4.340"},{"sp":"N","t":"qui quasi purgat eos ac nigras discutit umbras"},{"sp":"N","t":"aeris illius; nam multis partibus hic est"},{"sp":"N","t":"mobilior multisque minutior et mage pollens."},{"sp":"N","t":"qui simul atque vias oculorum luce replevit"},{"sp":"N","t":"atque pate fecit, quas ante obsederat aer","st":"4.345"},{"sp":"N","t":"ATER, continuo rerum simulacra secuntur,"},{"sp":"N","t":"quae sita sunt in luce, lacessuntque ut videamus."},{"sp":"N","t":"quod contra facere in tenebris e luce nequimus"},{"sp":"N","t":"propterea quia posterior caliginis aer"},{"sp":"N","t":"crassior insequitur, qui cuncta foramina complet","st":"4.350"},{"sp":"N","t":"obsiditque vias oculorum, ne simulacra"},{"sp":"N","t":"possint ullarum rerum coniecta moveri."},{"sp":"N","t":"Quadratasque procul turris cum cernimus urbis,"},{"sp":"N","t":"propterea fit uti videantur saepe rutundae,"},{"sp":"N","t":"angulus optusus quia longe cernitur omnis","st":"4.355"},{"sp":"N","t":"sive etiam potius non cernitur ac perit eius"},{"sp":"N","t":"plaga nec ad nostras acies perlabitur ictus,"},{"sp":"N","t":"aera per multum quia dum simulacra feruntur,"},{"sp":"N","t":"cogit hebescere eum crebris offensibus aer."},{"sp":"N","t":"hoc ubi suffugit sensum simul angulus omnis.","st":"4.360"},{"sp":"N","t":"fit quasi ut ad turnum saxorum structa tuantur;"},{"sp":"N","t":"non tamen ut coram quae sunt vereque rutunda,"},{"sp":"N","t":"sed quasi adumbratim paulum simulata videntur."},{"sp":"N","t":"Umbra videtur item nobis in sole moveri"},{"sp":"N","t":"et vestigia nostra sequi gestumque imitari,","st":"4.365"},{"sp":"N","t":"aera si credis privatum lumine posse"},{"sp":"N","t":"indugredi, motus hominum gestumque sequentem;"},{"sp":"N","t":"nam nihil esse potest aliud nisi lumine cassus"},{"sp":"N","t":"aer id quod nos umbram perhibere suemus."},{"sp":"N","t":"ni mirum, quia terra locis ex ordine certis","st":"4.370"},{"sp":"N","t":"lumine privatur solis qua cumque meantes"},{"sp":"N","t":"officimus, repletur item quod liquimus eius,"},{"sp":"N","t":"propterea fit uti videatur, quae fuit umbra"},{"sp":"N","t":"corporis, e regione eadem nos usque secuta."},{"sp":"N","t":"semper enim nova se radiorum lumina fundunt","st":"4.375"},{"sp":"N","t":"primaque dispereunt, quasi in ignem lana trahatur."},{"sp":"N","t":"propterea facile et spoliatur lumine terra"},{"sp":"N","t":"et repletur item nigrasque sibi abluit umbras."},{"sp":"N","t":"Nec tamen hic oculos falli concedimus hilum."},{"sp":"N","t":"nam quo cumque loco sit lux atque umbra tueri","st":"4.380"},{"sp":"N","t":"illorum est; eadem vero sint lumina necne,"},{"sp":"N","t":"umbraque quae fuit hic eadem nunc transeat illuc,"},{"sp":"N","t":"an potius fiat paulo quod diximus ante,"},{"sp":"N","t":"hoc animi demum ratio discernere debet,"},{"sp":"N","t":"nec possunt oculi naturam noscere rerum.","st":"4.385"},{"sp":"N","t":"proinde animi vitium hoc oculis adfingere noli."},{"sp":"N","t":"Qua vehimur navi, fertur, cum stare videtur;"},{"sp":"N","t":"quae manet in statione, ea praeter creditur ire."},{"sp":"N","t":"et fugere ad puppim colles campique videntur,"},{"sp":"N","t":"quos agimus praeter navem velisque volamus.","st":"4.390"},{"sp":"N","t":"Sidera cessare aetheriis adfixa cavernis"},{"sp":"N","t":"cuncta videntur, et adsiduo sunt omnia motu,"},{"sp":"N","t":"quandoquidem longos obitus exorta revisunt,"},{"sp":"N","t":"cum permensa suo sunt caelum corpore claro."},{"sp":"N","t":"solque pari ratione manere et luna videtur","st":"4.395"},{"sp":"N","t":"in statione, ea quae ferri res indicat ipsa."},{"sp":"N","t":"Exstantisque procul medio de gurgite montis"},{"sp":"N","t":"classibus inter quos liber patet exitus ingens,"},{"sp":"N","t":"insula coniunctis tamen ex his una videtur."},{"sp":"N","t":"atria versari et circum cursare columnae","st":"4.400"},{"sp":"N","t":"usque adeo fit uti pueris videantur, ubi ipsi"},{"sp":"N","t":"desierunt verti, vix ut iam credere possint"},{"sp":"N","t":"non supra sese ruere omnia tecta minari."},{"sp":"N","t":"Iamque rubrum tremulis iubar ignibus erigere alte"},{"sp":"N","t":"cum coeptat natura supraque extollere montes,","st":"4.405"},{"sp":"N","t":"quos tibi tum supra sol montis esse videtur"},{"sp":"N","t":"comminus ipse suo contingens fervidus igni,"},{"sp":"N","t":"vix absunt nobis missus bis mille sagittae,"},{"sp":"N","t":"vix etiam cursus quingentos saepe veruti;"},{"sp":"N","t":"inter eos solemque iacent immania ponti","st":"4.410"},{"sp":"N","t":"aequora substrata aetheriis ingentibus oris,"},{"sp":"N","t":"interiectaque sunt terrarum milia multa,"},{"sp":"N","t":"quae variae retinent gentes et saecla ferarum."},{"sp":"N","t":"At coniectus aquae digitum non altior unum,"},{"sp":"N","t":"qui lapides inter sistit per strata viarum,","st":"4.415"},{"sp":"N","t":"despectum praebet sub terras inpete tanto,"},{"sp":"N","t":"a terris quantum caeli patet altus hiatus,"},{"sp":"N","t":"nubila despicere et caelum ut videare videre,"},{"sp":"N","t":"corpora mirande sub terras abdita caelo."},{"sp":"N","t":"Denique ubi in medio nobis ecus acer obhaesit","st":"4.420"},{"sp":"N","t":"flumine et in rapidas amnis despeximus undas,"},{"sp":"N","t":"stantis equi corpus transversum ferre videtur"},{"sp":"N","t":"vis et in adversum flumen contrudere raptim,"},{"sp":"N","t":"et quo cumque oculos traiecimus omnia ferri"},{"sp":"N","t":"et fluere adsimili nobis ratione videntur.","st":"4.425"},{"sp":"N","t":"Porticus aequali quamvis est denique ductu"},{"sp":"N","t":"stansque in perpetuum paribus suffulta columnis,"},{"sp":"N","t":"longa tamen parte ab summa cum tota videtur,"},{"sp":"N","t":"paulatim trahit angusti fastigia coni,"},{"sp":"N","t":"tecta solo iungens atque omnia dextera laevis","st":"4.430"},{"sp":"N","t":"donec in obscurum coni conduxit acumen."},{"sp":"N","t":"In pelago nautis ex undis ortus in undis"},{"sp":"N","t":"sol fit uti videatur obire et condere lumen;"},{"sp":"N","t":"quippe ubi nil aliud nisi aquam caelumque tuentur;"},{"sp":"N","t":"ne leviter credas labefactari undique sensus.","st":"4.435"},{"sp":"N","t":"at maris ignaris in portu clauda videntur"},{"sp":"N","t":"navigia aplustris fractis obnitier undis."},{"sp":"N","t":"nam quae cumque supra rorem salis edita pars est"},{"sp":"N","t":"remorum, recta est, et recta superne guberna;"},{"sp":"N","t":"quae demersa liquore obeunt, refracta videntur","st":"4.440"},{"sp":"N","t":"omnia converti sursumque supina reverti"},{"sp":"N","t":"et reflexa prope in summo fluitare liquore."},{"sp":"N","t":"Raraque per caelum cum venti nubila portant"},{"sp":"N","t":"tempore nocturno, tum splendida signa videntur"},{"sp":"N","t":"labier adversum nimbos atque ire superne","st":"4.445"},{"sp":"N","t":"longe aliam in partem ac vera ratione feruntur"},{"sp":"N","t":"At si forte oculo manus uni subdita supter"},{"sp":"N","t":"pressit eum, quodam sensu fit uti videantur"},{"sp":"N","t":"omnia quae tuimur fieri tum bina tuendo,"},{"sp":"N","t":"bina lucernarum florentia lumina flammis","st":"4.450"},{"sp":"N","t":"binaque per totas aedis geminare supellex"},{"sp":"N","t":"et duplicis hominum facies et corpora bina."},{"sp":"N","t":"Denique cum suavi devinxit membra sopore"},{"sp":"N","t":"somnus et in summa corpus iacet omne quiete,"},{"sp":"N","t":"tum vigilare tamen nobis et membra movere","st":"4.455"},{"sp":"N","t":"nostra videmur, et in noctis caligine caeca"},{"sp":"N","t":"cernere censemus solem lumenque diurnum,"},{"sp":"N","t":"conclusoque loco caelum mare flumina montis"},{"sp":"N","t":"mutare et campos pedibus transire videmur,"},{"sp":"N","t":"et sonitus audire, severa silentia noctis","st":"4.460"},{"sp":"N","t":"undique cum constent, et reddere dicta tacentes."},{"sp":"N","t":"Cetera de genere hoc mirande multa videmus,"},{"sp":"N","t":"quae violare fidem quasi sensibus omnia quaerunt,"},{"sp":"N","t":"ne quiquam, quoniam pars horum maxima fallit"},{"sp":"N","t":"propter opinatus animi, quos addimus ipsi,","st":"4.465"},{"sp":"N","t":"pro visis ut sint quae non sunt sensibus visa;"},{"sp":"N","t":"nam nihil aegrius est quam res secernere apertas"},{"sp":"N","t":"ab dubiis, animus quas ab se protinus addit."},{"sp":"N","t":"Denique nil sciri siquis putat, id quoque nescit"},{"sp":"N","t":"an sciri possit, quoniam nil scire fatetur.","st":"4.470"},{"sp":"N","t":"hunc igitur contra minuam contendere causam,"},{"sp":"N","t":"qui capite ipse suo in statuit vestigia sese."},{"sp":"N","t":"et tamen hoc quoque uti concedam scire, at id ipsum"},{"sp":"N","t":"quaeram, cum in rebus veri nil viderit ante,"},{"sp":"N","t":"unde sciat quid sit scire et nescire vicissim,","st":"4.475"},{"sp":"N","t":"notitiam veri quae res falsique crearit"},{"sp":"N","t":"et dubium certo quae res differre probarit."},{"sp":"N","t":"invenies primis ab sensibus esse creatam"},{"sp":"N","t":"notitiem veri neque sensus posse refelli."},{"sp":"N","t":"nam maiore fide debet reperirier illud,","st":"4.480"},{"sp":"N","t":"sponte sua veris quod possit vincere falsa."},{"sp":"N","t":"quid maiore fide porro quam sensus haberi"},{"sp":"N","t":"debet? an ab sensu falso ratio orta valebit"},{"sp":"N","t":"dicere eos contra, quae tota ab sensibus orta est?"},{"sp":"N","t":"qui nisi sunt veri, ratio quoque falsa fit omnis.","st":"4.485"},{"sp":"N","t":"An poterunt oculos aures reprehendere, an aures"},{"sp":"N","t":"tactus? an hunc porro tactum sapor arguet oris,"},{"sp":"N","t":"an confutabunt nares oculive revincent?"},{"sp":"N","t":"non, ut opinor, ita est. nam seorsum cuique potestas"},{"sp":"N","t":"divisast, sua vis cuiquest, ideoque necesse est","st":"4.490"},{"sp":"N","t":"et quod molle sit et gelidum fervensve videre"},{"sp":"N","t":"et seorsum varios rerum sentire colores"},{"sp":"N","t":"et quae cumque coloribus sint coniuncta necessest."},{"sp":"N","t":"seorsus item sapor oris habet vim, seorsus odores"},{"sp":"N","t":"nascuntur, seorsum sonitus. ideoque necesse est","st":"4.495"},{"sp":"N","t":"non possint alios alii convincere sensus."},{"sp":"N","t":"nec porro poterunt ipsi reprehendere sese,"},{"sp":"N","t":"aequa fides quoniam debebit semper haberi."},{"sp":"N","t":"proinde quod in quoquest his visum tempore, verumst."},{"sp":"N","t":"Et si non poterit ratio dissolvere causam,","st":"4.500"},{"sp":"N","t":"cur ea quae fuerint iuxtim quadrata, procul sint"},{"sp":"N","t":"visa rutunda, tamen praestat rationis egentem"},{"sp":"N","t":"reddere mendose causas utriusque figurae,"},{"sp":"N","t":"quam manibus manifesta suis emittere quoquam"},{"sp":"N","t":"et violare fidem primam et convellere tota","st":"4.505"},{"sp":"N","t":"fundamenta quibus nixatur vita salusque."},{"sp":"N","t":"non modo enim ratio ruat omnis, vita quoque ipsa"},{"sp":"N","t":"concidat extemplo, nisi credere sensibus ausis"},{"sp":"N","t":"praecipitisque locos vitare et cetera quae sint"},{"sp":"N","t":"in genere hoc fugienda, sequi contraria quae sint.","st":"4.510"},{"sp":"N","t":"illa tibi est igitur verborum copia cassa"},{"sp":"N","t":"omnis, quae contra sensus instructa paratast."},{"sp":"N","t":"Denique ut in fabrica, si pravast regula prima,"},{"sp":"N","t":"normaque si fallax rectis regionibus exit,"},{"sp":"N","t":"et libella aliqua si ex parti claudicat hilum,","st":"4.515"},{"sp":"N","t":"omnia mendose fieri atque obstipa necessu est"},{"sp":"N","t":"prava cubantia prona supina atque absona tecta,"},{"sp":"N","t":"iam ruere ut quaedam videantur velle, ruantque"},{"sp":"N","t":"prodita iudiciis fallacibus omnia primis,"},{"sp":"N","t":"sic igitur ratio tibi rerum prava necessest","st":"4.520"},{"sp":"N","t":"falsaque sit, falsis quae cumque ab sensibus ortast."},{"sp":"N","t":"Nunc alii sensus quo pacto quisque suam rem"},{"sp":"N","t":"sentiat, haud quaquam ratio scruposa relicta est."},{"sp":"N","t":"Principio auditur sonus et vox omnis, in auris"},{"sp":"N","t":"insinuata suo pepulere ubi corpore sensum.","st":"4.525"},{"sp":"N","t":"corpoream quoque enim vocem constare fatendumst"},{"sp":"N","t":"et sonitum, quoniam possunt inpellere sensus."},{"sp":"N","t":"Praeterea radit vox fauces saepe facitque"},{"sp":"N","t":"asperiora foras gradiens arteria clamor,"},{"sp":"N","t":"quippe per angustum turba maiore coorta","st":"4.530"},{"sp":"N","t":"ire foras ubi coeperunt primordia vocum."},{"sp":"N","t":"scilicet expletis quoque ianua raditur oris."},{"sp":"N","t":"haud igitur dubiumst quin voces verbaque constent"},{"sp":"N","t":"corporeis e principiis, ut laedere possint."},{"sp":"N","t":"nec te fallit item quid corporis auferat et quid","st":"4.535"},{"sp":"N","t":"detrahat ex hominum nervis ac viribus ipsis"},{"sp":"N","t":"perpetuus sermo nigrai noctis ad umbram"},{"sp":"N","t":"aurorae perductus ab exoriente nitore,"},{"sp":"N","t":"praesertim si cum summost clamore profusus."},{"sp":"N","t":"ergo corpoream vocem constare necessest,","st":"4.540"},{"sp":"N","t":"multa loquens quoniam amittit de corpore partem."},{"sp":"N","t":"Asperitas autem vocis fit ab asperitate"},{"sp":"N","t":"principiorum et item levor levore creatur;"},{"sp":"N","t":"nec simili penetrant auris primordia forma,"},{"sp":"N","t":"cum tuba depresso graviter sub murmure mugit","st":"4.545"},{"sp":"N","t":"et reboat raucum retro cita barbita bombum,"},{"sp":"N","t":"et iam Dauliades natae hortis ex Heliconis"},{"sp":"N","t":"cum liquidam tollunt lugubri voce querellam."},{"sp":"N","t":"Hasce igitur penitus voces cum corpore nostro"},{"sp":"N","t":"exprimimus rectoque foras emittimus ore,","st":"4.550"},{"sp":"N","t":"mobilis articulat nervorum daedala lingua,"},{"sp":"N","t":"formaturaque labrorum pro parte figurat."},{"sp":"N","t":"hoc ubi non longum spatiumst unde illa profecta"},{"sp":"N","t":"perveniat vox quaeque, necessest verba quoque ipsa"},{"sp":"N","t":"plane exaudiri discernique articulatim;","st":"4.555"},{"sp":"N","t":"servat enim formaturam servatque figuram."},{"sp":"N","t":"at si inter positum spatium sit longius aequo,"},{"sp":"N","t":"aera per multum confundi verba necessest"},{"sp":"N","t":"et conturbari vocem, dum transvolat auras."},{"sp":"N","t":"ergo fit, sonitum ut possis sentire neque illam","st":"4.560"},{"sp":"N","t":"internoscere, verborum sententia quae sit;"},{"sp":"N","t":"usque adeo confusa venit vox inque pedita."},{"sp":"N","t":"Praeterea verbum saepe unum perciet auris"},{"sp":"N","t":"omnibus in populo missum praeconis ab ore."},{"sp":"N","t":"in multas igitur voces vox una repente","st":"4.565"},{"sp":"N","t":"diffugit, in privas quoniam se dividit auris"},{"sp":"N","t":"obsignans formam verbis clarumque sonorem."},{"sp":"N","t":"at quae pars vocum non auris incidit ipsas,"},{"sp":"N","t":"praeter lata perit frustra diffusa per auras."},{"sp":"N","t":"pars solidis adlisa locis reiecta sonorem","st":"4.570"},{"sp":"N","t":"reddit et inter dum frustratur imagine verbi."},{"sp":"N","t":"Quae bene cum videas, rationem reddere possis"},{"sp":"N","t":"tute tibi atque aliis, quo pacto per loca sola"},{"sp":"N","t":"saxa paris formas verborum ex ordine reddant."},{"sp":"N","t":"palantis comites com montis inter opacos","st":"4.575"},{"sp":"N","t":"quaerimus et magna dispersos voce ciemus."},{"sp":"N","t":"sex etiam aut septem loca vidi reddere vocis,"},{"sp":"N","t":"unam cum iaceres: ita colles collibus ipsi"},{"sp":"N","t":"verba repulsantes iterabant dicta referri."},{"sp":"N","t":"haec loca capripedes Satyros Nymphasque tenere","st":"4.580"},{"sp":"N","t":"finitimi fingunt et Faunos esse locuntur,"},{"sp":"N","t":"quorum noctivago strepitu ludoque iocanti"},{"sp":"N","t":"adfirmant volgo taciturna silentia rumpi"},{"sp":"N","t":"chordarumque sonos fieri dulcisque querellas,"},{"sp":"N","t":"tibia quas fundit digitis pulsata canentum,","st":"4.585"},{"sp":"N","t":"et genus agricolum late sentiscere, quom Pan"},{"sp":"N","t":"pinea semiferi capitis velamina quassans"},{"sp":"N","t":"unco saepe labro calamos percurrit hiantis,"},{"sp":"N","t":"fistula silvestrem ne cesset fundere musam."},{"sp":"N","t":"cetera de genere hoc monstra ac portenta loquontur,","st":"4.590"},{"sp":"N","t":"ne loca deserta ab divis quoque forte putentur"},{"sp":"N","t":"sola tenere. ideo iactant miracula dictis"},{"sp":"N","t":"aut aliqua ratione alia ducuntur, ut omne"},{"sp":"N","t":"humanum genus est avidum nimis auricularum."},{"sp":"N","t":"Quod super est, non est mirandum qua ratione,","st":"4.595"},{"sp":"N","t":"per loca quae nequeunt oculi res cernere apertas,"},{"sp":"N","t":"haec loca per voces veniant aurisque lacessant,"},{"sp":"N","t":"conloquium clausis foribus quoque saepe videmus;"},{"sp":"N","t":"ni mirum quia vox per flexa foramina rerum"},{"sp":"N","t":"incolumis transire potest, simulacra renutant;","st":"4.600"},{"sp":"N","t":"perscinduntur enim, nisi recta foramina tranant,"},{"sp":"N","t":"qualia sunt vitrei, species qua travolat omnis."},{"sp":"N","t":"praeterea partis in cunctas dividitur vox,"},{"sp":"N","t":"ex aliis aliae quoniam gignuntur, ubi una"},{"sp":"N","t":"dissuluit semel in multas exorta, quasi ignis","st":"4.605"},{"sp":"N","t":"saepe solet scintilla suos se spargere in ignis."},{"sp":"N","t":"ergo replentur loca vocibus abdita retro,"},{"sp":"N","t":"omnia quae circum fervunt sonituque cientur."},{"sp":"N","t":"at simulacra viis derectis omnia tendunt,"},{"sp":"N","t":"ut sunt missa semel; qua propter cernere nemo","st":"4.610"},{"sp":"N","t":"saepe supra potis est, at voces accipere extra."},{"sp":"N","t":"et tamen ipsa quoque haec, dum transit clausa domorum"},{"sp":"N","t":"vox optunditur atque auris confusa penetrat"},{"sp":"N","t":"et sonitum potius quam verba audire videmur."},{"sp":"N","t":"Hoc, qui sentimus sucum, lingua atque palatum","st":"4.615"},{"sp":"N","t":"plusculum habent in se rationis, plus operai."},{"sp":"N","t":"principio sucum sentimus in ore, cibum cum"},{"sp":"N","t":"mandendo exprimimus, ceu plenam spongiam aquai"},{"sp":"N","t":"siquis forte manu premere ac siccare coepit."},{"sp":"N","t":"inde quod exprimimus per caulas omne palati","st":"4.620"},{"sp":"N","t":"diditur et rarae per flexa foramina linguae,"},{"sp":"N","t":"hoc ubi levia sunt manantis corpora suci,"},{"sp":"N","t":"suaviter attingunt et suaviter omnia tractant"},{"sp":"N","t":"umida linguai circum sudantia templa;"},{"sp":"N","t":"at contra pungunt sensum lacerantque coorta,","st":"4.625"},{"sp":"N","t":"quanto quaeque magis sunt asperitate repleta."},{"sp":"N","t":"deinde voluptas est e suco fine palati;"},{"sp":"N","t":"cum vero deorsum per fauces praecipitavit,"},{"sp":"N","t":"nulla voluptas est, dum diditur omnis in artus;"},{"sp":"N","t":"nec refert quicquam quo victu corpus alatur,","st":"4.630"},{"sp":"N","t":"dum modo quod capias concoctum didere possis"},{"sp":"N","t":"artubus et stomachi tumidum servare tenorem."},{"sp":"N","t":"Nunc aliis alius qui sit cibus ut videamus,"},{"sp":"N","t":"expediam, quareve, aliis quod triste et amarumst,"},{"sp":"N","t":"hoc tamen esse aliis possit perdulce videri,","st":"4.635"},{"sp":"N","t":"tantaque in his rebus distantia differitasque est,"},{"sp":"N","t":"ut quod aliis cibus est aliis fuat acre venenum;"},{"sp":"N","t":"est itaque ut serpens, hominis quae tacta salivis"},{"sp":"N","t":"disperit ac sese mandendo conficit ipsa."},{"sp":"N","t":"praeterea nobis veratrum est acre venenum,","st":"4.640"},{"sp":"N","t":"at capris adipes et cocturnicibus auget."},{"sp":"N","t":"id quibus ut fiat rebus cognoscere possis,"},{"sp":"N","t":"principio meminisse decet quae diximus ante,"},{"sp":"N","t":"semina multimodis in rebus mixta teneri."},{"sp":"N","t":"porro omnes quae cumque cibum capiunt animantes,","st":"4.645"},{"sp":"N","t":"ut sunt dissimiles extrinsecus et generatim"},{"sp":"N","t":"extima membrorum circumcaesura coercet,"},{"sp":"N","t":"proinde et seminibus constant variantque figura."},{"sp":"N","t":"semina cum porro distent, differre necessest"},{"sp":"N","t":"intervalla viasque, foramina quae perhibemus,","st":"4.650"},{"sp":"N","t":"omnibus in membris et in ore ipsoque palato."},{"sp":"N","t":"esse minora igitur quaedam maioraque debent,"},{"sp":"N","t":"esse triquetra aliis, aliis quadrata necessest,"},{"sp":"N","t":"multa rutunda, modis multis multangula quaedam."},{"sp":"N","t":"namque figurarum ratio ut motusque reposcunt,","st":"4.655"},{"sp":"N","t":"proinde foraminibus debent differe figurae"},{"sp":"N","t":"et variare viae proinde ac textura coercet."},{"sp":"N","t":"hoc ubi quod suave est aliis aliis fit amarum,"},{"sp":"N","t":"illi, cui suave est, levissima corpora debent"},{"sp":"N","t":"contractabiliter caulas intrare palati,","st":"4.660"},{"sp":"N","t":"at contra quibus est eadem res intus acerba,"},{"sp":"N","t":"aspera ni mirum penetrant hamataque fauces."},{"sp":"N","t":"nunc facile est ex his rebus cognoscere quaeque."},{"sp":"N","t":"quippe ubi cui febris bili superante coorta est"},{"sp":"N","t":"aut alia ratione aliquast vis excita morbi,","st":"4.665"},{"sp":"N","t":"perturbatur ibi iam totum corpus et omnes"},{"sp":"N","t":"commutantur ibi positurae principiorum;"},{"sp":"N","t":"fit prius ad sensum ut quae corpora conveniebant"},{"sp":"N","t":"nunc non conveniant, et cetera sint magis apta,"},{"sp":"N","t":"quae penetrata queunt sensum progignere acerbum;","st":"4.670"},{"sp":"N","t":"utraque enim sunt in mellis commixta sapore;"},{"sp":"N","t":"id quod iam supera tibi saepe ostendimus ante."},{"sp":"N","t":"Nunc age, quo pacto naris adiectus odoris"},{"sp":"N","t":"tangat agam. primum res multas esse necessest"},{"sp":"N","t":"unde fluens volvat varius se fluctus odorum,","st":"4.675"},{"sp":"N","t":"et fluere et mitti volgo spargique putandumst;"},{"sp":"N","t":"verum aliis alius magis est animantibus aptus,"},{"sp":"N","t":"dissimilis propter formas. ideoque per auras"},{"sp":"N","t":"mellis apes quamvis longe ducuntur odore,"},{"sp":"N","t":"volturiique cadaveribus; tum fissa ferarum","st":"4.680"},{"sp":"N","t":"ungula quo tulerit gressum promissa canum vis"},{"sp":"N","t":"ducit, et humanum longe praesentit odorem"},{"sp":"N","t":"Romulidarum arcis servator, candidus anser."},{"sp":"N","t":"sic aliis alius nidor datus ad sua quemque"},{"sp":"N","t":"pabula ducit et a taetro resilire veneno","st":"4.685"},{"sp":"N","t":"cogit, eoque modo servantur saecla ferarum."},{"sp":"N","t":"Hic odor ipse igitur, naris qui cumque lacessit,"},{"sp":"N","t":"est alio ut possit permitti longius alter;"},{"sp":"N","t":"sed tamen haud quisquam tam longe fertur eorum"},{"sp":"N","t":"quam sonitus, quam vox, mitto iam dicere quam res","st":"4.690"},{"sp":"N","t":"quae feriunt oculorum acies visumque lacessunt."},{"sp":"N","t":"errabundus enim tarde venit ac perit ante"},{"sp":"N","t":"paulatim facilis distractus in aeris auras;"},{"sp":"N","t":"ex alto primum quia vix emittitur ex re;"},{"sp":"N","t":"nam penitus fluere atque recedere rebus odores","st":"4.695"},{"sp":"N","t":"significat quod fracta magis redolere videntur"},{"sp":"N","t":"omnia, quod contrita, quod igni conlabefacta."},{"sp":"N","t":"deinde videre licet maioribus esse creatum"},{"sp":"N","t":"principiis quam vox, quoniam per saxea saepta"},{"sp":"N","t":"non penetrat, qua vox volgo sonitusque feruntur.","st":"4.700"},{"sp":"N","t":"quare etiam quod olet non tam facile esse videbis"},{"sp":"N","t":"investigare in qua sit regione locatum;"},{"sp":"N","t":"refrigescit enim cunctando plaga per auras"},{"sp":"N","t":"nec calida ad sensum decurrunt nuntia rerum."},{"sp":"N","t":"errant saepe canes itaque et vestigia quaerunt.","st":"4.705"},{"sp":"N","t":"Nec tamen hoc solis in odoribus atque saporum"},{"sp":"N","t":"in generest, sed item species rerum atque colores"},{"sp":"N","t":"non ita conveniunt ad sensus omnibus omnes,"},{"sp":"N","t":"ut non sint aliis quaedam magis acria visu."},{"sp":"N","t":"quin etiam gallum noctem explaudentibus alis","st":"4.710"},{"sp":"N","t":"auroram clara consuetum voce vocare,"},{"sp":"N","t":"noenu queunt rapidi contra constare leones"},{"sp":"N","t":"inque tueri: ita continuo meminere fugai."},{"sp":"N","t":"ni mirum quia sunt gallorum in corpore quaedam"},{"sp":"N","t":"semina, quae cum sunt oculis inmissa leonum,","st":"4.715"},{"sp":"N","t":"pupillas interfodiunt acremque dolorem"},{"sp":"N","t":"praebent, ut nequeant contra durare feroces,"},{"sp":"N","t":"cum tamen haec nostras acies nil laedere possint,"},{"sp":"N","t":"aut quia non penetrant aut quod penetrantibus illis"},{"sp":"N","t":"exitus ex oculis liber datur, in remorando","st":"4.720"},{"sp":"N","t":"laedere ne possint ex ulla lumina parte."},{"sp":"N","t":"Nunc age, quae moveant animum res accipe, et unde"},{"sp":"N","t":"quae veniunt veniant in mentem percipe paucis."},{"sp":"N","t":"principio hoc dico, rerum simulacra vagari"},{"sp":"N","t":"multa modis multis in cunctas undique partis","st":"4.725"},{"sp":"N","t":"tenvia, quae facile inter se iunguntur in auris,"},{"sp":"N","t":"obvia cum veniunt, ut aranea bratteaque auri."},{"sp":"N","t":"quippe etenim multo magis haec sunt tenvia textu"},{"sp":"N","t":"quam quae percipiunt oculos visumque lacessunt,"},{"sp":"N","t":"corporis haec quoniam penetrant per rara cientque","st":"4.730"},{"sp":"N","t":"tenvem animi naturam intus sensumque lacessunt."},{"sp":"N","t":"Centauros itaque et Scyllarum membra videmus"},{"sp":"N","t":"Cerbereasque canum facies simulacraque eorum"},{"sp":"N","t":"quorum morte obita tellus amplectitur ossa;"},{"sp":"N","t":"omnigenus quoniam passim simulacra feruntur,","st":"4.735"},{"sp":"N","t":"partim sponte sua quae fiunt aere in ipso,"},{"sp":"N","t":"partim quae variis ab rebus cumque recedunt"},{"sp":"N","t":"et quae confiunt ex horum facta figuris."},{"sp":"N","t":"nam certe ex vivo Centauri non fit imago,"},{"sp":"N","t":"nulla fuit quoniam talis natura animata;","st":"4.740"},{"sp":"N","t":"verum ubi equi atque hominis casu convenit imago,"},{"sp":"N","t":"haerescit facile extemplo, quod diximus ante,"},{"sp":"N","t":"propter subtilem naturam et tenvia texta."},{"sp":"N","t":"cetera de genere hoc eadem ratione creantur."},{"sp":"N","t":"quae cum mobiliter summa levitate feruntur,","st":"4.745"},{"sp":"N","t":"ut prius ostendi, facile uno commovet ictu"},{"sp":"N","t":"quae libet una animum nobis subtilis imago;"},{"sp":"N","t":"tenvis enim mens est et mire mobilis ipsa."},{"sp":"N","t":"haec fieri ut memoro, facile hinc cognoscere possis."},{"sp":"N","t":"quatinus hoc simile est illi, quod mente videmus","st":"4.750"},{"sp":"N","t":"atque oculis, simili fieri ratione necessest."},{"sp":"N","t":"Nunc igitur docui quoniam me forte leonum"},{"sp":"N","t":"cernere per simulacra, oculos quae cumque lacessunt,"},{"sp":"N","t":"scire licet mentem simili ratione moveri"},{"sp":"N","t":"per simulacra leonum et cetera quae videt aeque","st":"4.755"},{"sp":"N","t":"nec minus atque oculi, nisi quod mage tenvia cernit."},{"sp":"N","t":"nec ratione alia, cum somnus membra profudit,"},{"sp":"N","t":"mens animi vigilat, nisi quod simulacra lacessunt"},{"sp":"N","t":"haec eadem nostros animos quae cum vigilamus,"},{"sp":"N","t":"usque adeo, certe ut videamur cernere eum quem","st":"4.760"},{"sp":"N","t":"rellicta vita iam mors et terra potitast."},{"sp":"N","t":"hoc ideo fieri cogit natura, quod omnes"},{"sp":"N","t":"corporis offecti sensus per membra quiescunt"},{"sp":"N","t":"nec possunt falsum veris convincere rebus."},{"sp":"N","t":"praeterea meminisse iacet languetque sopore,","st":"4.765"},{"sp":"N","t":"nec dissentit eum mortis letique potitum"},{"sp":"N","t":"iam pridem, quem mens vivom se cernere credit."},{"sp":"N","t":"quod super est, non est mirum simulacra moveri"},{"sp":"N","t":"bracchiaque in numerum iactare et cetera membra;"},{"sp":"N","t":"nam fit ut in somnis facere hoc videatur imago.","st":"4.770"},{"sp":"N","t":"quippe, ubi prima perit alioque est altera nata"},{"sp":"N","t":"inde statu, prior hic gestum mutasse videtur."},{"sp":"N","t":"scilicet id fieri celeri ratione putandumst:"},{"sp":"N","t":"tanta est mobilitas et rerum copia tanta"},{"sp":"N","t":"tantaque sensibili quovis est tempore in uno","st":"4.775"},{"sp":"N","t":"copia particularum, ut possit suppeditare."},{"sp":"N","t":"Multaque in his rebus quaeruntur multaque nobis"},{"sp":"N","t":"clarandumst, plane si res exponere avemus."},{"sp":"N","t":"quaeritur in primis quare, quod cuique libido"},{"sp":"N","t":"venerit, extemplo mens cogitet eius id ipsum.","st":"4.780"},{"sp":"N","t":"anne voluntatem nostram simulacra tuentur"},{"sp":"N","t":"et simul ac volumus nobis occurrit imago,"},{"sp":"N","t":"si mare, si terram cordist, si denique caelum?"},{"sp":"N","t":"conventus hominum, pompam, convivia, pugnas,"},{"sp":"N","t":"omnia sub verbone creat natura paratque?","st":"4.785"},{"sp":"N","t":"cum praesertim aliis eadem in regione locoque"},{"sp":"N","t":"longe dissimilis animus res cogitet omnis."},{"sp":"N","t":"quid porro, in numerum procedere cum simulacra"},{"sp":"N","t":"cernimus in somnis et mollia membra movere,"},{"sp":"N","t":"mollia mobiliter cum alternis bracchia mittunt","st":"4.790"},{"sp":"N","t":"et repetunt oculis gestum pede convenienti?"},{"sp":"N","t":"scilicet arte madent simulacra et docta vagantur,"},{"sp":"N","t":"nocturno facere ut possint in tempore ludos."},{"sp":"N","t":"an magis illud erit verum? quia tempore in uno,"},{"sp":"N","t":"cum sentimus, id est cum vox emittitur una,","st":"4.795"},{"sp":"N","t":"tempora multa latent, ratio quae comperit esse,"},{"sp":"N","t":"propterea fit uti quovis in tempore quaeque"},{"sp":"N","t":"praesto sint simulacra locis in quisque parata."},{"sp":"N","t":"tanta est mobilitas et rerum copia tanta."},{"sp":"N","t":"hoc ubi prima perit alioque est altera nata","st":"4.800"},{"sp":"N","t":"inde statu, prior hic gestum mutasse videtur."},{"sp":"N","t":"et quia tenvia sunt, nisi quae contendit, acute"},{"sp":"N","t":"cernere non potis est animus; proinde omnia quae sunt"},{"sp":"N","t":"praeterea pereunt, nisi quae ex sese ipse paravit."},{"sp":"N","t":"ipse parat sese porro speratque futurum","st":"4.805"},{"sp":"N","t":"ut videat quod consequitur rem quamque: fit ergo."},{"sp":"N","t":"nonne vides oculos etiam, cum tenvia quae sunt"},{"sp":"N","t":"praeterea pereunt, nisi quae ex se ipse paravit"},{"sp":"N","t":"cernere coeperunt, contendere se atque parare,"},{"sp":"N","t":"nec sine eo fieri posse ut cernamus acute?","st":"4.810"},{"sp":"N","t":"et tamen in rebus quoque apertis noscere possis,"},{"sp":"N","t":"si non advertas animum, proinde esse quasi omni"},{"sp":"N","t":"tempore semotum fuerit longeque remotum."},{"sp":"N","t":"cur igitur mirumst, animus si cetera perdit"},{"sp":"N","t":"praeter quam quibus est in rebus deditus ipse?","st":"4.815"},{"sp":"N","t":"deinde adopinamur de signis maxima parvis"},{"sp":"N","t":"ac nos in fraudem induimus frustraminis ipsi."},{"sp":"N","t":"Fit quoque ut inter dum non suppeditetur imago"},{"sp":"N","t":"eiusdem generis, sed femina quae fuit ante,"},{"sp":"N","t":"in manibus vir uti factus videatur adesse,","st":"4.820"},{"sp":"N","t":"aut alia ex alia facies aetasque sequatur."},{"sp":"N","t":"quod ne miremur sopor atque oblivia curant."},{"sp":"N","t":"Illud in his rebus vitium vehementer inesse"},{"sp":"N","t":"effugere errorem vitareque praemetuenter,"},{"sp":"N","t":"lumina ne facias oculorum clara creata,","st":"4.825"},{"sp":"N","t":"prospicere ut possimus, et ut proferre queamus"},{"sp":"N","t":"proceros passus, ideo fastigia posse"},{"sp":"N","t":"surarum ac feminum pedibus fundata plicari,"},{"sp":"N","t":"bracchia tum porro validis ex apta lacertis"},{"sp":"N","t":"esse manusque datas utraque ex parte ministras,","st":"4.830"},{"sp":"N","t":"ut facere ad vitam possemus quae foret usus."},{"sp":"N","t":"cetera de genere hoc inter quae cumque pretantur,"},{"sp":"N","t":"omnia perversa praepostera sunt ratione,"},{"sp":"N","t":"nil ideo quoniam natumst in corpore ut uti"},{"sp":"N","t":"possemus, sed quod natumst id procreat usum.","st":"4.835"},{"sp":"N","t":"nec fuit ante videre oculorum lumina nata,"},{"sp":"N","t":"nec dictis orare prius quam lingua creatast,"},{"sp":"N","t":"sed potius longe linguae praecessit origo"},{"sp":"N","t":"sermonem multoque creatae sunt prius aures"},{"sp":"N","t":"quam sonus est auditus, et omnia denique membra","st":"4.840"},{"sp":"N","t":"ante fuere, ut opinor, eorum quam foret usus;"},{"sp":"N","t":"haud igitur potuere utendi crescere causa."},{"sp":"N","t":"at contra conferre manu certamina pugnae"},{"sp":"N","t":"et lacerare artus foedareque membra cruore"},{"sp":"N","t":"ante fuit multo quam lucida tela volarent,","st":"4.845"},{"sp":"N","t":"et volnus vitare prius natura coegit"},{"sp":"N","t":"quam daret obiectum parmai laeva per artem."},{"sp":"N","t":"scilicet et fessum corpus mandare quieti"},{"sp":"N","t":"multo antiquius est quam lecti mollia strata,"},{"sp":"N","t":"et sedare sitim prius est quam pocula natum.","st":"4.850"},{"sp":"N","t":"haec igitur possunt utendi cognita causa"},{"sp":"N","t":"credier, ex usu quae sunt vitaque reperta."},{"sp":"N","t":"illa quidem seorsum sunt omnia, quae prius ipsa"},{"sp":"N","t":"nata dedere suae post notitiam utilitatis."},{"sp":"N","t":"quo genere in primis sensus et membra videmus;","st":"4.855"},{"sp":"N","t":"quare etiam atque etiam procul est ut credere possis"},{"sp":"N","t":"utilitatis ob officium potuisse creari."},{"sp":"N","t":"Illud item non est mirandum, corporis ipsa"},{"sp":"N","t":"quod natura cibum quaerit cuiusque animantis."},{"sp":"N","t":"quippe etenim fluere atque recedere corpora rebus","st":"4.860"},{"sp":"N","t":"multa modis multis docui, sed plurima debent"},{"sp":"N","t":"ex animalibus; quae quia sunt exercita motu,"},{"sp":"N","t":"multa per os exhalantur, cum languida anhelant,"},{"sp":"N","t":"multaque per sudorem ex alto pressa feruntur."},{"sp":"N","t":"his igitur rebus rarescit corpus et omnis","st":"4.865"},{"sp":"N","t":"subruitur natura, dolor quam consequitur rem."},{"sp":"N","t":"propterea capitur cibus, ut suffulciat artus"},{"sp":"N","t":"et recreet vires inter datus, atque patentem"},{"sp":"N","t":"per membra ac venas ut amorem opturet edendi."},{"sp":"N","t":"umor item discedit in omnia quae loca cumque","st":"4.870"},{"sp":"N","t":"poscunt umorem; glomerataque multa vaporis"},{"sp":"N","t":"corpora, quae stomacho praebent incendia nostro,"},{"sp":"N","t":"dissupat adveniens liquor ac restinguit ut ignem,"},{"sp":"N","t":"urere ne possit calor amplius aridus artus."},{"sp":"N","t":"sic igitur tibi anhela sitis de corpore nostro","st":"4.875"},{"sp":"N","t":"abluitur, sic expletur ieiuna cupido."},{"sp":"N","t":"Nunc qui fiat uti passus proferre queamus,"},{"sp":"N","t":"cum volumus, quareque datum sit membra movere"},{"sp":"N","t":"et quae res tantum hoc oneris protrudere nostri"},{"sp":"N","t":"corporis insuerit, dicam: tu percipe dicta.","st":"4.880"},{"sp":"N","t":"dico animo nostro primum simulacra meandi"},{"sp":"N","t":"accidere atque animum pulsare, ut diximus ante."},{"sp":"N","t":"inde voluntas fit; neque enim facere incipit ullam"},{"sp":"N","t":"rem quisquam, quam mens providit quid velit ante."},{"sp":"N","t":"id quod providet, illius rei constat imago,","st":"4.885"},{"sp":"N","t":"ergo animus cum sese ita commovet ut velit ire"},{"sp":"N","t":"inque gredi, ferit extemplo quae in corpore toto"},{"sp":"N","t":"per membra atque artus animai dissita vis est;"},{"sp":"N","t":"et facilest factu, quoniam coniuncta tenetur."},{"sp":"N","t":"inde ea proporro corpus ferit, atque ita tota","st":"4.890"},{"sp":"N","t":"paulatim moles protruditur atque movetur."},{"sp":"N","t":"praeterea tum rarescit quoque corpus et aer,"},{"sp":"N","t":"scilicet ut debet qui semper mobilis extat,"},{"sp":"N","t":"per patefacta venit penetratque foramina largus,"},{"sp":"N","t":"et dispargitur ad partis ita quasque minutas","st":"4.895"},{"sp":"N","t":"corporis. hic igitur rebus fit utrimque duabus,"},{"sp":"N","t":"corpus ut ac navis velis ventoque feratur."},{"sp":"N","t":"nec tamen illud in his rebus mirabile constat,"},{"sp":"N","t":"tantula quod tantum corpus corpuscula possunt"},{"sp":"N","t":"contorquere et onus totum convertere nostrum;","st":"4.900"},{"sp":"N","t":"quippe etenim ventus subtili corpore tenvis"},{"sp":"N","t":"trudit agens magnam magno molimine navem"},{"sp":"N","t":"et manus una regit quanto vis impete euntem"},{"sp":"N","t":"atque gubernaclum contorquet quo libet unum,"},{"sp":"N","t":"multaque per trocleas et tympana pondere magno","st":"4.905"},{"sp":"N","t":"commovet atque levi sustollit machina nisu."},{"sp":"N","t":"Nunc quibus ille modis somnus per membra quietem"},{"sp":"N","t":"inriget atque animi curas e pectore solvat,"},{"sp":"N","t":"suavidicis potius quom multis versibus edam,"},{"sp":"N","t":"parvus ut est cycni melior canor, ille gruum quam","st":"4.910"},{"sp":"N","t":"clamor in aetheriis dispersus nubibus austri."},{"sp":"N","t":"tu mihi da tenuis auris animumque sagacem,"},{"sp":"N","t":"ne fieri negites quae dicam posse retroque"},{"sp":"N","t":"vera repulsanti discedas pectore dicta,"},{"sp":"N","t":"tutemet in culpa cum sis neque cernere possis.","st":"4.915"},{"sp":"N","t":"Principio somnus fit ubi est distracta per artus"},{"sp":"N","t":"vis animae partimque foras eiecta recessit"},{"sp":"N","t":"et partim contrusa magis concessit in altum;"},{"sp":"N","t":"dissoluuntur enim tum demum membra fluuntque."},{"sp":"N","t":"nam dubium non est, animai quin opera sit","st":"4.920"},{"sp":"N","t":"sensus hic in nobis, quem cum sopor inpedit esse,"},{"sp":"N","t":"tum nobis animam perturbatam esse putandumst"},{"sp":"N","t":"eiectamque foras, non omnem; namque iaceret"},{"sp":"N","t":"aeterno corpus perfusum frigore leti."},{"sp":"N","t":"quippe ubi nulla latens animai pars remaneret","st":"4.925"},{"sp":"N","t":"in membris, cinere ut multa latet obrutus ignis,"},{"sp":"N","t":"unde reconflari sensus per membra repente"},{"sp":"N","t":"possit, ut ex igni caeco consurgere flamma?"},{"sp":"N","t":"Sed quibus haec rebus novitas confiat et unde"},{"sp":"N","t":"perturbari anima et corpus languescere possit,","st":"4.930"},{"sp":"N","t":"expediam: tu fac ne ventis verba profundam."},{"sp":"N","t":"Principio externa corpus de parte necessum est,"},{"sp":"N","t":"aeriis quoniam vicinum tangitur auris,"},{"sp":"N","t":"tundier atque eius crebro pulsarier ictu,"},{"sp":"N","t":"proptereaque fere res omnes aut corio sunt","st":"4.935"},{"sp":"N","t":"aut etiam conchis aut callo aut cortice tectae."},{"sp":"N","t":"interiorem etiam partem spirantibus aer"},{"sp":"N","t":"verberat hic idem, cum ducitur atque reflatur."},{"sp":"N","t":"quare utrimque secus cum corpus vapulet et cum"},{"sp":"N","t":"perveniant plagae per parva foramina nobis","st":"4.940"},{"sp":"N","t":"corporis ad primas partis elementaque prima,"},{"sp":"N","t":"fit quasi paulatim nobis per membra ruina."},{"sp":"N","t":"conturbantur enim positurae principiorum"},{"sp":"N","t":"corporis atque animi. fit uti pars inde animai"},{"sp":"N","t":"eliciatur et introrsum pars abdita cedat,","st":"4.945"},{"sp":"N","t":"pars etiam distracta per artus non queat esse"},{"sp":"N","t":"coniuncta inter se neque motu mutua fungi;"},{"sp":"N","t":"inter enim saepit coetus natura viasque."},{"sp":"N","t":"ergo sensus abit mutatis motibus alte."},{"sp":"N","t":"et quoniam non est quasi quod suffulciat artus,","st":"4.950"},{"sp":"N","t":"debile fit corpus languescuntque omnia membra,"},{"sp":"N","t":"bracchia palpebraeque cadunt poplitesque cubanti"},{"sp":"N","t":"saepe tamen summittuntur virisque resolvunt."},{"sp":"N","t":"Deinde cibum sequitur somnus, quia, quae facit aer,"},{"sp":"N","t":"haec eadem cibus, in venas dum diditur omnis,","st":"4.955"},{"sp":"N","t":"efficit. et multo sopor ille gravissimus exstat,"},{"sp":"N","t":"quem satur aut lassus capias, quia plurima tum se"},{"sp":"N","t":"corpora conturbant magno contusa labore."},{"sp":"N","t":"fit ratione eadem coniectus parte animai"},{"sp":"N","t":"altior atque foras eiectus largior eius,","st":"4.960"},{"sp":"N","t":"et divisior inter se ac distractior intus."},{"sp":"N","t":"Et quo quisque fere studio devinctus adhaeret"},{"sp":"N","t":"aut quibus in rebus multum sumus ante morati"},{"sp":"N","t":"atque in ea ratione fuit contenta magis mens,"},{"sp":"N","t":"in somnis eadem plerumque videmur obire:","st":"4.965"},{"sp":"N","t":"causidici causas agere et componere leges,"},{"sp":"N","t":"induperatores pugnare ac proelia obire,"},{"sp":"N","t":"nautae contractum cum ventis degere bellum,"},{"sp":"N","t":"nos agere hoc autem et naturam quaerere rerum"},{"sp":"N","t":"semper et inventam patriis exponere chartis.","st":"4.970"},{"sp":"N","t":"cetera sic studia atque artes plerumque videntur"},{"sp":"N","t":"in somnis animos hominum frustrata tenere."},{"sp":"N","t":"et qui cumque dies multos ex ordine ludis"},{"sp":"N","t":"adsiduas dederunt operas, plerumque videmus,"},{"sp":"N","t":"cum iam destiterunt ea sensibus usurpare,","st":"4.975"},{"sp":"N","t":"relicuas tamen esse vias in mente patentis,"},{"sp":"N","t":"qua possint eadem rerum simulacra venire;"},{"sp":"N","t":"per multos itaque illa dies eadem obversantur"},{"sp":"N","t":"ante oculos, etiam vigilantes ut videantur"},{"sp":"N","t":"cernere saltantis et mollia membra moventis","st":"4.980"},{"sp":"N","t":"et citharae liquidum carmen chordasque loquentis"},{"sp":"N","t":"auribus accipere et consessum cernere eundem"},{"sp":"N","t":"scenaique simul varios splendere decores."},{"sp":"N","t":"usque adeo magni refert studium atque voluntas,"},{"sp":"N","t":"et quibus in rebus consuerint esse operati","st":"4.985"},{"sp":"N","t":"non homines solum sed vero animalia cuncta."},{"sp":"N","t":"quippe videbis equos fortis, cum membra iacebunt,"},{"sp":"N","t":"in somnis sudare tamen spirareque semper"},{"sp":"N","t":"et quasi de palma summas contendere viris"},{"sp":"N","t":"aut quasi carceribus patefactis edere voces","st":"4.990"},{"sp":"N","t":"venantumque canes in molli saepe quiete"},{"sp":"N","t":"iactant crura tamen subito vocisque repente"},{"sp":"N","t":"mittunt et crebro redducunt naribus auras."},{"sp":"N","t":"ut vestigia si teneant inventa ferarum,"},{"sp":"N","t":"expergefactique secuntur inania saepe","st":"4.995"},{"sp":"N","t":"cervorum simulacra, fugae quasi dedita cernant,"},{"sp":"N","t":"donec discussis redeant erroribus ad se."},{"sp":"N","t":"at consueta domi catulorum blanda propago"},{"sp":"N","t":"discutere et corpus de terra corripere instant,"},{"sp":"N","t":"iactant crura tamen subito vocisque repente","st":"4.1000"},{"sp":"N","t":"mittunt et crebro redducunt naribus auras"},{"sp":"N","t":"ut vestigia si teneant inventa ferarum"},{"sp":"N","t":"expergefactique secuntur inania saepe"},{"sp":"N","t":"proinde quasi ignotas facies atque ora tuantur."},{"sp":"N","t":"et quo quaeque magis sunt aspera seminiorum,","st":"4.1005"},{"sp":"N","t":"tam magis in somnis eadem saevire necessust."},{"sp":"N","t":"at variae fugiunt volucres pinnisque repente"},{"sp":"N","t":"sollicitant divom nocturno tempore lucos,"},{"sp":"N","t":"accipitres somno in leni si proelia pugnas"},{"sp":"N","t":"edere sunt persectantes visaeque volantes.","st":"4.1010"},{"sp":"N","t":"porro hominum mentes, magnis quae motibus edunt"},{"sp":"N","t":"magna, itidem saepe in somnis faciuntque geruntque,"},{"sp":"N","t":"reges expugnant, capiuntur, proelia miscent,"},{"sp":"N","t":"tollunt clamorem, quasi si iugulentur ibidem."},{"sp":"N","t":"multi depugnant gemitusque doloribus edunt","st":"4.1015"},{"sp":"N","t":"et quasi pantherae morsu saevive leonis"},{"sp":"N","t":"mandantur, magnis clamoribus omnia complent."},{"sp":"N","t":"multi de magnis per somnum rebus loquuntur"},{"sp":"N","t":"indicioque sui facti persaepe fuere."},{"sp":"N","t":"multi mortem obeunt. multi, de montibus altis","st":"4.1020"},{"sp":"N","t":"ut quasi praecipitent ad terram corpore toto,"},{"sp":"N","t":"exterruntur et ex somno quasi mentibus capti"},{"sp":"N","t":"vix ad se redeunt permoti corporis aestu."},{"sp":"N","t":"flumen item sitiens aut fontem propter amoenum"},{"sp":"N","t":"adsidet et totum prope faucibus occupat amnem.","st":"4.1025"},{"sp":"N","t":"puri saepe lacum propter si ac dolia curta"},{"sp":"N","t":"somno devincti credunt se extollere vestem,"},{"sp":"N","t":"totius umorem saccatum corporis fundunt,"},{"sp":"N","t":"cum Babylonica magnifico splendore rigantur."},{"sp":"N","t":"tum quibus aetatis freta primitus insinuatur","st":"4.1030"},{"sp":"N","t":"semen, ubi ipsa dies membris matura creavit,"},{"sp":"N","t":"conveniunt simulacra foris e corpore quoque,"},{"sp":"N","t":"nuntia praeclari voltus pulchrique coloris,"},{"sp":"N","t":"qui ciet inritans loca turgida semine multo,"},{"sp":"N","t":"ut quasi transactis saepe omnibus rebus profundant","st":"4.1035"},{"sp":"N","t":"fluminis ingentis fluctus vestemque cruentent."},{"sp":"N","t":"Sollicitatur id in nobis, quod diximus ante,"},{"sp":"N","t":"semen, adulta aetas cum primum roborat artus."},{"sp":"N","t":"namque alias aliud res commovet atque lacessit;"},{"sp":"N","t":"ex homine humanum semen ciet una hominis vis.","st":"4.1040"},{"sp":"N","t":"quod simul atque suis eiectum sedibus exit,"},{"sp":"N","t":"per membra atque artus decedit corpore toto,"},{"sp":"N","t":"in loca conveniens nervorum certa cietque"},{"sp":"N","t":"continuo partis genitalis corporis ipsas."},{"sp":"N","t":"inritata tument loca semine fitque voluntas","st":"4.1045"},{"sp":"N","t":"eicere id quo se contendit dira lubido,"},{"sp":"N","t":"incitat inritans loca turgida semine multo"},{"sp":"N","t":"idque petit corpus, mens unde est saucia amore;"},{"sp":"N","t":"namque omnes plerumque cadunt in vulnus et illam"},{"sp":"N","t":"emicat in partem sanguis, unde icimur ictu,","st":"4.1050"},{"sp":"N","t":"et si comminus est, hostem ruber occupat umor."},{"sp":"N","t":"sic igitur Veneris qui telis accipit ictus,"},{"sp":"N","t":"sive puer membris muliebribus hunc iaculatur"},{"sp":"N","t":"seu mulier toto iactans e corpore amorem,"},{"sp":"N","t":"unde feritur, eo tendit gestitque coire","st":"4.1055"},{"sp":"N","t":"et iacere umorem in corpus de corpore ductum;"},{"sp":"N","t":"namque voluptatem praesagit muta cupido."},{"sp":"N","t":"Haec Venus est nobis; hinc autemst nomen Amoris,"},{"sp":"N","t":"hinc illaec primum Veneris dulcedinis in cor"},{"sp":"N","t":"stillavit gutta et successit frigida cura;","st":"4.1060"},{"sp":"N","t":"nam si abest quod ames, praesto simulacra tamen sunt"},{"sp":"N","t":"illius et nomen dulce obversatur ad auris."},{"sp":"N","t":"sed fugitare decet simulacra et pabula amoris"},{"sp":"N","t":"absterrere sibi atque alio convertere mentem"},{"sp":"N","t":"et iacere umorem coniectum in corpora quaeque","st":"4.1065"},{"sp":"N","t":"nec retinere semel conversum unius amore"},{"sp":"N","t":"et servare sibi curam certumque dolorem;"},{"sp":"N","t":"ulcus enim vivescit et inveterascit alendo"},{"sp":"N","t":"inque dies gliscit furor atque aerumna gravescit,"},{"sp":"N","t":"si non prima novis conturbes volnera plagis","st":"4.1070"},{"sp":"N","t":"volgivagaque vagus Venere ante recentia cures"},{"sp":"N","t":"aut alio possis animi traducere motus."},{"sp":"N","t":"Nec Veneris fructu caret is qui vitat amorem,"},{"sp":"N","t":"sed potius quae sunt sine poena commoda sumit;"},{"sp":"N","t":"nam certe purast sanis magis inde voluptas","st":"4.1075"},{"sp":"N","t":"quam miseris; etenim potiundi tempore in ipso"},{"sp":"N","t":"fluctuat incertis erroribus ardor amantum"},{"sp":"N","t":"nec constat quid primum oculis manibusque fruantur."},{"sp":"N","t":"quod petiere, premunt arte faciuntque dolorem"},{"sp":"N","t":"corporis et dentes inlidunt saepe labellis","st":"4.1080"},{"sp":"N","t":"osculaque adfigunt, quia non est pura voluptas"},{"sp":"N","t":"et stimuli subsunt, qui instigant laedere id ipsum,"},{"sp":"N","t":"quod cumque est, rabies unde illaec germina surgunt."},{"sp":"N","t":"sed leviter poenas frangit Venus inter amorem"},{"sp":"N","t":"blandaque refrenat morsus admixta voluptas.","st":"4.1085"},{"sp":"N","t":"namque in eo spes est, unde est ardoris origo,"},{"sp":"N","t":"restingui quoque posse ab eodem corpore flammam."},{"sp":"N","t":"quod fieri contra totum natura repugnat;"},{"sp":"N","t":"unaque res haec est, cuius quam plurima habemus,"},{"sp":"N","t":"tam magis ardescit dira cuppedine pectus.","st":"4.1090"},{"sp":"N","t":"nam cibus atque umor membris adsumitur intus;"},{"sp":"N","t":"quae quoniam certas possunt obsidere partis,"},{"sp":"N","t":"hoc facile expletur laticum frugumque cupido."},{"sp":"N","t":"ex hominis vero facie pulchroque colore"},{"sp":"N","t":"nil datur in corpus praeter simulacra fruendum","st":"4.1095"},{"sp":"N","t":"tenvia; quae vento spes raptast saepe misella."},{"sp":"N","t":"ut bibere in somnis sitiens quom quaerit et umor"},{"sp":"N","t":"non datur, ardorem qui membris stinguere possit,"},{"sp":"N","t":"sed laticum simulacra petit frustraque laborat"},{"sp":"N","t":"in medioque sitit torrenti flumine potans,","st":"4.1100"},{"sp":"N","t":"sic in amore Venus simulacris ludit amantis,"},{"sp":"N","t":"nec satiare queunt spectando corpora coram"},{"sp":"N","t":"nec manibus quicquam teneris abradere membris"},{"sp":"N","t":"possunt errantes incerti corpore toto."},{"sp":"N","t":"denique cum membris conlatis flore fruuntur","st":"4.1105"},{"sp":"N","t":"aetatis, iam cum praesagit gaudia corpus"},{"sp":"N","t":"atque in eost Venus ut muliebria conserat arva,"},{"sp":"N","t":"adfigunt avide corpus iunguntque salivas"},{"sp":"N","t":"oris et inspirant pressantes dentibus ora,"},{"sp":"N","t":"ne quiquam, quoniam nihil inde abradere possunt","st":"4.1110"},{"sp":"N","t":"nec penetrare et abire in corpus corpore toto;"},{"sp":"N","t":"nam facere inter dum velle et certare videntur."},{"sp":"N","t":"usque adeo cupide in Veneris compagibus haerent,"},{"sp":"N","t":"membra voluptatis dum vi labefacta liquescunt."},{"sp":"N","t":"tandem ubi se erupit nervis coniecta cupido,","st":"4.1115"},{"sp":"N","t":"parva fit ardoris violenti pausa parumper."},{"sp":"N","t":"inde redit rabies eadem et furor ille revisit,"},{"sp":"N","t":"cum sibi quod cupiant ipsi contingere quaerunt,"},{"sp":"N","t":"nec reperire malum id possunt quae machina vincat."},{"sp":"N","t":"usque adeo incerti tabescunt volnere caeco.","st":"4.1120"},{"sp":"N","t":"Adde quod absumunt viris pereuntque labore,"},{"sp":"N","t":"adde quod alterius sub nutu degitur aetas,"},{"sp":"N","t":"languent officia atque aegrotat fama vacillans."},{"sp":"N","t":"labitur interea res et Babylonia fiunt"},{"sp":"N","t":"unguenta et pulchra in pedibus Sicyonia rident,","st":"4.1125"},{"sp":"N","t":"scilicet et grandes viridi cum luce zmaragdi"},{"sp":"N","t":"auro includuntur teriturque thalassina vestis"},{"sp":"N","t":"adsidue et Veneris sudorem exercita potat."},{"sp":"N","t":"et bene parta patrum fiunt anademata, mitrae,"},{"sp":"N","t":"inter dum in pallam atque Alidensia Ciaque vertunt.","st":"4.1130"},{"sp":"N","t":"eximia veste et victu convivia, ludi,"},{"sp":"N","t":"pocula crebra, unguenta, coronae, serta parantur,"},{"sp":"N","t":"ne quiquam, quoniam medio de fonte leporum"},{"sp":"N","t":"surgit amari aliquid, quod in ipsis floribus angat,"},{"sp":"N","t":"aut cum conscius ipse animus se forte remordet","st":"4.1135"},{"sp":"N","t":"desidiose agere aetatem lustrisque perire,"},{"sp":"N","t":"aut quod in ambiguo verbum iaculata reliquit,"},{"sp":"N","t":"quod cupido adfixum cordi vivescit ut ignis,"},{"sp":"N","t":"aut nimium iactare oculos aliumve tueri"},{"sp":"N","t":"quod putat in voltuque videt vestigia risus.","st":"4.1140"},{"sp":"N","t":"Atque in amore mala haec proprio summeque secundo"},{"sp":"N","t":"inveniuntur; in adverso vero atque inopi sunt,"},{"sp":"N","t":"prendere quae possis oculorum lumine operto."},{"sp":"N","t":"innumerabilia; ut melius vigilare sit ante,"},{"sp":"N","t":"qua docui ratione, cavereque, ne inliciaris.","st":"4.1145"},{"sp":"N","t":"nam vitare, plagas in amoris ne iaciamur,"},{"sp":"N","t":"non ita difficile est quam captum retibus ipsis"},{"sp":"N","t":"exire et validos Veneris perrumpere nodos."},{"sp":"N","t":"et tamen implicitus quoque possis inque peditus"},{"sp":"N","t":"effugere infestum, nisi tute tibi obvius obstes","st":"4.1150"},{"sp":"N","t":"et praetermittas animi vitia omnia primum"},{"sp":"N","t":"aut quae corporis sunt eius, quam praepetis ac vis."},{"sp":"N","t":"nam faciunt homines plerumque cupidine caeci"},{"sp":"N","t":"et tribuunt ea quae non sunt his commoda vere."},{"sp":"N","t":"multimodis igitur pravas turpisque videmus","st":"4.1155"},{"sp":"N","t":"esse in deliciis summoque in honore vigere."},{"sp":"N","t":"atque alios alii inrident Veneremque suadent"},{"sp":"N","t":"ut placent, quoniam foedo adflictentur amore,"},{"sp":"N","t":"nec sua respiciunt miseri mala maxima saepe."},{"sp":"N","t":"nigra melichrus est, inmunda et fetida acosmos,","st":"4.1160"},{"sp":"N","t":"caesia Palladium, nervosa et lignea dorcas,"},{"sp":"N","t":"parvula, pumilio, chariton mia, tota merum sal,"},{"sp":"N","t":"magna atque inmanis cataplexis plenaque honoris."},{"sp":"N","t":"balba loqui non quit, traulizi, muta pudens est;"},{"sp":"N","t":"at flagrans, odiosa, loquacula Lampadium fit.","st":"4.1165"},{"sp":"N","t":"ischnon eromenion tum fit, cum vivere non quit"},{"sp":"N","t":"prae macie; rhadine verost iam mortua tussi."},{"sp":"N","t":"at nimia et mammosa Ceres est ipsa ab Iaccho,"},{"sp":"N","t":"simula Silena ac Saturast, labeosa philema."},{"sp":"N","t":"cetera de genere hoc longum est si dicere coner.","st":"4.1170"},{"sp":"N","t":"sed tamen esto iam quantovis oris honore,"},{"sp":"N","t":"cui Veneris membris vis omnibus exoriatur;"},{"sp":"N","t":"nempe aliae quoque sunt; nempe hac sine viximus ante;"},{"sp":"N","t":"nempe eadem facit et scimus facere omnia turpi"},{"sp":"N","t":"et miseram taetris se suffit odoribus ipsa,","st":"4.1175"},{"sp":"N","t":"quam famulae longe fugitant furtimque cachinnant."},{"sp":"N","t":"at lacrimans exclusus amator limina saepe"},{"sp":"N","t":"floribus et sertis operit postisque superbos"},{"sp":"N","t":"unguit amaracino et foribus miser oscula figit;"},{"sp":"N","t":"quem si iam ammissum venientem offenderit aura","st":"4.1180"},{"sp":"N","t":"una modo, causas abeundi quaerat honestas"},{"sp":"N","t":"et meditata diu cadat alte sumpta querella"},{"sp":"N","t":"stultitiaque ibi se damnet, tribuisse quod illi"},{"sp":"N","t":"plus videat quam mortali concedere par est."},{"sp":"N","t":"nec Veneres nostras hoc fallit; quo magis ipsae","st":"4.1185"},{"sp":"N","t":"omnia summo opere hos vitae poscaenia celant,"},{"sp":"N","t":"quos retinere volunt adstrictosque esse in amore,"},{"sp":"N","t":"ne quiquam, quoniam tu animo tamen omnia possis"},{"sp":"N","t":"protrahere in lucem atque omnis inquirere risus"},{"sp":"N","t":"et, si bello animost et non odiosa, vicissim","st":"4.1190"},{"sp":"N","t":"praetermittere et humanis concedere rebus."},{"sp":"N","t":"Nec mulier semper ficto suspirat amore,"},{"sp":"N","t":"quae conplexa viri corpus cum corpore iungit"},{"sp":"N","t":"et tenet adsuctis umectans oscula labris;"},{"sp":"N","t":"nam facit ex animo saepe et communia quaerens","st":"4.1195"},{"sp":"N","t":"gaudia sollicitat spatium decurrere amoris."},{"sp":"N","t":"nec ratione alia volucres armenta feraeque"},{"sp":"N","t":"et pecudes et equae maribus subsidere possent,"},{"sp":"N","t":"si non, ipsa quod illarum subat, ardet abundans"},{"sp":"N","t":"natura et Venerem salientum laeta retractat.","st":"4.1200"},{"sp":"N","t":"nonne vides etiam quos mutua saepe voluptas"},{"sp":"N","t":"vinxit, ut in vinclis communibus excrucientur,"},{"sp":"N","t":"in triviis cum saepe canes discedere aventis"},{"sp":"N","t":"divorsi cupide summis ex viribus tendunt,"},{"sp":"N","t":"quom interea validis Veneris compagibus haerent?","st":"4.1205"},{"sp":"N","t":"quod facerent numquam, nisi mutua gaudia nossent,"},{"sp":"N","t":"quae iacere in fraudem possent vinctosque tenere."},{"sp":"N","t":"quare etiam atque etiam, ut dico, est communis voluptas."},{"sp":"N","t":"Et commiscendo quom semine forte virilem"},{"sp":"N","t":"femina vim vicit subita vi corripuitque,","st":"4.1210"},{"sp":"N","t":"tum similes matrum materno semine fiunt,"},{"sp":"N","t":"ut patribus patrio. sed quos utriusque figurae"},{"sp":"N","t":"esse vides, iuxtim miscentes vulta parentum,"},{"sp":"N","t":"corpore de patrio et materno sanguine crescunt,"},{"sp":"N","t":"semina cum Veneris stimulis excita per artus","st":"4.1215"},{"sp":"N","t":"obvia conflixit conspirans mutuus ardor,"},{"sp":"N","t":"et neque utrum superavit eorum nec superatumst."},{"sp":"N","t":"fit quoque ut inter dum similes existere avorum"},{"sp":"N","t":"possint et referant proavorum saepe figuras,"},{"sp":"N","t":"propterea quia multa modis primordia multis","st":"4.1220"},{"sp":"N","t":"mixta suo celant in corpore saepe parentis,"},{"sp":"N","t":"quae patribus patres tradunt a stirpe profecta."},{"sp":"N","t":"inde Venus varia producit sorte figuras,"},{"sp":"N","t":"maiorumque refert voltus vocesque comasque;"},{"sp":"N","t":"quandoquidem nihilo magis haec de semine certo","st":"4.1225"},{"sp":"N","t":"fiunt quam facies et corpora membraque nobis."},{"sp":"N","t":"et muliebre oritur patrio de semine saeclum"},{"sp":"N","t":"maternoque mares existunt corpore creti;"},{"sp":"N","t":"semper enim partus duplici de semine constat,"},{"sp":"N","t":"atque utri similest magis id quod cumque creatur,","st":"4.1230"},{"sp":"N","t":"eius habet plus parte aequa; quod cernere possis,"},{"sp":"N","t":"sive virum suboles sivest muliebris origo."},{"sp":"N","t":"Nec divina satum genitalem numina cuiquam"},{"sp":"N","t":"absterrent, pater a gnatis ne dulcibus umquam"},{"sp":"N","t":"appelletur et ut sterili Venere exigat aevom;","st":"4.1235"},{"sp":"N","t":"quod plerumque putant et multo sanguine maesti"},{"sp":"N","t":"conspergunt aras adolentque altaria donis,"},{"sp":"N","t":"ut gravidas reddant uxores semine largo;"},{"sp":"N","t":"ne quiquam divom numen sortisque fatigant;"},{"sp":"N","t":"nam steriles nimium crasso sunt semine partim,","st":"4.1240"},{"sp":"N","t":"et liquido praeter iustum tenuique vicissim."},{"sp":"N","t":"tenve locis quia non potis est adfigere adhaesum,"},{"sp":"N","t":"liquitur extemplo et revocatum cedit abortu."},{"sp":"N","t":"crassius hinc porro quoniam concretius aequo"},{"sp":"N","t":"mittitur, aut non tam prolixo provolat ictu","st":"4.1245"},{"sp":"N","t":"aut penetrare locos aeque nequit aut penetratum"},{"sp":"N","t":"aegre admiscetur muliebri semine semen."},{"sp":"N","t":"nam multum harmoniae Veneris differre videntur."},{"sp":"N","t":"atque alias alii complent magis ex aliisque"},{"sp":"N","t":"succipiunt aliae pondus magis inque gravescunt.","st":"4.1250"},{"sp":"N","t":"et multae steriles Hymenaeis ante fuerunt"},{"sp":"N","t":"pluribus et nactae post sunt tamen unde puellos"},{"sp":"N","t":"suscipere et partu possent ditescere dulci."},{"sp":"N","t":"et quibus ante domi fecundae saepe nequissent"},{"sp":"N","t":"uxoris parere, inventast illis quoque compar","st":"4.1255"},{"sp":"N","t":"natura, ut possent gnatis munire senectam."},{"sp":"N","t":"usque adeo magni refert, ut semina possint"},{"sp":"N","t":"seminibus commisceri genitaliter apta"},{"sp":"N","t":"crassaque conveniant liquidis et liquida crassis."},{"sp":"N","t":"atque in eo refert quo victu vita colatur;","st":"4.1260"},{"sp":"N","t":"namque aliis rebus concrescunt semina membris"},{"sp":"N","t":"atque aliis extenvantur tabentque vicissim."},{"sp":"N","t":"et quibus ipsa modis tractetur blanda voluptas."},{"sp":"N","t":"id quoque permagni refert; nam more ferarum"},{"sp":"N","t":"quadrupedumque magis ritu plerumque putantur","st":"4.1265"},{"sp":"N","t":"concipere uxores, quia sic loca sumere possunt"},{"sp":"N","t":"pectoribus positis sublatis semina lumbis."},{"sp":"N","t":"nec molles opus sunt motus uxoribus hilum."},{"sp":"N","t":"nam mulier prohibet se concipere atque repugnat,"},{"sp":"N","t":"clunibus ipsa viri Venerem si laeta retractat","st":"4.1270"},{"sp":"N","t":"atque exossato ciet omni pectore fluctus;"},{"sp":"N","t":"eicit enim sulcum recta regione viaque"},{"sp":"N","t":"vomeris atque locis avertit seminis ictum."},{"sp":"N","t":"idque sua causa consuerunt scorta moveri,"},{"sp":"N","t":"ne complerentur crebro gravidaeque iacerent,","st":"4.1275"},{"sp":"N","t":"et simul ipsa viris Venus ut concinnior esset;"},{"sp":"N","t":"coniugibus quod nil nostris opus esse videtur."},{"sp":"N","t":"Nec divinitus inter dum Venerisque sagittis"},{"sp":"N","t":"deteriore fit ut forma muliercula ametur;"},{"sp":"N","t":"nam facit ipsa suis inter dum femina factis","st":"4.1280"},{"sp":"N","t":"morigerisque modis et munde corpore culto,"},{"sp":"N","t":"ut facile insuescat secum te degere vitam."},{"sp":"N","t":"quod super est, consuetudo concinnat amorem;"},{"sp":"N","t":"nam leviter quamvis quod crebro tunditur ictu,"},{"sp":"N","t":"vincitur in longo spatio tamen atque labascit.","st":"4.1285"},{"sp":"N","t":"nonne vides etiam guttas in saxa cadentis"},{"sp":"N","t":"umoris longo in spatio pertundere saxa?"},{"sp":"HDR","t":"Liber V"},{"sp":"N","t":"Quis potis est dignum pollenti pectore carmen","st":"5.1"},{"sp":"N","t":"condere pro rerum maiestate hisque repertis?"},{"sp":"N","t":"quisve valet verbis tantum, qui fingere laudes"},{"sp":"N","t":"pro meritis eius possit, qui talia nobis"},{"sp":"N","t":"pectore parta suo quaesitaque praemia liquit?","st":"5.5"},{"sp":"N","t":"nemo, ut opinor, erit mortali corpore cretus."},{"sp":"N","t":"nam si, ut ipsa petit maiestas cognita rerum,"},{"sp":"N","t":"dicendum est, deus ille fuit, deus, inclyte Memmi,"},{"sp":"N","t":"qui princeps vitae rationem invenit eam quae"},{"sp":"N","t":"nunc appellatur sapientia, quique per artem","st":"5.10"},{"sp":"N","t":"fluctibus et tantis vitam tantisque tenebris"},{"sp":"N","t":"in tam tranquillo et tam clara luce locavit."},{"sp":"N","t":"confer enim divina aliorum antiqua reperta."},{"sp":"N","t":"namque Ceres fertur fruges Liberque liquoris"},{"sp":"N","t":"vitigeni laticem mortalibus instituisse;","st":"5.15"},{"sp":"N","t":"cum tamen his posset sine rebus vita manere,"},{"sp":"N","t":"ut fama est aliquas etiam nunc vivere gentis."},{"sp":"N","t":"at bene non poterat sine puro pectore vivi;"},{"sp":"N","t":"quo magis hic merito nobis deus esse videtur,"},{"sp":"N","t":"ex quo nunc etiam per magnas didita gentis","st":"5.20"},{"sp":"N","t":"dulcia permulcent animos solacia vitae."},{"sp":"N","t":"Herculis antistare autem si facta putabis,"},{"sp":"N","t":"longius a vera multo ratione ferere."},{"sp":"N","t":"quid Nemeaeus enim nobis nunc magnus hiatus"},{"sp":"N","t":"ille leonis obesset et horrens Arcadius sus,","st":"5.25"},{"sp":"N","t":"tanto opere officerent nobis Stymphala colentes?"},{"sp":"N","t":"denique quid Cretae taurus Lernaeaque pestis"},{"sp":"N","t":"hydra venenatis posset vallata colubris?"},{"sp":"N","t":"quidve tripectora tergemini vis Geryonai"},{"sp":"N","t":"et Diomedis equi spirantes naribus ignem","st":"5.30"},{"sp":"N","t":"Thracia Bistoniasque plagas atque Ismara propter"},{"sp":"N","t":"aureaque Hesperidum servans fulgentia mala,"},{"sp":"N","t":"asper, acerba tuens, immani corpore serpens"},{"sp":"N","t":"arboris amplexus stirpes? quid denique obesset"},{"sp":"N","t":"propter Atlanteum litus pelagique severa,","st":"5.35"},{"sp":"N","t":"quo neque noster adit quisquam nec barbarus audet?"},{"sp":"N","t":"cetera de genere hoc quae sunt portenta perempta,"},{"sp":"N","t":"si non victa forent, quid tandem viva nocerent?"},{"sp":"N","t":"nil, ut opinor: ita ad satiatem terra ferarum"},{"sp":"N","t":"nunc etiam scatit et trepido terrore repleta est","st":"5.40"},{"sp":"N","t":"per nemora ac montes magnos silvasque profundas;"},{"sp":"N","t":"quae loca vitandi plerumque est nostra potestas."},{"sp":"N","t":"at nisi purgatumst pectus, quae proelia nobis"},{"sp":"N","t":"atque pericula tumst ingratis insinuandum!"},{"sp":"N","t":"quantae tum scindunt hominem cuppedinis acres","st":"5.45"},{"sp":"N","t":"sollicitum curae quantique perinde timores!"},{"sp":"N","t":"quidve superbia spurcitia ac petulantia? quantas"},{"sp":"N","t":"efficiunt clades! quid luxus desidiaeque?"},{"sp":"N","t":"haec igitur qui cuncta subegerit ex animoque"},{"sp":"N","t":"expulerit dictis, non armis, nonne decebit","st":"5.50"},{"sp":"N","t":"hunc hominem numero divom dignarier esse?"},{"sp":"N","t":"cum bene praesertim multa ac divinitus ipsis"},{"sp":"N","t":"iam mortalibus e divis dare dicta suerit"},{"sp":"N","t":"atque omnem rerum naturam pandere dictis."},{"sp":"N","t":"Cuius ego ingressus vestigia dum rationes","st":"5.55"},{"sp":"N","t":"persequor ac doceo dictis, quo quaeque creata"},{"sp":"N","t":"foedere sint, in eo quam sit durare necessum"},{"sp":"N","t":"nec validas valeant aevi rescindere leges,"},{"sp":"N","t":"quo genere in primis animi natura reperta est"},{"sp":"N","t":"nativo primum consistere corpore creta,","st":"5.60"},{"sp":"N","t":"nec posse incolumem magnum durare per aevum,"},{"sp":"N","t":"sed simulacra solere in somnis fallere mentem,"},{"sp":"N","t":"cernere cum videamur eum quem vita reliquit,"},{"sp":"N","t":"quod super est, nunc huc rationis detulit ordo,"},{"sp":"N","t":"ut mihi mortali consistere corpore mundum","st":"5.65"},{"sp":"N","t":"nativomque simul ratio reddunda sit esse;"},{"sp":"N","t":"et quibus ille modis congressus materiai"},{"sp":"N","t":"fundarit terram caelum mare sidera solem"},{"sp":"N","t":"lunaique globum; tum quae tellure animantes"},{"sp":"N","t":"extiterint, et quae nullo sint tempore natae;","st":"5.70"},{"sp":"N","t":"quove modo genus humanum variante loquella"},{"sp":"N","t":"coeperit inter se vesci per nomina rerum;"},{"sp":"N","t":"et quibus ille modis divom metus insinuarit"},{"sp":"N","t":"pectora, terrarum qui in orbi sancta tuetur"},{"sp":"N","t":"fana lacus lucos aras simulacraque divom.","st":"5.75"},{"sp":"N","t":"praeterea solis cursus lunaeque meatus"},{"sp":"N","t":"expediam qua vi flectat natura gubernans;"},{"sp":"N","t":"ne forte haec inter caelum terramque reamur"},{"sp":"N","t":"libera sponte sua cursus lustrare perennis,"},{"sp":"N","t":"morigera ad fruges augendas atque animantis,","st":"5.80"},{"sp":"N","t":"neve aliqua divom volvi ratione putemus."},{"sp":"N","t":"nam bene qui didicere deos securum agere aevom,"},{"sp":"N","t":"si tamen interea mirantur qua ratione"},{"sp":"N","t":"quaeque geri possint, praesertim rebus in illis"},{"sp":"N","t":"quae supera caput aetheriis cernuntur in oris,","st":"5.85"},{"sp":"N","t":"rursus in antiquas referuntur religiones"},{"sp":"N","t":"et dominos acris adsciscunt, omnia posse"},{"sp":"N","t":"quos miseri credunt, ignari quid queat esse,"},{"sp":"N","t":"quid nequeat, finita potestas denique cuique"},{"sp":"N","t":"qua nam sit ratione atque alte terminus haerens.","st":"5.90"},{"sp":"N","t":"Quod super est, ne te in promissis plura moremur,"},{"sp":"N","t":"principio maria ac terras caelumque tuere;"},{"sp":"N","t":"quorum naturam triplicem, tria corpora, Memmi,"},{"sp":"N","t":"tris species tam dissimilis, tria talia texta,"},{"sp":"N","t":"una dies dabit exitio, multosque per annos","st":"5.95"},{"sp":"N","t":"sustentata ruet moles et machina mundi."},{"sp":"N","t":"nec me animi fallit quam res nova miraque menti"},{"sp":"N","t":"accidat exitium caeli terraeque futurum,"},{"sp":"N","t":"et quam difficile id mihi sit pervincere dictis;"},{"sp":"N","t":"ut fit ubi insolitam rem adportes auribus ante","st":"5.100"},{"sp":"N","t":"nec tamen hanc possis oculorum subdere visu"},{"sp":"N","t":"nec iacere indu manus, via qua munita fidei"},{"sp":"N","t":"proxima fert humanum in pectus templaque mentis."},{"sp":"N","t":"sed tamen effabor. dictis dabit ipsa fidem res"},{"sp":"N","t":"forsitan et graviter terrarum motibus ortis","st":"5.105"},{"sp":"N","t":"omnia conquassari in parvo tempore cernes."},{"sp":"N","t":"quod procul a nobis flectat fortuna gubernans,"},{"sp":"N","t":"et ratio potius quam res persuadeat ipsa"},{"sp":"N","t":"succidere horrisono posse omnia victa fragore."},{"sp":"N","t":"Qua prius adgrediar quam de re fundere fata","st":"5.110"},{"sp":"N","t":"sanctius et multo certa ratione magis quam"},{"sp":"N","t":"Pythia quae tripode a Phoebi lauroque profatur,"},{"sp":"N","t":"multa tibi expediam doctis solacia dictis;"},{"sp":"N","t":"religione refrenatus ne forte rearis"},{"sp":"N","t":"terras et solem et caelum, mare sidera lunam,","st":"5.115"},{"sp":"N","t":"corpore divino debere aeterna manere,"},{"sp":"N","t":"proptereaque putes ritu par esse Gigantum"},{"sp":"N","t":"pendere eos poenas inmani pro scelere omnis,"},{"sp":"N","t":"qui ratione sua disturbent moenia mundi"},{"sp":"N","t":"praeclarumque velint caeli restinguere solem","st":"5.120"},{"sp":"N","t":"inmortalia mortali sermone notantes;"},{"sp":"N","t":"quae procul usque adeo divino a numine distent"},{"sp":"N","t":"inque deum numero quae sint indigna videri,"},{"sp":"N","t":"notitiam potius praebere ut posse putentur"},{"sp":"N","t":"quid sit vitali motu sensuque remotum.","st":"5.125"},{"sp":"N","t":"quippe etenim non est, cum quovis corpore ut esse"},{"sp":"N","t":"posse animi natura putetur consiliumque."},{"sp":"N","t":"sicut in aethere non arbor, non aequore salso"},{"sp":"N","t":"nubes esse queunt neque pisces vivere in arvis"},{"sp":"N","t":"nec cruor in lignis neque saxis sucus inesse,","st":"5.130"},{"sp":"N","t":"certum ac dispositumst ubi quicquid crescat et insit,"},{"sp":"N","t":"sic animi natura nequit sine corpore oriri"},{"sp":"N","t":"sola neque a nervis et sanguine longius esse."},{"sp":"N","t":"quod si posset enim, multo prius ipsa animi vis"},{"sp":"N","t":"in capite aut umeris aut imis calcibus esse","st":"5.135"},{"sp":"N","t":"posset et innasci quavis in parte soleret,"},{"sp":"N","t":"tandem in eodem homine atque in eodem vase manere."},{"sp":"N","t":"quod quoniam nostro quoque constat corpore certum"},{"sp":"N","t":"dispositumque videtur ubi esse et crescere possit"},{"sp":"N","t":"seorsum anima atque animus, tanto magis infitiandum","st":"5.140"},{"sp":"N","t":"totum posse extra corpus formamque animalem"},{"sp":"N","t":"putribus in glebis terrarum aut solis in igni"},{"sp":"N","t":"aut in aqua durare aut altis aetheris oris."},{"sp":"N","t":"haud igitur constant divino praedita sensu,"},{"sp":"N","t":"quandoquidem nequeunt vitaliter esse animata.","st":"5.145"},{"sp":"N","t":"Illud item non est ut possis credere, sedes"},{"sp":"N","t":"esse deum sanctas in mundi partibus ullis."},{"sp":"N","t":"tenvis enim natura deum longeque remota"},{"sp":"N","t":"sensibus ab nostris animi vix mente videtur;"},{"sp":"N","t":"quae quoniam manuum tactum suffugit et ictum,","st":"5.150"},{"sp":"N","t":"tactile nil nobis quod sit contingere debet;"},{"sp":"N","t":"tangere enim non quit quod tangi non licet ipsum."},{"sp":"N","t":"quare etiam sedes quoque nostris sedibus esse"},{"sp":"N","t":"dissimiles debent, tenues de corpore eorum;"},{"sp":"N","t":"quae tibi posterius largo sermone probabo.","st":"5.155"},{"sp":"N","t":"Dicere porro hominum causa voluisse parare"},{"sp":"N","t":"praeclaram mundi naturam proptereaque"},{"sp":"N","t":"adlaudabile opus divom laudare decere"},{"sp":"N","t":"aeternumque putare atque inmortale futurum,"},{"sp":"N","t":"nec fas esse, deum quod sit ratione vetusta","st":"5.160"},{"sp":"N","t":"gentibus humanis fundatum perpetuo aevo,"},{"sp":"N","t":"sollicitare suis ulla vi ex sedibus umquam"},{"sp":"N","t":"nec verbis vexare et ab imo evertere summa,"},{"sp":"N","t":"cetera de genere hoc adfingere et addere, Memmi,"},{"sp":"N","t":"desiperest. quid enim inmortalibus atque beatis","st":"5.165"},{"sp":"N","t":"gratia nostra queat largirier emolumenti,"},{"sp":"N","t":"ut nostra quicquam causa gerere adgrediantur?"},{"sp":"N","t":"quidve novi potuit tanto post ante quietos"},{"sp":"N","t":"inlicere ut cuperent vitam mutare priorem?"},{"sp":"N","t":"nam gaudere novis rebus debere videtur","st":"5.170"},{"sp":"N","t":"cui veteres obsunt; sed cui nihil accidit aegri"},{"sp":"N","t":"tempore in ante acto, cum pulchre degeret aevom,"},{"sp":"N","t":"quid potuit novitatis amorem accendere tali?"},{"sp":"N","t":"quidve mali fuerat nobis non esse creatis?"},{"sp":"N","t":"an, credo, in tenebris vita ac maerore iacebat,","st":"5.175"},{"sp":"N","t":"donec diluxit rerum genitalis origo?"},{"sp":"N","t":"natus enim debet qui cumque est velle manere"},{"sp":"N","t":"in vita, donec retinebit blanda voluptas;"},{"sp":"N","t":"qui numquam vero vitae gustavit amorem"},{"sp":"N","t":"nec fuit in numero, quid obest non esse creatum?","st":"5.180"},{"sp":"N","t":"exemplum porro gignundis rebus et ipsa"},{"sp":"N","t":"notities hominum divis unde insita primum est,"},{"sp":"N","t":"quid vellent facere ut scirent animoque viderent,"},{"sp":"N","t":"quove modost umquam vis cognita principiorum"},{"sp":"N","t":"quidque inter sese permutato ordine possent.","st":"5.185"},{"sp":"N","t":"si non ipsa dedit speciem natura creandi?"},{"sp":"N","t":"namque ita multa modis multis primordia rerum"},{"sp":"N","t":"ex infinito iam tempore percita plagis"},{"sp":"N","t":"ponderibusque suis consuerunt concita ferri"},{"sp":"N","t":"omnimodisque coire atque omnia pertemptare,","st":"5.190"},{"sp":"N","t":"quae cumque inter se possint congressa creare,"},{"sp":"N","t":"ut non sit mirum, si in talis disposituras"},{"sp":"N","t":"deciderunt quoque et in talis venere meatus,"},{"sp":"N","t":"qualibus haec rerum geritur nunc summa novando."},{"sp":"N","t":"Quod si iam rerum ignorem primordia quae sint,","st":"5.195"},{"sp":"N","t":"hoc tamen ex ipsis caeli rationibus ausim"},{"sp":"N","t":"confirmare aliisque ex rebus reddere multis,"},{"sp":"N","t":"nequaquam nobis divinitus esse paratam"},{"sp":"N","t":"naturam rerum: tanta stat praedita culpa."},{"sp":"N","t":"principio quantum caeli tegit impetus ingens,","st":"5.200"},{"sp":"N","t":"inde avidam partem montes silvaeque ferarum"},{"sp":"N","t":"possedere, tenent rupes vastaeque paludes"},{"sp":"N","t":"et mare, quod late terrarum distinet oras."},{"sp":"N","t":"inde duas porro prope partis fervidus ardor"},{"sp":"N","t":"adsiduusque geli casus mortalibus aufert.","st":"5.205"},{"sp":"N","t":"quod super est arvi, tamen id natura sua vi"},{"sp":"N","t":"sentibus obducat, ni vis humana resistat"},{"sp":"N","t":"vitai causa valido consueta bidenti"},{"sp":"N","t":"ingemere et terram pressis proscindere aratris."},{"sp":"N","t":"si non fecundas vertentes vomere glebas","st":"5.210"},{"sp":"N","t":"terraique solum subigentes cimus ad ortus."},{"sp":"N","t":"sponte sua nequeant liquidas existere in auras."},{"sp":"N","t":"et tamen inter dum magno quaesita labore"},{"sp":"N","t":"cum iam per terras frondent atque omnia florent,"},{"sp":"N","t":"aut nimiis torret fervoribus aetherius sol","st":"5.215"},{"sp":"N","t":"aut subiti peremunt imbris gelidaeque pruinae"},{"sp":"N","t":"flabraque ventorum violento turbine vexant."},{"sp":"N","t":"praeterea genus horriferum natura ferarum"},{"sp":"N","t":"humanae genti infestum terraque marique"},{"sp":"N","t":"cur alit atque auget? cur anni tempora morbos","st":"5.220"},{"sp":"N","t":"adportant? quare mors inmatura vagatur?"},{"sp":"N","t":"tum porro puer, ut saevis proiectus ab undis"},{"sp":"N","t":"navita, nudus humi iacet infans indigus omni"},{"sp":"N","t":"vitali auxilio, cum primum in luminis oras"},{"sp":"N","t":"nixibus ex alvo matris natura profudit,","st":"5.225"},{"sp":"N","t":"vagituque locum lugubri complet, ut aequumst"},{"sp":"N","t":"cui tantum in vita restet transire malorum."},{"sp":"N","t":"at variae crescunt pecudes armenta feraeque"},{"sp":"N","t":"nec crepitacillis opus est nec cuiquam adhibendast"},{"sp":"N","t":"almae nutricis blanda atque infracta loquella","st":"5.230"},{"sp":"N","t":"nec varias quaerunt vestes pro tempore caeli,"},{"sp":"N","t":"denique non armis opus est, non moenibus altis,"},{"sp":"N","t":"qui sua tutentur, quando omnibus omnia large"},{"sp":"N","t":"tellus ipsa parit naturaque daedala rerum."},{"sp":"N","t":"Principio quoniam terrai corpus et umor","st":"5.235"},{"sp":"N","t":"aurarumque leves animae calidique vapores,"},{"sp":"N","t":"e quibus haec rerum consistere summa videtur,"},{"sp":"N","t":"omnia nativo ac mortali corpore constant,"},{"sp":"N","t":"debet eodem omnis mundi natura putari."},{"sp":"N","t":"quippe etenim, quorum partis et membra videmus","st":"5.240"},{"sp":"N","t":"corpore nativo mortalibus esse figuris,"},{"sp":"N","t":"haec eadem ferme mortalia cernimus esse"},{"sp":"N","t":"et nativa simul. qua propter maxima mundi"},{"sp":"N","t":"cum videam membra ac partis consumpta regigni,"},{"sp":"N","t":"scire licet caeli quoque item terraeque fuisse","st":"5.245"},{"sp":"N","t":"principiale aliquod tempus clademque futuram."},{"sp":"N","t":"Illud in his rebus ne corripuisse rearis"},{"sp":"N","t":"me mihi, quod terram atque ignem mortalia sumpsi"},{"sp":"N","t":"esse neque umorem dubitavi aurasque perire"},{"sp":"N","t":"atque eadem gigni rursusque augescere dixi.","st":"5.250"},{"sp":"N","t":"principio pars terrai non nulla, perusta"},{"sp":"N","t":"solibus adsiduis, multa pulsata pedum vi,"},{"sp":"N","t":"pulveris exhalat nebulam nubesque volantis,"},{"sp":"N","t":"quas validi toto dispergunt aere venti."},{"sp":"N","t":"pars etiam glebarum ad diluviem revocatur","st":"5.255"},{"sp":"N","t":"imbribus et ripas radentia flumina rodunt."},{"sp":"N","t":"praeterea pro parte sua, quod cumque alit auget,"},{"sp":"N","t":"redditur; et quoniam dubio procul esse videtur"},{"sp":"N","t":"omniparens eadem rerum commune sepulcrum."},{"sp":"N","t":"ergo terra tibi libatur et aucta recrescit.","st":"5.260"},{"sp":"N","t":"Quod super est, umore novo mare flumina fontes"},{"sp":"N","t":"semper abundare et latices manare perennis"},{"sp":"N","t":"nil opus est verbis: magnus decursus aquarum"},{"sp":"N","t":"undique declarat. sed primum quicquid aquai"},{"sp":"N","t":"tollitur in summaque fit ut nihil umor abundet,","st":"5.265"},{"sp":"N","t":"partim quod validi verrentes aequora venti"},{"sp":"N","t":"deminuunt radiisque retexens aetherius sol,"},{"sp":"N","t":"partim quod supter per terras diditur omnis;"},{"sp":"N","t":"percolatur enim virus retroque remanat"},{"sp":"N","t":"materies umoris et ad caput amnibus omnis","st":"5.270"},{"sp":"N","t":"convenit, inde super terras fluit agmine dulci"},{"sp":"N","t":"qua via secta semel liquido pede detulit undas."},{"sp":"N","t":"Aera nunc igitur dicam, qui corpore toto"},{"sp":"N","t":"innumerabiliter privas mutatur in horas."},{"sp":"N","t":"semper enim, quod cumque fluit de rebus, id omne","st":"5.275"},{"sp":"N","t":"aeris in magnum fertur mare; qui nisi contra"},{"sp":"N","t":"corpora retribuat rebus recreetque fluentis,"},{"sp":"N","t":"omnia iam resoluta forent et in aera versa."},{"sp":"N","t":"haut igitur cessat gigni de rebus et in res"},{"sp":"N","t":"reccidere, adsidue quoniam fluere omnia constat.","st":"5.280"},{"sp":"N","t":"Largus item liquidi fons luminis, aetherius sol,"},{"sp":"N","t":"inrigat adsidue caelum candore recenti"},{"sp":"N","t":"suppeditatque novo confestim lumine lumen."},{"sp":"N","t":"nam primum quicquid fulgoris disperit ei,"},{"sp":"N","t":"quo cumque accidit. id licet hinc cognoscere possis,","st":"5.285"},{"sp":"N","t":"quod simul ac primum nubes succedere soli"},{"sp":"N","t":"coepere et radios inter quasi rumpere lucis,"},{"sp":"N","t":"extemplo inferior pars horum disperit omnis"},{"sp":"N","t":"terraque inumbratur qua nimbi cumque feruntur;"},{"sp":"N","t":"ut noscas splendore novo res semper egere","st":"5.290"},{"sp":"N","t":"et primum iactum fulgoris quemque perire"},{"sp":"N","t":"nec ratione alia res posse in sole videri,"},{"sp":"N","t":"perpetuo ni suppeditet lucis caput ipsum."},{"sp":"N","t":"quin etiam nocturna tibi, terrestria quae sunt,"},{"sp":"N","t":"lumina, pendentes lychni claraeque coruscis","st":"5.295"},{"sp":"N","t":"fulguribus pingues multa caligine taedae"},{"sp":"N","t":"consimili properant ratione, ardore ministro,"},{"sp":"N","t":"suppeditare novom lumen, tremere ignibus instant,"},{"sp":"N","t":"instant, nec loca lux inter quasi rupta relinquit:"},{"sp":"N","t":"usque adeo properanter ab omnibus ignibus ei","st":"5.300"},{"sp":"N","t":"exitium celeri celeratur origine flammae."},{"sp":"N","t":"sic igitur solem lunam stellasque putandum"},{"sp":"N","t":"ex alio atque alio lucem iactare subortu"},{"sp":"N","t":"et primum quicquid flammarum perdere semper,"},{"sp":"N","t":"inviolabilia haec ne credas forte vigere.","st":"5.305"},{"sp":"N","t":"Denique non lapides quoque vinci cernis ab aevo,"},{"sp":"N","t":"non altas turris ruere et putrescere saxa,"},{"sp":"N","t":"non delubra deum simulacraque fessa fatisci"},{"sp":"N","t":"nec sanctum numen fati protollere finis"},{"sp":"N","t":"posse neque adversus naturae foedera niti?","st":"5.310"},{"sp":"N","t":"denique non monimenta virum dilapsa videmus,"},{"sp":"N","t":"quaerere proporro, sibi cumque senescere credas,"},{"sp":"N","t":"non ruere avolsos silices a montibus altis"},{"sp":"N","t":"nec validas aevi vires perferre patique"},{"sp":"N","t":"finiti? neque enim caderent avolsa repente,","st":"5.315"},{"sp":"N","t":"ex infinito quae tempore pertolerassent"},{"sp":"N","t":"omnia tormenta aetatis, privata fragore."},{"sp":"N","t":"Denique iam tuere hoc, circum supraque quod omne"},{"sp":"N","t":"continet amplexu terram: si procreat ex se"},{"sp":"N","t":"omnia, quod quidam memorant, recipitque perempta,","st":"5.320"},{"sp":"N","t":"totum nativum mortali corpore constat."},{"sp":"N","t":"nam quod cumque alias ex se res auget alitque,"},{"sp":"N","t":"deminui debet, recreari, cum recipit res."},{"sp":"N","t":"Praeterea si nulla fuit genitalis origo"},{"sp":"N","t":"terrarum et caeli semperque aeterna fuere,","st":"5.325"},{"sp":"N","t":"cur supera bellum Thebanum et funera Troiae"},{"sp":"N","t":"non alias alii quoque res cecinere poetae?"},{"sp":"N","t":"quo tot facta virum totiens cecidere neque usquam"},{"sp":"N","t":"aeternis famae monimentis insita florent?"},{"sp":"N","t":"verum, ut opinor, habet novitatem summa recensque","st":"5.330"},{"sp":"N","t":"naturast mundi neque pridem exordia cepit."},{"sp":"N","t":"quare etiam quaedam nunc artes expoliuntur,"},{"sp":"N","t":"nunc etiam augescunt; nunc addita navigiis sunt"},{"sp":"N","t":"multa, modo organici melicos peperere sonores,"},{"sp":"N","t":"denique natura haec rerum ratioque repertast","st":"5.335"},{"sp":"N","t":"nuper, et hanc primus cum primis ipse repertus"},{"sp":"N","t":"nunc ego sum in patrias qui possim vertere voces."},{"sp":"N","t":"Quod si forte fuisse ante hac eadem omnia credis,"},{"sp":"N","t":"sed periise hominum torrenti saecla vapore,"},{"sp":"N","t":"aut cecidisse urbis magno vexamine mundi,","st":"5.340"},{"sp":"N","t":"aut ex imbribus adsiduis exisse rapaces"},{"sp":"N","t":"per terras amnes atque oppida coperuisse."},{"sp":"N","t":"tanto quique magis victus fateare necessest"},{"sp":"N","t":"exitium quoque terrarum caelique futurum;"},{"sp":"N","t":"nam cum res tantis morbis tantisque periclis","st":"5.345"},{"sp":"N","t":"temptarentur, ibi si tristior incubuisset"},{"sp":"N","t":"causa, darent late cladem magnasque ruinas."},{"sp":"N","t":"nec ratione alia mortales esse videmur,"},{"sp":"N","t":"inter nos nisi quod morbis aegrescimus isdem"},{"sp":"N","t":"atque illi quos a vita natura removit.","st":"5.350"},{"sp":"N","t":"Praeterea quae cumque manent aeterna necessust"},{"sp":"N","t":"aut, quia sunt solido cum corpore, respuere ictus"},{"sp":"N","t":"nec penetrare pati sibi quicquam quod queat artas"},{"sp":"N","t":"dissociare intus partis, ut materiai"},{"sp":"N","t":"corpora sunt, quorum naturam ostendimus ante,","st":"5.355"},{"sp":"N","t":"aut ideo durare aetatem posse per omnem,"},{"sp":"N","t":"plagarum quia sunt expertia, sicut inane est,"},{"sp":"N","t":"quod manet intactum neque ab ictu fungitur hilum,"},{"sp":"N","t":"aut etiam quia nulla loci sit copia circum,"},{"sp":"N","t":"quo quasi res possint discedere dissoluique,","st":"5.360"},{"sp":"N","t":"sicut summarum summa est aeterna, neque extra"},{"sp":"N","t":"qui locus est quo dissiliant neque corpora sunt quae"},{"sp":"N","t":"possint incidere et valida dissolvere plaga."},{"sp":"N","t":"at neque, uti docui, solido cum corpore mundi"},{"sp":"N","t":"naturast, quoniam admixtumst in rebus inane,","st":"5.365"},{"sp":"N","t":"nec tamen est ut inane, neque autem corpora desunt,"},{"sp":"N","t":"ex infinito quae possint forte coorta"},{"sp":"N","t":"corruere hanc rerum violento turbine summam"},{"sp":"N","t":"aut aliam quamvis cladem inportare pericli,"},{"sp":"N","t":"nec porro natura loci spatiumque profundi","st":"5.370"},{"sp":"N","t":"deficit, exspargi quo possint moenia mundi,"},{"sp":"N","t":"aut alia quavis possunt vi pulsa perire."},{"sp":"N","t":"haut igitur leti praeclusa est ianua caelo"},{"sp":"N","t":"nec soli terraeque neque altis aequoris undis,"},{"sp":"N","t":"sed patet immani et vasto respectat hiatu.","st":"5.375"},{"sp":"N","t":"quare etiam nativa necessumst confiteare"},{"sp":"N","t":"haec eadem; neque enim, mortali corpore quae sunt,"},{"sp":"N","t":"ex infinito iam tempore adhuc potuissent"},{"sp":"N","t":"inmensi validas aevi contemnere vires."},{"sp":"N","t":"Denique tantopere inter se cum maxima mundi","st":"5.380"},{"sp":"N","t":"pugnent membra, pio nequaquam concita bello,"},{"sp":"N","t":"nonne vides aliquam longi certaminis ollis"},{"sp":"N","t":"posse dari finem, vel cum sol et vapor omnis"},{"sp":"N","t":"omnibus epotis umoribus exsuperarint?"},{"sp":"N","t":"quod facere intendunt, neque adhuc conata patrantur;","st":"5.385"},{"sp":"N","t":"tantum suppeditant amnes ultraque minantur"},{"sp":"N","t":"omnia diluviare ex alto gurgite ponti:"},{"sp":"N","t":"ne quiquam, quoniam verrentes aequora venti"},{"sp":"N","t":"deminuunt radiisque retexens aetherius sol,"},{"sp":"N","t":"et siccare prius confidunt omnia posse","st":"5.390"},{"sp":"N","t":"quam liquor incepti possit contingere finem."},{"sp":"N","t":"tantum spirantes aequo certamine bellum"},{"sp":"N","t":"magnis inter se de rebus cernere certant,"},{"sp":"N","t":"cum semel interea fuerit superantior ignis"},{"sp":"N","t":"et semel, ut fama est, umor regnarit in arvis.","st":"5.395"},{"sp":"N","t":"ignis enim superavit et ambiens multa perussit,"},{"sp":"N","t":"avia cum Phaethonta rapax vis solis equorum"},{"sp":"N","t":"aethere raptavit toto terrasque per omnis."},{"sp":"N","t":"at pater omnipotens ira tum percitus acri"},{"sp":"N","t":"magnanimum Phaethonta repenti fulminis ictu","st":"5.400"},{"sp":"N","t":"deturbavit equis in terram, Solque cadenti"},{"sp":"N","t":"obvius aeternam succepit lampada mundi"},{"sp":"N","t":"disiectosque redegit equos iunxitque trementis,"},{"sp":"N","t":"inde suum per iter recreavit cuncta gubernans,"},{"sp":"N","t":"scilicet ut veteres Graium cecinere poetae.","st":"5.405"},{"sp":"N","t":"quod procul a vera nimis est ratione repulsum."},{"sp":"N","t":"ignis enim superare potest ubi materiai"},{"sp":"N","t":"ex infinito sunt corpora plura coorta;"},{"sp":"N","t":"inde cadunt vires aliqua ratione revictae,"},{"sp":"N","t":"aut pereunt res exustae torrentibus auris.","st":"5.410"},{"sp":"N","t":"umor item quondam coepit superare coortus,"},{"sp":"N","t":"ut fama est, hominum vitas quando obruit undis;"},{"sp":"N","t":"inde ubi vis aliqua ratione aversa recessit,"},{"sp":"N","t":"ex infinito fuerat quae cumque coorta,"},{"sp":"N","t":"constiterunt imbres et flumina vim minuerunt.","st":"5.415"},{"sp":"N","t":"Sed quibus ille modis coniectus materiai"},{"sp":"N","t":"fundarit terram et caelum pontique profunda,"},{"sp":"N","t":"solis lunai cursus, ex ordine ponam."},{"sp":"N","t":"nam certe neque consilio primordia rerum"},{"sp":"N","t":"ordine se suo quaeque sagaci mente locarunt","st":"5.420"},{"sp":"N","t":"nec quos quaeque darent motus pepigere profecto;"},{"sp":"N","t":"sed quia multa modis multis primordia rerum"},{"sp":"N","t":"ex infinito iam tempore percita plagis"},{"sp":"N","t":"ponderibusque suis consuerunt concita ferri"},{"sp":"N","t":"omnimodisque coire atque omnia pertemptare,","st":"5.425"},{"sp":"N","t":"quae cumque inter se possent congressa creare,"},{"sp":"N","t":"propterea fit uti magnum volgata per aevom"},{"sp":"N","t":"omnigenus coetus et motus experiundo"},{"sp":"N","t":"tandem conveniant ea quae coniecta repente"},{"sp":"N","t":"magnarum rerum fiunt exordia saepe,","st":"5.430"},{"sp":"N","t":"terrai maris et caeli generisque animantum."},{"sp":"N","t":"Hic neque tum solis rota cerni lumine largo"},{"sp":"N","t":"altivolans poterat nec magni sidera mundi"},{"sp":"N","t":"nec mare nec caelum nec denique terra neque aer"},{"sp":"N","t":"nec similis nostris rebus res ulla videri,","st":"5.435"},{"sp":"N","t":"sed nova tempestas quaedam molesque coorta."},{"sp":"N","t":"diffugere inde loci partes coepere paresque"},{"sp":"N","t":"cum paribus iungi res et discludere mundum"},{"sp":"N","t":"membraque dividere et magnas disponere partes"},{"sp":"N","t":"omnigenis e principiis, discordia quorum","st":"5.440"},{"sp":"N","t":"intervalla vias conexus pondera plagas"},{"sp":"N","t":"concursus motus turbabat proelia miscens"},{"sp":"N","t":"propter dissimilis formas variasque figuras,"},{"sp":"N","t":"quod non omnia sic poterant coniuncta manere"},{"sp":"N","t":"nec motus inter sese dare convenientis,","st":"5.445"},{"sp":"N","t":"hoc est, a terris altum secernere caelum,"},{"sp":"N","t":"et sorsum mare, uti secreto umore pateret,"},{"sp":"N","t":"seorsus item puri secretique aetheris ignes."},{"sp":"N","t":"Quippe etenim primum terrai corpora quaeque,"},{"sp":"N","t":"propterea quod erant gravia et perplexa, coibant","st":"5.450"},{"sp":"N","t":"in medio atque imas capiebant omnia sedes;"},{"sp":"N","t":"quae quanto magis inter se perplexa coibant,"},{"sp":"N","t":"tam magis expressere ea quae mare sidera solem"},{"sp":"N","t":"lunamque efficerent et magni moenia mundi;"},{"sp":"N","t":"omnia enim magis haec e levibus atque rutundis","st":"5.455"},{"sp":"N","t":"seminibus multoque minoribus sunt elementis"},{"sp":"N","t":"quam tellus. ideo per rara foramina terrae"},{"sp":"N","t":"partibus erumpens primus se sustulit aether"},{"sp":"N","t":"ignifer et multos secum levis abstulit ignis,"},{"sp":"N","t":"non alia longe ratione ac saepe videmus,","st":"5.460"},{"sp":"N","t":"aurea cum primum gemmantis rore per herbas"},{"sp":"N","t":"matutina rubent radiati lumina solis"},{"sp":"N","t":"exhalantque lacus nebulam fluviique perennes"},{"sp":"N","t":"ipsaque ut inter dum tellus fumare videtur;"},{"sp":"N","t":"omnia quae sursum cum conciliantur, in alto","st":"5.465"},{"sp":"N","t":"corpore concreto subtexunt nubila caelum."},{"sp":"N","t":"sic igitur tum se levis ac diffusilis aether"},{"sp":"N","t":"corpore concreto circum datus undique saepsit"},{"sp":"N","t":"et late diffusus in omnis undique partis"},{"sp":"N","t":"omnia sic avido complexu cetera saepsit.","st":"5.470"},{"sp":"N","t":"hunc exordia sunt solis lunaeque secuta,"},{"sp":"N","t":"interutrasque globi quorum vertuntur in auris;"},{"sp":"N","t":"quae neque terra sibi adscivit nec maximus aether,"},{"sp":"N","t":"quod neque tam fuerunt gravia ut depressa sederent,"},{"sp":"N","t":"nec levia ut possent per summas labier oras,","st":"5.475"},{"sp":"N","t":"et tamen interutrasque ita sunt, ut corpora viva"},{"sp":"N","t":"versent et partes ut mundi totius extent;"},{"sp":"N","t":"quod genus in nobis quaedam licet in statione"},{"sp":"N","t":"membra manere, tamen cum sint ea quae moveantur."},{"sp":"N","t":"his igitur rebus retractis terra repente,","st":"5.480"},{"sp":"N","t":"maxuma qua nunc se ponti plaga caerula tendit,"},{"sp":"N","t":"succidit et salso suffudit gurgite fossas."},{"sp":"N","t":"inque dies quanto circum magis aetheris aestus"},{"sp":"N","t":"et radii solis cogebant undique terram"},{"sp":"N","t":"verberibus crebris extrema ad limina fartam","st":"5.485"},{"sp":"N","t":"in medio ut propulsa suo condensa coiret,"},{"sp":"N","t":"tam magis expressus salsus de corpore sudor"},{"sp":"N","t":"augebat mare manando camposque natantis,"},{"sp":"N","t":"et tanto magis illa foras elapsa volabant"},{"sp":"N","t":"corpora multa vaporis et aeris altaque caeli","st":"5.490"},{"sp":"N","t":"densabant procul a terris fulgentia templa."},{"sp":"N","t":"sidebant campi, crescebant montibus altis"},{"sp":"N","t":"ascensus; neque enim poterant subsidere saxa"},{"sp":"N","t":"nec pariter tantundem omnes succumbere partis."},{"sp":"N","t":"Sic igitur terrae concreto corpore pondus","st":"5.495"},{"sp":"N","t":"constitit atque omnis mundi quasi limus in imum"},{"sp":"N","t":"confluxit gravis et subsedit funditus ut faex;"},{"sp":"N","t":"inde mare, inde aer, inde aether ignifer ipse"},{"sp":"N","t":"corporibus liquidis sunt omnia pura relicta"},{"sp":"N","t":"et leviora aliis alia, et liquidissimus aether","st":"5.500"},{"sp":"N","t":"atque levissimus aerias super influit auras"},{"sp":"N","t":"nec liquidum corpus turbantibus aeris auris"},{"sp":"N","t":"commiscet; sinit haec violentis omnia verti"},{"sp":"N","t":"turbinibus, sinit incertis turbare procellis,"},{"sp":"N","t":"ipse suos ignis certo fert impete labens.","st":"5.505"},{"sp":"N","t":"nam modice fluere atque uno posse aethera nisu"},{"sp":"N","t":"significat Pontos, mare certo quod fluit aestu"},{"sp":"N","t":"unum labendi conservans usque tenorem."},{"sp":"N","t":"Motibus astrorum nunc quae sit causa canamus."},{"sp":"N","t":"principio magnus caeli si vortitur orbis,","st":"5.510"},{"sp":"N","t":"ex utraque polum parti premere aera nobis"},{"sp":"N","t":"dicendum est extraque tenere et claudere utrimque;"},{"sp":"N","t":"inde alium supra fluere atque intendere eodem"},{"sp":"N","t":"quo volvenda micant aeterni sidera mundi;"},{"sp":"N","t":"aut alium supter, contra qui subvehat orbem,","st":"5.515"},{"sp":"N","t":"ut fluvios versare rotas atque austra videmus."},{"sp":"N","t":"est etiam quoque uti possit caelum omne manere"},{"sp":"N","t":"in statione, tamen cum lucida signa ferantur,"},{"sp":"N","t":"sive quod inclusi rapidi sunt aetheris aestus"},{"sp":"N","t":"quaerentesque viam circum versantur et ignes","st":"5.520"},{"sp":"N","t":"passim per caeli volvunt summania templa,"},{"sp":"N","t":"sive aliunde fluens alicunde extrinsecus aer"},{"sp":"N","t":"versat agens ignis, sive ipsi serpere possunt,"},{"sp":"N","t":"quo cuiusque cibus vocat atque invitat euntis,"},{"sp":"N","t":"flammea per caelum pascentis corpora passim.","st":"5.525"},{"sp":"N","t":"nam quid in hoc mundo sit eorum ponere certum"},{"sp":"N","t":"difficilest; sed quid possit fiatque per omne"},{"sp":"N","t":"in variis mundis varia ratione creatis,"},{"sp":"N","t":"id doceo plurisque sequor disponere causas,"},{"sp":"N","t":"motibus astrorum quae possint esse per omne;","st":"5.530"},{"sp":"N","t":"e quibus una tamen sit et haec quoque causa necessest,"},{"sp":"N","t":"quae vegeat motum signis; sed quae sit earum"},{"sp":"N","t":"praecipere haud quaquamst pedetemptim progredientis."},{"sp":"N","t":"Terraque ut in media mundi regione quiescat,"},{"sp":"N","t":"evanescere paulatim et decrescere pondus","st":"5.535"},{"sp":"N","t":"convenit atque aliam naturam supter habere"},{"sp":"N","t":"ex ineunte aevo coniunctam atque uniter aptam"},{"sp":"N","t":"partibus aeriis mundi, quibus insita vivit."},{"sp":"N","t":"propterea non est oneri neque deprimit auras,"},{"sp":"N","t":"ut sua cuique homini nullo sunt pondere membra","st":"5.540"},{"sp":"N","t":"nec caput est oneri collo nec denique totum"},{"sp":"N","t":"corporis in pedibus pondus sentimus inesse;"},{"sp":"N","t":"at quae cumque foris veniunt inpostaque nobis"},{"sp":"N","t":"pondera sunt laedunt, permulto saepe minora."},{"sp":"N","t":"usque adeo magni refert quid quaeque queat res.","st":"5.545"},{"sp":"N","t":"sic igitur tellus non est aliena repente"},{"sp":"N","t":"allata atque auris aliunde obiecta alienis,"},{"sp":"N","t":"sed pariter prima concepta ab origine mundi"},{"sp":"N","t":"certaque pars eius, quasi nobis membra videntur."},{"sp":"N","t":"Praeterea grandi tonitru concussa repente","st":"5.550"},{"sp":"N","t":"terra supra quae se sunt concutit omnia motu;"},{"sp":"N","t":"quod facere haut ulla posset ratione, nisi esset"},{"sp":"N","t":"partibus aeriis mundi caeloque revincta;"},{"sp":"N","t":"nam communibus inter se radicibus haerent"},{"sp":"N","t":"ex ineunte aevo coniuncta atque uniter aucta.","st":"5.555"},{"sp":"N","t":"Nonne vides etiam quam magno pondere nobis"},{"sp":"N","t":"sustineat corpus tenuissima vis animai,"},{"sp":"N","t":"propterea quia tam coniuncta atque uniter apta est?"},{"sp":"N","t":"Denique iam saltu pernici tollere corpus"},{"sp":"N","t":"quid potis est nisi vis animae, quae membra gubernat?","st":"5.560"},{"sp":"N","t":"iamne vides quantum tenuis natura valere"},{"sp":"N","t":"possit, ubi est coniuncta gravi cum corpore, ut aer"},{"sp":"N","t":"coniunctus terris et nobis est animi vis?"},{"sp":"N","t":"Nec nimio solis maior rota nec minor ardor"},{"sp":"N","t":"esse potest, nostris quam sensibus esse videtur.","st":"5.565"},{"sp":"N","t":"nam quibus e spatiis cumque ignes lumina possunt"},{"sp":"N","t":"adiicere et calidum membris adflare vaporem,"},{"sp":"N","t":"nil magnis intervallis de corpore libant"},{"sp":"N","t":"flammarum, nihil ad speciem est contractior ignis."},{"sp":"N","t":"proinde, calor quoniam solis lumenque profusum","st":"5.570"},{"sp":"N","t":"perveniunt nostros ad sensus et loca fulgent,"},{"sp":"N","t":"forma quoque hinc solis debet filumque videri,"},{"sp":"N","t":"nil adeo ut possis plus aut minus addere vere."},{"sp":"N","t":"perveniunt nostros ad sensus et loca fulgent"},{"sp":"N","t":"lunaque sive notho fertur loca lumine lustrans,","st":"5.575"},{"sp":"N","t":"sive suam proprio iactat de corpore lucem,"},{"sp":"N","t":"quidquid id est, nihilo fertur maiore figura"},{"sp":"N","t":"quam, nostris oculis qua cernimus, esse videtur."},{"sp":"N","t":"nam prius omnia, quae longe semota tuemur"},{"sp":"N","t":"aera per multum, specie confusa videntur","st":"5.580"},{"sp":"N","t":"quam minui filum. quapropter luna necesse est,"},{"sp":"N","t":"quandoquidem claram speciem certamque figuram"},{"sp":"N","t":"praebet, ut est oris extremis cumque notata,"},{"sp":"N","t":"quanta quoquest, tanta hinc nobis videatur in alto."},{"sp":"N","t":"postremo quos cumque vides hinc aetheris ignes,","st":"5.585"},{"sp":"N","t":"scire licet perquam pauxillo posse minores"},{"sp":"N","t":"esse vel exigua maioris parte brevique."},{"sp":"N","t":"quandoquidem quos cumque in terris cernimus ignes,"},{"sp":"N","t":"dum tremor et clarus dum cernitur ardor eorum,"},{"sp":"N","t":"perparvom quiddam inter dum mutare videntur","st":"5.590"},{"sp":"N","t":"alteram utram in partem filum, quo longius absunt."},{"sp":"N","t":"Illud item non est mirandum, qua ratione"},{"sp":"N","t":"tantulus ille queat tantum sol mittere lumen,"},{"sp":"N","t":"quod maria ac terras omnis caelumque rigando"},{"sp":"N","t":"compleat et calido perfundat cuncta vapore.","st":"5.595"},{"sp":"N","t":"quanta quoquest tanta hinc nobis videatur in alto"},{"sp":"N","t":"nam licet hinc mundi patefactum totius unum"},{"sp":"N","t":"largifluum fontem scatere atque erumpere lumen,"},{"sp":"N","t":"ex omni mundo quia sic elementa vaporis"},{"sp":"N","t":"undique conveniunt et sic coniectus eorum","st":"5.600"},{"sp":"N","t":"confluit, ex uno capite hic ut profluat ardor."},{"sp":"N","t":"nonne vides etiam quam late parvus aquai"},{"sp":"N","t":"prata riget fons inter dum campisque redundet?"},{"sp":"N","t":"est etiam quoque uti non magno solis ab igni"},{"sp":"N","t":"aera percipiat calidis fervoribus ardor,","st":"5.605"},{"sp":"N","t":"opportunus ita est si forte et idoneus aer,"},{"sp":"N","t":"ut queat accendi parvis ardoribus ictus;"},{"sp":"N","t":"quod genus inter dum segetes stipulamque videmus"},{"sp":"N","t":"accidere ex una scintilla incendia passim."},{"sp":"N","t":"forsitan et rosea sol alte lampade lucens","st":"5.610"},{"sp":"N","t":"possideat multum caecis fervoribus ignem"},{"sp":"N","t":"circum se, nullo qui sit fulgore notatus,"},{"sp":"N","t":"aestifer ut tantum radiorum exaugeat ictum."},{"sp":"N","t":"Nec ratio solis simplex et recta patescit,"},{"sp":"N","t":"quo pacto aestivis e partibus aegocerotis","st":"5.615"},{"sp":"N","t":"brumalis adeat flexus atque inde revertens"},{"sp":"N","t":"canceris ut vertat metas ad solstitialis,"},{"sp":"N","t":"lunaque mensibus id spatium videatur obire,"},{"sp":"N","t":"annua sol in quo consumit tempora cursu."},{"sp":"N","t":"non, inquam, simplex his rebus reddita causast.","st":"5.620"},{"sp":"N","t":"nam fieri vel cum primis id posse videtur,"},{"sp":"N","t":"Democriti quod sancta viri sententia ponit,"},{"sp":"N","t":"quanto quaeque magis sint terram sidera propter,"},{"sp":"N","t":"tanto posse minus cum caeli turbine ferri;"},{"sp":"N","t":"evanescere enim rapidas illius et acris","st":"5.625"},{"sp":"N","t":"imminui supter viris, ideoque relinqui"},{"sp":"N","t":"paulatim solem cum posterioribus signis,"},{"sp":"N","t":"inferior multo quod sit quam fervida signa."},{"sp":"N","t":"et magis hoc lunam: quanto demissior eius"},{"sp":"N","t":"cursus abest procul a caelo terrisque propinquat,","st":"5.630"},{"sp":"N","t":"tanto posse minus cum signis tendere cursum."},{"sp":"N","t":"flaccidiore etiam quanto iam turbine fertur"},{"sp":"N","t":"inferior quam sol, tanto magis omnia signa"},{"sp":"N","t":"hanc adipiscuntur circum praeterque feruntur."},{"sp":"N","t":"propterea fit ut haec ad signum quodque reverti","st":"5.635"},{"sp":"N","t":"mobilius videatur, ad hanc quia signa revisunt."},{"sp":"N","t":"fit quoque ut e mundi transversis partibus aer"},{"sp":"N","t":"alternis certo fluere alter tempore possit,"},{"sp":"N","t":"qui queat aestivis solem detrudere signis"},{"sp":"N","t":"brumalis usque ad flexus gelidumque rigorem,","st":"5.640"},{"sp":"N","t":"et qui reiciat gelidis a frigoris umbris"},{"sp":"N","t":"aestiferas usque in partis et fervida signa."},{"sp":"N","t":"et ratione pari lunam stellasque putandumst,"},{"sp":"N","t":"quae volvunt magnos in magnis orbibus annos,"},{"sp":"N","t":"aeribus posse alternis e partibus ire.","st":"5.645"},{"sp":"N","t":"nonne vides etiam diversis nubila ventis"},{"sp":"N","t":"diversas ire in partis inferna supernis?"},{"sp":"N","t":"qui minus illa queant per magnos aetheris orbis"},{"sp":"N","t":"aestibus inter se diversis sidera ferri?"},{"sp":"N","t":"At nox obruit ingenti caligine terras,","st":"5.650"},{"sp":"N","t":"aut ubi de longo cursu sol ultima caeli"},{"sp":"N","t":"impulit atque suos efflavit languidus ignis"},{"sp":"N","t":"concussos itere et labefactos aere multo,"},{"sp":"N","t":"aut quia sub terras cursum convortere cogit"},{"sp":"N","t":"vis eadem, supra quae terras pertulit orbem.","st":"5.655"},{"sp":"N","t":"Tempore item certo roseam Matuta per oras"},{"sp":"N","t":"aetheris auroram differt et lumina pandit,"},{"sp":"N","t":"aut quia sol idem, sub terras ille revertens,"},{"sp":"N","t":"anticipat caelum radiis accendere temptans,"},{"sp":"N","t":"aut quia conveniunt ignes et semina multa","st":"5.660"},{"sp":"N","t":"confluere ardoris consuerunt tempore certo,"},{"sp":"N","t":"quae faciunt solis nova semper lumina gigni;"},{"sp":"N","t":"quod genus Idaeis fama est e montibus altis"},{"sp":"N","t":"dispersos ignis orienti lumine cerni,"},{"sp":"N","t":"inde coire globum quasi in unum et conficere orbem.","st":"5.665"},{"sp":"N","t":"nec tamen illud in his rebus mirabile debet"},{"sp":"N","t":"esse, quod haec ignis tam certo tempore possint"},{"sp":"N","t":"semina confluere et solis reparare nitorem."},{"sp":"N","t":"multa videmus enim, certo quae tempore fiunt"},{"sp":"N","t":"omnibus in rebus. florescunt tempore certo","st":"5.670"},{"sp":"N","t":"arbusta et certo dimittunt tempore florem."},{"sp":"N","t":"nec minus in certo dentes cadere imperat aetas"},{"sp":"N","t":"tempore et inpubem molli pubescere veste"},{"sp":"N","t":"et pariter mollem malis demittere barbam."},{"sp":"N","t":"fulmina postremo nix imbres nubila venti","st":"5.675"},{"sp":"N","t":"non nimis incertis fiunt in partibus anni."},{"sp":"N","t":"namque ubi sic fuerunt causarum exordia prima"},{"sp":"N","t":"atque ita res mundi cecidere ab origine prima,"},{"sp":"N","t":"conseque quoque iam redeunt ex ordine certo."},{"sp":"N","t":"Crescere itemque dies licet et tabescere noctes,","st":"5.680"},{"sp":"N","t":"et minui luces, cum sumant augmina noctis,"},{"sp":"N","t":"aut quia sol idem sub terras atque superne"},{"sp":"N","t":"imparibus currens amfractibus aetheris oras"},{"sp":"N","t":"partit et in partis non aequas dividit orbem,"},{"sp":"N","t":"et quod ab alterutra detraxit parte, reponit","st":"5.685"},{"sp":"N","t":"eius in adversa tanto plus parte relatus,"},{"sp":"N","t":"donec ad id signum caeli pervenit, ubi anni"},{"sp":"N","t":"nodus nocturnas exaequat lucibus umbras;"},{"sp":"N","t":"nam medio cursu flatus aquilonis et austri"},{"sp":"N","t":"distinet aequato caelum discrimine metas","st":"5.690"},{"sp":"N","t":"propter signiferi posituram totius orbis,"},{"sp":"N","t":"annua sol in quo concludit tempora serpens,"},{"sp":"N","t":"obliquo terras et caelum lumine lustrans,"},{"sp":"N","t":"ut ratio declarat eorum qui loca caeli"},{"sp":"N","t":"omnia dispositis signis ornata notarunt.","st":"5.695"},{"sp":"N","t":"aut quia crassior est certis in partibus aer,"},{"sp":"N","t":"sub terris ideo tremulum iubar haesitat ignis"},{"sp":"N","t":"nec penetrare potest facile atque emergere ad ortus;"},{"sp":"N","t":"propterea noctes hiberno tempore longae"},{"sp":"N","t":"cessant, dum veniat radiatum insigne diei.","st":"5.700"},{"sp":"N","t":"aut etiam, quia sic alternis partibus anni"},{"sp":"N","t":"tardius et citius consuerunt confluere ignes,"},{"sp":"N","t":"qui faciunt solem certa de surgere parte,"},{"sp":"N","t":"propterea fit uti videantur dicere verum."},{"sp":"N","t":"Luna potest solis radiis percussa nitere","st":"5.705"},{"sp":"N","t":"inque dies magis id lumen convertere nobis"},{"sp":"N","t":"ad speciem, quantum solis secedit ab orbi,"},{"sp":"N","t":"donique eum contra pleno bene lumine fulsit"},{"sp":"N","t":"atque oriens obitus eius super edita vidit;"},{"sp":"N","t":"inde minutatim retro quasi condere lumen","st":"5.710"},{"sp":"N","t":"debet item, quanto propius iam solis ad ignem"},{"sp":"N","t":"labitur ex alia signorum parte per orbem;"},{"sp":"N","t":"ut faciunt, lunam qui fingunt esse pilai"},{"sp":"N","t":"consimilem cursusque viam sub sole tenere."},{"sp":"N","t":"est etiam quare proprio cum lumine possit","st":"5.715"},{"sp":"N","t":"volvier et varias splendoris reddere formas;"},{"sp":"N","t":"corpus enim licet esse aliud, quod fertur et una"},{"sp":"N","t":"labitur omnimodis occursans officiensque,"},{"sp":"N","t":"nec potis est cerni, quia cassum lumine fertur."},{"sp":"N","t":"versarique potest, globus ut, si forte, pilai","st":"5.720"},{"sp":"N","t":"dimidia ex parti candenti lumine tinctus,"},{"sp":"N","t":"versandoque globum variantis edere formas,"},{"sp":"N","t":"donique eam partem, quae cumque est ignibus aucta,"},{"sp":"N","t":"ad speciem vertit nobis oculosque patentis;"},{"sp":"N","t":"inde minutatim retro contorquet et aufert","st":"5.725"},{"sp":"N","t":"luciferam partem glomeraminis atque pilai;"},{"sp":"N","t":"ut Babylonica Chaldaeum doctrina refutans"},{"sp":"N","t":"astrologorum artem contra convincere tendit,"},{"sp":"N","t":"proinde quasi id fieri nequeat quod pugnat uterque"},{"sp":"N","t":"aut minus hoc illo sit cur amplectier ausis.","st":"5.730"},{"sp":"N","t":"denique cur nequeat semper nova luna creari"},{"sp":"N","t":"ordine formarum certo certisque figuris"},{"sp":"N","t":"inque dies privos aborisci quaeque creata"},{"sp":"N","t":"atque alia illius reparari in parte locoque,"},{"sp":"N","t":"difficilest ratione docere et vincere verbis,","st":"5.735"},{"sp":"N","t":"ordine cum videas tam certo multa creari."},{"sp":"N","t":"it Ver et Venus et Veneris praenuntius ante"},{"sp":"N","t":"pennatus graditur, Zephyri vestigia propter"},{"sp":"N","t":"Flora quibus mater praespargens ante viai"},{"sp":"N","t":"cuncta coloribus egregiis et odoribus opplet.","st":"5.740"},{"sp":"N","t":"inde loci sequitur Calor aridus et comes una"},{"sp":"N","t":"pulverulenta Ceres et etesia flabra aquilonum."},{"sp":"N","t":"inde Autumnus adit, graditur simul Euhius Euan."},{"sp":"N","t":"inde aliae tempestates ventique secuntur,"},{"sp":"N","t":"altitonans Volturnus et Auster fulmine pollens.","st":"5.745"},{"sp":"N","t":"tandem Bruma nives adfert pigrumque rigorem"},{"sp":"N","t":"reddit. Hiemps sequitur crepitans hanc dentibus algu."},{"sp":"N","t":"quo minus est mirum, si certo tempore luna"},{"sp":"N","t":"gignitur et certo deletur tempore rusus,"},{"sp":"N","t":"cum fieri possint tam certo tempore multa.","st":"5.750"},{"sp":"N","t":"Solis item quoque defectus lunaeque latebras"},{"sp":"N","t":"pluribus e causis fieri tibi posse putandumst."},{"sp":"N","t":"nam cur luna queat terram secludere solis"},{"sp":"N","t":"lumine et a terris altum caput obstruere ei,"},{"sp":"N","t":"obiciens caecum radiis ardentibus orbem,","st":"5.755"},{"sp":"N","t":"tempore eodem aliut facere id non posse putetur"},{"sp":"N","t":"corpus, quod cassum labatur lumine semper?"},{"sp":"N","t":"solque suos etiam dimittere languidus ignis"},{"sp":"N","t":"tempore cur certo nequeat recreareque lumen,"},{"sp":"N","t":"cum loca praeteriit flammis infesta per auras,","st":"5.760"},{"sp":"N","t":"quae faciunt ignis interstingui atque perire?"},{"sp":"N","t":"et cur terra queat lunam spoliare vicissim"},{"sp":"N","t":"lumine et oppressum solem super ipsa tenere,"},{"sp":"N","t":"menstrua dum rigidas coni perlabitur umbras,"},{"sp":"N","t":"tempore eodem aliud nequeat succurrere lunae","st":"5.765"},{"sp":"N","t":"corpus vel supra solis perlabier orbem,"},{"sp":"N","t":"quod radios inter rumpat lumenque profusum?"},{"sp":"N","t":"et tamen ipsa suo si fulget luna nitore,"},{"sp":"N","t":"cur nequeat certa mundi languescere parte,"},{"sp":"N","t":"dum loca luminibus propriis inimica per exit?","st":"5.770"},{"sp":"N","t":"menstrua dum rigidas coni perlabitur umbras."},{"sp":"N","t":"Quod superest, quoniam magni per caerula mundi"},{"sp":"N","t":"qua fieri quicquid posset ratione resolvi,"},{"sp":"N","t":"solis uti varios cursus lunaeque meatus"},{"sp":"N","t":"noscere possemus quae vis et causa cieret,","st":"5.775"},{"sp":"N","t":"quove modo possent offecto lumine obire"},{"sp":"N","t":"et neque opinantis tenebris obducere terras,"},{"sp":"N","t":"cum quasi conivent et aperto lumine rursum"},{"sp":"N","t":"omnia convisunt clara loca candida luce,"},{"sp":"N","t":"nunc redeo ad mundi novitatem et mollia terrae","st":"5.780"},{"sp":"N","t":"arva, novo fetu quid primum in luminis oras"},{"sp":"N","t":"tollere et incertis crerint committere ventis."},{"sp":"N","t":"Principio genus herbarum viridemque nitorem"},{"sp":"N","t":"terra dedit circum collis camposque per omnis,"},{"sp":"N","t":"florida fulserunt viridanti prata colore,","st":"5.785"},{"sp":"N","t":"arboribusque datumst variis exinde per auras"},{"sp":"N","t":"crescendi magnum inmissis certamen habenis."},{"sp":"N","t":"ut pluma atque pili primum saetaeque creantur"},{"sp":"N","t":"quadripedum membris et corpore pennipotentum,"},{"sp":"N","t":"sic nova tum tellus herbas virgultaque primum","st":"5.790"},{"sp":"N","t":"sustulit, inde loci mortalia saecla creavit"},{"sp":"N","t":"multa modis multis varia ratione coorta."},{"sp":"N","t":"nam neque de caelo cecidisse animalia possunt,"},{"sp":"N","t":"nec terrestria de salsis exisse lacunis."},{"sp":"N","t":"linquitur ut merito maternum nomen adepta","st":"5.795"},{"sp":"N","t":"terra sit, e terra quoniam sunt cuncta creata."},{"sp":"N","t":"multaque nunc etiam existunt animalia terris"},{"sp":"N","t":"imbribus et calido solis concreta vapore;"},{"sp":"N","t":"quo minus est mirum, si tum sunt plura coorta"},{"sp":"N","t":"et maiora, nova tellure atque aethere adulta.","st":"5.800"},{"sp":"N","t":"principio genus alituum variaeque volucres"},{"sp":"N","t":"ova relinquebant exclusae tempore verno,"},{"sp":"N","t":"folliculos ut nunc teretis aestate cicadae"},{"sp":"N","t":"lincunt sponte sua victum vitamque petentes."},{"sp":"N","t":"tum tibi terra dedit primum mortalia saecla.","st":"5.805"},{"sp":"N","t":"multus enim calor atque umor superabat in arvis."},{"sp":"N","t":"hoc ubi quaeque loci regio opportuna dabatur,"},{"sp":"N","t":"crescebant uteri terram radicibus apti;"},{"sp":"N","t":"quos ubi tempore maturo pate fecerat aetas"},{"sp":"N","t":"infantum, fugiens umorem aurasque petessens,","st":"5.810"},{"sp":"N","t":"convertebat ibi natura foramina terrae"},{"sp":"N","t":"et sucum venis cogebat fundere apertis"},{"sp":"N","t":"consimilem lactis, sicut nunc femina quaeque"},{"sp":"N","t":"cum peperit, dulci repletur lacte, quod omnis"},{"sp":"N","t":"impetus in mammas convertitur ille alimenti.","st":"5.815"},{"sp":"N","t":"terra cibum pueris, vestem vapor, herba cubile"},{"sp":"N","t":"praebebat multa et molli lanugine abundans."},{"sp":"N","t":"at novitas mundi nec frigora dura ciebat"},{"sp":"N","t":"nec nimios aestus nec magnis viribus auras."},{"sp":"N","t":"omnia enim pariter crescunt et robora sumunt.","st":"5.820"},{"sp":"N","t":"Quare etiam atque etiam maternum nomen adepta"},{"sp":"N","t":"terra tenet merito, quoniam genus ipsa creavit"},{"sp":"N","t":"humanum atque animal prope certo tempore fudit"},{"sp":"N","t":"omne quod in magnis bacchatur montibus passim,"},{"sp":"N","t":"aeriasque simul volucres variantibus formis.","st":"5.825"},{"sp":"N","t":"sed quia finem aliquam pariendi debet habere,"},{"sp":"N","t":"destitit, ut mulier spatio defessa vetusto."},{"sp":"N","t":"mutat enim mundi naturam totius aetas"},{"sp":"N","t":"ex alioque alius status excipere omnia debet"},{"sp":"N","t":"nec manet ulla sui similis res: omnia migrant,","st":"5.830"},{"sp":"N","t":"omnia commutat natura et vertere cogit."},{"sp":"N","t":"namque aliud putrescit et aevo debile languet,"},{"sp":"N","t":"porro aliud succrescit et e contemptibus exit."},{"sp":"N","t":"sic igitur mundi naturam totius aetas"},{"sp":"N","t":"mutat, et ex alio terram status excipit alter,","st":"5.835"},{"sp":"N","t":"quod potuit nequeat, possit quod non tulit ante."},{"sp":"N","t":"Multaque tum tellus etiam portenta creare"},{"sp":"N","t":"conatast mira facie membrisque coorta,"},{"sp":"N","t":"androgynem, interutras necutrumque utrimque remotum,"},{"sp":"N","t":"orba pedum partim, manuum viduata vicissim,","st":"5.840"},{"sp":"N","t":"muta sine ore etiam, sine voltu caeca reperta,"},{"sp":"N","t":"vinctaque membrorum per totum corpus adhaesu,"},{"sp":"N","t":"nec facere ut possent quicquam nec cedere quoquam"},{"sp":"N","t":"nec vitare malum nec sumere quod volet usus."},{"sp":"N","t":"cetera de genere hoc monstra ac portenta creabat,","st":"5.845"},{"sp":"N","t":"ne quiquam, quoniam natura absterruit auctum"},{"sp":"N","t":"nec potuere cupitum aetatis tangere florem"},{"sp":"N","t":"nec reperire cibum nec iungi per Veneris res."},{"sp":"N","t":"multa videmus enim rebus concurrere debere,"},{"sp":"N","t":"ut propagando possint procudere saecla;","st":"5.850"},{"sp":"N","t":"pabula primum ut sint, genitalia deinde per artus"},{"sp":"N","t":"semina qua possint membris manare remissis,"},{"sp":"N","t":"feminaque ut maribus coniungi possit, habere,"},{"sp":"N","t":"mutua qui mutent inter se gaudia uterque."},{"sp":"N","t":"Multaque tum interiisse animantum saecla necessest","st":"5.855"},{"sp":"N","t":"nec potuisse propagando procudere prolem."},{"sp":"N","t":"nam quae cumque vides vesci vitalibus auris,"},{"sp":"N","t":"aut dolus aut virtus aut denique mobilitas est"},{"sp":"N","t":"ex ineunte aevo genus id tutaTA reservans."},{"sp":"N","t":"multaque sunt, nobis ex utilitate sua quae","st":"5.860"},{"sp":"N","t":"commendata manent, tutelae tradita nostrae."},{"sp":"N","t":"principio genus acre leonum saevaque saecla"},{"sp":"N","t":"tutatast virtus, volpes dolus et fuga cervos."},{"sp":"N","t":"at levisomna canum fido cum pectore corda,"},{"sp":"N","t":"et genus omne quod est veterino semine partum","st":"5.865"},{"sp":"N","t":"lanigeraeque simul pecudes et bucera saecla"},{"sp":"N","t":"omnia sunt hominum tutelae tradita, Memmi;"},{"sp":"N","t":"nam cupide fugere feras pacemque secuta"},{"sp":"N","t":"sunt et larga suo sine pabula parta labore,"},{"sp":"N","t":"quae damus utilitatis eorum praemia causa.","st":"5.870"},{"sp":"N","t":"at quis nil horum tribuit natura, nec ipsa"},{"sp":"N","t":"sponte sua possent ut vivere nec dare nobis"},{"sp":"N","t":"utilitatem aliquam, quare pateremur eorum"},{"sp":"N","t":"praesidio nostro pasci genus esseque tutum,"},{"sp":"N","t":"scilicet haec aliis praedae lucroque iacebant","st":"5.875"},{"sp":"N","t":"indupedita suis fatalibus omnia vinclis,"},{"sp":"N","t":"donec ad interitum genus id natura redegit."},{"sp":"N","t":"Sed neque Centauri fuerunt nec tempore in ullo"},{"sp":"N","t":"esse queunt duplici natura et corpore bino"},{"sp":"N","t":"ex alienigenis membris compacta, potestas","st":"5.880"},{"sp":"N","t":"hinc illinc partis ut sat par esse potissit."},{"sp":"N","t":"id licet hinc quamvis hebeti cognoscere corde."},{"sp":"N","t":"principio circum tribus actis impiger annis"},{"sp":"N","t":"floret equus, puer haut quaquam; nam saepe etiam nunc"},{"sp":"N","t":"ubera mammarum in somnis lactantia quaeret.","st":"5.885"},{"sp":"N","t":"post ubi equum validae vires aetate senecta"},{"sp":"N","t":"membraque deficiunt fugienti languida vita,"},{"sp":"N","t":"tum demum puerili aevo florenta iuventas"},{"sp":"N","t":"officit et molli vestit lanugine malas;"},{"sp":"N","t":"ne forte ex homine et veterino semine equorum","st":"5.890"},{"sp":"N","t":"confieri credas Centauros posse neque esse,"},{"sp":"N","t":"aut rapidis canibus succinctas semimarinis"},{"sp":"N","t":"corporibus Scyllas et cetera de genere horum,"},{"sp":"N","t":"inter se quorum discordia membra videmus;"},{"sp":"N","t":"quae neque florescunt pariter nec robora sumunt","st":"5.895"},{"sp":"N","t":"corporibus neque proiciunt aetate senecta"},{"sp":"N","t":"nec simili Venere ardescunt nec moribus unis"},{"sp":"N","t":"conveniunt neque sunt eadem iucunda per artus."},{"sp":"N","t":"quippe videre licet pinguescere saepe cicuta"},{"sp":"N","t":"barbigeras pecudes, homini quae est acre venenum.","st":"5.900"},{"sp":"N","t":"flamma quidem vero cum corpora fulva leonum"},{"sp":"N","t":"tam soleat torrere atque urere quam genus omne"},{"sp":"N","t":"visceris in terris quod cumque et sanguinis extet,"},{"sp":"N","t":"qui fieri potuit, triplici cum corpore ut una,"},{"sp":"N","t":"prima leo, postrema draco, media ipsa, Chimaera","st":"5.905"},{"sp":"N","t":"ore foras acrem flaret de corpore flammam?"},{"sp":"N","t":"quare etiam tellure nova caeloque recenti"},{"sp":"N","t":"talia qui fingit potuisse animalia gigni,"},{"sp":"N","t":"nixus in hoc uno novitatis nomine inani,"},{"sp":"N","t":"multa licet simili ratione effutiat ore,","st":"5.910"},{"sp":"N","t":"aurea tum dicat per terras flumina vulgo"},{"sp":"N","t":"fluxisse et gemmis florere arbusta suesse"},{"sp":"N","t":"aut hominem tanto membrorum esse impete natum,"},{"sp":"N","t":"trans maria alta pedum nisus ut ponere posset"},{"sp":"N","t":"et manibus totum circum se vertere caelum.","st":"5.915"},{"sp":"N","t":"nam quod multa fuere in terris semina rerum,"},{"sp":"N","t":"tempore quo primum tellus animalia fudit,"},{"sp":"N","t":"nil tamen est signi mixtas potuisse creari"},{"sp":"N","t":"inter se pecudes compactaque membra animantum,"},{"sp":"N","t":"propterea quia quae de terris nunc quoque abundant","st":"5.920"},{"sp":"N","t":"herbarum genera ac fruges arbustaque laeta"},{"sp":"N","t":"non tamen inter se possunt complexa creari,"},{"sp":"N","t":"sed res quaeque suo ritu procedit et omnes"},{"sp":"N","t":"foedere naturae certo discrimina servant."},{"sp":"N","t":"Et genus humanum multo fuit illud in arvis","st":"5.925"},{"sp":"N","t":"durius, ut decuit, tellus quod dura creasset,"},{"sp":"N","t":"et maioribus et solidis magis ossibus intus"},{"sp":"N","t":"fundatum, validis aptum per viscera nervis,"},{"sp":"N","t":"nec facile ex aestu nec frigore quod caperetur"},{"sp":"N","t":"nec novitate cibi nec labi corporis ulla.","st":"5.930"},{"sp":"N","t":"multaque per caelum solis volventia lustra"},{"sp":"N","t":"volgivago vitam tractabant more ferarum."},{"sp":"N","t":"nec robustus erat curvi moderator aratri"},{"sp":"N","t":"quisquam, nec scibat ferro molirier arva"},{"sp":"N","t":"nec nova defodere in terram virgulta neque altis","st":"5.935"},{"sp":"N","t":"arboribus veteres decidere falcibus ramos."},{"sp":"N","t":"quod sol atque imbres dederant, quod terra crearat"},{"sp":"N","t":"sponte sua, satis id placabat pectora donum."},{"sp":"N","t":"glandiferas inter curabant corpora quercus"},{"sp":"N","t":"plerumque; et quae nunc hiberno tempore cernis","st":"5.940"},{"sp":"N","t":"arbita puniceo fieri matura colore,"},{"sp":"N","t":"plurima tum tellus etiam maiora ferebat."},{"sp":"N","t":"multaque praeterea novitas tum florida mundi"},{"sp":"N","t":"pabula dura tulit, miseris mortalibus ampla."},{"sp":"N","t":"at sedare sitim fluvii fontesque vocabant,","st":"5.945"},{"sp":"N","t":"ut nunc montibus e magnis decursus aquai"},{"sp":"N","t":"claricitat late sitientia saecla ferarum."},{"sp":"N","t":"denique nota vagis silvestria templa tenebant"},{"sp":"N","t":"nympharum, quibus e scibant umore fluenta"},{"sp":"N","t":"lubrica proluvie larga lavere umida saxa,","st":"5.950"},{"sp":"N","t":"umida saxa, super viridi stillantia musco,"},{"sp":"N","t":"et partim plano scatere atque erumpere campo."},{"sp":"N","t":"necdum res igni scibant tractare neque uti"},{"sp":"N","t":"pellibus et spoliis corpus vestire ferarum,"},{"sp":"N","t":"sed nemora atque cavos montis silvasque colebant","st":"5.955"},{"sp":"N","t":"et frutices inter condebant squalida membra"},{"sp":"N","t":"verbera ventorum vitare imbrisque coacti."},{"sp":"N","t":"nec commune bonum poterant spectare neque ullis"},{"sp":"N","t":"moribus inter se scibant nec legibus uti."},{"sp":"N","t":"quod cuique obtulerat praedae fortuna, ferebat","st":"5.960"},{"sp":"N","t":"sponte sua sibi quisque valere et vivere doctus."},{"sp":"N","t":"et Venus in silvis iungebat corpora amantum;"},{"sp":"N","t":"conciliabat enim vel mutua quamque cupido"},{"sp":"N","t":"vel violenta viri vis atque inpensa libido"},{"sp":"N","t":"vel pretium, glandes atque arbita vel pira lecta.","st":"5.965"},{"sp":"N","t":"et manuum mira freti virtute pedumque"},{"sp":"N","t":"consectabantur silvestria saecla ferarum"},{"sp":"N","t":"missilibus saxis et magno pondere clavae."},{"sp":"N","t":"multaque vincebant, vitabant pauca latebris;"},{"sp":"N","t":"saetigerisque pares subus silvestria membra","st":"5.970"},{"sp":"N","t":"nuda dabant terrae nocturno tempore capti,"},{"sp":"N","t":"circum se foliis ac frondibus involventes."},{"sp":"N","t":"nec plangore diem magno solemque per agros"},{"sp":"N","t":"quaerebant pavidi palantes noctis in umbris,"},{"sp":"N","t":"sed taciti respectabant somnoque sepulti,","st":"5.975"},{"sp":"N","t":"dum rosea face sol inferret lumina caelo."},{"sp":"N","t":"a parvis quod enim consuerant cernere semper"},{"sp":"N","t":"alterno tenebras et lucem tempore gigni,"},{"sp":"N","t":"non erat ut fieri posset mirarier umquam"},{"sp":"N","t":"nec diffidere, ne terras aeterna teneret","st":"5.980"},{"sp":"N","t":"nox in perpetuum detracto lumine solis."},{"sp":"N","t":"sed magis illud erat curae, quod saecla ferarum"},{"sp":"N","t":"infestam miseris faciebant saepe quietem."},{"sp":"N","t":"eiectique domo fugiebant saxea tecta"},{"sp":"N","t":"spumigeri suis adventu validique leonis","st":"5.985"},{"sp":"N","t":"atque intempesta cedebant nocte paventes"},{"sp":"N","t":"hospitibus saevis instrata cubilia fronde."},{"sp":"N","t":"Nec nimio tum plus quam nunc mortalia saecla"},{"sp":"N","t":"dulcia linquebant lamentis lumina vitae."},{"sp":"N","t":"unus enim tum quisque magis deprensus eorum","st":"5.990"},{"sp":"N","t":"pabula viva feris praebebat, dentibus haustus,"},{"sp":"N","t":"et nemora ac montis gemitu silvasque replebat"},{"sp":"N","t":"viva videns vivo sepeliri viscera busto."},{"sp":"N","t":"at quos effugium servarat corpore adeso,"},{"sp":"N","t":"posterius tremulas super ulcera tetra tenentes","st":"5.995"},{"sp":"N","t":"palmas horriferis accibant vocibus Orcum,"},{"sp":"N","t":"donique eos vita privarant vermina saeva"},{"sp":"N","t":"expertis opis, ignaros quid volnera vellent."},{"sp":"N","t":"at non multa virum sub signis milia ducta"},{"sp":"N","t":"una dies dabat exitio nec turbida ponti","st":"5.1000"},{"sp":"N","t":"aequora lidebant navis ad saxa virosque."},{"sp":"N","t":"nam temere in cassum frustra mare saepe coortum"},{"sp":"N","t":"saevibat leviterque minas ponebat inanis,"},{"sp":"N","t":"nec poterat quemquam placidi pellacia ponti"},{"sp":"N","t":"subdola pellicere in fraudem ridentibus undis.","st":"5.1005"},{"sp":"N","t":"improba navigii ratio tum caeca iacebat."},{"sp":"N","t":"tum penuria deinde cibi languentia leto"},{"sp":"N","t":"membra dabat, contra nunc rerum copia mersat."},{"sp":"N","t":"illi inprudentes ipsi sibi saepe venenum"},{"sp":"N","t":"vergebant, nunc dant aliis sollertius ipsi.","st":"5.1010"},{"sp":"N","t":"Inde casas postquam ac pellis ignemque pararunt"},{"sp":"N","t":"et mulier coniuncta viro concessit in unum"},{"sp":"N","t":"cognita sunt, prolemque ex se videre creatam,"},{"sp":"N","t":"tum genus humanum primum mollescere coepit."},{"sp":"N","t":"ignis enim curavit, ut alsia corpora frigus","st":"5.1015"},{"sp":"N","t":"non ita iam possent caeli sub tegmine ferre,"},{"sp":"N","t":"et Venus inminuit viris puerique parentum"},{"sp":"N","t":"blanditiis facile ingenium fregere superbum."},{"sp":"N","t":"tunc et amicitiem coeperunt iungere aventes"},{"sp":"N","t":"finitimi inter se nec laedere nec violari,","st":"5.1020"},{"sp":"N","t":"et pueros commendarunt muliebreque saeclum,"},{"sp":"N","t":"vocibus et gestu cum balbe significarent"},{"sp":"N","t":"imbecillorum esse aequum misererier omnis."},{"sp":"N","t":"nec tamen omnimodis poterat concordia gigni,"},{"sp":"N","t":"sed bona magnaque pars servabat foedera caste;","st":"5.1025"},{"sp":"N","t":"aut genus humanum iam tum foret omne peremptum"},{"sp":"N","t":"nec potuisset adhuc perducere saecla propago."},{"sp":"N","t":"At varios linguae sonitus natura subegit"},{"sp":"N","t":"mittere et utilitas expressit nomina rerum,"},{"sp":"N","t":"non alia longe ratione atque ipsa videtur","st":"5.1030"},{"sp":"N","t":"protrahere ad gestum pueros infantia linguae,"},{"sp":"N","t":"cum facit ut digito quae sint praesentia monstrent."},{"sp":"N","t":"sentit enim vim quisque suam quod possit abuti."},{"sp":"N","t":"cornua nata prius vitulo quam frontibus extent,"},{"sp":"N","t":"illis iratus petit atque infestus inurget.","st":"5.1035"},{"sp":"N","t":"at catuli pantherarum scymnique leonum"},{"sp":"N","t":"unguibus ac pedibus iam tum morsuque repugnant,"},{"sp":"N","t":"vix etiam cum sunt dentes unguesque creati."},{"sp":"N","t":"alituum porro genus alis omne videmus"},{"sp":"N","t":"fidere et a pennis tremulum petere auxiliatum.","st":"5.1040"},{"sp":"N","t":"proinde putare aliquem tum nomina distribuisse"},{"sp":"N","t":"rebus et inde homines didicisse vocabula prima,"},{"sp":"N","t":"desiperest. nam cur hic posset cuncta notare"},{"sp":"N","t":"vocibus et varios sonitus emittere linguae,"},{"sp":"N","t":"tempore eodem alii facere id non quisse putentur?","st":"5.1045"},{"sp":"N","t":"praeterea si non alii quoque vocibus usi"},{"sp":"N","t":"inter se fuerant, unde insita notities est"},{"sp":"N","t":"utilitatis et unde data est huic prima potestas,"},{"sp":"N","t":"quid vellet facere ut sciret animoque videret?"},{"sp":"N","t":"cogere item pluris unus victosque domare","st":"5.1050"},{"sp":"N","t":"non poterat, rerum ut perdiscere nomina vellent."},{"sp":"N","t":"nec ratione docere ulla suadereque surdis,"},{"sp":"N","t":"quid sit opus facto, facilest; neque enim paterentur"},{"sp":"N","t":"nec ratione ulla sibi ferrent amplius auris"},{"sp":"N","t":"vocis inauditos sonitus obtundere frustra.","st":"5.1055"},{"sp":"N","t":"postremo quid in hac mirabile tantoperest re,"},{"sp":"N","t":"si genus humanum, cui vox et lingua vigeret,"},{"sp":"N","t":"pro vario sensu varia res voce notaret?"},{"sp":"N","t":"cum pecudes mutae, cum denique saecla ferarum"},{"sp":"N","t":"dissimilis soleant voces variasque ciere,","st":"5.1060"},{"sp":"N","t":"cum metus aut dolor est et cum iam gaudia gliscunt."},{"sp":"N","t":"quippe etenim licet id rebus cognoscere apertis."},{"sp":"N","t":"inritata canum cum primum magna Molossum"},{"sp":"N","t":"mollia ricta fremunt duros nudantia dentes,"},{"sp":"N","t":"longe alio sonitu rabies restricta minatur,","st":"5.1065"},{"sp":"N","t":"et cum iam latrant et vocibus omnia complent;"},{"sp":"N","t":"at catulos blande cum lingua lambere temptant"},{"sp":"N","t":"aut ubi eos lactant, pedibus morsuque potentes"},{"sp":"N","t":"suspensis teneros imitantur dentibus haustus,"},{"sp":"N","t":"longe alio pacto gannitu vocis adulant,","st":"5.1070"},{"sp":"N","t":"et cum deserti baubantur in aedibus, aut cum"},{"sp":"N","t":"plorantis fugiunt summisso corpore plagas."},{"sp":"N","t":"denique non hinnitus item differre videtur,"},{"sp":"N","t":"inter equas ubi equus florenti aetate iuvencus"},{"sp":"N","t":"pinnigeri saevit calcaribus ictus Amoris","st":"5.1075"},{"sp":"N","t":"et fremitum patulis sub naribus edit ad arma,"},{"sp":"N","t":"et cum sic alias concussis artibus hinnit?"},{"sp":"N","t":"postremo genus alituum variaeque volucres,"},{"sp":"N","t":"accipitres atque ossifragae mergique marinis"},{"sp":"N","t":"fluctibus in salso victum vitamque petentes,","st":"5.1080"},{"sp":"N","t":"longe alias alio iaciunt in tempore voces,"},{"sp":"N","t":"et quom de victu certant praedaque repugnant."},{"sp":"N","t":"et partim mutant cum tempestatibus una"},{"sp":"N","t":"raucisonos cantus, cornicum ut saecla vetusta"},{"sp":"N","t":"corvorumque gregis ubi aquam dicuntur et imbris","st":"5.1085"},{"sp":"N","t":"poscere et inter dum ventos aurasque vocare."},{"sp":"N","t":"ergo si varii sensus animalia cogunt,"},{"sp":"N","t":"muta tamen cum sint, varias emittere voces,"},{"sp":"N","t":"quanto mortalis magis aequumst tum potuisse"},{"sp":"N","t":"dissimilis alia atque alia res voce notare!","st":"5.1090"},{"sp":"N","t":"Illud in his rebus tacitus ne forte requiras,"},{"sp":"N","t":"fulmen detulit in terram mortalibus ignem"},{"sp":"N","t":"primitus, inde omnis flammarum diditur ardor;"},{"sp":"N","t":"multa videmus enim caelestibus insita flammis"},{"sp":"N","t":"fulgere, cum caeli donavit plaga vaporis.","st":"5.1095"},{"sp":"N","t":"et ramosa tamen cum ventis pulsa vacillans"},{"sp":"N","t":"aestuat in ramos incumbens arboris arbor,"},{"sp":"N","t":"exprimitur validis extritus viribus ignis,"},{"sp":"N","t":"emicat inter dum flammai fervidus ardor,"},{"sp":"N","t":"mutua dum inter se rami stirpesque teruntur.","st":"5.1100"},{"sp":"N","t":"quorum utrumque dedisse potest mortalibus ignem."},{"sp":"N","t":"inde cibum quoquere ac flammae mollire vapore"},{"sp":"N","t":"sol docuit, quoniam mitescere multa videbant"},{"sp":"N","t":"verberibus radiorum atque aestu victa per agros."},{"sp":"N","t":"Inque dies magis hi victum vitamque priorem","st":"5.1105"},{"sp":"N","t":"commutare novis monstrabant rebus et igni,"},{"sp":"N","t":"ingenio qui praestabant et corde vigebant."},{"sp":"N","t":"condere coeperunt urbis arcemque locare"},{"sp":"N","t":"praesidium reges ipsi sibi perfugiumque,"},{"sp":"N","t":"et pecudes et agros divisere atque dedere","st":"5.1110"},{"sp":"N","t":"pro facie cuiusque et viribus ingenioque;"},{"sp":"N","t":"nam facies multum valuit viresque vigebant."},{"sp":"N","t":"posterius res inventast aurumque repertum,"},{"sp":"N","t":"quod facile et validis et pulchris dempsit honorem;"},{"sp":"N","t":"divitioris enim sectam plerumque secuntur","st":"5.1115"},{"sp":"N","t":"quam lubet et fortes et pulchro corpore creti."},{"sp":"N","t":"quod siquis vera vitam ratione gubernet,"},{"sp":"N","t":"divitiae grandes homini sunt vivere parce"},{"sp":"N","t":"aequo animo; neque enim est umquam penuria parvi."},{"sp":"N","t":"at claros homines voluerunt se atque potentes,","st":"5.1120"},{"sp":"N","t":"ut fundamento stabili fortuna maneret"},{"sp":"N","t":"et placidam possent opulenti degere vitam,"},{"sp":"N","t":"ne quiquam, quoniam ad summum succedere honorem"},{"sp":"N","t":"certantes iter infestum fecere viai,"},{"sp":"N","t":"et tamen e summo, quasi fulmen, deicit ictos","st":"5.1125"},{"sp":"N","t":"invidia inter dum contemptim in Tartara taetra;"},{"sp":"N","t":"invidia quoniam ceu fulmine summa vaporant"},{"sp":"N","t":"plerumque et quae sunt aliis magis edita cumque;"},{"sp":"N","t":"ut satius multo iam sit parere quietum"},{"sp":"N","t":"quam regere imperio res velle et regna tenere.","st":"5.1130"},{"sp":"N","t":"proinde sine in cassum defessi sanguine sudent,"},{"sp":"N","t":"angustum per iter luctantes ambitionis;"},{"sp":"N","t":"quandoquidem sapiunt alieno ex ore petuntque"},{"sp":"N","t":"res ex auditis potius quam sensibus ipsis,"},{"sp":"N","t":"nec magis id nunc est neque erit mox quam fuit ante.","st":"5.1135"},{"sp":"N","t":"Ergo regibus occisis subversa iacebat"},{"sp":"N","t":"pristina maiestas soliorum et sceptra superba,"},{"sp":"N","t":"et capitis summi praeclarum insigne cruentum"},{"sp":"N","t":"sub pedibus vulgi magnum lugebat honorem;"},{"sp":"N","t":"nam cupide conculcatur nimis ante metutum.","st":"5.1140"},{"sp":"N","t":"res itaque ad summam faecem turbasque redibat,"},{"sp":"N","t":"imperium sibi cum ac summatum quisque petebat."},{"sp":"N","t":"inde magistratum partim docuere creare"},{"sp":"N","t":"iuraque constituere, ut vellent legibus uti."},{"sp":"N","t":"nam genus humanum, defessum vi colere aevom,","st":"5.1145"},{"sp":"N","t":"ex inimicitiis languebat; quo magis ipsum"},{"sp":"N","t":"sponte sua cecidit sub leges artaque iura."},{"sp":"N","t":"acrius ex ira quod enim se quisque parabat"},{"sp":"N","t":"ulcisci quam nunc concessumst legibus aequis,"},{"sp":"N","t":"hanc ob rem est homines pertaesum vi colere aevom.","st":"5.1150"},{"sp":"N","t":"inde metus maculat poenarum praemia vitae."},{"sp":"N","t":"circumretit enim vis atque iniuria quemque"},{"sp":"N","t":"atque unde exortast, ad eum plerumque revertit,"},{"sp":"N","t":"nec facilest placidam ac pacatam degere vitam"},{"sp":"N","t":"qui violat factis communia foedera pacis.","st":"5.1155"},{"sp":"N","t":"etsi fallit enim divom genus humanumque,"},{"sp":"N","t":"perpetuo tamen id fore clam diffidere debet;"},{"sp":"N","t":"quippe ubi se multi per somnia saepe loquentes"},{"sp":"N","t":"aut morbo delirantes protraxe ferantur"},{"sp":"N","t":"et celata mala in medium et peccata dedisse.","st":"5.1160"},{"sp":"N","t":"Nunc quae causa deum per magnas numina gentis"},{"sp":"N","t":"pervulgarit et ararum compleverit urbis"},{"sp":"N","t":"suscipiendaque curarit sollemnia sacra,"},{"sp":"N","t":"quae nunc in magnis florent sacra rebus locisque,"},{"sp":"N","t":"unde etiam nunc est mortalibus insitus horror,","st":"5.1165"},{"sp":"N","t":"qui delubra deum nova toto suscitat orbi"},{"sp":"N","t":"terrarum et festis cogit celebrare diebus,"},{"sp":"N","t":"non ita difficilest rationem reddere verbis."},{"sp":"N","t":"quippe etenim iam tum divom mortalia saecla"},{"sp":"N","t":"egregias animo facies vigilante videbant","st":"5.1170"},{"sp":"N","t":"et magis in somnis mirando corporis auctu."},{"sp":"N","t":"his igitur sensum tribuebant propterea quod"},{"sp":"N","t":"membra movere videbantur vocesque superbas"},{"sp":"N","t":"mittere pro facie praeclara et viribus amplis."},{"sp":"N","t":"aeternamque dabant vitam, quia semper eorum","st":"5.1175"},{"sp":"N","t":"subpeditabatur facies et forma manebat,"},{"sp":"N","t":"et tamen omnino quod tantis viribus auctos"},{"sp":"N","t":"non temere ulla vi convinci posse putabant."},{"sp":"N","t":"fortunisque ideo longe praestare putabant,"},{"sp":"N","t":"quod mortis timor haut quemquam vexaret eorum,","st":"5.1180"},{"sp":"N","t":"et simul in somnis quia multa et mira videbant"},{"sp":"N","t":"efficere et nullum capere ipsos inde laborem."},{"sp":"N","t":"praeterea caeli rationes ordine certo"},{"sp":"N","t":"et varia annorum cernebant tempora verti"},{"sp":"N","t":"nec poterant quibus id fieret cognoscere causis.","st":"5.1185"},{"sp":"N","t":"ergo perfugium sibi habebant omnia divis"},{"sp":"N","t":"tradere et illorum nutu facere omnia flecti."},{"sp":"N","t":"in caeloque deum sedes et templa locarunt,"},{"sp":"N","t":"per caelum volvi quia nox et luna videtur,"},{"sp":"N","t":"luna dies et nox et noctis signa severa","st":"5.1190"},{"sp":"N","t":"noctivagaeque faces caeli flammaeque volantes,"},{"sp":"N","t":"nubila sol imbres nix venti fulmina grando"},{"sp":"N","t":"et rapidi fremitus et murmura magna minarum."},{"sp":"N","t":"O genus infelix humanum, talia divis"},{"sp":"N","t":"cum tribuit facta atque iras adiunxit acerbas!","st":"5.1195"},{"sp":"N","t":"quantos tum gemitus ipsi sibi, quantaque nobis"},{"sp":"N","t":"volnera, quas lacrimas peperere minoribus nostris!"},{"sp":"N","t":"nec pietas ullast velatum saepe videri"},{"sp":"N","t":"vertier ad lapidem atque omnis accedere ad aras"},{"sp":"N","t":"nec procumbere humi prostratum et pandere palmas","st":"5.1200"},{"sp":"N","t":"ante deum delubra nec aras sanguine multo"},{"sp":"N","t":"spargere quadrupedum nec votis nectere vota,"},{"sp":"N","t":"sed mage pacata posse omnia mente tueri."},{"sp":"N","t":"nam cum suspicimus magni caelestia mundi"},{"sp":"N","t":"templa super stellisque micantibus aethera fixum,","st":"5.1205"},{"sp":"N","t":"et venit in mentem solis lunaeque viarum,"},{"sp":"N","t":"tunc aliis oppressa malis in pectora cura"},{"sp":"N","t":"illa quoque expergefactum caput erigere infit,"},{"sp":"N","t":"ne quae forte deum nobis inmensa potestas"},{"sp":"N","t":"sit, vario motu quae candida sidera verset;","st":"5.1210"},{"sp":"N","t":"temptat enim dubiam mentem rationis egestas,"},{"sp":"N","t":"ecquae nam fuerit mundi genitalis origo,"},{"sp":"N","t":"et simul ecquae sit finis, quoad moenia mundi"},{"sp":"N","t":"et taciti motus hunc possint ferre laborem,"},{"sp":"N","t":"an divinitus aeterna donata salute","st":"5.1215"},{"sp":"N","t":"perpetuo possint aevi labentia tractu"},{"sp":"N","t":"inmensi validas aevi contemnere viris."},{"sp":"N","t":"praeterea cui non animus formidine divum"},{"sp":"N","t":"contrahitur, cui non correpunt membra pavore,"},{"sp":"N","t":"fulminis horribili cum plaga torrida tellus","st":"5.1220"},{"sp":"N","t":"contremit et magnum percurrunt murmura caelum?"},{"sp":"N","t":"non populi gentesque tremunt, regesque superbi"},{"sp":"N","t":"corripiunt divum percussi membra timore,"},{"sp":"N","t":"ne quod ob admissum foede dictumve superbe"},{"sp":"N","t":"poenarum grave sit solvendi tempus adauctum?","st":"5.1225"},{"sp":"N","t":"summa etiam cum vis violenti per mare venti"},{"sp":"N","t":"induperatorem classis super aequora verrit"},{"sp":"N","t":"cum validis pariter legionibus atque elephantis,"},{"sp":"N","t":"non divom pacem votis adit ac prece quaesit"},{"sp":"N","t":"ventorum pavidus paces animasque secundas?","st":"5.1230"},{"sp":"N","t":"ne quiquam, quoniam violento turbine saepe"},{"sp":"N","t":"correptus nihilo fertur minus ad vada leti."},{"sp":"N","t":"usque adeo res humanas vis abdita quaedam"},{"sp":"N","t":"opterit et pulchros fascis saevasque secures"},{"sp":"N","t":"proculcare ac ludibrio sibi habere videtur.","st":"5.1235"},{"sp":"N","t":"denique sub pedibus tellus cum tota vacillat"},{"sp":"N","t":"concussaeque cadunt urbes dubiaeque minantur,"},{"sp":"N","t":"quid mirum si se temnunt mortalia saecla"},{"sp":"N","t":"atque potestatis magnas mirasque relinquunt"},{"sp":"N","t":"in rebus viris divum, quae cuncta gubernent?","st":"5.1240"},{"sp":"N","t":"Quod super est, aes atque aurum ferrumque repertumst"},{"sp":"N","t":"et simul argenti pondus plumbique potestas,"},{"sp":"N","t":"ignis ubi ingentis silvas ardore cremarat"},{"sp":"N","t":"montibus in magnis, seu caelo fulmine misso,"},{"sp":"N","t":"sive quod inter se bellum silvestre gerentes","st":"5.1245"},{"sp":"N","t":"hostibus intulerant ignem formidinis ergo,"},{"sp":"N","t":"sive quod inducti terrae bonitate volebant"},{"sp":"N","t":"pandere agros pinguis et pascua reddere rura,"},{"sp":"N","t":"sive feras interficere et ditescere praeda;"},{"sp":"N","t":"nam fovea atque igni prius est venarier ortum","st":"5.1250"},{"sp":"N","t":"quam saepire plagis saltum canibusque ciere."},{"sp":"N","t":"quicquid id est, qua cumque e causa flammeus ardor"},{"sp":"N","t":"horribili sonitu silvas exederat altis"},{"sp":"N","t":"a radicibus et terram percoxerat igni,"},{"sp":"N","t":"manabat venis ferventibus in loca terrae","st":"5.1255"},{"sp":"N","t":"concava conveniens argenti rivus et auri,"},{"sp":"N","t":"aeris item et plumbi. quae cum concreta videbant"},{"sp":"N","t":"posterius claro in terra splendere colore,"},{"sp":"N","t":"tollebant nitido capti levique lepore,"},{"sp":"N","t":"et simili formata videbant esse figura","st":"5.1260"},{"sp":"N","t":"atque lacunarum fuerant vestigia cuique."},{"sp":"N","t":"tum penetrabat eos posse haec liquefacta calore"},{"sp":"N","t":"quamlibet in formam et faciem decurrere rerum,"},{"sp":"N","t":"et prorsum quamvis in acuta ac tenvia posse"},{"sp":"N","t":"mucronum duci fastigia procudendo,","st":"5.1265"},{"sp":"N","t":"ut sibi tela parent silvasque ut caedere possint"},{"sp":"N","t":"materiemque dolare et levia radere tigna"},{"sp":"N","t":"et terebrare etiam ac pertundere perque forare."},{"sp":"N","t":"nec minus argento facere haec auroque parabant"},{"sp":"N","t":"quam validi primum violentis viribus aeris,","st":"5.1270"},{"sp":"N","t":"ne quiquam, quoniam cedebat victa potestas"},{"sp":"N","t":"nec poterant pariter durum sufferre laborem."},{"sp":"N","t":"nam fuit in pretio magis aes aurumque iacebat"},{"sp":"N","t":"propter inutilitatem hebeti mucrone retusum;"},{"sp":"N","t":"nunc iacet aes, aurum in summum successit honorem.","st":"5.1275"},{"sp":"N","t":"sic volvenda aetas commutat tempora rerum."},{"sp":"N","t":"quod fuit in pretio, fit nullo denique honore;"},{"sp":"N","t":"porro aliud succedit et e contemptibus exit"},{"sp":"N","t":"inque dies magis adpetitur floretque repertum"},{"sp":"N","t":"laudibus et miro est mortalis inter honore.","st":"5.1280"},{"sp":"N","t":"Nunc tibi quo pacto ferri natura reperta"},{"sp":"N","t":"sit facilest ipsi per te cognoscere, Memmi."},{"sp":"N","t":"arma antiqua manus ungues dentesque fuerunt"},{"sp":"N","t":"et lapides et item silvarum fragmina rami"},{"sp":"N","t":"et flamma atque ignes, post quam sunt cognita primum.","st":"5.1285"},{"sp":"N","t":"posterius ferri vis est aerisque reperta."},{"sp":"N","t":"et prior aeris erat quam ferri cognitus usus,"},{"sp":"N","t":"quo facilis magis est natura et copia maior."},{"sp":"N","t":"aere solum terrae tractabant, aereque belli"},{"sp":"N","t":"miscebant fluctus et vulnera vasta serebant","st":"5.1290"},{"sp":"N","t":"et pecus atque agros adimebant; nam facile ollis"},{"sp":"N","t":"omnia cedebant armatis nuda et inerma."},{"sp":"N","t":"inde minutatim processit ferreus ensis"},{"sp":"N","t":"versaque in obprobrium species est falcis ahenae,"},{"sp":"N","t":"et ferro coepere solum proscindere terrae","st":"5.1295"},{"sp":"N","t":"exaequataque sunt creperi certamina belli."},{"sp":"N","t":"et prius est armatum in equi conscendere costas"},{"sp":"N","t":"et moderarier hunc frenis dextraque vigere"},{"sp":"N","t":"quam biiugo curru belli temptare pericla."},{"sp":"N","t":"et biiugo prius est quam bis coniungere binos","st":"5.1300"},{"sp":"N","t":"et quam falciferos armatum escendere currus."},{"sp":"N","t":"inde boves Lucas turrito corpore, tetras,"},{"sp":"N","t":"anguimanus, belli docuerunt volnera Poeni"},{"sp":"N","t":"sufferre et magnas Martis turbare catervas."},{"sp":"N","t":"sic alid ex alio peperit discordia tristis,","st":"5.1305"},{"sp":"N","t":"horribile humanis quod gentibus esset in armis,"},{"sp":"N","t":"inque dies belli terroribus addidit augmen."},{"sp":"N","t":"Temptarunt etiam tauros in moenere belli"},{"sp":"N","t":"expertique sues saevos sunt mittere in hostis."},{"sp":"N","t":"et validos partim prae se misere leones","st":"5.1310"},{"sp":"N","t":"cum doctoribus armatis saevisque magistris,"},{"sp":"N","t":"qui moderarier his possent vinclisque tenere,"},{"sp":"N","t":"ne quiquam, quoniam permixta caede calentes"},{"sp":"N","t":"turbabant saevi nullo discrimine turmas,"},{"sp":"N","t":"terrificas capitum quatientis undique cristas,","st":"5.1315"},{"sp":"N","t":"nec poterant equites fremitu perterrita equorum"},{"sp":"N","t":"pectora mulcere et frenis convertere in hostis."},{"sp":"N","t":"inritata leae iaciebant corpora saltu"},{"sp":"N","t":"undique et adversum venientibus ora patebant"},{"sp":"N","t":"et nec opinantis a tergo deripiebant","st":"5.1320"},{"sp":"N","t":"deplexaeque dabant in terram volnere victos,"},{"sp":"N","t":"morsibus adfixae validis atque unguibus uncis."},{"sp":"N","t":"iactabantque suos tauri pedibusque terebant"},{"sp":"N","t":"et latera ac ventres hauribant supter equorum"},{"sp":"N","t":"cornibus et terram minitanti mente ruebant.","st":"5.1325"},{"sp":"N","t":"et validis socios caedebant dentibus apri"},{"sp":"N","t":"tela infracta suo tinguentes sanguine saevi"},{"sp":"N","t":"in se fracta suo tinguentes sanguine tela,"},{"sp":"N","t":"permixtasque dabant equitum peditumque ruinas."},{"sp":"N","t":"nam transversa feros exibant dentis adactus","st":"5.1330"},{"sp":"N","t":"iumenta aut pedibus ventos erecta petebant,"},{"sp":"N","t":"ne quiquam, quoniam ab nervis succisa videres"},{"sp":"N","t":"concidere atque gravi terram consternere casu."},{"sp":"N","t":"si quos ante domi domitos satis esse putabant,"},{"sp":"N","t":"effervescere cernebant in rebus agundis","st":"5.1335"},{"sp":"N","t":"volneribus clamore fuga terrore tumultu,"},{"sp":"N","t":"nec poterant ullam partem redducere eorum;"},{"sp":"N","t":"diffugiebat enim varium genus omne ferarum,"},{"sp":"N","t":"ut nunc saepe boves Lucae ferro male mactae"},{"sp":"N","t":"diffugiunt, fera facta suis cum multa dedere.","st":"5.1340"},{"sp":"N","t":"Sed facere id non tam vincendi spe voluerunt;"},{"sp":"N","t":"quam dare quod gemerent hostes, ipsique perire,"},{"sp":"N","t":"qui numero diffidebant armisque vacabant,"},{"sp":"N","t":"si fuit ut facerent. sed vix adducor ut ante"},{"sp":"N","t":"non quierint animo praesentire atque videre,","st":"5.1345"},{"sp":"N","t":"quam commune malum fieret foedumque, futurum."},{"sp":"N","t":"et magis id possis factum contendere in omni"},{"sp":"N","t":"in variis mundis varia ratione creatis,"},{"sp":"N","t":"quam certo atque uno terrarum quolibet orbi."},{"sp":"N","t":"Nexilis ante fuit vestis quam textile tegmen.","st":"5.1350"},{"sp":"N","t":"textile post ferrumst, quia ferro tela paratur,"},{"sp":"N","t":"nec ratione alia possunt tam levia gigni"},{"sp":"N","t":"insilia ac fusi, radii, scapique sonantes."},{"sp":"N","t":"et facere ante viros lanam natura coegit"},{"sp":"N","t":"quam muliebre genus; nam longe praestat in arte","st":"5.1355"},{"sp":"N","t":"et sollertius est multo genus omne virile;"},{"sp":"N","t":"agricolae donec vitio vertere severi,"},{"sp":"N","t":"ut muliebribus id manibus concedere vellent"},{"sp":"N","t":"atque ipsi pariter durum sufferre laborem"},{"sp":"N","t":"atque opere in duro durarent membra manusque.","st":"5.1360"},{"sp":"N","t":"At specimen sationis et insitionis origo"},{"sp":"N","t":"ipsa fuit rerum primum natura creatrix,"},{"sp":"N","t":"arboribus quoniam bacae glandesque caducae"},{"sp":"N","t":"tempestiva dabant pullorum examina supter;"},{"sp":"N","t":"unde etiam libitumst stirpis committere ramis","st":"5.1365"},{"sp":"N","t":"et nova defodere in terram virgulta per agros."},{"sp":"N","t":"inde aliam atque aliam culturam dulcis agelli"},{"sp":"N","t":"temptabant fructusque feros mansuescere terra"},{"sp":"N","t":"cernebant indulgendo blandeque colendo."},{"sp":"N","t":"inque dies magis in montem succedere silvas","st":"5.1370"},{"sp":"N","t":"cogebant infraque locum concedere cultis,"},{"sp":"N","t":"prata lacus rivos segetes vinetaque laeta"},{"sp":"N","t":"collibus et campis ut haberent, atque olearum"},{"sp":"N","t":"caerula distinguens inter plaga currere posset"},{"sp":"N","t":"per tumulos et convallis camposque profusa;","st":"5.1375"},{"sp":"N","t":"ut nunc esse vides vario distincta lepore"},{"sp":"N","t":"omnia, quae pomis intersita dulcibus ornant"},{"sp":"N","t":"arbustisque tenent felicibus opsita circum."},{"sp":"N","t":"At liquidas avium voces imitarier ore"},{"sp":"N","t":"ante fuit multo quam levia carmina cantu","st":"5.1380"},{"sp":"N","t":"concelebrare homines possent aurisque iuvare."},{"sp":"N","t":"et zephyri cava per calamorum sibila primum"},{"sp":"N","t":"agrestis docuere cavas inflare cicutas."},{"sp":"N","t":"inde minutatim dulcis didicere querellas,"},{"sp":"N","t":"tibia quas fundit digitis pulsata canentum,","st":"5.1385"},{"sp":"N","t":"avia per nemora ac silvas saltusque reperta,"},{"sp":"N","t":"per loca pastorum deserta atque otia dia."},{"sp":"N","t":"sic unum quicquid paulatim protrahit aetas"},{"sp":"N","t":"in medium ratioque in luminis eruit oras."},{"sp":"N","t":"haec animos ollis mulcebant atque iuvabant","st":"5.1390"},{"sp":"N","t":"cum satiate cibi; nam tum sunt omnia cordi."},{"sp":"N","t":"saepe itaque inter se prostrati in gramine molli"},{"sp":"N","t":"propter aquae rivom sub ramis arboris altae."},{"sp":"N","t":"non magnis opibus iucunde corpora habebant,"},{"sp":"N","t":"praesertim cum tempestas ridebat et anni","st":"5.1395"},{"sp":"N","t":"tempora pingebant viridantis floribus herbas."},{"sp":"N","t":"tum ioca, tum sermo, tum dulces esse cachinni"},{"sp":"N","t":"consuerant; agrestis enim tum musa vigebat."},{"sp":"N","t":"tum caput atque umeros plexis redimire coronis"},{"sp":"N","t":"floribus et foliis lascivia laeta movebat,","st":"5.1400"},{"sp":"N","t":"atque extra numerum procedere membra moventes"},{"sp":"N","t":"duriter et duro terram pede pellere matrem;"},{"sp":"N","t":"unde oriebantur risus dulcesque cachinni,"},{"sp":"N","t":"omnia quod nova tum magis haec et mira vigebant."},{"sp":"N","t":"et vigilantibus hinc aderant solacia somno","st":"5.1405"},{"sp":"N","t":"ducere multimodis voces et flectere cantus"},{"sp":"N","t":"et supera calamos unco percurrere labro;"},{"sp":"N","t":"unde etiam vigiles nunc haec accepta tuentur."},{"sp":"N","t":"et numerum servare genus didicere, neque hilo"},{"sp":"N","t":"maiore interea capiunt dulcedine fructum","st":"5.1410"},{"sp":"N","t":"quam silvestre genus capiebat terrigenarum."},{"sp":"N","t":"nam quod adest praesto, nisi quid cognovimus ante"},{"sp":"N","t":"suavius, in primis placet et pollere videtur,"},{"sp":"N","t":"posteriorque fere melior res illa reperta"},{"sp":"N","t":"perdit et immutat sensus ad pristina quaeque.","st":"5.1415"},{"sp":"N","t":"sic odium coepit glandis, sic illa relicta"},{"sp":"N","t":"strata cubilia sunt herbis et frondibus aucta."},{"sp":"N","t":"pellis item cecidit vestis contempta ferina;"},{"sp":"N","t":"quam reor invidia tali tunc esse repertam,"},{"sp":"N","t":"ut letum insidiis qui gessit primus obiret,","st":"5.1420"},{"sp":"N","t":"et tamen inter eos distractam sanguine multo"},{"sp":"N","t":"disperiise neque in fructum convertere quisse."},{"sp":"N","t":"tunc igitur pelles, nunc aurum et purpura curis"},{"sp":"N","t":"exercent hominum vitam belloque fatigant;"},{"sp":"N","t":"quo magis in nobis, ut opinor, culpa resedit.","st":"5.1425"},{"sp":"N","t":"frigus enim nudos sine pellibus excruciabat"},{"sp":"N","t":"terrigenas; at nos nil laedit veste carere"},{"sp":"N","t":"purpurea atque auro signisque ingentibus apta,"},{"sp":"N","t":"dum plebeia tamen sit, quae defendere possit."},{"sp":"N","t":"Ergo hominum genus in cassum frustraque laborat","st":"5.1430"},{"sp":"N","t":"semper et in curis consumit inanibus aevom,"},{"sp":"N","t":"ni mirum quia non cognovit quae sit habendi"},{"sp":"N","t":"finis et omnino quoad crescat vera voluptas;"},{"sp":"N","t":"idque minutatim vitam provexit in altum"},{"sp":"N","t":"et belli magnos commovit funditus aestus.","st":"5.1435"},{"sp":"N","t":"at vigiles mundi magnum versatile templum"},{"sp":"N","t":"sol et luna suo lustrantes lumine circum"},{"sp":"N","t":"perdocuere homines annorum tempora verti"},{"sp":"N","t":"et certa ratione geri rem atque ordine certo."},{"sp":"N","t":"Iam validis saepti degebant turribus aevom,","st":"5.1440"},{"sp":"N","t":"et divisa colebatur discretaque tellus,"},{"sp":"N","t":"tum mare velivolis florebat navibus ponti,"},{"sp":"N","t":"auxilia ac socios iam pacto foedere habebant,"},{"sp":"N","t":"carminibus cum res gestas coepere poetae"},{"sp":"N","t":"tradere; nec multo prius sunt elementa reperta.","st":"5.1445"},{"sp":"N","t":"propterea quid sit prius actum respicere aetas"},{"sp":"N","t":"nostra nequit, nisi qua ratio vestigia monstrat."},{"sp":"N","t":"Navigia atque agri culturas moenia leges"},{"sp":"N","t":"arma vias vestes et cetera de genere horum,"},{"sp":"N","t":"praemia, delicias quoque vitae funditus omnis,","st":"5.1450"},{"sp":"N","t":"carmina, picturas et daedala signa polita"},{"sp":"N","t":"usus et impigrae simul experientia mentis"},{"sp":"N","t":"paulatim docuit pedetemptim progredientis."},{"sp":"N","t":"sic unum quicquid paulatim protrahit aetas"},{"sp":"N","t":"in medium ratioque in luminis erigit oras;","st":"5.1455"},{"sp":"N","t":"namque alid ex alio clarescere corde videbant,"},{"sp":"N","t":"artibus ad summum donec venere cacumen."},{"sp":"HDR","t":"Liber VI"},{"sp":"N","t":"Primae frugiparos fetus mortalibus aegris","st":"6.1"},{"sp":"N","t":"dididerunt quondam praeclaro nomine Athenae"},{"sp":"N","t":"et recreaverunt vitam legesque rogarunt"},{"sp":"N","t":"et primae dederunt solacia dulcia vitae,"},{"sp":"N","t":"cum genuere virum tali cum corde repertum,","st":"6.5"},{"sp":"N","t":"omnia veridico qui quondam ex ore profudit;"},{"sp":"N","t":"cuius et extincti propter divina reperta"},{"sp":"N","t":"divolgata vetus iam ad caelum gloria fertur."},{"sp":"N","t":"nam cum vidit hic ad victum quae flagitat usus"},{"sp":"N","t":"omnia iam ferme mortalibus esse parata","st":"6.10"},{"sp":"N","t":"et, pro quam possent, vitam consistere tutam,"},{"sp":"N","t":"divitiis homines et honore et laude potentis"},{"sp":"N","t":"affluere atque bona gnatorum excellere fama,"},{"sp":"N","t":"nec minus esse domi cuiquam tamen anxia cordi,"},{"sp":"N","t":"atque animi ingratis vitam vexare sine ulla","st":"6.15"},{"sp":"N","t":"pausa atque infestis cogi saevire querellis,"},{"sp":"N","t":"intellegit ibi vitium vas efficere ipsum"},{"sp":"N","t":"omniaque illius vitio corrumpier intus,"},{"sp":"N","t":"quae conlata foris et commoda cumque venirent;"},{"sp":"N","t":"partim quod fluxum pertusumque esse videbat,","st":"6.20"},{"sp":"N","t":"ut nulla posset ratione explerier umquam,"},{"sp":"N","t":"partim quod taetro quasi conspurcare sapore"},{"sp":"N","t":"omnia cernebat, quae cumque receperat, intus."},{"sp":"N","t":"veridicis igitur purgavit pectora dictis"},{"sp":"N","t":"et finem statuit cuppedinis atque timoris","st":"6.25"},{"sp":"N","t":"exposuitque bonum summum, quo tendimus omnes,"},{"sp":"N","t":"quid foret, atque viam monstravit, tramite parvo"},{"sp":"N","t":"qua possemus ad id recto contendere cursu,"},{"sp":"N","t":"quidve mali foret in rebus mortalibus passim,"},{"sp":"N","t":"quod fieret naturali varieque volaret","st":"6.30"},{"sp":"N","t":"seu casu seu vi, quod sic natura parasset,"},{"sp":"N","t":"et quibus e portis occurri cuique deceret,"},{"sp":"N","t":"et genus humanum frustra plerumque probavit"},{"sp":"N","t":"volvere curarum tristis in pectore fluctus."},{"sp":"N","t":"nam vel uti pueri trepidant atque omnia caecis","st":"6.35"},{"sp":"N","t":"in tenebris metuunt, sic nos in luce timemus"},{"sp":"N","t":"inter dum, nihilo quae sunt metuenda magis quam"},{"sp":"N","t":"quae pueri in tenebris pavitant finguntque futura."},{"sp":"N","t":"hunc igitur terrorem animi tenebrasque necessest"},{"sp":"N","t":"non radii solis nec lucida tela diei","st":"6.40"},{"sp":"N","t":"discutiant, sed naturae species ratioque."},{"sp":"N","t":"quo magis inceptum pergam pertexere dictis."},{"sp":"N","t":"Et quoniam docui mundi mortalia templa"},{"sp":"N","t":"esse et nativo consistere corpore caelum,"},{"sp":"N","t":"et quae cumque in eo fiunt fierique necessest","st":"6.45"},{"sp":"N","t":"pleraque dissolui, qui restant percipe porro,"},{"sp":"N","t":"quandoquidem semel insignem conscendere currum"},{"sp":"N","t":"tu mihi supremae praescripta ad candida callis"},{"sp":"N","t":"currenti spatium praemonstra, callida musa"},{"sp":"N","t":"Calliope, requies hominum divomque voluptas,","st":"6.50"},{"sp":"N","t":"te duce ut insigni capiam cum laude coronam."},{"sp":"N","t":"ventorum existant, placentur ut omnia rursum"},{"sp":"N","t":"quae fuerint, sint placato conversa furore."},{"sp":"N","t":"cetera quae fieri in terris caeloque tuentur"},{"sp":"N","t":"mortales, pavidis cum pendent mentibus saepe","st":"6.55"},{"sp":"N","t":"et faciunt animos humilis formidine divom"},{"sp":"N","t":"depressosque premunt ad terram propterea quod"},{"sp":"N","t":"ignorantia causarum conferre deorum"},{"sp":"N","t":"cogit ad imperium res et concedere regnum."},{"sp":"N","t":"quorum operum causas nulla ratione videre","st":"6.60"},{"sp":"N","t":"possunt ac fieri divino numine rentur."},{"sp":"N","t":"nam bene qui didicere deos securum agere aevom,"},{"sp":"N","t":"si tamen interea mirantur qua ratione"},{"sp":"N","t":"quaeque geri possint, praesertim rebus in illis"},{"sp":"N","t":"quae supera caput aetheriis cernuntur in oris,","st":"6.65"},{"sp":"N","t":"rursus in antiquas referuntur religionis"},{"sp":"N","t":"et dominos acris adsciscunt, omnia posse"},{"sp":"N","t":"quos miseri credunt, ignari quid queat esse,"},{"sp":"N","t":"quid nequeat, finita potestas denique cuique"},{"sp":"N","t":"qua nam sit ratione atque alte terminus haerens;","st":"6.70"},{"sp":"N","t":"quo magis errantes caeca ratione feruntur."},{"sp":"N","t":"quae nisi respuis ex animo longeque remittis"},{"sp":"N","t":"dis indigna putare alienaque pacis eorum,"},{"sp":"N","t":"delibata deum per te tibi numina sancta"},{"sp":"N","t":"saepe oberunt; non quo violari summa deum vis","st":"6.75"},{"sp":"N","t":"possit, ut ex ira poenas petere inbibat acris,"},{"sp":"N","t":"sed quia tute tibi placida cum pace quietos"},{"sp":"N","t":"constitues magnos irarum volvere fluctus,"},{"sp":"N","t":"nec delubra deum placido cum pectore adibis,"},{"sp":"N","t":"nec de corpore quae sancto simulacra feruntur","st":"6.80"},{"sp":"N","t":"in mentes hominum divinae nuntia formae,"},{"sp":"N","t":"suscipere haec animi tranquilla pace valebis."},{"sp":"N","t":"inde videre licet qualis iam vita sequatur."},{"sp":"N","t":"quam quidem ut a nobis ratio verissima longe"},{"sp":"N","t":"reiciat, quamquam sunt a me multa profecta,","st":"6.85"},{"sp":"N","t":"multa tamen restant et sunt ornanda politis"},{"sp":"N","t":"versibus; est ratio caeliQUE ignisque tenenda,"},{"sp":"N","t":"sunt tempestates et fulmina clara canenda,"},{"sp":"N","t":"quid faciant et qua de causa cumque ferantur;"},{"sp":"N","t":"ne trepides caeli divisis partibus amens,","st":"6.90"},{"sp":"N","t":"unde volans ignis pervenerit aut in utram se"},{"sp":"N","t":"verterit hinc partim, quo pacto per loca saepta"},{"sp":"N","t":"insinuarit, et hinc dominatus ut extulerit se."},{"sp":"N","t":"quorum operum causas nulla ratione videre"},{"sp":"N","t":"possunt ac fieri divino numine rentur.","st":"6.95"},{"sp":"N","t":"Principio tonitru quatiuntur caerula caeli"},{"sp":"N","t":"propterea quia concurrunt sublime volantes"},{"sp":"N","t":"aetheriae nubes contra pugnantibus ventis."},{"sp":"N","t":"nec fit enim sonitus caeli de parte serena,"},{"sp":"N","t":"verum ubi cumque magis denso sunt agmine nubes,","st":"6.100"},{"sp":"N","t":"tam magis hinc magno fremitus fit murmure saepe."},{"sp":"N","t":"praeterea neque tam condenso corpore nubes"},{"sp":"N","t":"esse queunt quam sunt lapides ac ligna, neque autem"},{"sp":"N","t":"tam tenues quam sunt nebulae fumique volantes;"},{"sp":"N","t":"nam cadere aut bruto deberent pondere pressae","st":"6.105"},{"sp":"N","t":"ut lapides, aut ut fumus constare nequirent"},{"sp":"N","t":"nec cohibere nives gelidas et grandinis imbris."},{"sp":"N","t":"Dant etiam sonitum patuli super aequora mundi,"},{"sp":"N","t":"carbasus ut quondam magnis intenta theatris"},{"sp":"N","t":"dat crepitum malos inter iactata trabesque,","st":"6.110"},{"sp":"N","t":"inter dum perscissa furit petulantibus auris"},{"sp":"N","t":"et fragilis sonitus chartarum commeditatur;"},{"sp":"N","t":"id quoque enim genus in tonitru cognoscere possis,"},{"sp":"N","t":"aut ubi suspensam vestem chartasque volantis"},{"sp":"N","t":"verberibus venti versant planguntque per auras.","st":"6.115"},{"sp":"N","t":"fit quoque enim inter dum ut non tam concurrere nubes"},{"sp":"N","t":"frontibus adversis possint quam de latere ire"},{"sp":"N","t":"diverso motu radentes corpora tractim,"},{"sp":"N","t":"aridus unde auris terget sonus ille diuque"},{"sp":"N","t":"ducitur, exierunt donec regionibus artis.","st":"6.120"},{"sp":"N","t":"Hoc etiam pacto tonitru concussa videntur"},{"sp":"N","t":"omnia saepe gravi tremere et divolsa repente"},{"sp":"N","t":"maxima dissiluisse capacis moenia mundi,"},{"sp":"N","t":"cum subito validi venti conlecta procella"},{"sp":"N","t":"nubibus intorsit sese conclusaque ibidem","st":"6.125"},{"sp":"N","t":"turbine versanti magis ac magis undique nubem"},{"sp":"N","t":"cogit uti fiat spisso cava corpore circum,"},{"sp":"N","t":"post ubi conminuit vis eius et impetus acer,"},{"sp":"N","t":"tum perterricrepo sonitu dat scissa fragorem."},{"sp":"N","t":"nec mirum, cum plena animae vensicula parva","st":"6.130"},{"sp":"N","t":"saepe haud dat parvum sonitum displosa repente."},{"sp":"N","t":"Est etiam ratio, cum venti nubila perflant,"},{"sp":"N","t":"ut sonitus faciant; etenim ramosa videmus"},{"sp":"N","t":"nubila saepe modis multis atque aspera ferri;"},{"sp":"N","t":"scilicet ut, crebram silvam cum flamina cauri","st":"6.135"},{"sp":"N","t":"perflant, dant sonitum frondes ramique fragorem."},{"sp":"N","t":"Fit quoque ut inter dum validi vis incita venti"},{"sp":"N","t":"perscindat nubem perfringens impete recto;"},{"sp":"N","t":"nam quid possit ibi flatus manifesta docet res,"},{"sp":"N","t":"hic, ubi lenior est, in terra cum tamen alta","st":"6.140"},{"sp":"N","t":"arbusta evolvens radicibus haurit ab imis."},{"sp":"N","t":"sunt etiam fluctus per nubila, qui quasi murmur"},{"sp":"N","t":"dant in frangendo graviter; quod item fit in altis"},{"sp":"N","t":"fluminibus magnoque mari, cum frangitur aestus."},{"sp":"N","t":"Fit quoque, ubi e nubi in nubem vis incidit ardens","st":"6.145"},{"sp":"N","t":"fulminis; haec multo si forte umore recepit"},{"sp":"N","t":"ignem, continuo magno clamore trucidat;"},{"sp":"N","t":"ut calidis candens ferrum e fornacibus olim"},{"sp":"N","t":"stridit, ubi in gelidum propter demersimus imbrem."},{"sp":"N","t":"Aridior porro si nubes accipit ignem,","st":"6.150"},{"sp":"N","t":"uritur ingenti sonitu succensa repente,"},{"sp":"N","t":"lauricomos ut si per montis flamma vagetur"},{"sp":"N","t":"turbine ventorum comburens impete magno;"},{"sp":"N","t":"nec res ulla magis quam Phoebi Delphica laurus"},{"sp":"N","t":"terribili sonitu flamma crepitante crematur.","st":"6.155"},{"sp":"N","t":"Denique saepe geli multus fragor atque ruina"},{"sp":"N","t":"grandinis in magnis sonitum dat nubibus alte;"},{"sp":"N","t":"ventus enim cum confercit, franguntur in artum"},{"sp":"N","t":"concreti montes nimborum et grandine mixti."},{"sp":"N","t":"Fulgit item, nubes ignis cum semina multa","st":"6.160"},{"sp":"N","t":"excussere suo concursu, ceu lapidem si"},{"sp":"N","t":"percutiat lapis aut ferrum; nam tum quoque lumen"},{"sp":"N","t":"exilit et claras scintillas dissipat ignis."},{"sp":"N","t":"sed tonitrum fit uti post auribus accipiamus,"},{"sp":"N","t":"fulgere quam cernant oculi, quia semper ad auris","st":"6.165"},{"sp":"N","t":"tardius adveniunt quam visum quae moveant res."},{"sp":"N","t":"id licet hinc etiam cognoscere: caedere si quem"},{"sp":"N","t":"ancipiti videas ferro procul arboris auctum,"},{"sp":"N","t":"ante fit ut cernas ictum quam plaga per auris"},{"sp":"N","t":"det sonitum; sic fulgorem quoque cernimus ante","st":"6.170"},{"sp":"N","t":"quam tonitrum accipimus, pariter qui mittitur igni"},{"sp":"N","t":"e simili causa, concursu natus eodem."},{"sp":"N","t":"Hoc etiam pacto volucri loca lumine tingunt"},{"sp":"N","t":"nubes et tremulo tempestas impete fulgit."},{"sp":"N","t":"ventus ubi invasit nubem et versatus ibidem","st":"6.175"},{"sp":"N","t":"fecit ut ante cavam docui spissescere nubem,"},{"sp":"N","t":"mobilitate sua fervescit; ut omnia motu"},{"sp":"N","t":"percalefacta vides ardescere, plumbea vero"},{"sp":"N","t":"glans etiam longo cursu volvenda liquescit."},{"sp":"N","t":"ergo fervidus hic nubem cum perscidit atram,","st":"6.180"},{"sp":"N","t":"dissipat ardoris quasi per vim expressa repente"},{"sp":"N","t":"semina, quae faciunt nictantia fulgura flammae;"},{"sp":"N","t":"inde sonus sequitur, qui tardius adlicit auris"},{"sp":"N","t":"quam quae perveniunt oculorum ad lumina nostra."},{"sp":"N","t":"scilicet hoc densis fit nubibus et simul alte","st":"6.185"},{"sp":"N","t":"extructis aliis alias super impete miro."},{"sp":"N","t":"ne tibi sit frudi quod nos inferne videmus"},{"sp":"N","t":"quam sint lata magis quam sursum extructa quid extent."},{"sp":"N","t":"contemplator enim, cum montibus adsimulata"},{"sp":"N","t":"nubila portabunt venti transversa per auras,","st":"6.190"},{"sp":"N","t":"aut ubi per magnos montis cumulata videbis"},{"sp":"N","t":"insuper esse aliis alia atque urguere superna"},{"sp":"N","t":"in statione locata sepultis undique ventis;"},{"sp":"N","t":"tum poteris magnas moles cognoscere eorum"},{"sp":"N","t":"speluncasque vel ut saxis pendentibus structas","st":"6.195"},{"sp":"N","t":"cernere, quas venti cum tempestate coorta"},{"sp":"N","t":"conplerunt, magno indignantur murmure clausi"},{"sp":"N","t":"nubibus in caveisque ferarum more minantur,"},{"sp":"N","t":"nunc hinc nunc illinc fremitus per nubila mittunt,"},{"sp":"N","t":"quaerentesque viam circum versantur et ignis","st":"6.200"},{"sp":"N","t":"semina convolvunt e nubibus atque ita cogunt"},{"sp":"N","t":"multa rotantque cavis flammam fornacibus intus,"},{"sp":"N","t":"donec divolsa fulserunt nube corusci."},{"sp":"N","t":"Hac etiam fit uti de causa mobilis ille"},{"sp":"N","t":"devolet in terram liquidi color aureus ignis,","st":"6.205"},{"sp":"N","t":"semina quod nubes ipsas permulta necessust"},{"sp":"N","t":"ignis habere; etenim cum sunt umore sine ullo,"},{"sp":"N","t":"flammeus est plerumque colos et splendidus ollis."},{"sp":"N","t":"quippe etenim solis de lumine multa necessest"},{"sp":"N","t":"concipere, ut merito rubeant ignesque profundant.","st":"6.210"},{"sp":"N","t":"hasce igitur cum ventus agens contrusit in unum"},{"sp":"N","t":"compressitque locum cogens, expressa profundunt"},{"sp":"N","t":"semina, quae faciunt flammae fulgere colores."},{"sp":"N","t":"Fulgit item, cum rarescunt quoque nubila caeli;"},{"sp":"N","t":"nam cum ventus eas leviter diducit euntis","st":"6.215"},{"sp":"N","t":"dissoluitque, cadant ingratius illa necessest"},{"sp":"N","t":"semina quae faciunt fulgorem. tum sine taetro"},{"sp":"N","t":"terrore atque sonis fulgit nulloque tumultu."},{"sp":"N","t":"Quod superest, quali natura praedita constent"},{"sp":"N","t":"fulmina, declarant ictus et inusta vaporis","st":"6.220"},{"sp":"N","t":"signa notaeque gravis halantis sulpuris auras;"},{"sp":"N","t":"ignis enim sunt haec non venti signa neque imbris."},{"sp":"N","t":"praeterea saepe accendunt quoque tecta domorum"},{"sp":"N","t":"et celeri flamma dominantur in aedibus ipsis."},{"sp":"N","t":"hunc tibi subtilem cum primis ignibus ignem","st":"6.225"},{"sp":"N","t":"constituit natura minutis mobilibusque"},{"sp":"N","t":"corporibus, cui nil omnino obsistere possit."},{"sp":"N","t":"transit enim validum fulmen per saepta domorum"},{"sp":"N","t":"clamor ut ac voces, transit per saxa, per aera"},{"sp":"N","t":"et liquidum puncto facit aes in tempore et aurum.","st":"6.230"},{"sp":"N","t":"curat item vasis integris vina repente"},{"sp":"N","t":"diffugiant, quia ni mirum facile omnia circum"},{"sp":"N","t":"conlaxat rareque facit lateramina vasis"},{"sp":"N","t":"adveniens calor eius et insinuatus in ipsum"},{"sp":"N","t":"mobiliter soluens differt primordia vini.","st":"6.235"},{"sp":"N","t":"quod solis vapor aetatem non posse videtur"},{"sp":"N","t":"efficere usque adeo pollens fervore corusco."},{"sp":"N","t":"tanto mobilior vis et dominantior haec est."},{"sp":"N","t":"Nunc ea quo pacto gignantur et impete tanto"},{"sp":"N","t":"fiant ut possint ictu discludere turris,","st":"6.240"},{"sp":"N","t":"disturbare domos, avellere tigna trabesque"},{"sp":"N","t":"et monimenta virum commoliri atque ciere,"},{"sp":"N","t":"exanimare homines, pecudes prosternere passim,"},{"sp":"N","t":"cetera de genere hoc qua vi facere omnia possint,"},{"sp":"N","t":"expediam neque te in promissis plura morabor.","st":"6.245"},{"sp":"N","t":"Fulmina gignier e crassis alteque putandumst"},{"sp":"N","t":"nubibus extructis; nam caelo nulla sereno"},{"sp":"N","t":"nec leviter densis mittuntur nubibus umquam."},{"sp":"N","t":"nam dubio procul hoc fieri manifesta docet res;"},{"sp":"N","t":"quod tunc per totum concrescunt aera nubes,","st":"6.250"},{"sp":"N","t":"undique uti tenebras omnis Acherunta reamur"},{"sp":"N","t":"liquisse et magnas caeli complesse cavernas,"},{"sp":"N","t":"usque adeo tetra nimborum nocte coorta"},{"sp":"N","t":"inpendent atrae formidinis ora superne,"},{"sp":"N","t":"cum commoliri tempestas fulmina coeptat.","st":"6.255"},{"sp":"N","t":"praeterea persaepe niger quoque per mare nimbus,"},{"sp":"N","t":"ut picis e caelo demissum flumen, in undas"},{"sp":"N","t":"sic cadit effertus tenebris procul et trahit atram"},{"sp":"N","t":"fulminibus gravidam tempestatem atque procellis,"},{"sp":"N","t":"ignibus ac ventis cum primis ipse repletus,","st":"6.260"},{"sp":"N","t":"in terra quoque ut horrescant ac tecta requirant."},{"sp":"N","t":"sic igitur supera nostrum caput esse putandumst"},{"sp":"N","t":"tempestatem altam; neque enim caligine tanta"},{"sp":"N","t":"obruerent terras, nisi inaedificata superne"},{"sp":"N","t":"multa forent multis exempto nubila sole;","st":"6.265"},{"sp":"N","t":"nec tanto possent venientes opprimere imbri,"},{"sp":"N","t":"flumina abundare ut facerent camposque natare,"},{"sp":"N","t":"si non extructis foret alte nubibus aether."},{"sp":"N","t":"hic igitur ventis atque ignibus omnia plena"},{"sp":"N","t":"sunt; ideo passim fremitus et fulgura fiunt.","st":"6.270"},{"sp":"N","t":"quippe etenim supra docui permulta vaporis"},{"sp":"N","t":"semina habere cavas nubes et multa necessest"},{"sp":"N","t":"concipere ex solis radiis ardoreque eorum."},{"sp":"N","t":"hoc ubi ventus eas idem qui cogit in unum"},{"sp":"N","t":"forte locum quemvis, expressit multa vaporis","st":"6.275"},{"sp":"N","t":"semina seque simul cum eo commiscuit igni,"},{"sp":"N","t":"insinuatus ibi vortex versatur in arto"},{"sp":"N","t":"et calidis acuit fulmen fornacibus intus;"},{"sp":"N","t":"nam duplici ratione accenditur: ipse sua cum"},{"sp":"N","t":"mobilitate calescit et e contagibus ignis.","st":"6.280"},{"sp":"N","t":"inde ubi percaluit venti vis et gravis ignis"},{"sp":"N","t":"impetus incessit, maturum tum quasi fulmen"},{"sp":"N","t":"perscindit subito nubem ferturque coruscis"},{"sp":"N","t":"omnia luminibus lustrans loca percitus ardor."},{"sp":"N","t":"quem gravis insequitur sonitus, displosa repente","st":"6.285"},{"sp":"N","t":"opprimere ut caeli videantur templa superne."},{"sp":"N","t":"inde tremor terras graviter pertemptat et altum"},{"sp":"N","t":"murmura percurrunt caelum; nam tota fere tum"},{"sp":"N","t":"tempestas concussa tremit fremitusque moventur."},{"sp":"N","t":"quo de concussu sequitur gravis imber et uber,","st":"6.290"},{"sp":"N","t":"omnis uti videatur in imbrem vertier aether"},{"sp":"N","t":"atque ita praecipitans ad diluviem revocare;"},{"sp":"N","t":"tantus discidio nubis ventique procella"},{"sp":"N","t":"mittitur, ardenti sonitus cum provolat ictu."},{"sp":"N","t":"Est etiam cum vis extrinsecus incita venti","st":"6.295"},{"sp":"N","t":"incidit in validam maturo culmine nubem;"},{"sp":"N","t":"quam cum perscidit, extemplo cadit igneus ille"},{"sp":"N","t":"vertex, quem patrio vocitamus nomine fulmen."},{"sp":"N","t":"hoc fit idem in partis alias, quo cumque tulit vis."},{"sp":"N","t":"Fit quoque ut inter dum venti vis missa sine igni","st":"6.300"},{"sp":"N","t":"igniscat tamen in spatio longoque meatu,"},{"sp":"N","t":"dum venit amittens in cursu corpora quaedam"},{"sp":"N","t":"grandia, quae nequeunt pariter penetrare per auras,"},{"sp":"N","t":"atque alia ex ipso conradens aere portat"},{"sp":"N","t":"parvola, quae faciunt ignem commixta volando;","st":"6.305"},{"sp":"N","t":"non alia longe ratione ac plumbea saepe"},{"sp":"N","t":"fervida fit glans in cursu, cum multa rigoris"},{"sp":"N","t":"corpora dimittens ignem concepit in auris."},{"sp":"N","t":"Fit quoque ut ipsius plagae vis excitet ignem,"},{"sp":"N","t":"frigida cum venti pepulit vis missa sine igni,","st":"6.310"},{"sp":"N","t":"ni mirum quia, cum vehementi perculit ictu,"},{"sp":"N","t":"confluere ex ipso possunt elementa vaporis"},{"sp":"N","t":"et simul ex illa quae tum res excipit ictum;"},{"sp":"N","t":"ut, lapidem ferro cum caedimus, evolat ignis,"},{"sp":"N","t":"nec, quod frigida vis ferrist, hoc setius illi","st":"6.315"},{"sp":"N","t":"semina concurrunt calidi fulgoris ad ictum."},{"sp":"N","t":"sic igitur quoque res accendi fulmine debet,"},{"sp":"N","t":"opportuna fuit si forte et idonea flammis."},{"sp":"N","t":"nec temere omnino plane vis frigida venti"},{"sp":"N","t":"esse potest, ea quae tanta vi missa supernest,","st":"6.320"},{"sp":"N","t":"quin, prius in cursu si non accenditur igni,"},{"sp":"N","t":"at tepefacta tamen veniat commixta calore."},{"sp":"N","t":"Mobilitas autem fit fulminis et gravis ictus"},{"sp":"N","t":"et celeri ferme percurrunt fulmina lapsu,"},{"sp":"N","t":"nubibus ipsa quod omnino prius incita se vis","st":"6.325"},{"sp":"N","t":"colligit et magnum conamen sumit eundi,"},{"sp":"N","t":"inde ubi non potuit nubes capere inpetis auctum,"},{"sp":"N","t":"exprimitur vis atque ideo volat impete miro,"},{"sp":"N","t":"ut validis quae de tormentis missa feruntur."},{"sp":"N","t":"Adde quod e parvis et levibus est elementis,","st":"6.330"},{"sp":"N","t":"nec facilest tali naturae obsistere quicquam;"},{"sp":"N","t":"inter enim fugit ac penetrat per rara viarum,"},{"sp":"N","t":"non igitur multis offensibus in remorando"},{"sp":"N","t":"haesitat, hanc ob rem celeri volat impete labens."},{"sp":"N","t":"Deinde, quod omnino natura pondera deorsum","st":"6.335"},{"sp":"N","t":"omnia nituntur, cum plagast addita vero,"},{"sp":"N","t":"mobilitas duplicatur et impetus ille gravescit,"},{"sp":"N","t":"ut vehementius et citius quae cumque morantur"},{"sp":"N","t":"obvia discutiat plagis itinerque sequatur."},{"sp":"N","t":"Denique quod longo venit impete, sumere debet","st":"6.340"},{"sp":"N","t":"mobilitatem etiam atque etiam, quae crescit eundo"},{"sp":"N","t":"et validas auget viris et roborat ictum;"},{"sp":"N","t":"nam facit ut quae sint illius semina cumque"},{"sp":"N","t":"e regione locum quasi in unum cuncta ferantur,"},{"sp":"N","t":"omnia coniciens in eum volventia cursum.","st":"6.345"},{"sp":"N","t":"Forsitan ex ipso veniens trahat aere quaedam"},{"sp":"N","t":"corpora, quae plagis incendunt mobilitatem."},{"sp":"N","t":"incolumisque venit per res atque integra transit"},{"sp":"N","t":"multa, foraminibus liquidus quia transviat ignis."},{"sp":"N","t":"multaque perfringit, cum corpora fulminis ipsa","st":"6.350"},{"sp":"N","t":"corporibus rerum inciderunt, qua texta tenentur."},{"sp":"N","t":"dissoluit porro facile aes aurumque repente"},{"sp":"N","t":"conferve facit, e parvis quia facta minute"},{"sp":"N","t":"corporibus vis est et levibus ex elementis,"},{"sp":"N","t":"quae facile insinuantur et insinuata repente","st":"6.355"},{"sp":"N","t":"dissoluont nodos omnis et vincla relaxant."},{"sp":"N","t":"Autumnoque magis stellis fulgentibus alta"},{"sp":"N","t":"concutitur caeli domus undique totaque tellus,"},{"sp":"N","t":"et cum tempora se veris florentia pandunt."},{"sp":"N","t":"frigore enim desunt ignes ventique calore","st":"6.360"},{"sp":"N","t":"deficiunt neque sunt tam denso corpore nubes."},{"sp":"N","t":"interutrasque igitur cum caeli tempora constant,"},{"sp":"N","t":"tum variae causae concurrunt fulminis omnes."},{"sp":"N","t":"nam fretus ipse anni permiscet frigus ad aestum."},{"sp":"N","t":"quorum utrumque opus est fabricanda ad fulmina nubi,","st":"6.365"},{"sp":"N","t":"ut discordia sit rerum magnoque tumultu"},{"sp":"N","t":"ignibus et ventis furibundus fluctuet aer."},{"sp":"N","t":"prima caloris enim pars est postrema rigoris;"},{"sp":"N","t":"tempus id est vernum; quare pugnare necessest"},{"sp":"N","t":"dissimilis res inter se turbareque mixtas.","st":"6.370"},{"sp":"N","t":"et calor extremus primo cum frigore mixtus"},{"sp":"N","t":"volvitur, autumni quod fertur nomine tempus,"},{"sp":"N","t":"hic quoque confligunt hiemes aestatibus acres."},{"sp":"N","t":"propterea freta sunt haec anni nominitanda,"},{"sp":"N","t":"nec mirumst, in eo si tempore plurima fiunt","st":"6.375"},{"sp":"N","t":"fulmina tempestasque cietur turbida caelo,"},{"sp":"N","t":"ancipiti quoniam bello turbatur utrimque,"},{"sp":"N","t":"hinc flammis, illinc ventis umoreque mixto."},{"sp":"N","t":"Hoc est igniferi naturam fulminis ipsam"},{"sp":"N","t":"perspicere et qua vi faciat rem quamque videre,","st":"6.380"},{"sp":"N","t":"non Tyrrhena retro volventem carmina frustra"},{"sp":"N","t":"indicia occultae divum perquirere mentis,"},{"sp":"N","t":"unde volans ignis pervenerit aut in utram se"},{"sp":"N","t":"verterit hinc partim, quo pacto per loca saepta"},{"sp":"N","t":"insinuarit, et hinc dominatus ut extulerit se,","st":"6.385"},{"sp":"N","t":"quidve nocere queat de caelo fulminis ictus."},{"sp":"N","t":"quod si Iuppiter atque alii fulgentia divi"},{"sp":"N","t":"terrifico quatiunt sonitu caelestia templa"},{"sp":"N","t":"et iaciunt ignem quo cuiquest cumque voluntas,"},{"sp":"N","t":"cur quibus incautum scelus aversabile cumquest","st":"6.390"},{"sp":"N","t":"non faciunt icti flammas ut fulguris halent"},{"sp":"N","t":"pectore perfixo, documen mortalibus acre,"},{"sp":"N","t":"et potius nulla sibi turpi conscius in re"},{"sp":"N","t":"volvitur in flammis innoxius inque peditur"},{"sp":"N","t":"turbine caelesti subito correptus et igni?","st":"6.395"},{"sp":"N","t":"cur etiam loca sola petunt frustraque laborant?"},{"sp":"N","t":"an tum bracchia consuescunt firmantque lacertos?"},{"sp":"N","t":"in terraque patris cur telum perpetiuntur"},{"sp":"N","t":"optundi? cur ipse sinit neque parcit in hostis?"},{"sp":"N","t":"denique cur numquam caelo iacit undique puro","st":"6.400"},{"sp":"N","t":"Iuppiter in terras fulmen sonitusque profundit?"},{"sp":"N","t":"an simul ac nubes successere, ipse in eas tum"},{"sp":"N","t":"descendit, prope ut hinc teli determinet ictus?"},{"sp":"N","t":"in mare qua porro mittit ratione? quid undas"},{"sp":"N","t":"arguit et liquidam molem camposque natantis?","st":"6.405"},{"sp":"N","t":"praeterea si vult caveamus fulminis ictum,"},{"sp":"N","t":"cur dubitat facere ut possimus cernere missum?"},{"sp":"N","t":"si nec opinantis autem volt opprimere igni,"},{"sp":"N","t":"cur tonat ex illa parte, ut vitare queamus,"},{"sp":"N","t":"cur tenebras ante et fremitus et murmura concit?","st":"6.410"},{"sp":"N","t":"et simul in multas partis qui credere possis"},{"sp":"N","t":"mittere? an hoc ausis numquam contendere factum,"},{"sp":"N","t":"ut fierent ictus uno sub tempore plures?"},{"sp":"N","t":"at saepest numero factum fierique necessest,"},{"sp":"N","t":"ut pluere in multis regionibus et cadere imbris,","st":"6.415"},{"sp":"N","t":"fulmina sic uno fieri sub tempore multa."},{"sp":"N","t":"postremo cur sancta deum delubra suasque"},{"sp":"N","t":"discutit infesto praeclaras fulmine sedes"},{"sp":"N","t":"et bene facta deum frangit simulacra suisque"},{"sp":"N","t":"demit imaginibus violento volnere honorem?","st":"6.420"},{"sp":"N","t":"altaque cur plerumque petit loca plurimaque eius"},{"sp":"N","t":"montibus in summis vestigia cernimus ignis?"},{"sp":"N","t":"Quod super est, facilest ex his cognoscere rebus,"},{"sp":"N","t":"presteras Graii quos ab re nominitarunt,"},{"sp":"N","t":"in mare qua missi veniant ratione superne.","st":"6.425"},{"sp":"N","t":"nam fit ut inter dum tam quam demissa columna"},{"sp":"N","t":"in mare de caelo descendat, quam freta circum"},{"sp":"N","t":"fervescunt graviter spirantibus incita flabris,"},{"sp":"N","t":"et quae cumque in eo tum sint deprensa tumultu"},{"sp":"N","t":"navigia in summum veniant vexata periclum.","st":"6.430"},{"sp":"N","t":"hoc fit ubi inter dum non quit vis incita venti"},{"sp":"N","t":"rumpere quam coepit nubem, sed deprimit, ut sit"},{"sp":"N","t":"in mare de caelo tam quam demissa columna,"},{"sp":"N","t":"paulatim, quasi quid pugno bracchique superne"},{"sp":"N","t":"coniectu trudatur et extendatur in undas;","st":"6.435"},{"sp":"N","t":"quam cum discidit, hinc prorumpitur in mare venti"},{"sp":"N","t":"vis et fervorem mirum concinnat in undis;"},{"sp":"N","t":"versabundus enim turbo descendit et illam"},{"sp":"N","t":"deducit pariter lento cum corpore nubem;"},{"sp":"N","t":"quam simul ac gravidam detrusit ad aequora ponti,","st":"6.440"},{"sp":"N","t":"ille in aquam subito totum se inmittit et omne"},{"sp":"N","t":"excitat ingenti sonitu mare fervere cogens."},{"sp":"N","t":"Fit quoque ut involvat venti se nubibus ipse"},{"sp":"N","t":"vertex conradens ex aere semina nubis"},{"sp":"N","t":"et quasi demissum caelo prestera imitetur;","st":"6.445"},{"sp":"N","t":"hic ubi se in terras demisit dissoluitque,"},{"sp":"N","t":"turbinis immanem vim provomit atque procellae."},{"sp":"N","t":"sed quia fit raro omnino montisque necessest"},{"sp":"N","t":"officere in terris, apparet crebrius idem"},{"sp":"N","t":"prospectu maris in magno caeloque patenti.","st":"6.450"},{"sp":"N","t":"Nubila concrescunt, ubi corpora multa volando"},{"sp":"N","t":"hoc super in caeli spatio coiere repente"},{"sp":"N","t":"asperiora, modis quae possint indupedita"},{"sp":"N","t":"exiguis tamen inter se compressa teneri."},{"sp":"N","t":"haec faciunt primum parvas consistere nubes;","st":"6.455"},{"sp":"N","t":"inde ea comprendunt inter se conque gregantur"},{"sp":"N","t":"et coniungendo crescunt ventisque feruntur"},{"sp":"N","t":"usque adeo donec tempestas saeva coortast."},{"sp":"N","t":"Fit quoque uti montis vicina cacumina caelo"},{"sp":"N","t":"quam sint quoque magis, tanto magis edita fument","st":"6.460"},{"sp":"N","t":"adsidue fulvae nubis caligine crassa"},{"sp":"N","t":"propterea quia, cum consistunt nubila primum,"},{"sp":"N","t":"ante videre oculi quam possint tenvia, venti"},{"sp":"N","t":"portantes cogunt ad summa cacumina montis;"},{"sp":"N","t":"hic demum fit uti turba maiore coorta","st":"6.465"},{"sp":"N","t":"et condensa queant apparere et simul ipso"},{"sp":"N","t":"vertice de montis videantur surgere in aethram."},{"sp":"N","t":"nam loca declarat sursum ventosa patere"},{"sp":"N","t":"res ipsa et sensus, montis cum ascendimus altos."},{"sp":"N","t":"Praeterea permulta mari quoque tollere toto","st":"6.470"},{"sp":"N","t":"corpora naturam declarant litore vestis"},{"sp":"N","t":"suspensae, cum concipiunt umoris adhaesum."},{"sp":"N","t":"quo magis ad nubis augendas multa videntur"},{"sp":"N","t":"posse quoque e salso consurgere momine ponti;"},{"sp":"N","t":"nam ratio consanguineast umoribus omnis.","st":"6.475"},{"sp":"N","t":"Praeterea fluviis ex omnibus et simul ipsa"},{"sp":"N","t":"surgere de terra nebulas aestumque videmus,"},{"sp":"N","t":"quae vel ut halitus hinc ita sursum expressa feruntur"},{"sp":"N","t":"suffunduntque sua caelum caligine et altas"},{"sp":"N","t":"sufficiunt nubis paulatim conveniundo;","st":"6.480"},{"sp":"N","t":"urget enim quoque signiferi super aetheris aestus"},{"sp":"N","t":"et quasi densendo subtexit caerula nimbis."},{"sp":"N","t":"Fit quoque ut hunc veniant in caelum extrinsecus illa"},{"sp":"N","t":"corpora quae faciunt nubis nimbosque volantis;"},{"sp":"N","t":"innumerabilem enim numerum summamque profundi","st":"6.485"},{"sp":"N","t":"esse infinitam docui, quantaque volarent"},{"sp":"N","t":"corpora mobilitate ostendi quamque repente"},{"sp":"N","t":"immemorabile per spatium transire solerent."},{"sp":"N","t":"haut igitur mirumst, si parvo tempore saepe"},{"sp":"N","t":"tam magnis ventis tempestas atque tenebrae","st":"6.490"},{"sp":"N","t":"coperiant maria ac terras inpensa superne,"},{"sp":"N","t":"undique quandoquidem per caulas aetheris omnis"},{"sp":"N","t":"et quasi per magni circum spiracula mundi"},{"sp":"N","t":"exitus introitusque elementis redditus extat."},{"sp":"N","t":"Nunc age, quo pacto pluvius concrescat in altis","st":"6.495"},{"sp":"N","t":"nubibus umor et in terras demissus ut imber"},{"sp":"N","t":"decidat, expediam. primum iam semina aquai"},{"sp":"N","t":"multa simul vincam consurgere nubibus ipsis"},{"sp":"N","t":"omnibus ex rebus pariterque ita crescere utrumque"},{"sp":"N","t":"et nubis et aquam, quae cumque in nubibus extat,","st":"6.500"},{"sp":"N","t":"ut pariter nobis corpus cum sanguine crescit,"},{"sp":"N","t":"sudor item atque umor qui cumque est denique membris."},{"sp":"N","t":"concipiunt etiam multum quoque saepe marinum"},{"sp":"N","t":"umorem, vel uti pendentia vellera lanae,"},{"sp":"N","t":"cum supera magnum mare venti nubila portant.","st":"6.505"},{"sp":"N","t":"consimili ratione ex omnibus amnibus umor"},{"sp":"N","t":"tollitur in nubis. quo cum bene semina aquarum"},{"sp":"N","t":"multa modis multis convenere undique adaucta,"},{"sp":"N","t":"confertae nubes umorem mittere certant"},{"sp":"N","t":"dupliciter; nam vis venti contrudit et ipsa","st":"6.510"},{"sp":"N","t":"copia nimborum turba maiore coacta"},{"sp":"N","t":"urget et e supero premit ac facit effluere imbris."},{"sp":"N","t":"praeterea cum rarescunt quoque nubila ventis"},{"sp":"N","t":"aut dissolvuntur solis super icta calore,"},{"sp":"N","t":"mittunt umorem pluvium stillantque, quasi igni","st":"6.515"},{"sp":"N","t":"cera super calido tabescens multa liquescat."},{"sp":"N","t":"sed vehemens imber fit, ubi vehementer utraque"},{"sp":"N","t":"nubila vi cumulata premuntur et impete venti."},{"sp":"N","t":"at retinere diu pluviae longumque morari"},{"sp":"N","t":"consuerunt, ubi multa cientur semina aquarum","st":"6.520"},{"sp":"N","t":"atque aliis aliae nubes nimbique rigantes"},{"sp":"N","t":"insuper atque omni vulgo de parte feruntur,"},{"sp":"N","t":"terraque cum fumans umorem tota redhalat."},{"sp":"N","t":"hic ubi sol radiis tempestatem inter opacam"},{"sp":"N","t":"adversa fulsit nimborum aspargine contra,","st":"6.525"},{"sp":"N","t":"tum color in nigris existit nubibus arqui."},{"sp":"N","t":"Cetera quae sursum crescunt sursumque creantur,"},{"sp":"N","t":"et quae concrescunt in nubibus, omnia, prorsum"},{"sp":"N","t":"omnia, nix venti grando gelidaeque pruinae"},{"sp":"N","t":"et vis magna geli, magnum duramen aquarum,","st":"6.530"},{"sp":"N","t":"et mora quae fluvios passim refrenat aventis,"},{"sp":"N","t":"perfacilest tamen haec reperire animoque videre,"},{"sp":"N","t":"omnia quo pacto fiant quareve creentur,"},{"sp":"N","t":"cum bene cognoris elementis reddita quae sint."},{"sp":"N","t":"Nunc age, quae ratio terrai motibus extet","st":"6.535"},{"sp":"N","t":"percipe. et in primis terram fac ut esse rearis"},{"sp":"N","t":"supter item ut supera ventosis undique plenam"},{"sp":"N","t":"speluncis multosque lacus multasque lucunas"},{"sp":"N","t":"in gremio gerere et rupes deruptaque saxa;"},{"sp":"N","t":"multaque sub tergo terrai flumina tecta","st":"6.540"},{"sp":"N","t":"volvere vi fluctus summersos caeca putandumst;"},{"sp":"N","t":"undique enim similem esse sui res postulat ipsa."},{"sp":"N","t":"his igitur rebus subiunctis suppositisque"},{"sp":"N","t":"terra superne tremit magnis concussa ruinis,"},{"sp":"N","t":"subter ubi ingentis speluncas subruit aetas;","st":"6.545"},{"sp":"N","t":"quippe cadunt toti montes magnoque repente"},{"sp":"N","t":"concussu late disserpunt inde tremores."},{"sp":"N","t":"et merito, quoniam plaustris concussa tremescunt"},{"sp":"N","t":"tecta viam propter non magno pondere tota,"},{"sp":"N","t":"nec minus exultant, si quidvis cumque viai","st":"6.550"},{"sp":"N","t":"ferratos utrimque rotarum succutit orbes."},{"sp":"N","t":"Fit quoque, ubi in magnas aquae vastasque lucunas"},{"sp":"N","t":"gleba vetustate e terra provolvitur ingens,"},{"sp":"N","t":"ut iactetur aquae fluctu quoque terra vacillans;"},{"sp":"N","t":"ut vas inter aquas non quit constare, nisi umor","st":"6.555"},{"sp":"N","t":"destitit in dubio fluctu iactarier intus."},{"sp":"N","t":"Praeterea ventus cum per loca subcava terrae"},{"sp":"N","t":"collectus parte ex una procumbit et urget"},{"sp":"N","t":"obnixus magnis speluncas viribus altas,"},{"sp":"N","t":"incumbit tellus quo venti prona premit vis.","st":"6.560"},{"sp":"N","t":"tum supera terram quae sunt extructa domorum"},{"sp":"N","t":"ad caelumque magis quanto sunt edita quaeque,"},{"sp":"N","t":"inclinata minent in eandem prodita partem"},{"sp":"N","t":"protractaeque trabes inpendent ire paratae."},{"sp":"N","t":"et metuunt magni naturam credere mundi","st":"6.565"},{"sp":"N","t":"exitiale aliquod tempus clademque manere,"},{"sp":"N","t":"cum videant tantam terrarum incumbere molem!"},{"sp":"N","t":"quod nisi respirent venti, vis nulla refrenet"},{"sp":"N","t":"res neque ab exitio possit reprehendere euntis;"},{"sp":"N","t":"nunc quia respirant alternis inque gravescunt","st":"6.570"},{"sp":"N","t":"et quasi collecti redeunt ceduntque repulsi,"},{"sp":"N","t":"saepius hanc ob rem minitatur terra ruinas"},{"sp":"N","t":"quam facit; inclinatur enim retroque recellit"},{"sp":"N","t":"et recipit prolapsa suas in pondere sedes."},{"sp":"N","t":"hac igitur ratione vacillant omnia tecta,","st":"6.575"},{"sp":"N","t":"summa magis mediis, media imis, ima perhilum."},{"sp":"N","t":"Est haec eiusdem quoque magni causa tremoris."},{"sp":"N","t":"ventus ubi atque animae subito vis maxima quaedam"},{"sp":"N","t":"aut extrinsecus aut ipsa tellure coorta"},{"sp":"N","t":"in loca se cava terrai coniecit ibique","st":"6.580"},{"sp":"N","t":"speluncas inter magnas fremit ante tumultu"},{"sp":"N","t":"versabundaQUE portatur, post incita cum vis"},{"sp":"N","t":"exagitata foras erumpitur et simul altam"},{"sp":"N","t":"diffindens terram magnum concinnat hiatum."},{"sp":"N","t":"in Syria Sidone quod accidit et fuit Aegi","st":"6.585"},{"sp":"N","t":"in Peloponneso, quas exitus hic animai"},{"sp":"N","t":"disturbat urbes et terrae motus obortus."},{"sp":"N","t":"multaque praeterea ceciderunt moenia magnis"},{"sp":"N","t":"motibus in terris et multae per mare pessum"},{"sp":"N","t":"subsedere suis pariter cum civibus urbes.","st":"6.590"},{"sp":"N","t":"quod nisi prorumpit, tamen impetus ipse animai"},{"sp":"N","t":"et fera vis venti per crebra foramina terrae"},{"sp":"N","t":"dispertitur ut horror et incutit inde tremorem;"},{"sp":"N","t":"frigus uti nostros penitus cum venit in artus,"},{"sp":"N","t":"concutit invitos cogens tremere atque movere.","st":"6.595"},{"sp":"N","t":"ancipiti trepidant igitur terrore per urbis,"},{"sp":"N","t":"tecta superne timent, metuunt inferne cavernas"},{"sp":"N","t":"terrai ne dissoluat natura repente,"},{"sp":"N","t":"neu distracta suum late dispandat hiatum"},{"sp":"N","t":"idque suis confusa velit complere ruinis.","st":"6.600"},{"sp":"N","t":"proinde licet quamvis caelum terramque reantur"},{"sp":"N","t":"incorrupta fore aeternae mandata saluti:"},{"sp":"N","t":"et tamen inter dum praesens vis ipsa pericli"},{"sp":"N","t":"subdit et hunc stimulum quadam de parte timoris,"},{"sp":"N","t":"ne pedibus raptim tellus subtracta feratur","st":"6.605"},{"sp":"N","t":"in barathrum rerumque sequatur prodita summa"},{"sp":"N","t":"funditus et fiat mundi confusa ruina."},{"sp":"N","t":"Principio mare mirantur non reddere maius"},{"sp":"N","t":"naturam, quo sit tantus decursus aquarum,"},{"sp":"N","t":"omnia quo veniant ex omni flumina parte.","st":"6.610"},{"sp":"N","t":"adde vagos imbris tempestatesque volantes,"},{"sp":"N","t":"omnia quae maria ac terras sparguntque rigantque;"},{"sp":"N","t":"adde suos fontis; tamen ad maris omnia summam"},{"sp":"N","t":"guttai vix instar erunt unius adaugmen;"},{"sp":"N","t":"quo minus est mirum mare non augescere magnum.","st":"6.615"},{"sp":"N","t":"Praeterea magnam sol partem detrahit aestu."},{"sp":"N","t":"quippe videmus enim vestis umore madentis"},{"sp":"N","t":"exsiccare suis radiis ardentibus solem;"},{"sp":"N","t":"at pelage multa et late substrata videmus."},{"sp":"N","t":"proinde licet quamvis ex uno quoque loco sol","st":"6.620"},{"sp":"N","t":"umoris parvam delibet ab aequore partem,"},{"sp":"N","t":"largiter in tanto spatio tamen auferet undis."},{"sp":"N","t":"Tum porro venti quoque magnam tollere partem"},{"sp":"N","t":"umoris possunt verrentes aequora, ventis"},{"sp":"N","t":"una nocte vias quoniam persaepe videmus","st":"6.625"},{"sp":"N","t":"siccari mollisque luti concrescere crustas."},{"sp":"N","t":"Praeterea docui multum quoque tollere nubes"},{"sp":"N","t":"umorem magno conceptum ex aequore ponti"},{"sp":"N","t":"et passim toto terrarum spargere in orbi,"},{"sp":"N","t":"cum pluit in terris et venti nubila portant.","st":"6.630"},{"sp":"N","t":"Postremo quoniam raro cum corpore tellus"},{"sp":"N","t":"est et coniunctast oras maris undique cingens,"},{"sp":"N","t":"debet, ut in mare de terris venit umor aquai,"},{"sp":"N","t":"in terras itidem manare ex aequore salso;"},{"sp":"N","t":"percolatur enim virus retroque remanat","st":"6.635"},{"sp":"N","t":"materies umoris et ad caput amnibus omnis"},{"sp":"N","t":"confluit, inde super terras redit agmine dulci"},{"sp":"N","t":"qua via secta semel liquido pede detulit undas."},{"sp":"N","t":"Nunc ratio quae sit, per fauces montis ut Aetnae"},{"sp":"N","t":"expirent ignes inter dum turbine tanto,","st":"6.640"},{"sp":"N","t":"expediam; neque enim mediocri clade coorta"},{"sp":"N","t":"flammae tempestas Siculum dominata per agros"},{"sp":"N","t":"finitimis ad se convertit gentibus ora,"},{"sp":"N","t":"fumida cum caeli scintillare omnia templa"},{"sp":"N","t":"cernentes pavida complebant pectora cura,","st":"6.645"},{"sp":"N","t":"quid moliretur rerum natura novarum."},{"sp":"N","t":"Hisce tibi in rebus latest alteque videndum"},{"sp":"N","t":"et longe cunctas in partis dispiciendum,"},{"sp":"N","t":"ut reminiscaris summam rerum esse profundam"},{"sp":"N","t":"et videas caelum summai totius unum","st":"6.650"},{"sp":"N","t":"quam sit parvula pars et quam multesima constet"},{"sp":"N","t":"nec tota pars, homo terrai quota totius unus."},{"sp":"N","t":"quod bene propositum si plane contueare"},{"sp":"N","t":"ac videas plane, mirari multa relinquas."},{"sp":"N","t":"numquis enim nostrum miratur, siquis in artus","st":"6.655"},{"sp":"N","t":"accepit calido febrim fervore coortam"},{"sp":"N","t":"aut alium quemvis morbi per membra dolorem?"},{"sp":"N","t":"opturgescit enim subito pes, arripit acer"},{"sp":"N","t":"saepe dolor dentes, oculos invadit in ipsos,"},{"sp":"N","t":"existit sacer ignis et urit corpore serpens","st":"6.660"},{"sp":"N","t":"quam cumque arripuit partem repitque per artus,"},{"sp":"N","t":"ni mirum quia sunt multarum semina rerum"},{"sp":"N","t":"et satis haec tellus morbi caelumque mali fert,"},{"sp":"N","t":"unde queat vis immensi procrescere morbi."},{"sp":"N","t":"sic igitur toti caelo terraeque putandumst","st":"6.665"},{"sp":"N","t":"ex infinito satis omnia suppeditare,"},{"sp":"N","t":"unde repente queat tellus concussa moveri"},{"sp":"N","t":"perque mare ac terras rapidus percurrere turbo,"},{"sp":"N","t":"ignis abundare Aetnaeus, flammescere caelum;"},{"sp":"N","t":"id quoque enim fit et ardescunt caelestia templa","st":"6.670"},{"sp":"N","t":"et tempestates pluviae graviore coortu"},{"sp":"N","t":"sunt, ubi forte ita se tetulerunt semina aquarum."},{"sp":"N","t":"'at nimis est ingens incendi turbidus ardor.'"},{"sp":"N","t":"scilicet et fluvius qui visus maximus ei,"},{"sp":"N","t":"qui non ante aliquem maiorem vidit, et ingens","st":"6.675"},{"sp":"N","t":"arbor homoque videtur et omnia de genere omni"},{"sp":"N","t":"maxima quae vidit quisque, haec ingentia fingit,"},{"sp":"N","t":"cum tamen omnia cum caelo terraque marique"},{"sp":"N","t":"nil sint ad summam summai totius omnem."},{"sp":"N","t":"Nunc tamen illa modis quibus inritata repente","st":"6.680"},{"sp":"N","t":"flamma foras vastis Aetnae fornacibus efflet,"},{"sp":"N","t":"expediam. primum totius subcava montis"},{"sp":"N","t":"est natura fere silicum suffulta cavernis."},{"sp":"N","t":"omnibus est porro in speluncis ventus et aer."},{"sp":"N","t":"ventus enim fit, ubi est agitando percitus aer.","st":"6.685"},{"sp":"N","t":"hic ubi percaluit cale fecitque omnia circum"},{"sp":"N","t":"saxa furens, qua contingit, terramque et ab ollis"},{"sp":"N","t":"excussit calidum flammis velocibus ignem,"},{"sp":"N","t":"tollit se ac rectis ita faucibus eicit alte."},{"sp":"N","t":"fert itaque ardorem longe longeque favillam","st":"6.690"},{"sp":"N","t":"differt et crassa volvit caligine fumum"},{"sp":"N","t":"extruditque simul mirando pondere saxa;"},{"sp":"N","t":"ne dubites quin haec animai turbida sit vis."},{"sp":"N","t":"praeterea magna ex parti mare montis ad eius"},{"sp":"N","t":"radices frangit fluctus aestumque resolvit.","st":"6.695"},{"sp":"N","t":"ex hoc usque mari speluncae montis ad altas"},{"sp":"N","t":"perveniunt subter fauces. hac ire fatendumst"},{"sp":"N","t":"et penetrare mari penitus res cogit aperto"},{"sp":"N","t":"atque efflare foras ideoque extollere flammam"},{"sp":"N","t":"saxaque subiectare et arenae tollere nimbos.","st":"6.700"},{"sp":"N","t":"in summo sunt vertice enim crateres, ut ipsi"},{"sp":"N","t":"nominitant, nos quod fauces perhibemus et ora."},{"sp":"N","t":"Sunt aliquot quoque res quarum unam dicere causam"},{"sp":"N","t":"non satis est, verum pluris, unde una tamen sit;"},{"sp":"N","t":"corpus ut exanimum siquod procul ipse iacere","st":"6.705"},{"sp":"N","t":"conspicias hominis, fit ut omnis dicere causas"},{"sp":"N","t":"conveniat leti, dicatur ut illius una;"},{"sp":"N","t":"nam neque eum ferro nec frigore vincere possis"},{"sp":"N","t":"interiisse neque a morbo neque forte veneno,"},{"sp":"N","t":"verum aliquid genere esse ex hoc quod contigit ei","st":"6.710"},{"sp":"N","t":"scimus. item in multis hoc rebus dicere habemus."},{"sp":"N","t":"Nilus in aestatem crescit campisque redundat"},{"sp":"N","t":"unicus in terris, Aegypti totius amnis."},{"sp":"N","t":"is rigat Aegyptum medium per saepe calorem,"},{"sp":"N","t":"aut quia sunt aestate aquilones ostia contra,","st":"6.715"},{"sp":"N","t":"anni tempore eo, qui etesiae esse feruntur,"},{"sp":"N","t":"et contra fluvium flantes remorantur et undas"},{"sp":"N","t":"cogentes sursus replent coguntque manere."},{"sp":"N","t":"nam dubio procul haec adverso flabra feruntur"},{"sp":"N","t":"flumine, quae gelidis ab stellis axis aguntur;","st":"6.720"},{"sp":"N","t":"ille ex aestifera parti venit amnis ab austro"},{"sp":"N","t":"inter nigra virum percocto saecla colore"},{"sp":"N","t":"exoriens penitus media ab regione diei."},{"sp":"N","t":"est quoque uti possit magnus congestus harenae"},{"sp":"N","t":"fluctibus adversis oppilare ostia contra,","st":"6.725"},{"sp":"N","t":"cum mare permotum ventis ruit intus harenam;"},{"sp":"N","t":"quo fit uti pacto liber minus exitus amnis"},{"sp":"N","t":"et proclivis item fiat minus impetus undis."},{"sp":"N","t":"fit quoque uti pluviae forsan magis ad caput ei"},{"sp":"N","t":"tempore eo fiant, quo etesia flabra aquilonum","st":"6.730"},{"sp":"N","t":"nubila coniciunt in eas tunc omnia partis."},{"sp":"N","t":"scilicet, ad mediam regionem eiecta diei"},{"sp":"N","t":"cum convenerunt, ibi ad altos denique montis"},{"sp":"N","t":"contrusae nubes coguntur vique premuntur."},{"sp":"N","t":"forsitan Aethiopum penitus de montibus altis","st":"6.735"},{"sp":"N","t":"crescat, ubi in campos albas descendere ningues"},{"sp":"N","t":"tabificis subigit radiis sol omnia lustrans."},{"sp":"N","t":"Nunc age, Averna tibi quae sint loca cumque lacusque,"},{"sp":"N","t":"expediam, quali natura praedita constent."},{"sp":"N","t":"principio, quod Averna vocantur nomine, id ab re","st":"6.740"},{"sp":"N","t":"inpositumst, quia sunt avibus contraria cunctis,"},{"sp":"N","t":"e regione ea quod loca cum venere volantes,"},{"sp":"N","t":"remigii oblitae pennarum vela remittunt"},{"sp":"N","t":"praecipitesque cadunt molli cervice profusae"},{"sp":"N","t":"in terram, si forte ita fert natura locorum,","st":"6.745"},{"sp":"N","t":"aut in aquam, si forte lacus substratus Averni."},{"sp":"N","t":"is locus est Cumas aput, acri sulpure montis"},{"sp":"N","t":"oppleti calidis ubi fumant fontibus aucti."},{"sp":"N","t":"est et Athenaeis in moenibus, arcis in ipso"},{"sp":"N","t":"vertice, Palladis ad templum Tritonidis almae,","st":"6.750"},{"sp":"N","t":"quo numquam pennis appellunt corpora raucae"},{"sp":"N","t":"cornices, non cum fumant altaria donis;"},{"sp":"N","t":"usque adeo fugitant non iras Palladis acris"},{"sp":"N","t":"pervigili causa, Graium ut cecinere poetae,"},{"sp":"N","t":"sed natura loci opus efficit ipsa suapte.","st":"6.755"},{"sp":"N","t":"in Syria quoque fertur item locus esse videri,"},{"sp":"N","t":"quadripedes quoque quo simul ac vestigia primum"},{"sp":"N","t":"intulerint, graviter vis cogat concidere ipsa,"},{"sp":"N","t":"manibus ut si sint divis mactata repente."},{"sp":"N","t":"omnia quae naturali ratione geruntur,","st":"6.760"},{"sp":"N","t":"et quibus e fiant causis apparet origo;"},{"sp":"N","t":"ianua ne pote eis Orci regionibus esse"},{"sp":"N","t":"credatur, post hinc animas Acheruntis in oras"},{"sp":"N","t":"ducere forte deos manis inferne reamur,"},{"sp":"N","t":"naribus alipedes ut cervi saepe putantur","st":"6.765"},{"sp":"N","t":"ducere de latebris serpentia saecla ferarum."},{"sp":"N","t":"quod procul a vera quam sit ratione repulsum"},{"sp":"N","t":"percipe; nam de re nunc ipsa dicere conor."},{"sp":"N","t":"Principio hoc dico, quod dixi saepe quoque ante,"},{"sp":"N","t":"in terra cuiusque modi rerum esse figuras;","st":"6.770"},{"sp":"N","t":"multa, cibo quae sunt, vitalia multaque, morbos"},{"sp":"N","t":"incutere et mortem quae possint adcelerare."},{"sp":"N","t":"et magis esse aliis alias animantibus aptas"},{"sp":"N","t":"res ad vitai rationem ostendimus ante"},{"sp":"N","t":"propter dissimilem naturam dissimilisque","st":"6.775"},{"sp":"N","t":"texturas inter sese primasque figuras."},{"sp":"N","t":"multa meant inimica per auris, multa per ipsas"},{"sp":"N","t":"insinuant naris infesta atque aspera tactu,"},{"sp":"N","t":"nec sunt multa parum tactu vitanda neque autem"},{"sp":"N","t":"aspectu fugienda saporeque tristia quae sint.","st":"6.780"},{"sp":"N","t":"Deinde videre licet quam multae sint homini res"},{"sp":"N","t":"acriter infesto sensu spurcaeque gravisque;"},{"sp":"N","t":"arboribus primum certis gravis umbra tributa"},{"sp":"N","t":"usque adeo, capitis faciant ut saepe dolores,"},{"sp":"N","t":"siquis eas subter iacuit prostratus in herbis.","st":"6.785"},{"sp":"N","t":"est etiam magnis Heliconis montibus arbos"},{"sp":"N","t":"floris odore hominem taetro consueta necare."},{"sp":"N","t":"scilicet haec ideo terris ex omnia surgunt,"},{"sp":"N","t":"multa modis multis multarum semina rerum"},{"sp":"N","t":"quod permixta gerit tellus discretaque tradit.","st":"6.790"},{"sp":"N","t":"nocturnumque recens extinctum lumen ubi acri"},{"sp":"N","t":"nidore offendit nares, consopit ibidem,"},{"sp":"N","t":"concidere et spumas qui morbo mittere suevit."},{"sp":"N","t":"castoreoque gravi mulier sopita recumbit,"},{"sp":"N","t":"et manibus nitidum teneris opus effluit ei,","st":"6.795"},{"sp":"N","t":"tempore eo si odoratast quo menstrua solvit."},{"sp":"N","t":"multaque praeterea languentia membra per artus"},{"sp":"N","t":"solvunt atque animam labefactant sedibus intus."},{"sp":"N","t":"denique si calidis etiam cunctere lavabris"},{"sp":"N","t":"plenior et lueris, solio ferventis aquai","st":"6.800"},{"sp":"N","t":"quam facile in medio fit uti des saepe ruinas!"},{"sp":"N","t":"carbonumque gravis vis atque odor insinuatur"},{"sp":"N","t":"quam facile in cerebrum, nisi aqua praecepimus ante!"},{"sp":"N","t":"at cum membra domans percepit fervida febris,"},{"sp":"N","t":"tum fit odor vini plagae mactabilis instar.","st":"6.805"},{"sp":"N","t":"nonne vides etiam terra quoque sulpur in ipsa"},{"sp":"N","t":"gignier et taetro concrescere odore bitumen,"},{"sp":"N","t":"denique ubi argenti venas aurique secuntur,"},{"sp":"N","t":"terrai penitus scrutantes abdita ferro,"},{"sp":"N","t":"qualis expiret Scaptensula subter odores?","st":"6.810"},{"sp":"N","t":"quidve mali fit ut exalent aurata metalla!"},{"sp":"N","t":"quas hominum reddunt facies qualisque colores!"},{"sp":"N","t":"nonne vides audisve perire in tempore parvo"},{"sp":"N","t":"quam soleant et quam vitai copia desit,"},{"sp":"N","t":"quos opere in tali cohibet vis magna necessis?","st":"6.815"},{"sp":"N","t":"hos igitur tellus omnis exaestuat aestus"},{"sp":"N","t":"expiratque foras in apertum promptaque caeli."},{"sp":"N","t":"Sic et Averna loca alitibus summittere debent"},{"sp":"N","t":"mortiferam vim. de terra quae surgit in auras,"},{"sp":"N","t":"ut spatium caeli quadam de parte venenet;","st":"6.820"},{"sp":"N","t":"quo simul ac primum pennis delata sit ales,"},{"sp":"N","t":"impediatur ibi caeco correpta veneno,"},{"sp":"N","t":"ut cadat e regione loci, qua derigit aestus."},{"sp":"N","t":"quo cum conruit, hic eadem vis illius aestus"},{"sp":"N","t":"reliquias vitae membris ex omnibus aufert.","st":"6.825"},{"sp":"N","t":"quippe etenim primo quasi quendam conciet aestum;"},{"sp":"N","t":"posterius fit uti. cum iam cecidere veneni"},{"sp":"N","t":"in fontis ipsos, ibi sit quoque vita vomenda,"},{"sp":"N","t":"propterea quod magna mali fit copia circum."},{"sp":"N","t":"Fit quoque ut inter dum vis haec atque aestus Averni","st":"6.830"},{"sp":"N","t":"aera, qui inter avis cumquest terramque locatus."},{"sp":"N","t":"discutiat, prope uti locus hic linquatur inanis."},{"sp":"N","t":"cuius ubi e regione loci venere volantis,"},{"sp":"N","t":"claudicat extemplo pinnarum nisus inanis"},{"sp":"N","t":"et conamen utrimque alarum proditur omne.","st":"6.835"},{"sp":"N","t":"hic ubi nixari nequeunt insistereque alis,"},{"sp":"N","t":"scilicet in terram delabi pondere cogit"},{"sp":"N","t":"natura, et vacuum prope iam per inane iacentes"},{"sp":"N","t":"dispergunt animas per caulas corporis omnis."},{"sp":"N","t":"frigidior porro in puteis aestate fit umor,","st":"6.840"},{"sp":"N","t":"arescit quia terra calore et semina si qua"},{"sp":"N","t":"forte vaporis habet proprie, dimittit in auras."},{"sp":"N","t":"quo magis est igitur tellus effeta calore,"},{"sp":"N","t":"fit quoque frigidior qui in terrast abditus umor."},{"sp":"N","t":"frigore cum premitur porro omnis terra coitque","st":"6.845"},{"sp":"N","t":"et quasi concrescit, fit scilicet ut coeundo"},{"sp":"N","t":"exprimat in puteos si quem gerit ipsa calorem."},{"sp":"N","t":"Esse apud Hammonis fanum fons luce diurna"},{"sp":"N","t":"frigidus et calidus nocturno tempore fertur."},{"sp":"N","t":"hunc homines fontem nimis admirantur et acri","st":"6.850"},{"sp":"N","t":"sole putant subter terras fervescere partim,"},{"sp":"N","t":"nox ubi terribili terras caligine texit."},{"sp":"N","t":"quod nimis a verast longe ratione remotum."},{"sp":"N","t":"quippe ubi sol nudum contractans corpus aquai"},{"sp":"N","t":"non quierit calidum supera de reddere parte,","st":"6.855"},{"sp":"N","t":"cum superum lumen tanto fervore fruatur,"},{"sp":"N","t":"qui queat hic supter tam crasso corpore terram"},{"sp":"N","t":"perquoquere umorem et calido focilare vapore?"},{"sp":"N","t":"praesertim cum vix possit per saepta domorum"},{"sp":"N","t":"insinuare suum radiis ardentibus aestum.","st":"6.860"},{"sp":"N","t":"quae ratiost igitur? ni mirum terra magis quod"},{"sp":"N","t":"rara tenet circum fontem quam cetera tellus"},{"sp":"N","t":"multaque sunt ignis prope semina corpus aquai."},{"sp":"N","t":"hoc ubi roriferis terram nox obruit undis,"},{"sp":"N","t":"extemplo penitus frigescit terra coitque.","st":"6.865"},{"sp":"N","t":"hac ratione fit ut, tam quam compressa manu sit,"},{"sp":"N","t":"exprimat in fontem quae semina cumque habet ignis,"},{"sp":"N","t":"quae calidum faciunt laticis tactum atque vaporem."},{"sp":"N","t":"inde ubi sol radiis terram dimovit obortus"},{"sp":"N","t":"et rare fecit calido miscente vapore,","st":"6.870"},{"sp":"N","t":"rursus in antiquas redeunt primordia sedes"},{"sp":"N","t":"ignis et in terram cedit calor omnis aquai."},{"sp":"N","t":"frigidus hanc ob rem fit fons in luce diurna."},{"sp":"N","t":"praeterea solis radiis iactatur aquai"},{"sp":"N","t":"umor et in lucem tremulo rarescit ab aestu;","st":"6.875"},{"sp":"N","t":"propterea fit uti quae semina cumque habet ignis"},{"sp":"N","t":"dimittat; quasi saepe gelum, quod continet in se,"},{"sp":"N","t":"mittit et exsolvit glaciem nodosque relaxat."},{"sp":"N","t":"Frigidus est etiam fons, supra quem sita saepe"},{"sp":"N","t":"stuppa iacit flammam concepto protinus igni,","st":"6.880"},{"sp":"N","t":"taedaque consimili ratione accensa per undas"},{"sp":"N","t":"conlucet, quo cumque natans impellitur auris."},{"sp":"N","t":"ni mirum quia sunt in aqua permulta vaporis"},{"sp":"N","t":"semina de terraque necessest funditus ipsa"},{"sp":"N","t":"ignis corpora per totum consurgere fontem","st":"6.885"},{"sp":"N","t":"et simul exspirare foras exireque in auras,"},{"sp":"N","t":"non ita multa tamen, calidus queat ut fieri fons;"},{"sp":"N","t":"praeterea dispersa foras erumpere cogit"},{"sp":"N","t":"vis per aquam subito sursumque ea conciliari."},{"sp":"N","t":"quod genus endo marist Aradi fons, dulcis aquai","st":"6.890"},{"sp":"N","t":"qui scatit et salsas circum se dimovet undas;"},{"sp":"N","t":"et multis aliis praebet regionibus aequor"},{"sp":"N","t":"utilitatem opportunam sitientibus nautis,"},{"sp":"N","t":"quod dulcis inter salsas intervomit undas."},{"sp":"N","t":"sic igitur per eum possunt erumpere fontem","st":"6.895"},{"sp":"N","t":"et scatere illa foras; in stuppam semina quae cum"},{"sp":"N","t":"conveniunt aut in taedai corpore adhaerent,"},{"sp":"N","t":"ardescunt facile extemplo, quia multa quoque in se"},{"sp":"N","t":"semina habent ignis stuppae taedaeque tenentes."},{"sp":"N","t":"nonne vides etiam, nocturna ad lumina linum","st":"6.900"},{"sp":"N","t":"nuper ubi extinctum admoveas, accendier ante"},{"sp":"N","t":"quam tetigit flammam, taedamque pari ratione?"},{"sp":"N","t":"multaque praeterea prius ipso tacta vapore"},{"sp":"N","t":"eminus ardescunt quam comminus imbuat ignis."},{"sp":"N","t":"hoc igitur fieri quoque in illo fonte putandumst.","st":"6.905"},{"sp":"N","t":"Quod super est, agere incipiam quo foedere fiat"},{"sp":"N","t":"naturae, lapis hic ut ferrum ducere possit,"},{"sp":"N","t":"quem Magneta vocant patrio de nomine Grai,"},{"sp":"N","t":"Magnetum quia sit patriis in finibus ortus."},{"sp":"N","t":"hunc homines lapidem mirantur; quippe catenam","st":"6.910"},{"sp":"N","t":"saepe ex anellis reddit pendentibus ex se."},{"sp":"N","t":"quinque etenim licet inter dum pluresque videre"},{"sp":"N","t":"ordine demisso levibus iactarier auris,"},{"sp":"N","t":"unus ubi ex uno dependet supter adhaerens"},{"sp":"N","t":"ex alioque alius lapidis vim vinclaque noscit;","st":"6.915"},{"sp":"N","t":"usque adeo permananter vis pervalet eius."},{"sp":"N","t":"Hoc genus in rebus firmandumst multa prius quam"},{"sp":"N","t":"ipsius rei rationem reddere possis,"},{"sp":"N","t":"et nimium longis ambagibus est adeundum;"},{"sp":"N","t":"quo magis attentas auris animumque reposco.","st":"6.920"},{"sp":"N","t":"Principio omnibus ab rebus, quas cumque videmus,"},{"sp":"N","t":"perpetuo fluere ac mitti spargique necessest"},{"sp":"N","t":"corpora quae feriant oculos visumque lacessant."},{"sp":"N","t":"perpetuoque fluunt certis ab rebus odores;"},{"sp":"N","t":"frigus ut a fluviis, calor a sole, aestus ab undis","st":"6.925"},{"sp":"N","t":"aequoris, exesor moerorum, litora propter;"},{"sp":"N","t":"nec varii cessant sonitus manare per auras;"},{"sp":"N","t":"denique in os salsi venit umor saepe saporis,"},{"sp":"N","t":"cum mare versamur propter, dilutaque contra"},{"sp":"N","t":"cum tuimur misceri absinthia, tangit amaror.","st":"6.930"},{"sp":"N","t":"usque adeo omnibus ab rebus res quaeque fluenter"},{"sp":"N","t":"fertur et in cunctas dimittitur undique partis"},{"sp":"N","t":"nec mora nec requies interdatur ulla fluendi,"},{"sp":"N","t":"perpetuo quoniam sentimus et omnia semper"},{"sp":"N","t":"cernere odorari licet et sentire sonare.","st":"6.935"},{"sp":"N","t":"Nunc omnis repetam quam raro corpore sint res"},{"sp":"N","t":"commemorare; quod in primo quoque carmine claret."},{"sp":"N","t":"quippe etenim, quamquam multas hoc pertinet ad res"},{"sp":"N","t":"noscere, cum primis hanc ad rem protinus ipsam,"},{"sp":"N","t":"qua de disserere adgredior, firmare necessest","st":"6.940"},{"sp":"N","t":"nil esse in promptu nisi mixtum corpus inani."},{"sp":"N","t":"principio fit ut in speluncis saxa superna"},{"sp":"N","t":"sudent umore et guttis manantibus stillent."},{"sp":"N","t":"manat item nobis e toto corpore sudor,"},{"sp":"N","t":"crescit barba pilique per omnia membra, per artus.","st":"6.945"},{"sp":"N","t":"diditur in venas cibus omnis, auget alitque"},{"sp":"N","t":"corporis extremas quoque partis unguiculosque."},{"sp":"N","t":"frigus item transire per aes calidumque vaporem"},{"sp":"N","t":"sentimus, sentimus item transire per aurum"},{"sp":"N","t":"atque per argentum, cum pocula plena tenemus.","st":"6.950"},{"sp":"N","t":"denique per dissaepta domorum saxea voces"},{"sp":"N","t":"pervolitant, permanat odor frigusque vaposque"},{"sp":"N","t":"ignis, qui ferri quoque vim penetrare suevit,"},{"sp":"N","t":"denique qua circum caeli lorica coercet,"},{"sp":"N","t":"morbida visque simul, cum extrinsecus insinuatur;","st":"6.955"},{"sp":"N","t":"et tempestate in terra caeloque coorta"},{"sp":"N","t":"in caelum terrasque remotae iure facessunt;"},{"sp":"N","t":"quandoquidem nihil est nisi raro corpore nexum."},{"sp":"N","t":"Huc accedit uti non omnia, quae iaciuntur"},{"sp":"N","t":"corpora cumque ab rebus, eodem praedita sensu","st":"6.960"},{"sp":"N","t":"atque eodem pacto rebus sint omnibus apta."},{"sp":"N","t":"principio terram sol excoquit et facit are,"},{"sp":"N","t":"at glaciem dissolvit et altis montibus altas"},{"sp":"N","t":"extructasque nives radiis tabescere cogit;"},{"sp":"N","t":"denique cera lique fit in eius posta vapore.","st":"6.965"},{"sp":"N","t":"ignis item liquidum facit aes aurumque resolvit,"},{"sp":"N","t":"at coria et carnem trahit et conducit in unum."},{"sp":"N","t":"umor aquae porro ferrum condurat ab igni,"},{"sp":"N","t":"at coria et carnem mollit durata calore."},{"sp":"N","t":"barbigeras oleaster eo iuvat usque capellas,","st":"6.970"},{"sp":"N","t":"effluat ambrosias quasi vero et nectare tinctus;"},{"sp":"N","t":"qua nihil est homini quod amarius fronde acida extet."},{"sp":"N","t":"denique amaracinum fugitat sus et timet omne"},{"sp":"N","t":"unguentum; nam saetigeris subus acre venenumst;"},{"sp":"N","t":"quod nos inter dum tam quam recreare videtur.","st":"6.975"},{"sp":"N","t":"at contra nobis caenum taeterrima cum sit"},{"sp":"N","t":"spurcities, eadem subus haec iucunda videtur,"},{"sp":"N","t":"insatiabiliter toti ut volvantur ibidem."},{"sp":"N","t":"Hoc etiam super est, ipsa quam dicere de re"},{"sp":"N","t":"adgredior, quod dicendum prius esse videtur.","st":"6.980"},{"sp":"N","t":"multa foramina cum variis sint reddita rebus,"},{"sp":"N","t":"dissimili inter se natura praedita debent"},{"sp":"N","t":"esse et habere suam naturam quaeque viasque."},{"sp":"N","t":"quippe etenim varii sensus animantibus insunt,"},{"sp":"N","t":"quorum quisque suam proprie rem percipit in se;","st":"6.985"},{"sp":"N","t":"nam penetrare alio sonitus alioque saporem"},{"sp":"N","t":"cernimus e sucis, alio nidoris odores."},{"sp":"N","t":"scilicet id fieri cogit natura viarum"},{"sp":"N","t":"multimodis varians, ut paulo ostendimus ante."},{"sp":"N","t":"praeterea manare aliud per saxa videtur,","st":"6.990"},{"sp":"N","t":"atque aliud lignis, aliud transire per aurum,"},{"sp":"N","t":"argentoque foras aliud vitroque meare;"},{"sp":"N","t":"nam fluere hac species, illac calor ire videtur,"},{"sp":"N","t":"atque aliis aliud citius transmittere eadem."},{"sp":"N","t":"scilicet id fieri cogit natura viarum","st":"6.995"},{"sp":"N","t":"multimodis varians, ut paulo ostendimus ante,"},{"sp":"N","t":"propter dissimilem naturam textaque rerum."},{"sp":"N","t":"Qua propter, bene ubi haec confirmata atque locata"},{"sp":"N","t":"omnia constiterint nobis praeposta parata,"},{"sp":"N","t":"quod super est, facile hinc ratio reddetur et omnis","st":"6.1000"},{"sp":"N","t":"causa pate fiet, quae ferri pelliciat vim."},{"sp":"N","t":"Principio fluere e lapide hoc permulta necessest"},{"sp":"N","t":"semina sive aestum, qui discutit aera plagis,"},{"sp":"N","t":"inter qui lapidem ferrumque est cumque locatus."},{"sp":"N","t":"hoc ubi inanitur spatium multusque vace fit","st":"6.1005"},{"sp":"N","t":"in medio locus, extemplo primordia ferri"},{"sp":"N","t":"in vacuum prolapsa cadunt coniuncta, fit utque"},{"sp":"N","t":"anulus ipse sequatur eatque ita corpore toto."},{"sp":"N","t":"nec res ulla magis primoribus ex elementis"},{"sp":"N","t":"indupedita suis arte conexa cohaeret","st":"6.1010"},{"sp":"N","t":"quam validi ferri natura et frigidus horror."},{"sp":"N","t":"quo minus est mirum, quod dicitur esse alienum,"},{"sp":"N","t":"corpora si nequeunt e ferro plura coorta"},{"sp":"N","t":"in vacuum ferri, quin anulus ipse sequatur;"},{"sp":"N","t":"quod facit et sequitur, donec pervenit ad ipsum","st":"6.1015"},{"sp":"N","t":"iam lapidem caecisque in eo compagibus haesit."},{"sp":"N","t":"hoc fit idem cunctas in partis; unde vace fit"},{"sp":"N","t":"cumque locus, sive e transverso sive superne,"},{"sp":"N","t":"corpora continuo in vacuum vicina feruntur;"},{"sp":"N","t":"quippe agitantur enim plagis aliunde nec ipsa","st":"6.1020"},{"sp":"N","t":"sponte sua sursum possunt consurgere in auras."},{"sp":"N","t":"huc accedit item, quare queat id magis esse,"},{"sp":"N","t":"haec quoque res adiumento motuque iuvatur,"},{"sp":"N","t":"quod, simul a fronte est anelli rarior aer"},{"sp":"N","t":"factus inanitusque locus magis ac vacuatus,","st":"6.1025"},{"sp":"N","t":"continuo fit uti qui post est cumque locatus"},{"sp":"N","t":"aer a tergo quasi provehat atque propellat."},{"sp":"N","t":"semper enim circum positus res verberat aer;"},{"sp":"N","t":"sed tali fit uti propellat tempore ferrum,"},{"sp":"N","t":"parte quod ex una spatium vacat et capit in se.","st":"6.1030"},{"sp":"N","t":"hic, tibi quem memoro, per crebra foramina ferri"},{"sp":"N","t":"parvas ad partis subtiliter insinuatus"},{"sp":"N","t":"trudit et inpellit, quasi navem velaque ventus."},{"sp":"N","t":"denique res omnes debent in corpore habere"},{"sp":"N","t":"aera, quandoquidem raro sunt corpore et aer","st":"6.1035"},{"sp":"N","t":"omnibus est rebus circum datus adpositusque."},{"sp":"N","t":"hic igitur, penitus qui in ferrost abditus aer,"},{"sp":"N","t":"sollicito motu semper iactatur eoque"},{"sp":"N","t":"verberat anellum dubio procul et ciet intus,"},{"sp":"N","t":"scilicet illo eodem fertur, quo praecipitavit","st":"6.1040"},{"sp":"N","t":"iam semel et partem in vacuam conamina sumpsit."},{"sp":"N","t":"Fit quoque ut a lapide hoc ferri natura recedat"},{"sp":"N","t":"inter dum, fugere atque sequi consueta vicissim."},{"sp":"N","t":"exultare etiam Samothracia ferrea vidi"},{"sp":"N","t":"et ramenta simul ferri furere intus ahenis","st":"6.1045"},{"sp":"N","t":"in scaphiis, lapis hic Magnes cum subditus esset;"},{"sp":"N","t":"usque adeo fugere a saxo gestire videtur."},{"sp":"N","t":"aere interposito discordia tanta creatur"},{"sp":"N","t":"propterea quia ni mirum prius aestus ubi aeris"},{"sp":"N","t":"praecepit ferrique vias possedit apertas,","st":"6.1050"},{"sp":"N","t":"posterior lapidis venit aestus et omnia plena"},{"sp":"N","t":"invenit in ferro neque habet qua tranet ut ante;"},{"sp":"N","t":"cogitur offensare igitur pulsareque fluctu"},{"sp":"N","t":"ferrea texta suo; quo pacto respuit ab se"},{"sp":"N","t":"atque per aes agitat, sine eo quod saepe resorbet.","st":"6.1055"},{"sp":"N","t":"Illud in his rebus mirari mitte, quod aestus"},{"sp":"N","t":"non valet e lapide hoc alias impellere item res."},{"sp":"N","t":"pondere enim fretae partim stant, quod genus aurum;"},{"sp":"N","t":"at partim raro quia sunt cum corpore, ut aestus"},{"sp":"N","t":"pervolet intactus, nequeunt inpellier usquam,","st":"6.1060"},{"sp":"N","t":"lignea materies in quo genere esse videtur."},{"sp":"N","t":"interutrasque igitur ferri natura locata"},{"sp":"N","t":"aeris ubi accepit quaedam corpuscula, tum fit,"},{"sp":"N","t":"inpellant ut eo Magnesia flumine saxa."},{"sp":"N","t":"nec tamen haec ita sunt aliarum rerum aliena,","st":"6.1065"},{"sp":"N","t":"ut mihi multa parum genere ex hoc suppeditentur,"},{"sp":"N","t":"quae memorare queam inter se singlariter apta."},{"sp":"N","t":"saxa vides primum sola colescere calce."},{"sp":"N","t":"glutine materies taurino iungitur una,"},{"sp":"N","t":"ut vitio venae tabularum saepius hiscant","st":"6.1070"},{"sp":"N","t":"quam laxare queant compages taurea vincla."},{"sp":"N","t":"vitigeni latices aquai fontibus audent"},{"sp":"N","t":"misceri, cum pix nequeat gravis et leve olivom."},{"sp":"N","t":"purpureusque colos conchyli iungitur uno"},{"sp":"N","t":"corpore cum lanae, dirimi qui non queat usquam,","st":"6.1075"},{"sp":"N","t":"non si Neptuni fluctu renovare operam des,"},{"sp":"N","t":"non mare si totum velit eluere omnibus undis."},{"sp":"N","t":"denique res auro non aurum copulat una,"},{"sp":"N","t":"aerique aes plumbo fit uti iungatur ab albo?"},{"sp":"N","t":"cetera iam quam multa licet reperire! quid ergo?","st":"6.1080"},{"sp":"N","t":"nec tibi tam longis opus est ambagibus usquam"},{"sp":"N","t":"nec me tam multam hic operam consumere par est,"},{"sp":"N","t":"sed breviter paucis praestat comprendere multa."},{"sp":"N","t":"quorum ita texturae ceciderunt mutua contra,"},{"sp":"N","t":"ut cava conveniant plenis haec illius illa","st":"6.1085"},{"sp":"N","t":"huiusque inter se, iunctura haec optima constat."},{"sp":"N","t":"est etiam, quasi ut anellis hamisque plicata"},{"sp":"N","t":"inter se quaedam possint coplata teneri;"},{"sp":"N","t":"quod magis in lapide hoc fieri ferroque videtur."},{"sp":"N","t":"Nunc ratio quae sit morbis aut unde repente","st":"6.1090"},{"sp":"N","t":"mortiferam possit cladem conflare coorta"},{"sp":"N","t":"morbida vis hominum generi pecudumque catervis,"},{"sp":"N","t":"expediam, primum multarum semina rerum"},{"sp":"N","t":"esse supra docui quae sint vitalia nobis,"},{"sp":"N","t":"et contra quae sint morbo mortique necessest","st":"6.1095"},{"sp":"N","t":"multa volare; ea cum casu sunt forte coorta"},{"sp":"N","t":"et perturbarunt caelum, fit morbidus aer."},{"sp":"N","t":"atque ea vis omnis morborum pestilitasque"},{"sp":"N","t":"aut extrinsecus ut nubes nebulaeque superne"},{"sp":"N","t":"per caelum veniunt aut ipsa saepe coorta","st":"6.1100"},{"sp":"N","t":"de terra surgunt, ubi putorem umida nactast"},{"sp":"N","t":"intempestivis pluviisque et solibus icta."},{"sp":"N","t":"nonne vides etiam caeli novitate et aquarum"},{"sp":"N","t":"temptari procul a patria qui cumque domoque"},{"sp":"N","t":"adveniunt ideo quia longe discrepitant res?","st":"6.1105"},{"sp":"N","t":"nam quid Brittannis caelum differre putamus,"},{"sp":"N","t":"et quod in Aegypto est, qua mundi claudicat axis,"},{"sp":"N","t":"quidve quod in Ponto est differre et Gadibus atque"},{"sp":"N","t":"usque ad nigra virum percocto saecla colore?"},{"sp":"N","t":"quae cum quattuor inter se diversa videmus","st":"6.1110"},{"sp":"N","t":"quattuor a ventis et caeli partibus esse,"},{"sp":"N","t":"tum color et facies hominum distare videntur"},{"sp":"N","t":"largiter et morbi generatim saecla tenere."},{"sp":"N","t":"est elephas morbus qui propter flumina Nili"},{"sp":"N","t":"gignitur Aegypto in media neque praeterea usquam.","st":"6.1115"},{"sp":"N","t":"Atthide temptantur gressus oculique in Achaeis"},{"sp":"N","t":"finibus. inde aliis alius locus est inimicus"},{"sp":"N","t":"partibus ac membris; varius concinnat id aer."},{"sp":"N","t":"proinde ubi se caelum, quod nobis forte alienum,"},{"sp":"N","t":"commovet atque aer inimicus serpere coepit,","st":"6.1120"},{"sp":"N","t":"ut nebula ac nubes paulatim repit et omne"},{"sp":"N","t":"qua graditur conturbat et immutare coactat,"},{"sp":"N","t":"fit quoque ut, in nostrum cum venit denique caelum,"},{"sp":"N","t":"corrumpat reddatque sui simile atque alienum."},{"sp":"N","t":"haec igitur subito clades nova pestilitasque","st":"6.1125"},{"sp":"N","t":"aut in aquas cadit aut fruges persidit in ipsas"},{"sp":"N","t":"aut alios hominum pastus pecudumque cibatus,"},{"sp":"N","t":"aut etiam suspensa manet vis aere in ipso"},{"sp":"N","t":"et, cum spirantes mixtas hinc ducimus auras,"},{"sp":"N","t":"illa quoque in corpus pariter sorbere necessest.","st":"6.1130"},{"sp":"N","t":"consimili ratione venit bubus quoque saepe"},{"sp":"N","t":"pestilitas et iam pigris balantibus aegror."},{"sp":"N","t":"nec refert utrum nos in loca deveniamus"},{"sp":"N","t":"nobis adversa et caeli mutemus amictum,"},{"sp":"N","t":"an caelum nobis ultro natura corumptum","st":"6.1135"},{"sp":"N","t":"deferat aut aliquid quo non consuevimus uti,"},{"sp":"N","t":"quod nos adventu possit temptare recenti."},{"sp":"N","t":"Haec ratio quondam morborum et mortifer aestus"},{"sp":"N","t":"finibus in Cecropis funestos reddidit agros"},{"sp":"N","t":"vastavitque vias, exhausit civibus urbem.","st":"6.1140"},{"sp":"N","t":"nam penitus veniens Aegypti finibus ortus,"},{"sp":"N","t":"aera permensus multum camposque natantis,"},{"sp":"N","t":"incubuit tandem populo Pandionis omni."},{"sp":"N","t":"inde catervatim morbo mortique dabantur."},{"sp":"N","t":"principio caput incensum fervore gerebant","st":"6.1145"},{"sp":"N","t":"et duplicis oculos suffusa luce rubentes."},{"sp":"N","t":"sudabant etiam fauces intrinsecus atrae"},{"sp":"N","t":"sanguine et ulceribus vocis via saepta coibat"},{"sp":"N","t":"atque animi interpres manabat lingua cruore"},{"sp":"N","t":"debilitata malis, motu gravis, aspera tactu.","st":"6.1150"},{"sp":"N","t":"inde ubi per fauces pectus complerat et ipsum"},{"sp":"N","t":"morbida vis in cor maestum confluxerat aegris,"},{"sp":"N","t":"omnia tum vero vitai claustra lababant."},{"sp":"N","t":"spiritus ore foras taetrum volvebat odorem,"},{"sp":"N","t":"rancida quo perolent proiecta cadavera ritu.","st":"6.1155"},{"sp":"N","t":"atque animi prorsum tum vires totius, omne"},{"sp":"N","t":"languebat corpus leti iam limine in ipso."},{"sp":"N","t":"intolerabilibusque malis erat anxius angor"},{"sp":"N","t":"adsidue comes et gemitu commixta querella,"},{"sp":"N","t":"singultusque frequens noctem per saepe diemque","st":"6.1160"},{"sp":"N","t":"corripere adsidue nervos et membra coactans"},{"sp":"N","t":"dissoluebat eos, defessos ante, fatigans."},{"sp":"N","t":"nec nimio cuiquam posses ardore tueri"},{"sp":"N","t":"corporis in summo summam fervescere partem,"},{"sp":"N","t":"sed potius tepidum manibus proponere tactum","st":"6.1165"},{"sp":"N","t":"et simul ulceribus quasi inustis omne rubere"},{"sp":"N","t":"corpus, ut est per membra sacer dum diditur ignis."},{"sp":"N","t":"intima pars hominum vero flagrabat ad ossa,"},{"sp":"N","t":"flagrabat stomacho flamma ut fornacibus intus."},{"sp":"N","t":"nil adeo posses cuiquam leve tenveque membris","st":"6.1170"},{"sp":"N","t":"vertere in utilitatem, at ventum et frigora semper."},{"sp":"N","t":"in fluvios partim gelidos ardentia morbo"},{"sp":"N","t":"membra dabant nudum iacientes corpus in undas."},{"sp":"N","t":"multi praecipites nymphis putealibus alte"},{"sp":"N","t":"inciderunt ipso venientes ore patente:","st":"6.1175"},{"sp":"N","t":"insedabiliter sitis arida corpora mersans"},{"sp":"N","t":"aequabat multum parvis umoribus imbrem."},{"sp":"N","t":"nec requies erat ulla mali: defessa iacebant"},{"sp":"N","t":"corpora. mussabat tacito medicina timore,"},{"sp":"N","t":"quippe patentia cum totiens ardentia morbis","st":"6.1180"},{"sp":"N","t":"lumina versarent oculorum expertia somno."},{"sp":"N","t":"multaque praeterea mortis tum signa dabantur:"},{"sp":"N","t":"perturbata animi mens in maerore metuque,"},{"sp":"N","t":"triste supercilium, furiosus voltus et acer,"},{"sp":"N","t":"sollicitae porro plenaeque sonoribus aures,","st":"6.1185"},{"sp":"N","t":"creber spiritus aut ingens raroque coortus,"},{"sp":"N","t":"sudorisque madens per collum splendidus umor,"},{"sp":"N","t":"tenvia sputa minuta, croci contacta colore"},{"sp":"N","t":"salsaque per fauces rauca vix edita tussi."},{"sp":"N","t":"in manibus vero nervi trahere et tremere artus","st":"6.1190"},{"sp":"N","t":"a pedibusque minutatim succedere frigus"},{"sp":"N","t":"non dubitabat. item ad supremum denique tempus"},{"sp":"N","t":"conpressae nares, nasi primoris acumen"},{"sp":"N","t":"tenve, cavati oculi, cava tempora, frigida pellis"},{"sp":"N","t":"duraque in ore, iacens rictu, frons tenta manebat.","st":"6.1195"},{"sp":"N","t":"nec nimio rigida post artus morte iacebant."},{"sp":"N","t":"octavoque fere candenti lumine solis"},{"sp":"N","t":"aut etiam nona reddebant lampade vitam."},{"sp":"N","t":"quorum siquis, ut est, vitarat funera leti,"},{"sp":"N","t":"ulceribus taetris et nigra proluvie alvi","st":"6.1200"},{"sp":"N","t":"posterius tamen hunc tabes letumque manebat,"},{"sp":"N","t":"aut etiam multus capitis cum saepe dolore"},{"sp":"N","t":"corruptus sanguis expletis naribus ibat."},{"sp":"N","t":"huc hominis totae vires corpusque fluebat."},{"sp":"N","t":"profluvium porro qui taetri sanguinis acre","st":"6.1205"},{"sp":"N","t":"exierat, tamen in nervos huic morbus et artus"},{"sp":"N","t":"ibat et in partis genitalis corporis ipsas."},{"sp":"N","t":"et graviter partim metuentes limina leti"},{"sp":"N","t":"vivebant ferro privati parte virili,"},{"sp":"N","t":"et manibus sine non nulli pedibusque manebant","st":"6.1210"},{"sp":"N","t":"in vita tamen et perdebant lumina partim."},{"sp":"N","t":"usque adeo mortis metus iis incesserat acer."},{"sp":"N","t":"atque etiam quosdam cepere oblivia rerum"},{"sp":"N","t":"cunctarum, neque se possent cognoscere ut ipsi."},{"sp":"N","t":"multaque humi cum inhumata iacerent corpora supra","st":"6.1215"},{"sp":"N","t":"corporibus, tamen alituum genus atque ferarum"},{"sp":"N","t":"aut procul absiliebat, ut acrem exiret odorem,"},{"sp":"N","t":"aut, ubi gustarat, languebat morte propinqua."},{"sp":"N","t":"nec tamen omnino temere illis solibus ulla"},{"sp":"N","t":"comparebat avis, nec tristia saecla ferarum","st":"6.1220"},{"sp":"N","t":"exibant silvis. languebant pleraque morbo"},{"sp":"N","t":"et moriebantur. cum primis fida canum vis"},{"sp":"N","t":"strata viis animam ponebat in omnibus aegre;"},{"sp":"N","t":"extorquebat enim vitam vis morbida membris."},{"sp":"N","t":"incomitata rapi certabant funera vasta","st":"6.1225"},{"sp":"N","t":"nec ratio remedii communis certa dabatur;"},{"sp":"N","t":"nam quod ali dederat vitalis aeris auras"},{"sp":"N","t":"volvere in ore licere et caeli templa tueri,"},{"sp":"N","t":"hoc aliis erat exitio letumque parabat."},{"sp":"N","t":"Illud in his rebus miserandum magnopere unum","st":"6.1230"},{"sp":"N","t":"aerumnabile erat, quod ubi se quisque videbat"},{"sp":"N","t":"implicitum morbo, morti damnatus ut esset,"},{"sp":"N","t":"deficiens animo maesto cum corde iacebat,"},{"sp":"N","t":"funera respectans animam amittebat ibidem."},{"sp":"N","t":"quippe etenim nullo cessabant tempore apisci","st":"6.1235"},{"sp":"N","t":"ex aliis alios avidi contagia morbi,"},{"sp":"N","t":"lanigeras tam quam pecudes et bucera saecla,"},{"sp":"N","t":"idque vel in primis cumulabat funere funus"},{"sp":"N","t":"nam qui cumque suos fugitabant visere ad aegros,"},{"sp":"N","t":"vitai nimium cupidos mortisque timentis","st":"6.1240"},{"sp":"N","t":"poenibat paulo post turpi morte malaque,"},{"sp":"N","t":"desertos, opis expertis, incuria mactans."},{"sp":"N","t":"qui fuerant autem praesto, contagibus ibant"},{"sp":"N","t":"atque labore, pudor quem tum cogebat obire"},{"sp":"N","t":"blandaque lassorum vox mixta voce querellae.","st":"6.1245"},{"sp":"N","t":"optimus hoc leti genus ergo quisque subibat."},{"sp":"N","t":"Praeterea iam pastor et armentarius omnis"},{"sp":"N","t":"et robustus item curvi moderator aratri"},{"sp":"N","t":"languebat, penitusque casa contrusa iacebant"},{"sp":"N","t":"corpora paupertate et morbo dedita morti.","st":"6.1250"},{"sp":"N","t":"exanimis pueris super exanimata parentum"},{"sp":"N","t":"corpora non numquam posses retroque videre"},{"sp":"N","t":"matribus et patribus natos super edere vitam."},{"sp":"N","t":"nec minimam partem ex agris maeror is in urbem"},{"sp":"N","t":"confluxit, languens quem contulit agricolarum","st":"6.1255"},{"sp":"N","t":"copia conveniens ex omni morbida parte."},{"sp":"N","t":"omnia conplebant loca tectaque quo magis aestu,"},{"sp":"N","t":"confertos ita acervatim mors accumulabat."},{"sp":"N","t":"multa siti prostrata viam per proque voluta"},{"sp":"N","t":"corpora silanos ad aquarum strata iacebant","st":"6.1260"},{"sp":"N","t":"interclusa anima nimia ab dulcedine aquarum,"},{"sp":"N","t":"multaque per populi passim loca prompta viasque"},{"sp":"N","t":"languida semanimo cum corpore membra videres"},{"sp":"N","t":"horrida paedore et pannis cooperta perire,"},{"sp":"N","t":"corporis inluvie, pelli super ossibus una,","st":"6.1265"},{"sp":"N","t":"ulceribus taetris prope iam sordeque sepulta."},{"sp":"N","t":"omnia denique sancta deum delubra replerat"},{"sp":"N","t":"corporibus mors exanimis onerataque passim"},{"sp":"N","t":"cuncta cadaveribus caelestum templa manebant,"},{"sp":"N","t":"hospitibus loca quae complerant aedituentes.","st":"6.1270"},{"sp":"N","t":"nec iam religio divom nec numina magni"},{"sp":"N","t":"pendebantur enim: praesens dolor exsuperabat."},{"sp":"N","t":"nec mos ille sepulturae remanebat in urbe,"},{"sp":"N","t":"quo prius hic populus semper consuerat humari;"},{"sp":"N","t":"perturbatus enim totus trepidabat et unus","st":"6.1275"},{"sp":"N","t":"quisque suum pro re cognatum maestus humabat."},{"sp":"N","t":"multaque res subita et paupertas horrida suasit;"},{"sp":"N","t":"namque suos consanguineos aliena rogorum"},{"sp":"N","t":"insuper extructa ingenti clamore locabant"},{"sp":"N","t":"subdebantque faces, multo cum sanguine saepe","st":"6.1280"},{"sp":"N","t":"rixantes, potius quam corpora desererentur,"},{"sp":"N","t":"inque aliis alium populum sepelire suorum"},{"sp":"N","t":"certantes; lacrimis lassi luctuque redibant;"},{"sp":"N","t":"inde bonam partem in lectum maerore dabantur;"},{"sp":"N","t":"nec poterat quisquam reperiri, quem neque morbus","st":"6.1285"},{"sp":"N","t":"nec mors nec luctus temptaret tempore tali."}],[]);})();